  if (lk) parts.push(MR_UNITS[lk] + ' लाख'); if (th) parts.push(MR_UNITS[th] + ' हजार'); if (hu) parts.push(MR_UNITS[hu] + 'शे'); if (n) parts.push(MR_UNITS[n]);
