  <div class="ap-d" tabindex="${disabled ? -1 : 0}" onclick="${disabled ? '' : `apOpen('${id}')`}" onkeydown="apKey(event,'${id}')">${sel ? `<span class="gd d-${sel.grp}"></span><span class="tx">${esc(sel.label)}</span>` : `<span class="tx ph">${esc(ph)}</span>`}</div>
