// A team manager who is not admin may only handle plain accountants / viewers (not admins, not other team managers, not themselves)
const canManage = (uid, a) => isAdmin() ? uid !== S.meta.owner : (canTeam() && uid !== S.user.uid && a && a.r !== 'admin' && a.tm !== true);
