function guardDate(d, what = 'entry') {
  if (!S.fy) throw new Error('No financial year selected.');
  if (!isYmd(d)) throw new Error('Please enter a valid date.');
  if (d < S.fy.start || d > S.fy.end) throw new Error(`Date ${fd(d)} is outside FY ${S.fy.label} (${fd(S.fy.start)} – ${fd(S.fy.end)}).`);
  if (S.fy.closed) throw new Error(`FY ${S.fy.label} is closed. Reopen it from Year-End & Locks to change entries.`);
  if (S.fy.lock && d <= S.fy.lock) throw new Error(`Books are locked up to ${fd(S.fy.lock)} (audit lock). This ${what} can't be added or changed.`);
}

// ── Writes: atomic multi-path commit + audit trail ──────────────────────
async function commit(updates, audit) {
  const full = {};
  for (const [k, v] of Object.entries(updates)) full[sp(k)] = v === undefined ? null : v;
  if (audit) full[sp('audit/' + FBX.key(sp('audit')))] = { at: FBX.ts(), u: S.user.uid, n: uname(), a: audit.a || '', e: audit.e || '', id: audit.id || '', s: String(audit.s || '').slice(0, 300), ...(audit.dif ? { dif: String(audit.dif).slice(0, 4000) } : {}) };
  await FBX.update(full);
  applyLocal(updates);
}
// Apply a committed write to local state at once (Realtime Database also does this), so follow-up
