    const runs = Object.values(S.runs || {}).filter(r => r && !r.supp).map(r => r.from).sort();
    const sm = { out: r2(out), adv: r2(adv), members: Object.values(S.members).filter(m => m && m.active !== false).length, lastBill: runs[runs.length - 1] || '', fy: S.fy.label, amc: amcSummary(), rem: typeof remSummary === 'function' ? remSummary() : [], top: Object.entries(mb).filter(([, r]) => r.bal > 0.5).sort((a, b) => b[1].bal - a[1].bal).slice(0, 5).map(([mid, r]) => ({ f: flatLbl(M(mid)), n: (M(mid) || {}).name || '', b: r2(r.bal) })), lastV: Object.values(S.vch || {}).reduce((a, v) => (v && v.d > a ? v.d : a), ''), at: Date.now(), by: uname() };
    try { if (typeof summaryX === 'function') sm.x = summaryX(); } catch (e) { }
    const cur = S.summary || {};
    if (cur.out !== sm.out || cur.adv !== sm.adv || cur.members !== sm.members || cur.lastBill !== sm.lastBill || cur.fy !== sm.fy || JSON.stringify(cur.amc || []) !== JSON.stringify(sm.amc) || JSON.stringify(cur.rem || []) !== JSON.stringify(sm.rem) || JSON.stringify(cur.top || []) !== JSON.stringify(sm.top) || (cur.lastV || '') !== sm.lastV || JSON.stringify(cur.x || null) !== JSON.stringify(sm.x || null)) await FBX.set(sp('summary'), sm);
