  try { s = a.selectionStart; e = a.selectionEnd; } catch (x) { }
  const r = fn();
  if (id) { const n = $(id); if (n && n !== document.activeElement) { n.focus({ preventScroll: true }); try { if (s != null) n.setSelectionRange(s, e); } catch (x) { } } }
