// ── Jump-to links: click an entry / bill / head anywhere to open it ──────
const lk = (on, text, title) => `<a href="#" class="lk"${title ? ` title="${esc(title)}"` : ''} onclick="${on};return false">${text}</a>`;
function closeModals() { document.querySelectorAll('#modals .ov').forEach(o => o.remove()); MODAL_DEPTH = 0; }
function openVch(vid) { const v = S.vch[vid]; if (!v) return toast('Entry not found (it may have been deleted)', 'warn'); closeModals();
  if (canEdit() && !S.fy.closed && !v.rev && /^[RPCJ]$/.test(v.t)) return editVoucher(vid); printVoucher(vid); }
function openBill(bid) { const b = S.bills[bid]; if (!b) return toast('Bill not found (it may have been deleted)', 'warn'); closeModals(); go('bills', b.run); setTimeout(() => billView(bid), 80); }
