  $('tbPresence').innerHTML = S.sid && others.length ? `<span class="dot on"></span> Also here: ${others.map(([, p]) => `<b title="on ${esc(p.p || '')}">${esc(p.n || 'user')}</b>`).join(', ')}` : '';
