window.addEventListener('fbsdk', boot);
function boot() {
  applyTheme();
  try { FBX.init(); } catch (e) { document.body.innerHTML = `<div class="pc"><div class="alert a-err">Firebase failed to start: ${esc(e.message)}</div></div>`; return; }
  const q = new URLSearchParams(location.search);
  if (q.get('l')) return showPublicLedger(q.get('l'));
  FBX.connected(on => { S.online = on; const c = $('tbConn'); if (c) c.innerHTML = `<span class="dot ${on ? 'on' : 'off'}"></span><span>${on ? 'Live' : 'Offline – will sync'}</span>`; });
  if (FBX.isLink && FBX.isLink(location.href)) { linkComplete(); return FBX.onAuth(u => { if (u) afterLogin(u); }); }
  FBX.onAuth(u => { if (u) afterLogin(u); else showAuth(); });
}

