// ── Open a society: live listeners ───────────────────────────────────────
function closeSociety() {
  try { socPark(); } catch (e) { }
  try { if (S.sid && S.fy && S.loaded && S.loaded.vch === true && canEdit()) pushSummaryNow(); } catch (e) { } // save the latest summary before leaving
  SUBS.soc.forEach(u => { try { u && u(); } catch (e) { } }); SUBS.fy.forEach(u => { try { u && u(); } catch (e) { } });
  SUBS.soc = []; SUBS.fy = [];
  if (S.sid && S.user) FBX.remove(sp('presence/' + S.user.uid)).catch(() => { });
  Object.assign(S, { sid: null, role: null, meta: {}, heads: {}, members: {}, bcfg: {}, pending: {}, fys: {}, fyId: null, fy: null, ob: { heads: {}, members: {} }, vch: {}, bills: {}, runs: {}, inv: {}, fa: {}, mtg: {}, ntc: {}, cmp: {}, shr: {}, brs: {}, presence: {}, summary: {}, loaded: {} });
  S.ver++;
}
function waitFor(cond, ms = 20000) { return new Promise((res, rej) => { const t0 = Date.now(); const tick = () => { if (cond()) return res(); if (Date.now() - t0 > ms) return rej(new Error('Timed out loading data. Check your internet connection or database rules.')); setTimeout(tick, 60); }; tick(); }); }
async function openSociety(sid) {
  closeSociety(); SUBS.firm.forEach(u => u && u()); SUBS.firm = [];
  S.sid = sid; LS.set('sb_last_' + S.user.uid, sid);
  buildSide(); $('main').innerHTML = loading('Opening society…');
  const sub = (path, key, after) => SUBS.soc.push(FBX.listen(sp(path), (v, err) => {
    if (err) { S.loaded[key] = 'err'; S.loadErr = err.message; return; }
    S[key] = v || {}; S.loaded[key] = true; if (after) after(v); if (key !== 'presence') dataChanged(); // who-is-online only updates the top bar
  }));
  sub('meta', 'meta', v => { S.role = (((v || {}).access || {})[S.user.uid] || {}).r || null; updateTopbar(); });
  sub('fys', 'fys', () => chooseFY());
  ['heads', 'members', 'bcfg', 'pending', 'summary', 'inv', 'fa', 'mtg', 'ntc', 'cmp', 'shr'].forEach(k => sub(k, k));
  sub('presence', 'presence', () => updateTopbar());
  try {
    await waitFor(() => ['meta', 'fys', 'heads', 'members'].every(k => S.loaded[k]));
    if (['meta', 'fys', 'heads', 'members'].some(k => S.loaded[k] === 'err') || !S.role) throw new Error('You do not have access to this society.');
    await waitFor(() => S.fyId && ['ob', 'vch', 'bills', 'runs'].every(k => S.loaded[k]));
  } catch (e) { $('main').innerHTML = `<div class="pc"><div class="alert a-err">${esc(e.message)}</div><button onclick="goFirm()">← Back</button></div>`; return; }
  FBX.onDisconnectRemove(sp('presence/' + S.user.uid)); setPresence();
  if (canEdit()) ensureSystemHeads().catch(e => console.warn(e));
  updateTopbar(); const lp = contPage(); go(lp.p, lp.a);
}
function chooseFY() {
  const fys = S.fys || {}; const keys = Object.keys(fys).sort();
  if (!keys.length) { S.fyId = null; S.fy = null; return; }
  let id = S.fyId && fys[S.fyId] ? S.fyId : null;
  if (!id) { const pref = LS.get('sb_fy_' + S.sid, ''); if (fys[pref]) id = pref; }
  if (!id) { const t = today(); id = keys.find(k => fys[k].start <= t && fys[k].end >= t) || keys[keys.length - 1]; }
  S.fy = { id, ...fys[id] };
  if (id !== S.fyId) subscribeFY(id);
  updateTopbar();
}
function subscribeFY(id) {
  SUBS.fy.forEach(u => { try { u && u(); } catch (e) { } }); SUBS.fy = [];
  S.fyId = id; LS.set('sb_fy_' + S.sid, id);
  ['ob', 'vch', 'bills', 'runs', 'brs'].forEach(k => { S.loaded[k] = false; });
  S.vch = {}; S.bills = {}; S.runs = {}; S.ob = { heads: {}, members: {} }; S.brs = {};
  const sub = (path, key, fix) => SUBS.fy.push(FBX.listen(sp(path + '/' + id), (v, err) => { if (err) { S.loaded[key] = 'err'; return; } S[key] = fix ? fix(v) : (v || {}); S.loaded[key] = true; dataChanged(); }));
  sub('ob', 'ob', v => ({ heads: (v || {}).heads || {}, members: (v || {}).members || {}, py: (v || {}).py || {} }));
  sub('vch', 'vch'); sub('bills', 'bills'); sub('runs', 'runs'); sub('brs', 'brs');
}
function pickFY() {
  const keys = Object.keys(S.fys || {}).sort().reverse();
  openModal({
    title: 'Financial Year', hideOk: true, body: keys.map(k => { const f = S.fys[k]; return `<div class="row" style="justify-content:space-between;padding:8px 0;border-bottom:1px solid var(--border)"><div><b>FY ${esc(f.label)}</b> <span class="small muted">${fd(f.start)} – ${fd(f.end)}</span> ${f.closed ? '<span class="tag t-grey">closed</span>' : ''} ${f.lock ? `<span class="tag t-warn">locked to ${fd(f.lock)}</span>` : ''}</div>${k === S.fyId ? '<span class="tag t-ok">current</span>' : `<button class="sm" onclick="switchFY('${k}')">Open</button>`}</div>`; }).join('') + `<p class="small muted" style="margin-top:12px">Create the next year or close a year from <b>Administration → Year-End & Locks</b>.</p>`
  });
}
function switchFY(id) { $$('.ov').forEach(o => o.remove()); MODAL_DEPTH = 0; S.fy = { id, ...S.fys[id] }; subscribeFY(id); updateTopbar(); waitFor(() => ['ob', 'vch', 'bills', 'runs'].every(k => S.loaded[k])).then(() => go(CUR.id || 'dash')); }

async function ensureSystemHeads() {
  const have = new Set(Object.values(S.heads).map(h => h && h.tag).filter(Boolean));
  const up = {}; let n = 0;
  for (const [tag] of Object.entries(SYS_TAGS)) {
    if (have.has(tag)) continue;
    const d = DEFAULT_HEADS.find(x => x[5] === tag); if (!d) continue;
    const exist = Object.entries(S.heads).find(([, h]) => h && h.name === d[3]);
    if (exist) { up[`heads/${exist[0]}/tag`] = tag; } else up[`heads/${FBX.key('x')}`] = headRec(d);
    n++;
  }
  let m = 0; for (const [id, h] of Object.entries(S.heads)) if (h && h.grp === 'Expenses' && h.sub === 'Utilities') { up[`heads/${id}/sub`] = 'Service Charges'; m++; } // sub-group renamed
  if (n || m) await commit(up, { a: 'system', e: 'heads', s: [n && `Added ${n} required system head(s)`, m && `${m} head(s) moved from Utilities to Service Charges`].filter(Boolean).join('; ') });
}

// ── Public read-only member ledger (shared link) ────────────────────────
