function headByName(name) { const n = String(name || '').trim().toLowerCase(); if (!n) return ''; const e = Object.entries(S.heads).filter(([, h]) => h); const hit = e.find(([, h]) => h.name.toLowerCase() === n) || e.find(([, h]) => `${h.name} (${h.grp})`.toLowerCase() === n) || e.find(([, h]) => String(h.code || '').toLowerCase() === n); return hit ? hit[0] : ''; }
