  const m = mid ? M(mid) : null; $('bk' + i).dataset.mid = mid || '';
  $('bk-n' + i).innerHTML = m ? esc(m.name) : (k ? '<span class="dr">not found</span>' : '');
  const r = mid ? MB()[mid] : null; $('bk-o' + i).innerHTML = r ? (r.bal > 0 ? `<span class="dr">${fmt(r.bal)}</span>` : r.bal < 0 ? `<span class="cr">adv ${fmt(-r.bal)}</span>` : '0') : '';
