    shell('👥 Members', 'Flats, shops and their owners', `${canEdit() ? `<button onclick="memberModal()">+ Add Member</button><button class="ghost" onclick="importMembers()">📥 Import</button>` : ''}<button class="ghost" onclick="memberTemplate()">⬇ Template</button><button class="ghost" onclick="exportMembers()">📤 Excel</button>`,
      `<div class="toolbar"><input id="mb-q" placeholder="Search flat, name, phone…" value="${esc(LS.get('sb_mq', ''))}" type="search" oninput="LS.set('sb_mq',this.value);keepFocus(()=>PAGES.members.refresh())" style="min-width:260px"><label class="row small"><input type="checkbox" id="mb-in" onchange="PAGES.members.refresh()"> show inactive</label><span id="mb-c" class="small muted"></span></div><div id="mb-res"></div>`);
