  const isNew = !tok; if (!tok) tok = rid(22);
  await FBX.update({ [`publicLedgers/${tok}`]: snap, [sp(`members/${mid}/tok`)]: tok });
  const url = location.origin + location.pathname + '?l=' + tok;
