const waNum = p => { const d = String(p || '').replace(/\D/g, ''); return d.length === 10 ? '91' + d : d; };
function waStatement(mid) { const m = M(mid), r = MB()[mid] || { bal: 0 }; const t = `Dear ${m.name} (${flatLbl(m)}), your ${r.bal >= 0 ? 'outstanding dues' : 'advance'} with ${S.meta.name} as on ${fd(today())} is ₹${fmt(Math.abs(r.bal))}.${SET().bill.upi && r.bal > 0 ? ` Pay by UPI: upi://pay?pa=${SET().bill.upi}&pn=${encodeURIComponent(S.meta.name)}&am=${r2(r.bal)}&cu=INR` : ''}`; window.open(`https://wa.me/${waNum(m.phone)}?text=${encodeURIComponent(t)}`, '_blank'); }

