function bcImport() {
  pickFile('.xlsx,.xls,.csv', async f => {
    try {
      const rows = await readSheet(f); const bh = billHeads(); const up = {}; let n = 0; const miss = [], unknownCols = [];
      const nk = s => String(s).toLowerCase().replace(/[^a-z0-9]/g, '');
      const byName = {}; bh.forEach(([id, h]) => byName[nk(h.name)] = id); Object.entries(S.heads).forEach(([id, h]) => { if (h && h.bill && h.bill.on && !byName[nk(h.name)]) byName[nk(h.name)] = id; });
      const idx = {}; for (const [id, m] of Object.entries(S.members)) if (m) idx[nk(m.wing || '') + '|' + nk(m.flat)] = id; const fi = flatIndex();
      const skip = new Set(['wing', 'flat', 'flatno', 'name', 'member', 'total', 'unit']);
      if (rows.length) for (const k of Object.keys(rows[0])) if (!byName[nk(k)] && !skip.has(nk(k)) && !/^__empty/i.test(k)) unknownCols.push(k);
      for (const r of rows) {
        const keys = Object.keys(r); const g = n2 => { const k = keys.find(k => nk(k) === n2); return k ? String(r[k] == null ? '' : r[k]).trim() : ''; };
        const fl = g('flat') || g('flatno') || g('unit'); if (!fl && !g('name')) continue;
        const mid = idx[nk(g('wing')) + '|' + nk(fl)] || fi[String(fl).toLowerCase().replace(/\s+/g, '')] || fi[(g('wing') + '-' + fl).toLowerCase().replace(/\s+/g, '')];
        if (!mid) { miss.push([g('wing'), fl].filter(Boolean).join('-')); continue; }
        for (const k of keys) { const hid = byName[nk(k)]; if (!hid) continue; const v = r2(numv(r[k])); const old = +((S.bcfg[mid] || {})[hid] || 0); if (v !== old) { up[`bcfg/${mid}/${hid}`] = v || null; n++; } }
      }
      if (!n) return toast(miss.length ? `Nothing changed. Flats not found: ${miss.slice(0, 5).join(', ')}` : unknownCols.length ? `Nothing changed. Columns not matching any billing head: ${unknownCols.slice(0, 4).join(', ')}` : 'Nothing changed — the amounts in the file are the same as now.', 'warn', 8000);
      if (!(await confirmBox(`Change ${n} amount(s)?${miss.length ? `\n\nFlats not found (skipped): ${miss.slice(0, 8).join(', ')}${miss.length > 8 ? '…' : ''}` : ''}${unknownCols.length ? `\n\nColumns ignored (not a billing head): ${unknownCols.slice(0, 6).join(', ')}` : ''}`))) return;
      await commit(up, { a: 'import', e: 'Billing setup', s: `${n} amounts imported` }); $$('.bgrid input').forEach(i => delete i.dataset.dirty); render(); toast(`Imported — ${n} amount(s) changed`);
    } catch (e) { toast(e.message, 'err'); }
  });
}
