  const row = $('blr-' + bid); if (row) { try { row.scrollIntoView({ block: 'center', behavior: 'smooth' }); } catch (e) { } row.classList.add('flash'); setTimeout(() => row.classList.remove('flash'), 2500); }
  openModal({ title: `🧾 ${esc(b.no)} — ${esc(memLbl(m))}`, xwide: true, hideOk: true, cancel: 'Close',
    body: `<div class="row" style="margin-bottom:8px;flex-wrap:wrap"><button class="sm" onclick="printBills(['${bid}'])">🖨 Print / PDF</button>${canEdit() ? `<button class="sm ghost" onclick="closeModals();editBill('${bid}')">✏ Edit</button><button class="sm ghost" onclick="closeModals();hnModal('${b.run}','${bid}')">📝 Particulars</button>` : ''}${m.phone ? `<button class="sm ghost" onclick="waBill('${bid}')">💬 WhatsApp</button>` : ''}<button class="sm ghost" onclick="waPdf('bill','${bid}')">💬 WhatsApp with PDF</button>${m.email && MAILER.on() ? `<button class="sm ghost" onclick="mailBills(['${bid}'])">📧 Email</button>` : ''}<button class="sm ghost" onclick="openMember('${b.mid}')">👤 Member ledger</button><button class="sm ghost" onclick="closeModals();go('bills','${b.run}')">All bills of this month</button></div>
      <iframe id="bv-f" style="width:100%;height:68vh;border:1px solid var(--border);border-radius:8px;background:#fff"></iframe>`,
    onOpen: () => loadPrevFY().then(() => { const f = $('bv-f'); if (f) f.srcdoc = `<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">${EMOJI_HEAD()}<style>${PRINT_CSS}.np{display:none!important}body{padding:10px}</style></head><body>${TPL_CSS()}${billDocHtml(bid)}</body></html>`; }) });
