const billMeta = P => { const { b, m } = P; return { who: `<b style="font-size:13px">${esc(m.name || '')}</b>${m.name2 ? `<br><span class="small">${esc(m.name2)}</span>` : ''}<br>${T('flat')}: <b>${esc(pn(flatLbl(m)))}</b>${m.area ? ` · ${T('area')}: ${pn(m.area)} sq.ft` : ''}`,
  ref: `${T('billNo')}: <b>${esc(pn(b.no))}</b><br>${T('billDate')}: <b>${pn(fd(b.d))}</b>${b.due ? `<br>${T('due')}: <b>${pn(fd(b.due))}</b>` : ''}<br>${P.period}` }; };
const chargeRows = P => P.rows.map(x => `<tr><td>${esc(x.l)}</td>${amtTd(x)}</tr>`).join('') + P.notes.map(n => `<tr><td class="small muted" colspan="2">↳ ${esc(n)}</td></tr>`).join('');
const payBlock = P => { const { st, upi } = P; return `${st.bankAc ? `<p class="small" style="margin-top:4px"><b>${T('bank')}:</b> ${esc([st.bankName, 'A/c ' + st.bankAc, st.bankIfsc && 'IFSC ' + st.bankIfsc, st.bankBranch].filter(Boolean).join(' · '))}${st.upi ? ' · UPI ' + esc(st.upi) : ''}</p>` : ''}${st.notes ? `<div class="small" style="margin-top:4px;white-space:pre-line"><b>${T('notes')}:</b>\n${esc(st.notes)}</div>` : ''}`; };
const qrBox = (P, w = 110) => (P.upi && P.st.qr ? `<div class="center small qrb" style="width:${w}px;flex:0 0 ${w}px">${qrImg(P.upi)}<div>${T('pay')}</div></div>` : '');
const totalLine = P => `<tr class="tot"><td>${P.pay < 0 ? T('advCf') : T('total')}</td><td class="n" style="font-size:13px">₹ ${pn(fmt(Math.abs(P.pay)))}</td></tr>`;
const arrRows = P => P.arr.map(x => `<tr><td>${esc(x.l)}</td>${amtTd(x)}</tr>`).join('');
// Previous balance → payments → carried forward → this bill → total (statement & ledger templates)
function stmtFigures(P) { const rc = receiptsSincePrev(P.b); const paid = r2(sum(rc, r => (r.bnc ? 0 : r.amt)));
  const cf = r2(P.pay - P.cur); return { paid, cf, prev: r2(cf + paid) }; }

