  const lab = { v: r.label, ind: r.k === 's' ? 2 : 0, b: r.k === 'gt' || r.k === 'tt' }; const amt = { v: r.amt == null || (r.zero === false && !r.amt) ? null : n(r.amt), b: r.k === 'gt' || r.k === 'tt', top: r.k === 'gt', dbl: r.k === 'tt' };
  const pv = { v: r.pv == null || (r.k !== 'tt' && !r.pv) ? null : n(r.pv), b: r.k === 'tt', dbl: r.k === 'tt', color: 'FF555555' };
