async function mdbLibLoad() { if (window.MDBReader || $('mdb-lib')) return; say_(); await loadScript('mdb.' + APP_BUILD + '.js').catch(() => { throw new Error('Could not load the MAXX reader. Check the internet connection and try again.'); });
  if (window.MDBReader) return; throw new Error('The MAXX reader did not start.'); function say_() { const e = $('mxp'); if (e) e.innerHTML = loading('Loading the MAXX reader…'); } }
