  return txt.replace(/&#(x0*[0-8bcef]|x0*1[0-9a-f]|0*[0-8]|0*1[1-2]|0*1[4-9]|0*2[0-9]|0*3[01]);/gi, '').replace(/[\x00-\x08\x0B\x0C\x0E-\x1F]/g, '');
