    if (chq) { rec.mode = /cheque|chq/i.test(chq.mode) ? 'Cheque' : /neft/i.test(chq.mode) ? 'NEFT' : /rtgs/i.test(chq.mode) ? 'RTGS' : /upi/i.test(chq.mode) ? 'UPI' : /imps/i.test(chq.mode) ? 'IMPS' : chq.mode || ''; if (chq.no) rec.chq = Object.fromEntries(Object.entries({ no: chq.no, d: chq.d }).filter(([, x]) => x)); }
    if (!rec.mode && (t === 'R' || t === 'P')) rec.mode = (heads[cb.h] || S.heads[cb.h] || {}).type === 'cash' ? 'Cash' : 'Cheque';
