// ── Head-wise arrears (item 10) ─────────────────────────────────────────
function arrHeadData() {
  const cols = new Map(); const rows = []; const add = (o, k, v) => { if (Math.abs(v) < 0.005) return; o[k] = r2((o[k] || 0) + v); };
  for (const [mid, m] of memSorted(true)) {
    const f = FF(mid); if (!f.open.length) continue; const o = {};
    for (const it of f.open) {
      if (it.ref === 'OB') { add(o, '_ob', it.bal); continue; } const b = S.bills[it.ref];
      if (!b) { add(o, '_oth', it.bal); continue; } const parts = Object.entries(b.ch || {}).map(([h, a]) => [h, +a || 0]); if (b.int) parts.push(['_int', +b.int]); if (b.gst) parts.push(['_gst', r2((+b.gst.c || 0) + (+b.gst.s || 0))]);
      const tot = sum(parts, x => x[1]); if (!(tot > 0)) { add(o, '_oth', it.bal); continue; } let left = it.bal;
      parts.forEach(([h, a], i) => { const v = i === parts.length - 1 ? left : r2(it.bal * a / tot); left = r2(left - v); add(o, h, v); if (h[0] !== '_') cols.set(h, 1); });
    }
    rows.push({ mid, m, o, t: r2(sum(Object.values(o))) });
  }
  const hs = [...cols.keys()].sort((a, b) => ((H(a).bill || {}).order || 99) - ((H(b).bill || {}).order || 99) || H(a).name.localeCompare(H(b).name));
  const C = [...hs.map(h => [h, H(h).name]), ['_int', 'Interest'], ['_gst', 'GST'], ['_ob', 'Opening arrears'], ['_oth', 'Other debits']].filter(([k]) => rows.some(r => r.o[k]));
  return { C, rows };
}
page('arrhead', {
  render() {
    const { C, rows } = arrHeadData(); const w = RP.get('ah_w', ''); const wings = [...new Set(rows.map(r => r.m.wing || ''))].filter(Boolean).sort(); const R = rows.filter(r => !w || (r.m.wing || '') === w);
    shell('📊 Head-wise Arrears', 'Each member\'s unpaid amount split by the heads of the unpaid bills (oldest bills are treated as paid first)', `<button class="ghost" onclick="arrHeadOut('x')">📥 Excel</button><button class="ghost" onclick="arrHeadOut('p')">🖨 Print</button>`,
      `${wings.length ? `<div class="toolbar"><label style="margin:0">Wing</label><select onchange="RP.set('ah_w',this.value);render()"><option value="">All</option>${wings.map(x => `<option ${x === w ? 'selected' : ''}>${esc(x)}</option>`).join('')}</select></div>` : ''}
      <div class="tw tall"><table><thead><tr><th>Flat</th><th>Member</th>${C.map(([, l]) => `<th class="n">${esc(l)}</th>`).join('')}<th class="n">Total</th></tr></thead><tbody>
      ${R.map(r => `<tr><td class="b">${lk(`openMember('${r.mid}')`, esc(flatLbl(r.m)))}</td><td class="small">${esc(r.m.name)}</td>${C.map(([k]) => `<td class="n">${r.o[k] ? fmt(r.o[k]) : ''}</td>`).join('')}<td class="n b">${fmt(r.t)}</td></tr>`).join('') || `<tr><td colspan="${C.length + 3}" class="empty">No arrears 🎉</td></tr>`}
      <tr class="tot"><td colspan="2">Total (${R.length})</td>${C.map(([k]) => `<td class="n">${fmt(sum(R, r => r.o[k] || 0))}</td>`).join('')}<td class="n">${fmt(sum(R, r => r.t))}</td></tr></tbody></table></div>`);
  }
});
function arrHeadOut(k) {
  const { C, rows } = arrHeadData(); const w = RP.get('ah_w', ''); const R = rows.filter(r => !w || (r.m.wing || '') === w); const head = ['Flat', 'Member', ...C.map(c => c[1]), 'Total'];
  const body = R.map(r => [flatLbl(r.m), r.m.name, ...C.map(([c]) => r.o[c] || 0), r.t]); const tot = ['Total', '', ...C.map(([c]) => r2(sum(R, r => r.o[c] || 0))), r2(sum(R, r => r.t))];
  if (k === 'x') return xlsx(`HeadwiseArrears_${S.fy.label}`, [{ name: 'Head-wise arrears', rows: [head, ...body, tot], cols: [10, 28, ...C.map(() => 14), 14] }]);
  printReport('Head-wise Arrears', `As on ${fd(today())}${w ? ' · Wing ' + w : ''}`, `<table><thead><tr>${head.map((h, i) => `<th class="${i > 1 ? 'n' : ''}">${esc(h)}</th>`).join('')}</tr></thead><tbody>${body.map(r => `<tr>${r.map((c, i) => `<td class="${i > 1 ? 'n' : ''}">${i > 1 ? (c ? fmt(c) : '') : esc(c)}</td>`).join('')}</tr>`).join('')}<tr class="tot">${tot.map((c, i) => `<td class="${i > 1 ? 'n' : ''}">${i > 1 ? fmt(c) : esc(c)}</td>`).join('')}</tr></tbody></table>`);
}

