function wordsHI(n) {
  n = Math.round(Math.abs(+n || 0)); if (!n) return 'शून्य रुपये मात्र';
  const p = []; const cr = Math.floor(n / 1e7); n %= 1e7; const lk = Math.floor(n / 1e5); n %= 1e5; const th = Math.floor(n / 1e3); n %= 1e3; const hu = Math.floor(n / 100); n %= 100;
  if (cr) p.push((cr < 100 ? HI1[cr] : wordsHI(cr).replace(' रुपये मात्र', '')) + ' करोड़'); if (lk) p.push(HI1[lk] + ' लाख'); if (th) p.push(HI1[th] + ' हज़ार'); if (hu) p.push(HI1[hu] + ' सौ'); if (n) p.push(HI1[n]);
  return p.join(' ') + ' रुपये मात्र';
}
