// ── Receipt allocation (item 18) ────────────────────────────────────────
function rcAlBox(mid) {
  let el = $('vf-alw'); const info = $('vf-info'); if (!info) return;
  if (!mid || VF.t !== 'R') { if (el) el.remove(); return; }
  if (!el) { info.insertAdjacentHTML('afterend', '<div id="vf-alw" style="margin-top:8px"></div>'); el = $('vf-alw'); }
  let cur = el.dataset.v || '', ci = '', cp = '';
  if (VF.edit && !el.dataset.done) { const v = S.vch[VF.edit]; const ml = v ? vLines(v).filter(l => l.m && l.cr) : []; if (ml.length > 1) { cur = 'S'; ci = sum(ml.filter(l => l.al === 'I'), l => l.cr) || ''; cp = sum(ml.filter(l => l.al === 'P'), l => l.cr) || ''; } else if (ml[0] && ml[0].al) cur = ml[0].al; el.dataset.done = 1; }
  el.innerHTML = `<div class="row small" style="gap:6px;flex-wrap:wrap"><label style="margin:0">Apply this receipt to</label><select id="vf-al" style="width:auto" onchange="$('vf-als').style.display=this.value==='S'?'':'none'">${[['', 'Auto — interest first, then principal'], ['P', 'Principal only'], ['I', 'Interest only'], ['N', 'Non-interest charges only'], ['S', 'Split by amount…']].map(([k, l]) => `<option value="${k}" ${k === cur ? 'selected' : ''}>${l}</option>`).join('')}</select>
    <span id="vf-als" style="${cur === 'S' ? '' : 'display:none'}">Interest ₹ <input id="vf-ali" class="num" type="number" step="0.01" value="${ci}" style="width:100px;min-width:0"> Principal ₹ <input id="vf-alp" class="num" type="number" step="0.01" value="${cp}" style="width:100px;min-width:0"> <span class="muted">(rest: auto)</span></span></div>`;
}
(() => { const o = vfAccChanged; window.vfAccChanged = vfAccChanged = function (v) { const r = o.apply(this, arguments); try { rcAlBox(v && v.startsWith('M:') ? v.slice(2) : ''); } catch (e) { console.warn(e); } return r; }; })();
function rcAlApply(v) {
  const sel = $('vf-al'); if (!sel || !sel.value || v.t !== 'R') return; const I = IDS(); const i = v.lines.findIndex(l => l.h === I.dues && l.m && l.cr); if (i < 0) return; const l = v.lines[i];
  if (sel.value !== 'S') { v.lines[i] = { ...l, al: sel.value }; return; }
  const a = r2(nval('vf-ali')), p = r2(nval('vf-alp')); if (a < 0 || p < 0) throw new Error('Split amounts cannot be negative'); if (a + p > l.cr + 0.004) throw new Error(`Interest ₹${fmt(a)} + principal ₹${fmt(p)} is more than the receipt ₹${fmt(l.cr)}`);
  const rest = r2(l.cr - a - p); const nl = []; if (a) nl.push({ h: l.h, m: l.m, cr: a, al: 'I' }); if (p) nl.push({ h: l.h, m: l.m, cr: p, al: 'P' }); if (rest) nl.push({ h: l.h, m: l.m, cr: rest }); v.lines.splice(i, 1, ...nl);
}

// ── UTR / cheque number checks (item 24) + allocation, wrapped around saving ──
const UTR_RX = { NEFT: [/^[A-Z0-9]{16}$/, '16 letters/digits'], RTGS: [/^[A-Z0-9]{22}$/, '22 letters/digits'], IMPS: [/^\d{12}$/, '12 digits'], UPI: [/^\d{12}$/, '12 digits'] };
function utrIssues(v, exceptId) {
  const ref = String((v.chq && v.chq.no) || v.ref || '').trim().toUpperCase().replace(/\s+/g, ''); const out = []; if (!ref || !(v.t === 'R' || v.t === 'P')) return out;
  const rx = UTR_RX[v.mode]; if (rx && !rx[0].test(ref)) out.push(`${v.mode} reference "${ref}" does not look like a ${v.mode} UTR (usually ${rx[1]}).`);
  if (v.mode === 'Cheque' && !/^\d{6}$/.test(ref)) out.push(`Cheque number "${ref}" is not 6 digits.`);
  if (ref.length >= 5) { const ml = (v.lines || []).filter(l => l.m).map(l => l.m); const bank = String((v.chq && v.chq.bank) || '').trim().toLowerCase();
    const dup = Object.entries(S.vch).find(([id, x]) => { if (!x || id === exceptId || x.t !== v.t || x.bnc || x.rev) return false; const r2_ = String((x.chq && x.chq.no) || x.ref || '').trim().toUpperCase().replace(/\s+/g, ''); if (r2_ !== ref) return false;
      if (/cheque|demand/i.test(v.mode || '')) { const xb = String((x.chq && x.chq.bank) || '').trim().toLowerCase(); return (bank && xb && bank === xb) || vLines(x).some(l => l.m && ml.includes(l.m)); } return true; });
    if (dup) out.push(`${/cheque|demand/i.test(v.mode || '') ? 'Cheque' : 'Reference / UTR'} "${ref}" is already used in ${dup[1].no} (${fd(dup[1].d)}, ${vParticulars(dup[1])}, ₹${fmt(vAmount(dup[1]))}).`); }
  return out;
}
(() => { const o = saveVoucher; window.saveVoucher = saveVoucher = async function (v, opt = {}) {
  if (CUR.id === 'receipt' && v && v.t === 'R' && !opt.noDup) rcAlApply(v);
  if (!opt.noDup && v && ['receipt', 'payment'].includes(CUR.id)) { const iss = utrIssues(v, opt.editId); if (iss.length && !(await confirmBox(iss.join('\n\n') + '\n\nSave anyway?', { title: '⚠ Please check the reference', ok: 'Save anyway' }))) return null; }
  return o(v, opt);
}; })();

// ── One receipt for several flats of the same member (item 25) ──────────
const nmKey = s => String(s || '').toLowerCase().replace(/\b(mr|mrs|ms|shri|smt|dr|m\/s)\.?\s+/g, '').replace(/[^a-z0-9]/g, '');
function mfModal(mid) {
  try { guardEdit(); } catch (e) { return toast(e.message, 'err'); }
  openModal({ title: '🏢 One receipt for several flats', xwide: true, ok: '💾 Save receipt', body: `<div data-form><div class="fr c3"><div><label>Member (any one flat) *</label>${accPicker('mf-m', memberOptions(''), { value: mid || '', ph: 'Flat no. or name', onchange: 'mfPick' })}</div><div><label>Date *</label><input type="date" id="mf-d" value="${today() > S.fy.end ? S.fy.end : today()}" min="${S.fy.start}" max="${S.fy.end}"></div><div><label>Received in *</label>${accPicker('mf-cb', cbOptions(), { value: (cbOptions()[0] || {}).v || '', ph: 'Cash / Bank' })}</div></div>
    <div id="mf-list" class="small muted">Pick a member — their other flats (same name or mobile) are listed here.</div>
    <div class="fr c4" style="margin-top:8px"><div><label>Total amount ₹ *</label><input id="mf-a" class="num" type="number" step="0.01" oninput="mfSplit()"></div><div><label>Mode</label><select id="mf-mode">${MODES.map(x => `<option>${x}</option>`).join('')}</select></div><div><label>Cheque / UTR No.</label><input id="mf-chq"></div><div><label>Cheque date / bank</label><div class="row"><input id="mf-chqd" type="date"><input id="mf-chqb" placeholder="Bank"></div></div></div>
    <div class="fr"><div><label>Narration</label><input id="mf-nar"></div></div></div>`,
    onOpen: () => { if (mid) mfPick(mid); }, onOk: () => mfSave() });
}
function mfPick(mid) {
  const m = M(mid); const box = $('mf-list'); if (!m || !box) return; const k = nmKey(m.name), ph = String(m.phone || '').replace(/\D/g, '').slice(-10);
  const all = memSorted(false); const same = all.filter(([id, x]) => id === mid || (k && nmKey(x.name) === k) || (ph.length === 10 && String(x.phone || '').replace(/\D/g, '').slice(-10) === ph)).map(([id]) => id); const MB_ = MB();
  box.innerHTML = `<div class="toolbar" style="margin:6px 0"><b>Flats in this receipt</b><label class="row small" style="margin:0 0 0 auto"><input type="checkbox" onchange="$$('#mf-t tr[data-o]').forEach(r=>r.style.display=this.checked?'':'none')"> show all flats</label></div>
    <div class="tw" style="max-height:36vh"><table id="mf-t"><thead><tr><th></th><th>Flat</th><th>Member</th><th class="n">Outstanding</th><th class="n">Amount ₹</th></tr></thead><tbody>${[...same.map(id => [id, M(id)]), ...all.filter(([id]) => !same.includes(id))].map(([id, x]) => { const s = same.includes(id); const bal = (MB_[id] || {}).bal || 0; return `<tr data-m="${id}" ${s ? '' : 'data-o style="display:none"'}><td><input type="checkbox" class="mf-cb" ${s ? 'checked' : ''} onchange="mfSplit()"></td><td class="b">${esc(flatLbl(x))}</td><td class="small">${esc(x.name)}</td><td class="n">${bal > 0 ? fmt(bal) : bal < 0 ? fmt(-bal) + ' adv' : 'Nil'}</td><td><input class="num mf-a" type="number" step="0.01" data-bal="${r2(Math.max(0, bal))}" oninput="this.dataset.t=1;mfTot()" style="width:120px;min-width:0"></td></tr>`; }).join('')}</tbody></table></div><div id="mf-tot" class="small" style="margin-top:4px"></div>`;
  if (!val('mf-a')) $('mf-a').value = r2(sum(same, id => Math.max(0, (MB_[id] || {}).bal || 0))) || ''; if (!val('mf-nar')) $('mf-nar').value = `Received from ${m.name}`; mfSplit();
}
function mfSplit() { const rows = $$('#mf-t tr[data-m]').filter(r => r.querySelector('.mf-cb').checked); $$('#mf-t .mf-a').forEach(i => { if (!i.closest('tr').querySelector('.mf-cb').checked) { i.value = ''; delete i.dataset.t; } }); let left = r2(nval('mf-a'));
  rows.forEach(r => { const i = r.querySelector('.mf-a'); delete i.dataset.t; const a = Math.min(left, +i.dataset.bal || 0); i.value = a > 0 ? r2(a) : ''; left = r2(left - Math.max(0, a)); });
  if (left > 0 && rows.length) { const i = rows[0].querySelector('.mf-a'); i.value = r2(numv(i.value) + left); } mfTot(); }
function mfTot() { const t = r2(sum($$('#mf-t .mf-a'), i => numv(i.value))); const e = $('mf-tot'); if (e) e.innerHTML = `Split total ₹${fmt(t)}${Math.abs(t - nval('mf-a')) > 0.004 ? ` <span class="dr">— does not match the total ₹${fmt(nval('mf-a'))}</span>` : ' ✓'}`; }
async function mfSave() {
  const d = val('mf-d'), cb = val('mf-cb'), amt = r2(nval('mf-a')); if (!cb) throw new Error('Select cash / bank'); if (!(amt > 0)) throw new Error('Enter the amount');
  const parts = $$('#mf-t tr[data-m]').map(r => ({ mid: r.dataset.m, a: r2(numv(r.querySelector('.mf-a').value)) })).filter(x => x.a > 0);
  if (parts.length < 1) throw new Error('Enter the amount for at least one flat'); if (Math.abs(sum(parts, x => x.a) - amt) > 0.004) throw new Error('Flat-wise amounts must add up to the total');
  const I = IDS(); const v = { t: 'R', d, mode: val('mf-mode'), nar: val('mf-nar'), ref: val('mf-chq'), mf: parts.length > 1 || null, lines: [{ h: cb, dr: amt }, ...parts.map(x => ({ h: I.dues, m: x.mid, cr: x.a }))] };
  const chq = { no: val('mf-chq'), d: val('mf-chqd'), bank: val('mf-chqb') }; if (chq.no || chq.d || chq.bank) v.chq = chq;
  const iss = utrIssues(v); if (iss.length && !(await confirmBox(iss.join('\n\n') + '\n\nSave anyway?', { title: '⚠ Please check the reference', ok: 'Save anyway' }))) return false;
  const r = await saveVoucher(v, { noDup: true }); if (!r) return false; toast(`✓ ${r.rec.no} saved for ${parts.length} flat(s)`);
  setTimeout(() => { closeAllModals(); if (CUR.id === 'receipt') render(); confirmBox('Print the receipt now?', { ok: '🖨 Print' }).then(y => y && printVoucher(r.vid)); }, 200);
}
addAct('receipt', () => canEdit() ? `<button class="ghost" onclick="mfModal()">🏢 Multi-flat receipt</button>` : '');
