function nmModal(k) { const x = k ? BC('_nm')[k] : { from: today() };
  openModal({ title: k ? 'Edit nominal member' : '+ Nominal member', ok: 'Save', extraBtns: k ? `<button class="danger" onclick="commit({['bcfg/_nm/${k}']:null},{a:'delete',e:'Nominal member',s:'deleted'}).then(()=>{closeModals();render()})">Delete</button>` : '',
    body: `<div data-form><div class="fr c2"><div><label>Name *</label><input id="nm-n" value="${esc(x.n || '')}"></div><div><label>Flat</label>${accPicker('nm-m', memberOptions(''), { value: x.mid || '', ph: 'Flat (optional)' })}</div></div><div class="fr c2"><div><label>Purpose</label><input id="nm-p" value="${esc(x.p || '')}" placeholder="Tenant / licensee / company occupant"></div><div><label>Fee ₹</label><input id="nm-f" class="num" type="number" value="${x.fee || ''}"></div></div><div class="fr c2"><div><label>Admitted on *</label><input type="date" id="nm-d" value="${x.from || ''}"></div><div><label>Ceased on</label><input type="date" id="nm-t" value="${x.to || ''}"></div></div></div>`,
    onOk: async () => { guardEdit(); const n = val('nm-n'), d = val('nm-d'); if (!n || !d) throw new Error('Name and admission date are required'); if (val('nm-t') && val('nm-t') < d) throw new Error('Ceased date is before admission');
      await commit({ [`bcfg/_nm/${k || FBX.key('n')}`]: { n, mid: val('nm-m') || null, p: val('nm-p') || null, fee: r2(nval('nm-f')) || null, from: d, to: val('nm-t') || null } }, { a: k ? 'edit' : 'create', e: 'Nominal member', s: n }); toast('Saved'); render(); } }); }
function asOut(t) { if (t === 'n') return xlsx('Nominal_Members', [{ name: 'Nominal members', rows: [['Sr.', 'Name', 'Flat', 'Purpose', 'Admitted', 'Ceased', 'Fee'], ...NML().map(([, x], i) => [i + 1, x.n, x.mid && M(x.mid) ? flatLbl(M(x.mid)) : '', x.p || '', fd(x.from), fd(x.to), x.fee || ''])], cols: [6, 28, 10, 26, 12, 12, 10] }]);
  xlsx('Associate_Members', [{ name: 'Associate members', rows: [['Sr.', 'Flat', 'Member', 'Associate member', 'Relation', 'Admitted'], ...memSorted(true).filter(([, m]) => (m.kyc || {}).assoc || m.name2).map(([, m], i) => { const a = (m.kyc || {}).assoc || { n: m.name2, r: 'Joint / associate' }; return [i + 1, flatLbl(m), m.name, a.n, a.r || '', fd(a.d)]; })], cols: [6, 10, 28, 28, 18, 12] }]); }

// ── Managing committee & election (items 34, 53) ────────────────────────
const MC_DES = ['Chairman', 'Vice-Chairman', 'Secretary', 'Joint Secretary', 'Treasurer', 'Member', 'Co-opted Member', 'Invitee'];
const MCL = () => Object.entries(BC('_mc')).filter(([, x]) => x && x.n).sort((a, b) => MC_DES.indexOf(a[1].des) - MC_DES.indexOf(b[1].des) || String(a[1].n).localeCompare(String(b[1].n)));
const MC_ON = (x, d = today()) => (!x.from || x.from <= d) && (!x.to || x.to >= d);
const EL_STEPS = [['res', 'MC resolution to hold election / appoint Returning Officer'], ['pvl', 'Provisional voters list displayed'], ['fvl', 'Final voters list published'], ['prog', 'Election programme notice to members'], ['nomf', 'Nominations received'], ['scr', 'Scrutiny of nominations'], ['wd', 'Withdrawal & final list of candidates'], ['poll', 'Polling / counting'], ['res2', 'Result declared'], ['new', 'First meeting of new committee (office bearers elected)'], ['reg', 'Election report sent to the Registrar / Authority']];
const EL = () => BC('_el');
const elDue = e => (e.last ? ymd(new Date(pd(e.last).getFullYear() + (+e.term || 5), pd(e.last).getMonth(), pd(e.last).getDate())) : '');
page('committee', {
  render() {
    const L = MCL(); const cur = L.filter(([, x]) => MC_ON(x)); const old = L.filter(([, x]) => !MC_ON(x)); const e = EL(); const due = elDue(e); const left = due ? daysBetween(today(), due) : null;
    const row = ([k, x]) => `<tr><td><b>${esc(x.des)}</b></td><td>${esc(x.n)}${x.mid && M(x.mid) ? ` <span class="small muted">(${esc(flatLbl(M(x.mid)))})</span>` : ''}</td><td class="small">${esc(x.ph || '')}</td><td>${fd(x.from) || '—'}</td><td>${fd(x.to) || '—'}</td><td class="small">${esc(x.how || '')}</td><td>${canEdit() ? `<button class="xs ghost" onclick="mcModal('${k}')">✏</button>` : ''}</td></tr>`;
    shell('🏛 Managing Committee & Election', 'Office bearers with their terms, and the next election timeline', `${canEdit() ? `<button onclick="mcModal()">+ Committee member</button>` : ''}<button class="ghost" onclick="mcPrint()">🖨 Print list</button>`,
      `<div class="grid g2"><div class="card"><h3>Present committee (${cur.length})</h3><div class="tw"><table><thead><tr><th>Designation</th><th>Name</th><th>Mobile</th><th>From</th><th>To</th><th>How</th><th></th></tr></thead><tbody>${cur.map(row).join('') || '<tr><td colspan="7" class="empty">Add the committee members</td></tr>'}</tbody></table></div>
        ${old.length ? `<details style="margin-top:8px"><summary class="small">Past / future members (${old.length})</summary><table><tbody>${old.map(row).join('')}</tbody></table></details>` : ''}</div>
      <div class="card" data-form><h3>🗳 Election</h3>${due ? `<div class="alert ${left < 0 ? 'a-err' : left < 180 ? 'a-warn' : 'a-info'} small">Committee term ends on <b>${fd(due)}</b> — ${left < 0 ? `<b>overdue by ${-left} days</b>` : `${left} days left`}. Start the election process about 6 months before.</div>` : ''}
        <div class="fr c3"><div><label>Last election held on</label><input type="date" id="el-l" value="${e.last || ''}" ${canEdit() ? '' : 'disabled'}></div><div><label>Term (years)</label><input id="el-t" class="num" type="number" value="${e.term || 5}" ${canEdit() ? '' : 'disabled'}></div><div><label>Returning officer</label><input id="el-ro" value="${esc(e.ro || '')}" ${canEdit() ? '' : 'disabled'}></div></div>
        <table><tbody>${EL_STEPS.map(([k, l]) => { const s = (e.steps || {})[k] || {}; return `<tr data-es="${k}"><td style="width:30px"><input type="checkbox" class="es-ok" ${s.d ? 'checked' : ''} ${canEdit() ? '' : 'disabled'}></td><td class="small">${l}</td><td style="width:150px"><input type="date" class="es-d" value="${s.d || ''}" style="min-width:0" ${canEdit() ? '' : 'disabled'}></td></tr>`; }).join('')}</tbody></table>
        <p class="small muted">Societies with up to 250 members conduct their own election under the MCS Act (Chapter XIII-B) rules; larger ones through the State Co-operative Election Authority. Please verify the current rules.</p>
        ${canEdit() ? `<button onclick="elSave().catch(e=>toast(e.message,'err'))">💾 Save election details</button>` : ''}</div></div>`);
  }
});
function mcModal(k) { const x = k ? BC('_mc')[k] : { des: 'Member', from: today() };
  openModal({ title: k ? 'Edit committee member' : '+ Committee member', ok: 'Save', extraBtns: k ? `<button class="danger" onclick="commit({['bcfg/_mc/${k}']:null},{a:'delete',e:'Committee',s:'deleted'}).then(()=>{closeModals();render()})">Delete</button>` : '',
    body: `<div data-form><div class="fr"><div><label>Member (flat)</label>${accPicker('mc-m', memberOptions(''), { value: x.mid || '', ph: 'Pick to fill name (optional)', onchange: 'mcPick' })}</div></div><div class="fr c2"><div><label>Name *</label><input id="mc-n" value="${esc(x.n || '')}"></div><div><label>Designation *</label><select id="mc-d">${MC_DES.map(d => `<option ${x.des === d ? 'selected' : ''}>${d}</option>`).join('')}</select></div></div>
      <div class="fr c3"><div><label>Mobile</label><input id="mc-p" value="${esc(x.ph || '')}"></div><div><label>Term from</label><input type="date" id="mc-f" value="${x.from || ''}"></div><div><label>Term to</label><input type="date" id="mc-t" value="${x.to || ''}"></div></div><div class="fr"><div><label>Elected / co-opted / appointed (resolution)</label><input id="mc-h" value="${esc(x.how || '')}" placeholder="e.g. Elected in election dt. 10-01-2026"></div></div></div>`,
    onOk: async () => { guardEdit(); const n = val('mc-n'); if (!n) throw new Error('Name is required'); if (val('mc-t') && val('mc-f') && val('mc-t') < val('mc-f')) throw new Error('Term "to" is before "from"');
      await commit({ [`bcfg/_mc/${k || FBX.key('c')}`]: { n, mid: val('mc-m') || null, des: val('mc-d'), ph: val('mc-p') || null, from: val('mc-f') || null, to: val('mc-t') || null, how: val('mc-h') || null } }, { a: k ? 'edit' : 'create', e: 'Committee', s: `${val('mc-d')}: ${n}` }); toast('Saved'); render(); } }); }
function mcPick(mid) { const m = M(mid); if (m) { if (!val('mc-n')) $('mc-n').value = m.name; if (!val('mc-p')) $('mc-p').value = m.phone || ''; } }
async function elSave() {
  guardEdit(); const last = val('el-l'), term = Math.round(nval('el-t')) || 5; const steps = {}; $$('tr[data-es]').forEach(tr => { const d = tr.querySelector('.es-d').value; if (tr.querySelector('.es-ok').checked || d) steps[tr.dataset.es] = { d: d || today() }; });
  const e = { last: last || null, term, ro: val('el-ro') || null, steps: Object.keys(steps).length ? steps : null }; const up = { 'bcfg/_el': e }; const due = elDue(e);
  if (due) { const start = ymd(new Date(pd(due).getFullYear(), pd(due).getMonth() - 6, pd(due).getDate())); up['bcfg/_rem/election'] = { t: `Committee election due (term ends ${fd(due)}) — start the process`, d: start, rep: 'none' }; }
  await commit(up, { a: 'edit', e: 'Election', s: last ? `Last election ${fd(last)}, term ${term} yrs, due ${fd(due)}` : 'Election details' }); pushSummary(); toast(due ? 'Saved — reminder added to the Compliance Calendar' : 'Saved'); render();
}
function mcPrint() { const cur = MCL().filter(([, x]) => MC_ON(x));
  printReport('Managing Committee', `As on ${fd(today())}`, `<table><thead><tr><th>Sr.</th><th>Designation</th><th>Name</th><th>Flat</th><th>Mobile</th><th>Term</th></tr></thead><tbody>${cur.map(([, x], i) => `<tr><td>${i + 1}</td><td>${esc(x.des)}</td><td>${esc(x.n)}</td><td>${x.mid && M(x.mid) ? esc(flatLbl(M(x.mid))) : ''}</td><td>${esc(x.ph || '')}</td><td>${fd(x.from)} – ${fd(x.to)}</td></tr>`).join('')}</tbody></table>`); }

// ── Hooks into existing screens ─────────────────────────────────────────
(() => { const o = m360; window.m360 = m360 = function (mid) { const r = o.apply(this, arguments); try { const mds = $$('.ov'); const box = mds.length && mds[mds.length - 1].querySelector('.md-b > .row:last-child'); if (box) box.insertAdjacentHTML('beforeend', `<button class="sm ghost" onclick="closeModals();kycModal('${mid}')">🪪 KYC & documents</button><button class="sm ghost" onclick="closeModals();ownerHist('${mid}')">🕘 Owner history</button>${canEdit() ? `<button class="sm ghost" onclick="closeModals();transferModal('${mid}')">🔁 Transfer flat</button><button class="sm ghost" onclick="closeModals();oneBillModal('${mid}')">🧾 One-off bill</button><button class="sm ghost" onclick="closeModals();cnModal('CN','${mid}')">📝 Credit note</button>` : ''}`); } catch (e) { } return r; }; })();
addAct('members', () => `${canEdit() ? `<button class="ghost" onclick="transferModal()">🔁 Flat transfer</button>` : ''}<button class="ghost" onclick="go('kyc')">🪪 KYC</button>`);
navAdd('Masters', ['transfers', '🔁', 'Flat Transfers & Owner History'], 'members');
navAdd('Masters', ['kyc', '🪪', 'Member KYC & Documents'], 'transfers');
navAdd('Registers', ['assocreg', '🧾', 'Associate & Nominal Members'], 'statreg');
navAdd('Registers', ['committee', '🏛', 'Committee & Election'], 'meetings');

// ═══════════════════════════════════════════════════════════════════════
// VENDORS & STATUTORY (v10.8 phase C)
//  Vendor master & balance confirmation · GSTR-1 / 3B summary · TDS challans, Form 16A register, Form 140 (26Q) data
//  Society income-tax computation with 80P · Annual return to the Registrar · Statutory meeting checklist
//  Licences, taxes & certificates tracker · Conveyance status
// Data: heads/{id}/vm (vendor details) · brs/{fy}/tdsc, f16a, itr, anr, mchk · bcfg/_tdsmap, _tds, _ct, _cv
// ═══════════════════════════════════════════════════════════════════════
const BRS = k => ((S.brs || {})[k]) || {};
const QTR = d => { const m = +String(d).slice(5, 7); return m >= 4 && m <= 6 ? 'Q1' : m >= 7 && m <= 9 ? 'Q2' : m >= 10 ? 'Q3' : 'Q4'; };
const QLBL = { Q1: 'Apr–Jun', Q2: 'Jul–Sep', Q3: 'Oct–Dec', Q4: 'Jan–Mar' };
const fyMonths = () => { const out = []; const y = +S.fy.start.slice(0, 4); for (let i = 0; i < 12; i++) { const d = new Date(y, 3 + i, 1); out.push(ymd(d).slice(0, 7)); } return out; };
const addMon = (s, n) => { const d = pd(s); return ymd(new Date(d.getFullYear(), d.getMonth() + n, d.getDate())); };

// ── Vendor master (39) & balance confirmation (40) ──────────────────────
const VM = hid => ((S.heads[hid] || {}).vm) || {};
page('vendors', {
  render() {
    const V = vendorHeads(); const q = (RP.get('vn_q', '') || '').toLowerCase();
    shell('🏢 Vendor Master', 'Suppliers and contractors — PAN, GSTIN, bank and contact details; balance confirmation letters', `${canEdit() ? `<button onclick="vmModal()">+ New vendor</button>` : ''}<button class="ghost" onclick="vmOut()">📥 Excel</button>`,
      `<div class="toolbar"><input type="search" id="vn-q" placeholder="Search vendor, PAN, GSTIN…" value="${esc(q)}" oninput="RP.set('vn_q',this.value);keepFocus(()=>render())" style="min-width:240px"><span class="small muted">${V.length} vendor(s)</span></div>
      <div class="tw tall"><table><thead><tr><th>Vendor</th><th>PAN</th><th>GSTIN</th><th>Contact</th><th>Bank</th><th>TDS</th><th class="n">Balance payable</th><th></th></tr></thead><tbody>
      ${V.filter(([, h]) => !q || (h.name + ' ' + JSON.stringify(h.vm || {})).toLowerCase().includes(q)).map(([hid, h]) => { const v = h.vm || {}; const st = vendorStatus(hid); return `<tr><td class="b">${lk(`openHead('${hid}')`, esc(h.name), 'Ledger')}${v.msme ? ' <span class="tag t-purple">MSME</span>' : ''}</td><td class="mono small">${esc(v.pan || '—')}</td><td class="mono small">${esc(v.gst || '—')}</td><td class="small">${esc([v.cp, v.ph].filter(Boolean).join(' · ') || '—')}</td><td class="small">${esc([v.bank, v.ac ? 'A/c ' + v.ac : '', v.ifsc].filter(Boolean).join(' · ') || '—')}</td><td class="small">${v.sec != null && SET().tds.sections[v.sec] ? esc(SET().tds.sections[v.sec].c) : ''}</td><td class="n ${st.bal < 0 ? 'cr' : ''}">${st.bal >= 0 ? fmt(st.bal) : 'Adv ' + fmt(-st.bal)}</td><td style="white-space:nowrap">${canEdit() ? `<button class="xs ghost" onclick="vmModal('${hid}')">✏</button> ` : ''}<button class="xs ghost" title="Balance confirmation letter" onclick="vcModal('${hid}')">📄 Confirm</button></td></tr>`; }).join('') || '<tr><td colspan="8" class="empty">No vendors yet</td></tr>'}</tbody></table></div>
      <p class="small muted" style="margin-top:8px">Vendors are account heads under Liabilities → Sundry Creditors. PAN and TDS section are filled in automatically on vendor bills and payments.</p>`);
  }
});
function vmModal(hid) {
  const h = hid ? S.heads[hid] : { name: '' }; const v = (h && h.vm) || {}; const secs = SET().tds.sections;
  openModal({ title: hid ? `✏ ${esc(h.name)}` : '+ New vendor', wide: true, ok: 'Save', body: `<div data-form><div class="fr c2"><div><label>Vendor name *</label><input id="vm-n" value="${esc(h.name || '')}"></div><div><label>Contact person</label><input id="vm-cp" value="${esc(v.cp || '')}"></div></div>
    <div class="fr c3"><div><label>PAN</label><input id="vm-pan" value="${esc(v.pan || '')}" maxlength="10" style="text-transform:uppercase"></div><div><label>GSTIN</label><input id="vm-gst" value="${esc(v.gst || '')}" maxlength="15" style="text-transform:uppercase"></div><div><label>Udyam (MSME) no.</label><input id="vm-ms" value="${esc(v.msme || '')}"></div></div>
    <div class="fr c3"><div><label>Mobile</label><input id="vm-ph" value="${esc(v.ph || '')}"></div><div><label>Email</label><input id="vm-em" value="${esc(v.em || '')}"></div><div><label>Usual TDS section</label><select id="vm-sec"><option value="">— none —</option>${secs.map((s, i) => `<option value="${i}" ${String(v.sec) === String(i) ? 'selected' : ''}>${esc(s.c)} – ${esc(s.d)} (${s.r}%)</option>`).join('')}</select></div></div>
    <div class="fr"><div><label>Address</label><input id="vm-ad" value="${esc(v.ad || '')}"></div></div>
    <div class="fr c3"><div><label>Bank</label><input id="vm-bk" value="${esc(v.bank || '')}"></div><div><label>Account no.</label><input id="vm-ac" value="${esc(v.ac || '')}"></div><div><label>IFSC</label><input id="vm-if" value="${esc(v.ifsc || '')}" style="text-transform:uppercase"></div></div></div>`,
    onOk: async () => { guardEdit(); const n = val('vm-n'); if (!n) throw new Error('Name is required'); const pan = val('vm-pan').toUpperCase(), gst = val('vm-gst').toUpperCase(), ifsc = val('vm-if').toUpperCase();
      if (pan && !/^[A-Z]{5}\d{4}[A-Z]$/.test(pan)) throw new Error('PAN should look like ABCDE1234F'); if (gst && !/^\d{2}[A-Z]{5}\d{4}[A-Z][A-Z0-9]Z[A-Z0-9]$/.test(gst)) throw new Error('GSTIN is not valid (15 characters, e.g. 27ABCDE1234F1Z5)'); if (gst && pan && gst.slice(2, 12) !== pan) throw new Error('GSTIN does not contain this PAN'); if (ifsc && !/^[A-Z]{4}0[A-Z0-9]{6}$/.test(ifsc)) throw new Error('IFSC should look like SBIN0001234');
      const dup = Object.entries(S.heads).find(([k, x]) => x && k !== hid && String(x.name).trim().toLowerCase() === n.toLowerCase()); if (dup) throw new Error('An account head with this name already exists');
      const vm = { cp: val('vm-cp') || null, pan: pan || null, gst: gst || null, msme: val('vm-ms') || null, ph: val('vm-ph') || null, em: val('vm-em') || null, sec: val('vm-sec') === '' ? null : +val('vm-sec'), ad: val('vm-ad') || null, bank: val('vm-bk') || null, ac: val('vm-ac') || null, ifsc: ifsc || null };
      if (hid) await commit({ [`heads/${hid}/name`]: n, [`heads/${hid}/vm`]: vm }, { a: 'edit', e: 'Vendor', s: n });
      else { const nos = Object.values(S.heads).map(x => /^V(\d+)$/.exec((x && x.code) || '')).filter(Boolean).map(m => +m[1]); await commit({ [`heads/${FBX.key('x')}`]: { name: n, grp: 'Liabilities', sub: 'Sundry Creditors', code: 'V' + String((nos.length ? Math.max(...nos) : 0) + 1).padStart(3, '0'), type: 'gen', active: true, vm } }, { a: 'create', e: 'Vendor', s: n }); }
      toast('Saved'); if (CUR.id === 'vendors') render(); } });
}
function vmOut() { xlsx('Vendor_Master', [{ name: 'Vendors', rows: [['Vendor', 'PAN', 'GSTIN', 'MSME', 'Contact person', 'Mobile', 'Email', 'Address', 'Bank', 'Account no.', 'IFSC', 'Balance payable'], ...vendorHeads().map(([hid, h]) => { const v = h.vm || {}; return [h.name, v.pan || '', v.gst || '', v.msme || '', v.cp || '', v.ph || '', v.em || '', v.ad || '', v.bank || '', v.ac || '', v.ifsc || '', vendorStatus(hid).bal]; })], cols: [30, 12, 17, 14, 18, 12, 22, 30, 16, 16, 12, 14] }]); }
function vcModal(hid) {
  openModal({ title: `📄 Balance confirmation — ${esc(H(hid).name)}`, ok: '🖨 Print letter', body: `<div data-form><div class="fr c2"><div><label>Statement from</label><input type="date" id="vc-f" value="${S.fy.start}"></div><div><label>Balance as on</label><input type="date" id="vc-t" value="${today() > S.fy.end ? S.fy.end : today()}"></div></div><label class="row small"><input type="checkbox" id="vc-s" checked> Attach the statement of account</label></div>`,
    onOk: () => vcLetter(hid, val('vc-f'), val('vc-t'), $('vc-s').checked) });
}
function vcLetter(hid, f, t, withSt) {
  const h = H(hid); const v = h.vm || {}; const st = statement(hid, f, t); const bal = -st.close; // credit balance = payable
  printDoc('Balance confirmation', `<div class="doc">${letterhead()}<div style="display:flex;justify-content:space-between;margin:10px 0"><span>Ref.: BC/${esc(S.fy.label)}</span><span>Date: ${fd(today())}</span></div>
    <p style="line-height:1.7">To,<br><b>${esc(h.name)}</b>${v.ad ? '<br>' + esc(v.ad) : ''}${v.pan ? '<br>PAN: ' + esc(v.pan) : ''}</p>
    <p style="margin:12px 0"><b>Sub: Confirmation of balance as on ${fd(t)}</b></p>
    <p style="line-height:1.9;text-align:justify">Dear Sir / Madam,<br>As per our books of account, the balance in your account as on <b>${fd(t)}</b> is <b>₹${fmt(Math.abs(bal))} ${bal >= 0 ? 'payable to you (Cr.)' : 'receivable from you (Dr.)'}</b>${withSt ? ', as per the statement attached' : ''}. Kindly confirm the balance by signing and returning a copy of this letter. If there is any difference, please send us your statement of account so that it can be reconciled. If we do not hear from you within 15 days, the balance will be treated as confirmed.</p>
    ${signBlock(['Hon. Treasurer'], { space: 46 })}
    <div style="border-top:1px dashed #888;margin-top:22px;padding-top:10px"><p><b>Confirmation</b></p><p style="line-height:1.9">We confirm that the balance of ₹ ____________ (${bal >= 0 ? 'Cr' : 'Dr'}) as on ${fd(t)} is correct / the correct balance is ₹ ____________.</p><div style="display:flex;justify-content:space-between;margin-top:30px"><span>Date: __________</span><span>For ${esc(h.name)} (Signature & stamp)</span></div></div></div>
    ${withSt ? `<div class="doc pb" style="page-break-before:always">${letterhead(true)}<h2 class="tt">STATEMENT OF ACCOUNT — ${esc(h.name)}</h2><p class="center small">${fd(f)} to ${fd(t)}</p><table><thead><tr><th>Date</th><th>Voucher</th><th>Particulars</th><th class="n">Debit</th><th class="n">Credit</th><th class="n">Balance</th></tr></thead><tbody><tr><td colspan="5"><b>Opening balance</b></td><td class="n">${drcr(st.open)}</td></tr>${st.rows.map(r => `<tr><td>${fd(r.d)}</td><td>${esc(r.no || '')}</td><td>${esc(r.part)}${r.nar ? ' — ' + esc(r.nar) : ''}</td><td class="n">${r.dr ? fmt(r.dr) : ''}</td><td class="n">${r.cr ? fmt(r.cr) : ''}</td><td class="n">${drcr(r.bal)}</td></tr>`).join('')}<tr class="tot"><td colspan="3">Total / closing</td><td class="n">${fmt(st.dr)}</td><td class="n">${fmt(st.cr)}</td><td class="n">${drcr(st.close)}</td></tr></tbody></table></div>` : ''}`, { auto: false });
}
// Fill PAN / party from the vendor master on payments
