const ctRem = (k, x) => (x.due ? { t: `${x.t} — due / renewal`, d: x.due, rep: 'none' } : null);
function ctModal(k) { const x = k ? BC('_ct')[k] : { rep: 12 };
  openModal({ title: k ? 'Edit' : '+ Licence / tax / certificate', ok: 'Save', extraBtns: k ? `<button class="danger" onclick="commit({['bcfg/_ct/${k}']:null,['bcfg/_rem/ct_${k}']:null},{a:'delete',e:'Certificate',s:'deleted'}).then(()=>{closeModals();render()})">Delete</button>` : '',
    body: `<div data-form><div class="fr"><div><label>Item *</label><input id="ct-t" list="ct-l" value="${esc(x.t || '')}"><datalist id="ct-l">${CT_PRE.map(p => `<option value="${esc(p[0])}">`).join('')}</datalist></div></div><div class="fr c2"><div><label>Authority / agency</label><input id="ct-a" value="${esc(x.auth || '')}"></div><div><label>Ref. / licence / policy no.</label><input id="ct-n" value="${esc(x.no || '')}"></div></div>
    <div class="fr c4"><div><label>Last done / paid on</label><input type="date" id="ct-l2" value="${x.last || ''}"></div><div><label>Valid till / next due</label><input type="date" id="ct-d" value="${x.due || ''}"></div><div><label>Repeats every (months)</label><input id="ct-r" class="num" type="number" value="${x.rep || ''}"></div><div><label>Amount ₹</label><input id="ct-m" class="num" type="number" value="${x.amt || ''}"></div></div></div>`,
    onOk: async () => { guardEdit(); const t = val('ct-t'); if (!t) throw new Error('Enter the item'); const rec = { t, auth: val('ct-a') || null, no: val('ct-n') || null, last: val('ct-l2') || null, due: val('ct-d') || (val('ct-l2') && nval('ct-r') ? addMon(val('ct-l2'), Math.round(nval('ct-r'))) : null), rep: Math.round(nval('ct-r')) || null, amt: r2(nval('ct-m')) || null }; const id = k || FBX.key('c');
      await commit({ [`bcfg/_ct/${id}`]: rec, [`bcfg/_rem/ct_${id}`]: ctRem(id, rec) }, { a: k ? 'edit' : 'create', e: 'Certificate', s: `${t}${rec.due ? ' due ' + fd(rec.due) : ''}` }); pushSummary(); toast('Saved'); render(); } }); }
async function ctPresets() { guardEdit(); const up = {}; CT_PRE.forEach(([t, a, r]) => { const id = FBX.key('c'); up[`bcfg/_ct/${id}`] = { t, auth: a || null, rep: r }; }); await commit(up, { a: 'create', e: 'Certificate', s: 'Common items added' }); toast('Added — enter the dates for each'); render(); }
async function ctRenew(k) { const x = BC('_ct')[k]; if (!x) return; const d = await promptBox(`"${x.t}" renewed / paid on:`, today(), { title: 'Renewed', type: 'date' }); if (!d) return; const due = x.rep ? addMon(x.due && x.due > d ? x.due : d, x.rep) : x.due;
  const rec = { ...x, last: d, due: due || null, hist: [...(x.hist || []), { d, due: x.due || null }].slice(-10) }; await commit({ [`bcfg/_ct/${k}`]: rec, [`bcfg/_rem/ct_${k}`]: ctRem(k, rec) }, { a: 'edit', e: 'Certificate', s: `${x.t} renewed ${fd(d)}${due ? ', next ' + fd(due) : ''}` }); pushSummary(); toast(due ? `Next due ${fd(due)}` : 'Saved'); render(); }

