const CV_STEPS = [['docs', 'Documents collected from members & builder'], ['notice', 'Legal notice to the promoter / builder'], ['app', 'Application to the District Deputy Registrar (Form VII) with fees'], ['hear', 'Hearings before the competent authority'], ['order', 'Order / certificate for deemed conveyance received'], ['stamp', 'Stamp duty adjudication & payment'], ['regd', 'Conveyance deed registered (Sub-Registrar)'], ['mut', 'Mutation in 7/12 extract / property card in the society\'s name']];
const CV_DOCS = ['7/12 extract / property card', 'Approved building plan', 'Commencement certificate', 'Occupation / completion certificate', 'List of members with Index II of each', 'Copies of agreements for sale (all flats)', 'Proof of stamp duty paid on agreements', 'Society registration certificate', 'Architect certificate (built-up area)', 'Title search report', 'Development agreement / power of attorney', 'Legal notice to builder & acknowledgement'];
page('conv', {
  render() {
    const c = BC('_cv'); const st = c.steps || {}; const done = CV_STEPS.filter(([k]) => (st[k] || {}).d).length; const ro = canEdit() ? '' : 'disabled';
    shell('🏠 Conveyance Status', 'Track conveyance / deemed conveyance of the land and building to the society', '',
      `<div class="grid g2"><div class="card" data-form><div class="fr c2"><div><label>Type</label><select id="cv-ty" ${ro}>${['Conveyance by builder', 'Deemed conveyance', 'Already conveyed'].map(t => `<option ${c.ty === t ? 'selected' : ''}>${t}</option>`).join('')}</select></div><div><label>Advocate / consultant</label><input id="cv-ad" value="${esc(c.adv || '')}" ${ro}></div></div>
        <div class="alert ${done === CV_STEPS.length ? 'a-ok' : 'a-info'} small">${done} of ${CV_STEPS.length} stages completed</div>
        <table><tbody>${CV_STEPS.map(([k, l]) => { const s = st[k] || {}; return `<tr data-cv="${k}"><td style="width:30px"><input type="checkbox" class="cv-ok" ${s.d ? 'checked' : ''} ${ro}></td><td class="small">${l}</td><td style="width:140px"><input type="date" class="cv-d" value="${s.d || ''}" style="min-width:0" ${ro}></td><td><input class="cv-n" value="${esc(s.n || '')}" placeholder="note / ref." style="min-width:0" ${ro}></td></tr>`; }).join('')}</tbody></table></div>
      <div class="card"><h3>Documents checklist</h3><table><tbody>${CV_DOCS.map((d, i) => `<tr><td style="width:30px"><input type="checkbox" class="cv-doc" data-i="${i}" ${(c.docs || {})[i] ? 'checked' : ''} ${ro}></td><td class="small">${d}</td></tr>`).join('')}</tbody></table></div></div>
      ${canEdit() ? `<button style="margin-top:10px" onclick="cvSave().catch(e=>toast(e.message,'err'))">💾 Save</button>` : ''}<p class="small muted" style="margin-top:8px">Stages as generally followed in Maharashtra under section 11 of MOFA — confirm with your advocate.</p>`);
  }
});
async function cvSave() { guardEdit(); const steps = {}; $$('tr[data-cv]').forEach(tr => { const d = tr.querySelector('.cv-d').value, n = tr.querySelector('.cv-n').value.trim(); if (tr.querySelector('.cv-ok').checked || d || n) steps[tr.dataset.cv] = { d: d || (tr.querySelector('.cv-ok').checked ? today() : null), n: n || null }; });
  const docs = {}; $$('.cv-doc').forEach(c => { if (c.checked) docs[c.dataset.i] = true; }); await commit({ 'bcfg/_cv': { ty: val('cv-ty'), adv: val('cv-ad') || null, steps: Object.keys(steps).length ? steps : null, docs: Object.keys(docs).length ? docs : null } }, { a: 'edit', e: 'Conveyance', s: `${Object.values(steps).filter(s => s.d).length}/${CV_STEPS.length} stages` }); toast('Saved'); render(); }

