// ═══════════════════════════════════════════════════════════════════════
// ACCOUNTS & AUDIT REPORTS (v10.8 phase D)
//  Balance-sheet schedules · ratio analysis · cash-flow statement · 3-year comparison · notes to accounts
//  Auditor query sheet · ledger scrutiny · voucher sampling · investment maturity calendar · annual member statement
// Data: brs/{fy}/notes, aq (auditor queries) · inv/{id}/plan (reinvestment plan)
// ═══════════════════════════════════════════════════════════════════════
const accTitle = (t, sub) => `<h2 class="tt">${esc(t)}</h2>${sub ? `<p class="center small muted" style="margin:-4px 0 8px">${esc(sub)}</p>` : ''}`;
const asOnFY = () => (today() < S.fy.end ? today() : S.fy.end);

// ── 59. Schedules for every balance-sheet group ─────────────────────────
function schedData() {
  const I = IDS(); const bal = ENG.balances(S, { lines: L_() }); const bs = ENG.balanceSheet(S); const groups = {};
  for (const [hid, b] of Object.entries(bal)) { const h = S.heads[hid]; if (!h || (h.grp !== 'Assets' && h.grp !== 'Liabilities') || hid === I.dues || hid === I.ie) continue; if (!b.ob && !b.dr && !b.cr && !b.cl) continue;
    const k = h.grp + '|' + (h.sub || (h.grp === 'Assets' ? 'Current Assets' : 'Current Liabilities')); (groups[k] = groups[k] || { grp: h.grp, sub: k.split('|')[1], rows: [] }).rows.push({ hid, h, ob: b.ob, dr: b.dr, cr: b.cr, cl: b.cl }); }
  const G = Object.values(groups).sort((a, b) => (a.grp === 'Liabilities' ? 0 : 1) - (b.grp === 'Liabilities' ? 0 : 1) || a.sub.localeCompare(b.sub)); G.forEach((g, i) => { g.no = String.fromCharCode(65 + (i % 26)) + (i >= 26 ? Math.floor(i / 26) : ''); g.rows.sort((a, b) => String(a.h.code).localeCompare(String(b.h.code))); });
  return { G, bs };
}
const sgn = (g, v) => (g === 'Liabilities' ? -v : v);
page('schedules', {
  render() {
    const { G, bs } = schedData();
    shell('📎 Balance Sheet Schedules', `Head-wise schedule for every group — FY ${esc(S.fy.label)}`, `<button class="ghost" onclick="schedOut('x')">📥 Excel</button><button class="ghost" onclick="schedOut('p')">🖨 Print all</button>`,
      G.map(g => `<div class="card" style="margin-bottom:10px"><h3>Schedule ${g.no} — ${esc(g.sub)} <span class="gtag gt-${g.grp}">${g.grp}</span></h3><div class="tw"><table><thead><tr><th>Account</th><th class="n">Opening</th><th class="n">Debit</th><th class="n">Credit</th><th class="n">Closing</th></tr></thead><tbody>${g.rows.map(r => `<tr><td>${lk(`openHead('${r.hid}')`, esc(r.h.name))}</td><td class="n">${fmt(sgn(g.grp, r.ob))}</td><td class="n">${fmt(r.dr)}</td><td class="n">${fmt(r.cr)}</td><td class="n b">${fmt(sgn(g.grp, r.cl))}</td></tr>`).join('')}<tr class="tot"><td>Total</td><td class="n">${fmt(sgn(g.grp, sum(g.rows, r => r.ob)))}</td><td class="n">${fmt(sum(g.rows, r => r.dr))}</td><td class="n">${fmt(sum(g.rows, r => r.cr))}</td><td class="n">${fmt(sgn(g.grp, sum(g.rows, r => r.cl)))}</td></tr></tbody></table></div></div>`).join('') +
      `<div class="card"><h3>Schedule — Dues from members (${bs.dues.length})</h3><p class="small">Total ₹${fmt(bs.td)} · Advances from members ₹${fmt(bs.tadv)} (${bs.adv.length}) — detailed list in ${lk("go('dues')", 'Outstanding List')}.</p></div>`);
  }
});
function schedOut(k) {
  const { G, bs } = schedData();
  if (k === 'x') return xlsx(`Schedules_${S.fy.label}`, [...G.map(g => ({ name: `Sch ${g.no} ${g.sub}`.slice(0, 30), rows: [['Account', 'Opening', 'Debit', 'Credit', 'Closing'], ...g.rows.map(r => [r.h.name, sgn(g.grp, r.ob), r.dr, r.cr, sgn(g.grp, r.cl)]), ['Total', sgn(g.grp, r2(sum(g.rows, r => r.ob))), r2(sum(g.rows, r => r.dr)), r2(sum(g.rows, r => r.cr)), sgn(g.grp, r2(sum(g.rows, r => r.cl)))]], cols: [34, 14, 14, 14, 14] })),
    { name: 'Sch Member dues', rows: [['Flat', 'Member', 'Principal', 'Interest', 'Total'], ...bs.dues.map(d => [flatLbl(d.m), d.m.name, r2(d.P + d.N), d.I, d.amt]), ['Total', '', '', '', bs.td]], cols: [10, 30, 14, 14, 14] }]);
  printDoc('Schedules', G.map(g => `<div class="doc nb" style="margin-bottom:14px">${letterhead(true)}${accTitle(`SCHEDULE ${g.no} — ${g.sub.toUpperCase()}`, `as on ${fd(S.fy.end)}`)}<table><thead><tr><th>Account</th><th class="n">Opening</th><th class="n">Debit</th><th class="n">Credit</th><th class="n">Closing</th></tr></thead><tbody>${g.rows.map(r => `<tr><td>${esc(r.h.name)}</td><td class="n">${fmt(sgn(g.grp, r.ob))}</td><td class="n">${fmt(r.dr)}</td><td class="n">${fmt(r.cr)}</td><td class="n">${fmt(sgn(g.grp, r.cl))}</td></tr>`).join('')}<tr class="tot"><td>Total</td><td class="n">${fmt(sgn(g.grp, sum(g.rows, r => r.ob)))}</td><td class="n">${fmt(sum(g.rows, r => r.dr))}</td><td class="n">${fmt(sum(g.rows, r => r.cr))}</td><td class="n">${fmt(sgn(g.grp, sum(g.rows, r => r.cl)))}</td></tr></tbody></table></div>`).join('<div class="pb"></div>'));
}

// ── 61. Ratio analysis ──────────────────────────────────────────────────
function ratioData() {
  const I = IDS(); const L = L_(); const ie = ENG.incomeExpenditure(S); const bs = ENG.balanceSheet(S); const bal = ENG.balances(S, { lines: L });
  const billed = r2(sum(Object.values(S.bills).filter(Boolean), b => ENG.billTotal(b))); const obDues = r2(sum(Object.keys(S.members), mid => { const o = ENG.memberOB(S, mid); return Math.max(0, o.p + o.n + o.i); }));
  const rcvd = r2(sum(L.filter(l => l.h === I.dues && l.src === 'v' && l.t === 'R' && !l.bnc), l => l.cr)); const dues = bs.td;
  const cb = r2(sum(Object.entries(bal).filter(([h]) => isCB(h)), ([, b]) => b.cl)); const invH = new Set(Object.values(S.inv || {}).filter(Boolean).map(x => x.head)); const inv = r2(sum([...invH].filter(Boolean), h => (bal[h] || {}).cl || 0));
  const cl = r2(sum(bs.liabs.filter(x => /current|creditor|payable|provision/i.test(x.sub)), x => x.amt) + bs.tadv); const funds = r2(sum(bs.liabs.filter(x => /fund|reserve/i.test(x.sub + ' ' + x.h.name)), x => x.amt));
  const exBy = {}; ie.exp.forEach(x => exBy[x.sub] = r2((exBy[x.sub] || 0) + x.amt)); const months = Math.max(1, Math.min(12, Math.round(daysBetween(S.fy.start, asOnFY()) / 30.4) + 1));
  const mb = MB(); const def3 = Object.entries(mb).filter(([mid, r]) => r.bal > 0 && FF(mid).open.some(o => daysBetween(o.d || S.fy.start, asOnFY()) > 90)).length; const act = Object.values(S.members).filter(m => m && m.active !== false).length;
  const pct = (a, b) => (b ? r2(a / b * 100) : 0);
  return { R: [
    ['Collection efficiency', pct(rcvd, obDues + billed), '%', `Received ₹${fmt0(rcvd)} of opening dues ₹${fmt0(obDues)} + billed ₹${fmt0(billed)}`, v => v >= 90 ? 'ok' : v >= 75 ? 'warn' : 'err'],
    ['Outstanding dues in months of billing', billed ? r2(dues / (billed / months)) : 0, 'months', `Dues ₹${fmt0(dues)} ÷ average monthly billing ₹${fmt0(billed / months)}`, v => v <= 1.5 ? 'ok' : v <= 3 ? 'warn' : 'err'],
    ['Members overdue > 90 days', pct(def3, act), '%', `${def3} of ${act} members`, v => v <= 5 ? 'ok' : v <= 15 ? 'warn' : 'err'],
    ['Surplus as % of income', pct(ie.surplus, ie.ti), '%', `Surplus ₹${fmt0(ie.surplus)} on income ₹${fmt0(ie.ti)}`, v => v >= 0 ? 'ok' : 'err'],
    ['Liquidity (cash + bank + deposits ÷ current liabilities)', cl ? r2((cb + inv) / cl) : 0, '×', `₹${fmt0(cb + inv)} ÷ ₹${fmt0(cl)}`, v => v >= 1.5 ? 'ok' : v >= 1 ? 'warn' : 'err'],
    ['Funds backed by investments', pct(inv, funds), '%', `Deposits ₹${fmt0(inv)} against funds & reserves ₹${fmt0(funds)}`, v => v >= 80 ? 'ok' : v >= 50 ? 'warn' : 'err'],
    ...Object.entries(exBy).sort((a, b) => b[1] - a[1]).map(([s, a]) => [`${s} — share of expenses`, pct(a, ie.te), '%', `₹${fmt0(a)} of ₹${fmt0(ie.te)}`, null])], months };
}
page('ratios', {
  render() {
    const { R, months } = ratioData(); const col = { ok: 'var(--ok,#16a34a)', warn: 'var(--warn,#d97706)', err: 'var(--err,#dc2626)' };
    shell('📐 Ratio Analysis', `FY ${esc(S.fy.label)} — ${months} month(s) of data`, `<button class="ghost" onclick="printMain('Ratio Analysis','FY '+S.fy.label)">🖨 Print</button>`,
      `<div class="tw"><table><thead><tr><th>Ratio</th><th class="n">Value</th><th>Working</th><th></th></tr></thead><tbody>${R.map(([l, v, u, w, f]) => { const s = f ? f(v) : null; return `<tr><td class="b">${esc(l)}</td><td class="n b" style="${s ? 'color:' + col[s] : ''}">${fmt(v)} ${u}</td><td class="small muted">${esc(w)}</td><td>${s ? `<span class="tag t-${s === 'ok' ? 'ok' : s === 'warn' ? 'warn' : 'err'}">${s === 'ok' ? 'good' : s === 'warn' ? 'watch' : 'attention'}</span>` : `<div style="width:120px;height:7px;background:var(--border);border-radius:4px"><div style="width:${Math.min(100, Math.max(0, v))}%;height:7px;border-radius:4px;background:var(--pri,#2554b8)"></div></div>`}</td></tr>`; }).join('')}</tbody></table></div>
      <p class="small muted" style="margin-top:8px">Benchmarks are rules of thumb for housing societies — use judgement.</p>`);
  }
});

// ── 62. Cash-flow statement (direct method) ─────────────────────────────
function cfClass(hid) { const h = S.heads[hid] || {}; const I = IDS(); const invH = new Set(Object.values(S.inv || {}).filter(Boolean).map(x => x.head)); const t = (h.sub || '') + ' ' + (h.name || '');
  if (hid === I.dues) return ['op', 'Received from members']; if (h.grp === 'Income') return /interest/i.test(h.name) ? ['inv', 'Interest received'] : ['op', 'Other income received']; if (h.grp === 'Expenses') return ['op', 'Expenses paid'];
  if (h.grp === 'Assets') { if (invH.has(hid) || /investment|fixed deposit|\bfd\b|deposit with bank|recurring/i.test(t)) return ['inv', 'Deposits placed / matured']; if (/fixed asset|building|plant|furniture|equipment|machinery|computer/i.test(t)) return ['inv', 'Fixed assets bought / sold']; return ['op', 'Advances, deposits & receivables']; }
  if (h.grp === 'Liabilities') { if (/fund|reserve|share capital|loan|borrow/i.test(t)) return ['fin', /loan|borrow/i.test(t) ? 'Loans' : 'Funds & share capital']; return ['op', 'Payables & provisions']; }
  return ['op', 'Other']; }
function cfData() { const rp = ENG.receiptsPayments(S, S.fy.start, asOnFY()); const g = {}; const add = (hid, v) => { const [s, l] = cfClass(hid); const k = s + '|' + l; g[k] = r2((g[k] || 0) + v); };
  rp.rec.forEach(x => add(x.hid, x.amt)); rp.pay.forEach(x => add(x.hid, -x.amt));
  const sec = s => Object.entries(g).filter(([k]) => k.startsWith(s + '|')).map(([k, v]) => [k.split('|')[1], v]).sort((a, b) => b[1] - a[1]);
  return { rp, op: sec('op'), inv: sec('inv'), fin: sec('fin'), net: { op: r2(sum(sec('op'), x => x[1])), inv: r2(sum(sec('inv'), x => x[1])), fin: r2(sum(sec('fin'), x => x[1])) } }; }
function cfPrint() { const t = $('cf-t'); if (!t) return; printReport('Cash Flow Statement', `${fd(S.fy.start)} to ${fd(asOnFY())} · FY ${S.fy.label}`, t.outerHTML); }
function cfOut() { const c = cfData(); const R = [['Particulars', 'Amount ₹']]; const sec = (h, L, k) => { R.push([h, '']); L.forEach(([l, v]) => R.push(['   ' + l, v])); R.push(['Net cash from ' + k, c.net[k === 'operating activities' ? 'op' : k === 'investing activities' ? 'inv' : 'fin']]); };
  sec('A. Operating activities', c.op, 'operating activities'); sec('B. Investing activities', c.inv, 'investing activities'); sec('C. Financing activities', c.fin, 'financing activities');
  R.push(['Net increase / (decrease) in cash & bank', r2(c.net.op + c.net.inv + c.net.fin)], ['Opening cash & bank', c.rp.to], ['Closing cash & bank', c.rp.tc]); xlsx(`Cash_Flow_${S.fy.label}`, [{ name: 'Cash Flow', rows: R, cols: [55, 16] }]); }
page('cashflow', {
  render() {
    const c = cfData(); const row = ([l, v]) => `<tr><td style="padding-left:20px">${esc(l)}</td><td class="n">${v < 0 ? `(${fmt(-v)})` : fmt(v)}</td></tr>`; const tot = (l, v) => `<tr class="tot"><td>${l}</td><td class="n">${v < 0 ? `(${fmt(-v)})` : fmt(v)}</td></tr>`;
    shell('💧 Cash Flow Statement', `${fd(S.fy.start)} to ${fd(asOnFY())} — direct method from cash & bank entries`, `<button class="ghost" onclick="cfPrint()">🖨 Print / PDF</button><button class="ghost" onclick="cfOut()">📥 Excel</button>`,
      `<div class="card" style="max-width:760px"><table id="cf-t"><tbody><tr class="g"><td colspan="2">A. Operating activities</td></tr>${c.op.map(row).join('')}${tot('Net cash from operating activities', c.net.op)}
      <tr class="g"><td colspan="2">B. Investing activities</td></tr>${c.inv.map(row).join('') || '<tr><td colspan="2" class="small muted" style="padding-left:20px">—</td></tr>'}${tot('Net cash from investing activities', c.net.inv)}
      <tr class="g"><td colspan="2">C. Financing activities</td></tr>${c.fin.map(row).join('') || '<tr><td colspan="2" class="small muted" style="padding-left:20px">—</td></tr>'}${tot('Net cash from financing activities', c.net.fin)}
      ${tot('Net increase / (decrease) in cash & bank (A + B + C)', r2(c.net.op + c.net.inv + c.net.fin))}<tr><td>Opening cash & bank</td><td class="n">${fmt(c.rp.to)}</td></tr>${tot('Closing cash & bank', c.rp.tc)}</tbody></table>
      ${Math.abs(c.rp.check) > 0.5 ? `<div class="alert a-warn small" style="margin-top:8px">Check difference ₹${fmt(c.rp.check)} — some entries between cash/bank and other accounts may be incomplete.</div>` : ''}</div>`);
  }
});

// ── 63. Three-year comparison ───────────────────────────────────────────
const CMP3 = { key: null, data: null };
async function cmp3Data() {
  const keys = Object.keys(S.fys || {}).filter(k => k <= S.fyId).sort().slice(-3); const key = keys.join(',') + ':' + S.ver; if (CMP3.key === key) return CMP3.data;
  const out = []; for (const k of keys) { const T = await fyState(k); const ie = ENG.incomeExpenditure(T); const bs = ENG.balanceSheet(T); out.push({ k, label: (S.fys[k] || {}).label || k, ie, bs }); }
  CMP3.key = key; CMP3.data = out; return out;
}
function cmp3Rows(D) {
  const ieR = {}, bsR = {}; const put = (o, sec, name, i, v) => { const k = sec + '|' + name; (o[k] = o[k] || { sec, name, v: D.map(() => 0) }).v[i] = r2(o[k].v[i] + v); };
  D.forEach((d, i) => { d.ie.inc.forEach(x => put(ieR, 'Income', x.sub, i, x.amt)); d.ie.exp.forEach(x => put(ieR, 'Expenditure', x.sub, i, x.amt));
    d.bs.liabs.forEach(x => put(bsR, 'Liabilities', x.sub, i, x.amt)); put(bsR, 'Liabilities', 'Advances from members', i, d.bs.tadv); if (d.bs.ieTotal >= 0) put(bsR, 'Liabilities', 'I&E account (surplus)', i, d.bs.ieTotal);
    d.bs.assets.forEach(x => put(bsR, 'Assets', x.sub, i, x.amt)); put(bsR, 'Assets', 'Dues from members', i, d.bs.td); if (d.bs.ieTotal < 0) put(bsR, 'Assets', 'I&E account (deficit)', i, -d.bs.ieTotal); });
  return { ie: Object.values(ieR), bs: Object.values(bsR) };
}
page('cmp3', {
  async render() {
    shell('📊 Three-year Comparison', 'Income & Expenditure and Balance Sheet — this year and the two before', '', loading('Loading previous years…'));
    let D; try { D = await cmp3Data(); } catch (e) { $('main').querySelector('.pc').innerHTML = `<div class="alert a-err">${esc(e.message)}</div>`; return; } if (CUR.id !== 'cmp3') return;
    const R = cmp3Rows(D); const th = `<th>Particulars</th>${D.map(d => `<th class="n">FY ${esc(d.label)}</th>`).join('')}${D.length > 1 ? '<th class="n">Change</th>' : ''}`;
    const tbl = (rows, secs) => secs.map(s => { const rs = rows.filter(r => r.sec === s); const t = D.map((_, i) => r2(sum(rs, r => r.v[i]))); return `<tr class="g"><td colspan="${D.length + 2}">${s}</td></tr>${rs.map(r => `<tr><td style="padding-left:16px">${esc(r.name)}</td>${r.v.map(v => `<td class="n">${fmt(v)}</td>`).join('')}${D.length > 1 ? `<td class="n small">${chg(r.v[D.length - 2], r.v[D.length - 1])}</td>` : ''}</tr>`).join('')}<tr class="tot"><td>Total ${s.toLowerCase()}</td>${t.map(v => `<td class="n">${fmt(v)}</td>`).join('')}${D.length > 1 ? `<td class="n small">${chg(t[D.length - 2], t[D.length - 1])}</td>` : ''}</tr>`; }).join('');
    shell('📊 Three-year Comparison', 'Income & Expenditure and Balance Sheet — this year and the two before', `<button class="ghost" onclick="cmp3Out()">📥 Excel</button><button class="ghost" onclick="printMain('Three-year Comparison','')">🖨 Print</button>`,
      `${D.length < 2 ? '<div class="alert a-info small">Only one financial year exists in the software — earlier years will appear here once they are added.</div>' : ''}
      <div class="card" style="margin-bottom:12px"><h3>Income & Expenditure</h3><div class="tw"><table><thead><tr>${th}</tr></thead><tbody>${tbl(R.ie, ['Income', 'Expenditure'])}<tr class="tot"><td>Surplus / (deficit)</td>${D.map(d => `<td class="n">${fmt(d.ie.surplus)}</td>`).join('')}${D.length > 1 ? '<td></td>' : ''}</tr></tbody></table></div></div>
      <div class="card"><h3>Balance Sheet</h3><div class="tw"><table><thead><tr>${th}</tr></thead><tbody>${tbl(R.bs, ['Liabilities', 'Assets'])}</tbody></table></div></div>`);
  }
});
const chg = (a, b) => (!a ? (b ? 'new' : '') : `${b >= a ? '▲' : '▼'} ${Math.abs(r2((b - a) / Math.abs(a) * 100))}%`);
async function cmp3Out() { const D = await cmp3Data(); const R = cmp3Rows(D); const h = ['Section', 'Particulars', ...D.map(d => 'FY ' + d.label)];
  xlsx('ThreeYear_Comparison', [{ name: 'I&E', rows: [h, ...R.ie.map(r => [r.sec, r.name, ...r.v]), ['', 'Surplus / (deficit)', ...D.map(d => d.ie.surplus)]], cols: [14, 34, 15, 15, 15] }, { name: 'Balance Sheet', rows: [h, ...R.bs.map(r => [r.sec, r.name, ...r.v])], cols: [14, 34, 15, 15, 15] }]); }

