// ── 65. Auditor query sheet ─────────────────────────────────────────────
const AQ = () => Object.entries(BRS('aq')).filter(([, x]) => x && x.q).sort((a, b) => String(a[1].d).localeCompare(String(b[1].d)) || (a[1].at || 0) - (b[1].at || 0));
