// ── 66. Ledger scrutiny ─────────────────────────────────────────────────
const SCR_RULES = { cash10k: 'Cash payment above ₹10,000 in a day to one party', round: 'Round-sum payment (₹10,000+ in exact thousands)', nonar: 'No narration', late: 'Entered more than 30 days after its date', sunday: 'Dated on a Sunday', dup: 'Same payee & amount within 7 days', cash2l: 'Cash receipt of ₹2 lakh or more', negexp: 'Expense head with credit balance', bigjv: 'Journal of ₹50,000+ touching income or expenses' };
function scrutiny() {
  const out = []; const V = Object.entries(S.vch).filter(([, v]) => v && !v.rev); const I = IDS(); const add = (r, id, v, note) => out.push({ r, id, v, note });
  const cashPay = {};
  for (const [id, v] of V) { const ls = vLines(v); const amt = vAmount(v); const cash = ls.some(l => (S.heads[l.h] || {}).type === 'cash');
    if (v.t === 'P' && cash) { const party = ls.filter(l => l.dr).map(l => l.m || l.h).join(); const k = v.d + '|' + party; cashPay[k] = (cashPay[k] || []).concat([[id, v, amt]]); }
    if (v.t === 'P' && amt >= 10000 && amt % 1000 === 0) add('round', id, v, `₹${fmt0(amt)}`);
    if (!String(v.nar || '').trim() && !v.bs) add('nonar', id, v, '');
    if (v.at && daysBetween(v.d, ymd(new Date(v.at))) > 30) add('late', id, v, `entered on ${fd(ymd(new Date(v.at)))}`);
    if (pd(v.d).getDay() === 0) add('sunday', id, v, '');
    if (v.t === 'R' && cash && amt >= 200000) add('cash2l', id, v, `₹${fmt0(amt)}`);
    if (v.t === 'J' && amt >= 50000 && ls.some(l => ['Income', 'Expenses'].includes((S.heads[l.h] || {}).grp)) && !v.rb && !v.ad) add('bigjv', id, v, `₹${fmt0(amt)}`); }
  for (const arr of Object.values(cashPay)) { const t = sum(arr, x => x[2]); if (t > 10000) arr.forEach(([id, v]) => add('cash10k', id, v, `₹${fmt0(t)} in cash that day`)); }
  const P = V.filter(([, v]) => v.t === 'P').map(([id, v]) => ({ id, v, a: vAmount(v), p: vLines(v).filter(l => l.dr).map(l => l.m || l.h).join() })).sort((a, b) => a.v.d.localeCompare(b.v.d));
  for (let i = 0; i < P.length; i++) for (let j = i + 1; j < P.length && daysBetween(P[i].v.d, P[j].v.d) <= 7; j++) if (P[i].p === P[j].p && Math.abs(P[i].a - P[j].a) < 0.01) add('dup', P[j].id, P[j].v, `same as ${P[i].v.no}`);
  const bal = ENG.balances(S, { lines: L_() }); for (const [hid, b] of Object.entries(bal)) { const h = S.heads[hid]; if (h && h.grp === 'Expenses' && b.cl < -0.5) out.push({ r: 'negexp', head: hid, note: `${h.name}: Cr ₹${fmt(-b.cl)}` }); }
  return out;
}
