// ── 67. Voucher sampling ────────────────────────────────────────────────
function rng(seed) { let s = (+seed || 1) >>> 0; return () => { s = (s * 1664525 + 1013904223) >>> 0; return s / 4294967296; }; }
function sampleVch(o) { let V = Object.entries(S.vch).filter(([, v]) => v && !v.rev && (!o.t || v.t === o.t) && vAmount(v) >= (o.min || 0)); const n = Math.max(1, Math.min(V.length, o.n || 25));
  if (o.m === 'top') return V.sort((a, b) => vAmount(b[1]) - vAmount(a[1])).slice(0, n);
  V.sort((a, b) => a[1].d.localeCompare(b[1].d) || String(a[1].no).localeCompare(String(b[1].no)));
  if (o.m === 'nth') { const step = V.length / n; return Array.from({ length: n }, (_, i) => V[Math.floor(i * step)]); }
  const r = rng(o.seed); const pool = V.slice(); const out = []; while (out.length < n && pool.length) out.push(pool.splice(Math.floor(r() * pool.length), 1)[0]); return out.sort((a, b) => a[1].d.localeCompare(b[1].d)); }
page('sampling', {
  render() {
    const o = { t: RP.get('sm_t', 'P'), m: RP.get('sm_m', 'rand'), n: +RP.get('sm_n', 25), min: +RP.get('sm_min', 0), seed: +RP.get('sm_s', 2026) }; const L = sampleVch(o); const set = (k, v) => `RP.set('${k}',${v});render()`;
    shell('🎲 Voucher Sampling', 'Pick a sample of vouchers for vouching — random (repeatable with the seed), largest, or every n-th', `<button class="ghost" onclick="smOut('x')">📥 Excel</button><button class="ghost" onclick="smOut('p')">🖨 Print checklist</button>`,
      `<div class="toolbar" data-form><select onchange="${set('sm_t', 'this.value')}">${[['', 'All vouchers'], ['P', 'Payments'], ['R', 'Receipts'], ['J', 'Journals'], ['C', 'Contra']].map(([k, l]) => `<option value="${k}" ${o.t === k ? 'selected' : ''}>${l}</option>`).join('')}</select>
      <select onchange="${set('sm_m', 'this.value')}">${[['rand', 'Random'], ['top', 'Largest amounts'], ['nth', 'Every n-th (systematic)']].map(([k, l]) => `<option value="${k}" ${o.m === k ? 'selected' : ''}>${l}</option>`).join('')}</select>
      <label style="margin:0">Sample</label><input type="number" value="${o.n}" style="width:80px;min-width:0" onchange="${set('sm_n', '+this.value')}"><label style="margin:0">Min ₹</label><input type="number" value="${o.min}" style="width:100px;min-width:0" onchange="${set('sm_min', '+this.value')}">${o.m === 'rand' ? `<label style="margin:0">Seed</label><input type="number" value="${o.seed}" style="width:90px;min-width:0" onchange="${set('sm_s', '+this.value')}">` : ''}</div>
      <div class="tw tall"><table><thead><tr><th>#</th><th>Date</th><th>Voucher</th><th>Particulars</th><th class="n">Amount</th></tr></thead><tbody>${L.map(([id, v], i) => `<tr><td>${i + 1}</td><td>${fd(v.d)}</td><td class="mono small">${lk(`openVch('${id}')`, esc(v.no))}</td><td class="small">${esc(vParticulars(v))}${v.nar ? `<div class="muted">${esc(v.nar)}</div>` : ''}</td><td class="n">${fmt(vAmount(v))}</td></tr>`).join('') || '<tr><td colspan="5" class="empty">No vouchers match</td></tr>'}<tr class="tot"><td colspan="4">${L.length} vouchers</td><td class="n">${fmt(sum(L, ([, v]) => vAmount(v)))}</td></tr></tbody></table></div>`);
  }
});
function smOut(k) { const o = { t: RP.get('sm_t', 'P'), m: RP.get('sm_m', 'rand'), n: +RP.get('sm_n', 25), min: +RP.get('sm_min', 0), seed: +RP.get('sm_s', 2026) }; const L = sampleVch(o); const desc = `${{ rand: 'Random (seed ' + o.seed + ')', top: 'Largest amounts', nth: 'Systematic' }[o.m]} · ${L.length} vouchers${o.min ? ' ≥ ₹' + o.min : ''}`;
  if (k === 'x') return xlsx(`Voucher_Sample_${S.fy.label}`, [{ name: 'Sample', rows: [['#', 'Date', 'Voucher', 'Particulars', 'Narration', 'Amount', 'Bill / invoice seen', 'Approval seen', 'Remarks'], ...L.map(([, v], i) => [i + 1, fd(v.d), v.no, vParticulars(v), v.nar || '', vAmount(v), '', '', ''])], cols: [5, 11, 11, 32, 34, 13, 12, 12, 24] }]);
  printReport('Voucher Sample — Vouching Checklist', `FY ${S.fy.label} · ${desc}`, `<table><thead><tr><th>#</th><th>Date</th><th>Voucher</th><th>Particulars</th><th class="n">Amount</th><th>Bill seen</th><th>Approval</th><th>Remarks</th></tr></thead><tbody>${L.map(([, v], i) => `<tr><td>${i + 1}</td><td>${fd(v.d)}</td><td>${esc(v.no)}</td><td>${esc(vParticulars(v))}</td><td class="n">${fmt(vAmount(v))}</td><td style="width:60px"></td><td style="width:60px"></td><td style="width:110px"></td></tr>`).join('')}</tbody></table>`); }

// ── 68. Investment maturity calendar & reinvestment plan ────────────────
page('invcal', {
  render() {
    const L = Object.entries(S.inv || {}).filter(([, x]) => x && x.status !== 'Closed' && x.mat).sort((a, b) => a[1].mat.localeCompare(b[1].mat)); const t = today(); const by = {};
    L.forEach(([id, x]) => { const k = x.mat < t ? 'past' : x.mat.slice(0, 7); (by[k] = by[k] || []).push([id, x]); });
    const keys = Object.keys(by).sort((a, b) => (a === 'past' ? -1 : b === 'past' ? 1 : a.localeCompare(b)));
    shell('📆 Investment Maturity Calendar', 'Deposits falling due month by month, with a reinvestment plan for each', `<button class="ghost" onclick="go('inv')">💰 Investments register</button>`,
      `${!L.length ? '<div class="empty">No active deposits with a maturity date.</div>' : ''}${keys.map(k => `<div class="card" style="margin-bottom:10px"><h3>${k === 'past' ? '<span class="dr">Matured — not yet closed</span>' : monLbl(k + '-01')} <span class="small muted">₹${fmt(sum(by[k], ([, x]) => +x.matAmt || +x.amt || 0))}</span></h3><div class="tw"><table><thead><tr><th>Maturity</th><th>Bank</th><th>No.</th><th class="n">Principal</th><th class="n">Rate</th><th class="n">Maturity amount</th><th>Plan</th><th></th></tr></thead><tbody>
        ${by[k].map(([id, x]) => `<tr><td>${fd(x.mat)} <span class="small muted">${daysBetween(t, x.mat) >= 0 ? 'in ' + daysBetween(t, x.mat) + ' d' : ''}</span></td><td>${esc(x.bank)}</td><td class="small">${esc(x.no || '')}</td><td class="n">${fmt(x.amt)}</td><td class="n">${x.rate || ''}%</td><td class="n">${x.matAmt ? fmt(x.matAmt) : ''}</td><td><select class="ic-p" data-i="${id}" onchange="icPlan('${id}',this.value)" ${canEdit() ? '' : 'disabled'} style="min-width:0">${['', 'Renew in same bank', 'Renew — compare rates', 'Move to another bank', 'Withdraw for expenses', 'Transfer to Sinking / Repair fund investment'].map(p => `<option ${(x.plan || '') === p ? 'selected' : ''} value="${esc(p)}">${p || '— plan —'}</option>`).join('')}</select></td><td>${canEdit() ? `<button class="xs" onclick="invMature('${id}')">Mature / renew</button>` : ''}</td></tr>`).join('')}</tbody></table></div></div>`).join('')}`);
  }
});
async function icPlan(id, p) { guardEdit(); await commit({ [`inv/${id}/plan`]: p || null }, { a: 'edit', e: 'investment', s: `${S.inv[id].bank} ${S.inv[id].no || ''}: plan "${p}"` }); toast('Plan saved'); }

// ── 70. Annual maintenance statement per member ─────────────────────────
function annStmt(mid) {
  const I = IDS(); const m = M(mid) || {}; const ob = ENG.memberOB(S, mid); const r = ENG.replayMember(S, mid, { lines: L_() }); const heads = {}; let int = 0, gst = 0;
  for (const b of Object.values(S.bills)) { if (!b || b.mid !== mid) continue; for (const [h, a] of Object.entries(b.ch || {})) heads[h] = r2((heads[h] || 0) + (+a || 0)); int = r2(int + (+b.int || 0)); if (b.gst) gst = r2(gst + (+b.gst.c || 0) + (+b.gst.s || 0)); }
  const ls = L_().filter(l => l.h === I.dues && l.m === mid && l.src === 'v'); const rc = ls.filter(l => l.t === 'R' && !l.bnc); const paid = r2(sum(rc, l => l.cr)); const other = r2(sum(ls.filter(l => l.t !== 'R' && !l.rev && !l.bnc), l => l.cr - l.dr));
  return { m, ob: r2(ob.p + ob.n + ob.i), heads: Object.entries(heads).sort((a, b) => ((H(a[0]).bill || {}).order || 99) - ((H(b[0]).bill || {}).order || 99)), int, gst, rc, paid, other, close: r.bal };
}
function annStmtHtml(mid) { const s = annStmt(mid); const row = (l, a, b) => `<tr${b ? ' class="tot"' : ''}><td>${l}</td><td class="n">${fmt(a)}</td></tr>`;
  return `<div class="doc nb" style="margin-bottom:12px">${letterhead(true)}${accTitle('ANNUAL STATEMENT OF ACCOUNT', `FY ${S.fy.label} (${fd(S.fy.start)} to ${fd(S.fy.end)})`)}<div class="meta"><div>Member: <b>${esc(s.m.name || '')}</b>${s.m.name2 ? ' & ' + esc(s.m.name2) : ''}<br>Flat: <b>${esc(flatLbl(s.m))}</b>${s.m.area ? ' · ' + s.m.area + ' sq.ft' : ''}</div><div class="right">Date: ${fd(today())}</div></div>
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px"><table><tbody>${row(s.ob < 0 ? 'Opening advance' : 'Opening balance', s.ob)}${s.heads.map(([h, a]) => row(H(h).name, a)).join('')}${s.int ? row('Interest on arrears', s.int) : ''}${s.gst ? row('GST', s.gst) : ''}${row('Total charged during the year', r2(s.ob + sum(s.heads, x => x[1]) + s.int + s.gst), 1)}${s.other ? row('Less: credits / adjustments (net)', s.other) : ''}${row('Less: paid during the year', s.paid)}${row(s.close < 0 ? 'Closing advance' : 'Balance outstanding', Math.abs(s.close), 1)}</tbody></table>
    <table><thead><tr><th>Date</th><th>Receipt</th><th class="n">Amount</th></tr></thead><tbody>${s.rc.map(l => `<tr><td>${fd(l.d)}</td><td>${esc(l.no || '')}${l.mode ? ' · ' + esc(l.mode) : ''}</td><td class="n">${fmt(l.cr)}</td></tr>`).join('') || '<tr><td colspan="3">No payments</td></tr>'}<tr class="tot"><td colspan="2">Total paid</td><td class="n">${fmt(s.paid)}</td></tr></tbody></table></div>
    <p class="small" style="margin-top:6px">This statement is for your records${s.paid ? ' and may be used for your income-tax / HRA purposes' : ''}. Please report any difference to the society office.</p>${billSign('bill', 30)}</div>`; }
page('annstmt', {
  render() {
    const L = memSorted(false);
    shell('📄 Annual Statement per Member', `What each member was charged and paid in FY ${esc(S.fy.label)} — print for all, or one at a time`, `<button class="ghost" onclick="annAll()">🖨 Print all (${L.length})</button><button class="ghost" onclick="annXl()">📥 Excel</button>`,
      `<div class="tw tall"><table><thead><tr><th>Flat</th><th>Member</th><th class="n">Opening</th><th class="n">Charged</th><th class="n">Paid</th><th class="n">Closing</th><th></th></tr></thead><tbody>${L.map(([mid, m]) => { const s = annStmt(mid); const ch = r2(sum(s.heads, x => x[1]) + s.int + s.gst); return `<tr><td class="b">${esc(flatLbl(m))}</td><td class="small">${esc(m.name)}</td><td class="n">${fmt(s.ob)}</td><td class="n">${fmt(ch)}</td><td class="n">${fmt(s.paid)}</td><td class="n ${s.close > 0 ? 'dr' : ''}">${fmt(s.close)}</td><td><button class="xs ghost" onclick="printDoc('Annual statement',annStmtHtml('${mid}'))">🖨</button></td></tr>`; }).join('')}</tbody></table></div>`);
  }
});
function annAll() { printDoc('Annual statements', memSorted(false).map(([mid]) => annStmtHtml(mid)).join('<div class="pb"></div>')); }
function annXl() { const hs = billHeads(); xlsx(`Annual_Statement_${S.fy.label}`, [{ name: 'Members', rows: [['Flat', 'Member', 'Opening', ...hs.map(([, h]) => h.name), 'Other heads', 'Interest', 'GST', 'Credits', 'Paid', 'Closing'], ...memSorted(false).map(([mid, m]) => { const s = annStmt(mid); const hm = Object.fromEntries(s.heads); const oth = r2(sum(s.heads.filter(([h]) => !hs.some(([x]) => x === h)), x => x[1])); return [flatLbl(m), m.name, s.ob, ...hs.map(([h]) => hm[h] || 0), oth, s.int, s.gst, s.other, s.paid, s.close]; })], cols: [9, 26, 12, ...hs.map(() => 13), 12, 11, 10, 11, 12, 12] }]); }

navAdd('Final Accounts', ['schedules', '📎', 'BS Schedules'], 'bs');
navAdd('Final Accounts', ['cashflow', '💧', 'Cash Flow Statement'], 'rp');
