  if (last.sign) up['meta/settings/bill/sign'] = last.sign; if (last.meta) { if (last.meta.name) up['meta/name'] = last.meta.name; if (last.meta.regNo) up['meta/regNo'] = last.meta.regNo; if (last.meta.address) up['meta/address'] = last.meta.address; }
  for (const y of years) { up[`fys/${y.fid}`] = { label: fyLabelFor(y.fs), start: y.fs, end: fyEndFor(y.fs), closed: false }; up[`ob/${y.fid}`] = { ...y.ob, imp: 1 }; up[`runs/${y.fid}`] = y.runs; for (const [k, v] of Object.entries(y.counters)) up[`counters/${y.fid}/${k}`] = v; }
