    for (const id of inLast) { const src = Object.entries(last.members).find(([pid]) => mm[pid] === id); if (src && S.members[id]) { const m = src[1]; for (const f of ['name', 'phone', 'email', 'area']) if (m[f] && m[f] !== S.members[id][f]) up[`members/${id}/${f}`] = m[f]; if (S.members[id].active === false) up[`members/${id}/active`] = true; } }
