  for (const k of Object.keys(up)) if (/^counters\/[^/]+$/.test(k) && Object.keys(up).some(x => x.startsWith(k + '/'))) delete up[k];
  await commit(up, { a: 'import', e: 'MAXX', s: `Added MAXX years ${years.map(y => fyLabelFor(y.fs)).join(', ')} — ${Object.keys(M.newHeads).length} new accounts, ${Object.keys(M.newMembers).length} new members` });
  for (const y of years) for (const [kind, obj] of [['bills', y.bills], ['vch', y.vch]]) { const ks = Object.keys(obj); for (let i = 0; i < ks.length; i += 400) { say(`FY ${fyLabelFor(y.fs)}: saving ${kind === 'vch' ? 'vouchers' : 'bills'} ${i + 1}–${Math.min(i + 400, ks.length)} of ${ks.length}…`); const m = {}; ks.slice(i, i + 400).forEach(k => m[sp(`${kind}/${y.fid}/${k}`)] = obj[k]); await FBX.update(m); } }
