    const R = await aiTry('Reading the cheque…', () => aiRun('This is a photo of an Indian bank cheque given to a housing society. Return {"cheque_no":"6 digits at bottom-left of the MICR line","date":"YYYY-MM-DD","bank":"drawee bank name","branch":"","ifsc":"","amount":number (figures),"amount_words_matches":true|false,"payee":"","drawer":"account holder name printed / signed","account_no":""}. If several cheques are shown, return {"cheques":[...]} with one object each.', files)); if (!R) return;
    const L = R.cheques || [R]; if (L.length > 1 || CUR.id !== 'receipt') return aiChqBulk(L);
