      e('vf-amt', R.total); e('vf-nar', [R.description, R.vendor && 'to ' + R.vendor, R.bill_no && 'bill no. ' + R.bill_no, R.bill_date && 'dt ' + fd(R.bill_date), R.period && 'for ' + R.period].filter(Boolean).join(' ').replace(/^./, c => c.toUpperCase()));
