  let acc = ''; if (o.acc) { const m = memLabelList().find(x => x.label.toLowerCase() === o.acc.toLowerCase()); const h = headLabelList().find(x => x.label.toLowerCase() === o.acc.toLowerCase()); acc = m ? 'M:' + m.mid : h ? h.id : ''; }
