  if (acc) { apSet('vf-acc', acc); vfAccChanged(acc); } const e = (id, v) => { const x = $(id); if (x && v != null && v !== '') { x.value = v; x.dispatchEvent(new Event('input')); } };
  e('vf-amt', o.amt); if (o.mode && $('vf-mode')) $('vf-mode').value = o.mode; e('vf-chq', o.ref); e('vf-nar', o.nar);
  toast(acc ? 'Filled — check and save' : 'Filled — choose the ' + (kind === 'R' ? 'member' : 'head'), acc ? 'ok' : 'warn');
