// ── 15: recurring-payment suggestions from history ──────────────────────────────────────────────
function recurSuggest() {
  const have = new Set(Object.values(REC()).filter(Boolean).map(r => r.h)); const G = {};
  for (const v of Object.values(S.vch)) { if (!v || v.t !== 'P') continue; const o = (v.lines || []).find(l => l.dr && !isCB(l.h) && l.h !== IDS().tds); const c = (v.lines || []).find(l => l.cr && isCB(l.h)); if (!o || !c) continue; const k = o.h; (G[k] = G[k] || []).push({ m: v.d.slice(0, 7), a: vAmount(v), cb: c.h, mode: v.mode, nar: v.nar, day: +v.d.slice(8) }); }
  return Object.entries(G).filter(([h]) => !have.has(h)).map(([h, L]) => { const ms = new Set(L.map(x => x.m)); const am = L.map(x => x.a).sort((a, b) => a - b); const med = am[Math.floor(am.length / 2)]; const near = L.filter(x => Math.abs(x.a - med) <= med * 0.1);
    return { h, months: ms.size, n: L.length, amt: med, cb: L[L.length - 1].cb, mode: L[L.length - 1].mode, day: Math.min(28, Math.round(sum(L, x => x.day) / L.length) || 5), nar: L[L.length - 1].nar, steady: near.length / L.length }; })
    .filter(x => x.months >= 3 && x.n <= x.months + 1 && x.steady >= 0.6).sort((a, b) => b.months - a.months);
}
function recurSuggestModal() { const L = recurSuggest(); AIX.rs = L;
  openModal({ title: '💡 Payments that repeat every month', wide: true, ok: L.length ? 'Make ticked recurring' : '', hideOk: !L.length, body: L.length ? `<p class="small muted">Found from this year's payments — same head, about the same amount, month after month.</p><div class="tw"><table><thead><tr><th></th><th>Head</th><th class="n">Usual amount</th><th>Months</th><th>Day</th><th>Mode</th></tr></thead><tbody>${L.map((x, i) => `<tr><td><input type="checkbox" class="rs-ck" data-i="${i}" checked></td><td>${esc(H(x.h).name)}<div class="small muted">${esc(x.nar || '')}</div></td><td class="n">${fmt(x.amt)}</td><td>${x.months}</td><td>${x.day}</td><td class="small">${esc(x.mode || '')}</td></tr>`).join('')}</tbody></table></div>` : '<p class="muted">No monthly pattern found yet (needs at least 3 months of payments).</p>',
    onOk: async () => { guardEdit(); const up = {}; $$('.rs-ck').filter(c => c.checked).forEach(c => { const x = AIX.rs[+c.dataset.i]; up[`bcfg/_rec/${FBX.key('r')}`] = { h: x.h, cb: x.cb, amt: x.amt, day: x.day, mode: x.mode || 'NEFT', on: true, nar: x.nar || '', base: today().slice(0, 7) }; }); if (!Object.keys(up).length) throw new Error('Nothing ticked'); await commit(up, { a: 'create', e: 'Recurring payment', s: `${Object.keys(up).length} recurring payment(s) from suggestions` }); toast('Recurring payments created'); } }); }
// ── 18: paste from Excel ────────────────────────────────────────────────────────────────────────
function pasteParse(t) { return String(t || '').replace(/\r/g, '').split('\n').filter(l => l.trim()).map(l => l.split('\t').map(c => c.trim())); }
function pasteModal(kind) {
  openModal({ title: '📋 Paste from Excel', wide: true, ok: 'Use these rows', body: `<p class="small muted" style="margin-bottom:6px">${kind === 'members' ? 'Copy the member rows in Excel (with or without the heading row) — any column order: wing, flat, name, joint member, mobile, email, area…' : 'Copy the rows in Excel / Google Sheets — any column order: flat, amount, date, mode, cheque / UTR, narration. A heading row helps but is not needed.'} Then paste here (Ctrl+V).</p><textarea id="ps-t" rows="12" style="width:100%;font-family:var(--mono);font-size:12px" placeholder="Paste here"></textarea>`,
    onOk: () => { const G = pasteParse(val('ps-t')); if (!G.length) throw new Error('Nothing pasted'); kind === 'members' ? pasteMembers(G) : pasteBulk(G); } });
}
function pasteCols(G) {
  const hd = G[0].map(c => c.toLowerCase()); const isHead = hd.some(c => /flat|amount|date|name|mode|ref|utr|cheque/.test(c)); const body = isHead ? G.slice(1) : G; const ix = flatIndex(); const nc = Math.max(...G.map(r => r.length)); const col = {};
  const by = re => hd.findIndex(c => re.test(c)); if (isHead) { col.flat = by(/flat|unit|room/); col.amt = by(/amount|amt|rs|₹|paid|credit|deposit/); col.d = by(/date/); col.mode = by(/mode/); col.ref = by(/ref|utr|cheque|chq/); col.nar = by(/narr|remark|note|particular/); col.wing = by(/wing|bldg/); }
  for (let c = 0; c < nc; c++) { const vals = body.map(r => r[c] || '').filter(Boolean); if (!vals.length || Object.values(col).includes(c)) continue; const frac = f => vals.filter(f).length / vals.length;
    if (col.flat == null || col.flat < 0) { if (frac(v => ix[v.toLowerCase().replace(/\s+/g, '')]) > 0.6) { col.flat = c; continue; } }
    if (col.d == null || col.d < 0) { if (frac(v => /^\d{1,2}[\/\-.]\d{1,2}[\/\-.]\d{2,4}$|^\d{4}-\d{2}-\d{2}$|^\d{1,2}[ -][A-Za-z]{3}/.test(v)) > 0.6) { col.d = c; continue; } }
    if (col.mode == null || col.mode < 0) { if (frac(v => /^(cash|cheque|chq|upi|neft|rtgs|imps|online)$/i.test(v)) > 0.6) { col.mode = c; continue; } }
    if (col.ref == null || col.ref < 0) { if (frac(v => /^\d{6,22}$/.test(v.replace(/\s/g, ''))) > 0.6) { col.ref = c; continue; } }
    if (col.amt == null || col.amt < 0) { if (frac(v => /^₹?\s*[\d,]+(\.\d{1,2})?$/.test(v) && numv(v) > 0) > 0.6) { col.amt = c; continue; } } }
  return { body, col };
}
function pasteBulk(G) {
  const { body, col } = pasteCols(G); if (!(col.flat >= 0) || !(col.amt >= 0)) throw new Error('Could not find the flat and amount columns — add a heading row (Flat, Amount, Date, Mode, Ref)');
  const g = (r, k) => (col[k] >= 0 ? r[col[k]] || '' : ''); const MO = { chq: 'Cheque', cheque: 'Cheque', cash: 'Cash', upi: 'UPI', neft: 'NEFT', rtgs: 'RTGS', imps: 'IMPS', online: 'NEFT' };
  const rows = body.filter(r => g(r, 'flat') && numv(g(r, 'amt')) > 0).map(r => ({ flat: (col.wing >= 0 && r[col.wing] ? r[col.wing] + '-' : '') + g(r, 'flat'), amt: r2(numv(g(r, 'amt'))), d: excelDate(g(r, 'd')) || '', mode: MO[g(r, 'mode').toLowerCase()] || '', ref: g(r, 'ref'), nar: g(r, 'nar') }));
  if (CUR.id !== 'bulk') go('bulk'); setTimeout(() => { $('bk-body').innerHTML = ''; BULK.n = 0; bulkAddRows(rows.length + 3, rows); bulkTot(); toast(`${rows.length} rows pasted — check and Save all`, 'ok'); }, 150);
}
function pasteMembers(G) {
  const hd = G[0].map(c => c.toLowerCase()); const isHead = hd.some(c => /flat|name|mobile|wing/.test(c)); const body = isHead ? G.slice(1) : G; const by = re => isHead ? hd.findIndex(c => re.test(c)) : -1;
  let c = { w: by(/wing|bldg/), f: by(/flat|unit|room/), n: by(/^name|member|owner/), j: by(/joint|second/), m: by(/mob|phone|contact/), e: by(/mail/), a: by(/area|sq/) };
  if (!isHead) { const nc = Math.max(...body.map(r => r.length)); for (let k = 0; k < nc; k++) { const vals = body.map(r => r[k] || '').filter(Boolean); const fr = f => vals.filter(f).length / Math.max(1, vals.length); if (c.f < 0 && fr(v => /^\w?-?\d{1,4}$/.test(v)) > 0.7) c.f = k; else if (c.m < 0 && fr(v => /^[6-9]\d{9}$/.test(v.replace(/\D/g, '').slice(-10))) > 0.7) c.m = k; else if (c.e < 0 && fr(v => /@/.test(v)) > 0.7) c.e = k; else if (c.n < 0 && fr(v => /[a-z]{3,}/i.test(v)) > 0.7) c.n = k; } }
  if (!(c.f >= 0) || !(c.n >= 0)) throw new Error('Could not find the flat and name columns — add a heading row (Wing, Flat, Name, Mobile, Email)');
  const g = (r, k) => (c[k] >= 0 ? r[c[k]] || '' : ''); const rows = body.filter(r => g(r, 'f') && g(r, 'n')).map(r => [g(r, 'w'), g(r, 'f'), g(r, 'n'), g(r, 'j'), 'Flat', g(r, 'a'), g(r, 'm'), g(r, 'e'), '', '', '', '', '', 'Yes']);
  const wb = XLSX.utils.book_new(); XLSX.utils.book_append_sheet(wb, XLSX.utils.aoa_to_sheet([MEM_COLS, ...rows]), 'Members'); asPickedFile(wb, 'Pasted members.xlsx', importMembers);
}
// ── 19: bills & statements straight from Gmail ──────────────────────────────────────────────────
const GIS_URL = 'https://accounts.google.com/gsi/client';
async function gmailToken() {
  const cid = (aiCfg() || {}).gcid; if (!cid) throw new Error('Gmail is not linked — add the Google OAuth Client ID in All Societies → 🤖 AI');
  if (AIX.tok && AIX.tokExp > Date.now()) return AIX.tok; if (typeof google === 'undefined' || !google.accounts) await loadScript(GIS_URL);
  return new Promise((res, rej) => { const tc = google.accounts.oauth2.initTokenClient({ client_id: cid, scope: 'https://www.googleapis.com/auth/gmail.readonly', callback: r => { if (r.error) return rej(new Error(r.error)); AIX.tok = r.access_token; AIX.tokExp = Date.now() + (r.expires_in || 3000) * 1000 - 60000; res(r.access_token); } }); tc.requestAccessToken(); });
}
async function gmailGet(path, tok) { const r = await fetch('https://gmail.googleapis.com/gmail/v1/users/me/' + path, { headers: { Authorization: 'Bearer ' + tok } }); const j = await r.json(); if (!r.ok) throw new Error((j.error || {}).message || 'Gmail error'); return j; }
async function gmailPick(then) {
  const tok = await aiTry('Opening Gmail…', gmailToken); if (!tok) return; const q = encodeURIComponent('has:attachment newer_than:45d (filename:pdf OR filename:jpg OR filename:jpeg OR filename:png OR filename:xlsx OR filename:xls OR filename:csv)');
  const L = await aiTry('Looking for statements and bills…', async () => { const j = await gmailGet(`messages?maxResults=25&q=${q}`, tok); const out = [];
    for (const m of j.messages || []) { const x = await gmailGet(`messages/${m.id}?format=full`, tok); const hd = n => ((x.payload.headers || []).find(h => h.name.toLowerCase() === n) || {}).value || ''; const walk = p => [p, ...(p.parts || []).flatMap(walk)];
      walk(x.payload).filter(p => p.filename && p.body && p.body.attachmentId).forEach(p => out.push({ mid: m.id, aid: p.body.attachmentId, name: p.filename, mime: p.mimeType, subj: hd('subject'), from: hd('from'), date: hd('date') })); } return out; }); if (!L) return;
  AIX.gm = L; openModal({ title: '📧 Attachments in Gmail (last 45 days)', xwide: true, hideOk: true, cancel: 'Close', body: L.length ? `<div class="tw" style="max-height:60vh"><table><thead><tr><th>File</th><th>Email</th><th>From</th><th></th></tr></thead><tbody>${L.map((x, i) => `<tr><td>${esc(x.name)}</td><td class="small">${esc(x.subj)}<div class="muted">${esc(x.date)}</div></td><td class="small">${esc(x.from)}</td><td><button class="xs" onclick="gmailUse(${i},'${then}')">Use</button></td></tr>`).join('')}</tbody></table></div>` : '<p class="muted">No attachments found.</p>' });
}
async function gmailUse(i, then) { const x = AIX.gm[i]; const tok = await gmailToken(); const j = await gmailGet(`messages/${x.mid}/attachments/${x.aid}`, tok); const bin = atob(j.data.replace(/-/g, '+').replace(/_/g, '/')); const u = new Uint8Array(bin.length); for (let k = 0; k < bin.length; k++) u[k] = bin.charCodeAt(k);
  const f = new File([u], x.name, { type: x.mime }); closeAllModals(); const pf = pickFiles; window.pickFiles = pickFiles = (a, cb) => cb([f]); try { ({ stmt: aiStatement, bill: aiBill, fd: aiFD, as: ai26AS })[then](); } finally { window.pickFiles = pickFiles = pf; } }
// ── buttons on the pages ────────────────────────────────────────────────────────────────────────
addAct('receipt', () => canEdit() ? `<button class="ghost" onclick="aiCheque()" title="Photo of a cheque → receipt filled in">📷 Cheque</button><button class="ghost" onclick="aiShots()" title="UPI / bank payment screenshots → receipts awaiting bank confirmation">📸 Screenshots</button><button class="ghost" onclick="aiVoice()" title="Say: Received 3500 from A 101 by UPI">🎤</button>` : '');
addAct('payment', () => canEdit() ? `<button class="ghost" onclick="aiBill()" title="Photo / PDF of the bill → payment filled in">📷 Bill</button>${(aiCfg() || {}).gcid ? `<button class="ghost" onclick="gmailPick('bill')">📧 From Gmail</button>` : ''}<button class="ghost" onclick="aiVoice()" title="Say: Paid 4500 to MSEB electricity by NEFT">🎤</button>` : '');
addAct('bstmt', () => canEdit() ? `<button onclick="aiStatement()" title="PDF / photos / Excel of the statement or passbook — read by AI, no template needed">🤖 Read statement with AI</button>${(aiCfg() || {}).gcid ? `<button class="ghost" onclick="gmailPick('stmt')">📧 From Gmail</button>` : ''}` : '');
addAct('bulk', () => canEdit() ? `<button class="ghost" onclick="pasteModal('bulk')">📋 Paste from Excel</button><button class="ghost" onclick="aiCheque()" title="Photo of several cheques">📷 Cheques</button>` : '');
addAct('members', () => canEdit() ? `<button class="ghost" onclick="pasteModal('members')">📋 Paste</button><button class="ghost" onclick="aiMembers()" title="Member list in any layout — photo, PDF, Excel">🤖 From any list</button><button class="ghost" onclick="aiTable()" title="Photo of an old register → Excel / members">📷 Register</button>` : '');
addAct('bsetup', () => canEdit() ? `<button class="ghost" onclick="aiBillRates()" title="Last bills (PDF / photos) → amounts filled in the grid">🤖 Rates from bills</button>` : '');
addAct('inv', () => canEdit() ? `<button class="ghost" onclick="aiFD()">📷 From FD receipt</button>` : '');
addAct('tdsreg', () => `<button class="ghost" onclick="ai26AS()">🤖 Check with 26AS / 16A</button>`);
addAct('recur', () => canEdit() ? `<button class="ghost" onclick="recurSuggestModal()">💡 Suggestions</button>` : '');
addAct('data', () => `<button class="ghost" onclick="aiTable()">📷 Register → Excel</button>`);

// ═══════════════════════════════════════════════════════════════════════
// COLLECTION & RECOVERY — features 22–35
//  22 UPI "Pay now" link on every WhatsApp bill (public pay page, no gateway charges)
//  23 Reminder run by stage (gentle → firm → final → notice), one click per member, sent marks kept
//  24 Reminder letters written by AI for each member's history (template letters without AI)
//  25 Defaulter risk score · 35 collection forecast (dashboard + Collection page)
//  26 Interest-waiver rule (paid within N days of due) · 27 rate-revision wizard
//  28 "Why this bill is different" line on bills · 30 non-occupancy from the Tenant Register
//  31 Instalment plans for arrears · 32 Recovery workflow up to the Section 154B-29 application
//  34 Bill language per member
// Data: bcfg/_coll {explain, grace, tnAuto} · bcfg/_rms/{mid} {stage, at} · members/{mid}/inst · members/{mid}/rcv · members/{mid}/lang
// ═══════════════════════════════════════════════════════════════════════
const COLL = () => BC('_coll');
const monthlyOf = mid => r2(sum(Object.entries((S.bcfg || {})[mid] || {}).filter(([k]) => k[0] !== '_'), ([, v]) => +v || 0));
const daysAgo = d => Math.floor((pd(today()) - pd(d)) / 864e5);
// oldest unpaid bill → days past its due date
function overdueOf(mid) { const f = ENG.fifo(S, mid, { lines: L_() }); const o = (f.open || []).find(x => x.bal > 0.5); if (!o) return { days: 0, since: '' }; const b = S.bills[o.ref]; const due = (b && b.due) || o.d || S.fy.start; return { days: Math.max(0, daysAgo(due)), since: due }; }
// ── 25: risk score 0–100 ─────────────────────────────────────────────────
function riskOf(mid) {
  const bal = (MB()[mid] || {}).bal || 0; const mon = monthlyOf(mid) || 1; const owe = Math.max(0, bal / mon);
  const bills = Object.values(S.bills).filter(b => b && b.mid === mid && !b.supp).sort((a, b) => a.d.localeCompare(b.d)).slice(-6);
  const rc = Object.values(S.vch).filter(v => v && v.t === 'R' && vMembers(v).includes(mid)); const rcD = rc.filter(v => !v.bnc).map(v => v.d).sort();
  let late = 0, n = 0; for (const b of bills) { const due = b.due || b.d; if (due > today()) continue; const p = rcD.find(d => d >= b.d); const delay = p ? daysBetween(due, p) : daysAgo(due); late += Math.max(0, delay); n++; }
  const avgLate = n ? late / n : 0; const bnc = rc.filter(v => v.bnc).length;
  const b0 = (bills[0] || {}).d || today(); const mset = new Set(rcD.filter(d => d >= b0).map(d => d.slice(0, 7))); const bset = new Set(bills.map(b => b.d.slice(0, 7))); const reg = bset.size ? Math.min(1, mset.size / bset.size) : 1;
  const sc = Math.round(Math.min(100, 35 * Math.min(1, owe / 2) + 30 * Math.min(1, avgLate / 30) + 20 * (1 - reg) + 15 * Math.min(1, bnc / 2)));
  return { sc, lvl: sc >= 60 ? 'High' : sc >= 30 ? 'Medium' : 'Low', owe: r2(owe), avgLate: Math.round(avgLate), bnc, bal };
}
const riskTag = r => `<span class="tag ${r.lvl === 'High' ? 't-err' : r.lvl === 'Medium' ? 't-warn' : 't-ok'}" title="Months owed ${r.owe} · avg ${r.avgLate} days late · ${r.bnc} bounced">${r.lvl} ${r.sc}</span>`;
// ── 35: forecast ─────────────────────────────────────────────────────────
function collForecast() {
  const m0 = today().slice(0, 7); const back = k => { const d = pd(m0 + '-01'); d.setMonth(d.getMonth() - k); return ymd(d).slice(0, 7); }; const last3 = [1, 2, 3].map(back);
  const billed = sum(Object.values(S.bills).filter(b => b && last3.includes(b.d.slice(0, 7))), b => ENG.billTotal(b)); const coll = sum(Object.values(S.vch).filter(v => v && v.t === 'R' && !v.bnc && last3.includes(v.d.slice(0, 7))), v => sum(v.lines.filter(l => l.m && l.cr), l => l.cr));
  const eff = billed > 0 ? Math.min(1.2, coll / billed) : 0.85; const due = r2(sum(Object.values(MB()), b => Math.max(0, b.bal || 0)));
  const thisMonth = r2(sum(Object.values(S.vch).filter(v => v && v.t === 'R' && !v.bnc && v.d.slice(0, 7) === m0), v => sum(v.lines.filter(l => l.m && l.cr), l => l.cr)));
  const monthly = r2(sum(Object.keys(S.members).filter(k => S.members[k] && S.members[k].active !== false), monthlyOf));
  return { eff, due, exp: r2(Math.min(due, monthly * eff)), monthly, got: thisMonth };
}
// ── 23: reminder stages ──────────────────────────────────────────────────
const REM_ST = [{ k: 1, n: 'Gentle reminder', min: 1 }, { k: 2, n: 'Firm reminder', min: 15 }, { k: 3, n: 'Final reminder', min: 45 }, { k: 4, n: 'Notice before recovery', min: 90 }];
const remStage = days => (days >= 90 ? 4 : days >= 45 ? 3 : days >= 15 ? 2 : days >= 1 ? 1 : 0);
function remText(mid, st) { const m = M(mid), b = MB()[mid] || {}; const o = overdueOf(mid); const amt = fmt(b.bal || 0); const soc = S.meta.name || 'the society';
  return ({ 1: `Dear ${m.name} (${flatLbl(m)}), a gentle reminder that ₹${amt} is due to ${soc} (since ${fd(o.since)}). Kindly pay at the earliest. Please ignore if already paid. — Secretary`,
    2: `Dear ${m.name} (${flatLbl(m)}), our records show ₹${amt} outstanding to ${soc} for ${o.days} days. Interest is being charged as per the bye-laws. Please clear the dues within 7 days. — Secretary`,
    3: `FINAL REMINDER: Dear ${m.name} (${flatLbl(m)}), ₹${amt} has been outstanding for ${o.days} days. Please pay within 7 days, failing which the Managing Committee will be constrained to take action as per the bye-laws and the MCS Act. — Secretary, ${soc}`,
    4: `Dear ${m.name} (${flatLbl(m)}), despite reminders ₹${amt} remains unpaid for ${o.days} days. A formal notice is being issued; the society may apply for recovery under Section 154B-29 of the Maharashtra Co-operative Societies Act, 1960. — Secretary, ${soc}` })[st] || ''; }
function payLink(mid, amt) { const st = SET().bill; if (!st.upi) return ''; const m = M(mid) || {}; const q = new URLSearchParams({ pay: '1', v: st.upi, n: S.meta.name || '', a: r2(Math.max(0, amt || 0)).toFixed(2), f: flatLbl(m), s: S.meta.name || '', w: waNum(S.meta.phone || '') || '' }); return location.origin + location.pathname + '?' + q.toString(); }
// ── page ─────────────────────────────────────────────────────────────────
page('coll', {
  render() {
    const tab = RP.get('cl_tab', 'risk'); const T = [['risk', '📊 Risk & forecast'], ['rem', '📨 Reminders'], ['inst', '🗓 Instalments'], ['rcv', '⚖ Recovery'], ['tools', '🛠 Rules & tools']];
    shell('💰 Collection & Recovery', 'Who will pay late, reminders by stage, instalment plans and recovery under Section 154B-29', '', `<div class="tabs" style="margin-bottom:12px">${T.map(([k, l]) => `<button class="${k === tab ? '' : 'ghost'} sm" onclick="RP.set('cl_tab','${k}');render()">${l}</button>`).join(' ')}</div><div id="cl-b"></div>`);
    ({ risk: clRisk, rem: clRem, inst: clInst, rcv: clRcv, tools: clTools })[tab]();
  }
});
function clMembers() { return memSorted(false).filter(([, m]) => m.active !== false); }
function clRisk() {
  const F = collForecast(); const L = clMembers().map(([mid, m]) => ({ mid, m, r: riskOf(mid) })).filter(x => x.r.bal > 0.5).sort((a, b) => b.r.sc - a.r.sc);
  $('cl-b').innerHTML = `<div class="grid g4" style="margin-bottom:12px"><div class="stat"><div class="v">₹${fmt0(F.exp)}</div><div class="l">expected to come in this month</div></div><div class="stat"><div class="v">₹${fmt0(F.got)}</div><div class="l">received so far this month</div></div><div class="stat"><div class="v">${Math.round(F.eff * 100)}%</div><div class="l">collection rate, last 3 months</div></div><div class="stat"><div class="v dr">₹${fmt0(F.due)}</div><div class="l">total outstanding</div></div></div>
    <div class="tw"><table><thead><tr><th>Flat</th><th>Member</th><th class="n">Outstanding</th><th class="n">Months owed</th><th class="n">Avg days late</th><th class="n">Bounced</th><th>Risk</th><th></th></tr></thead><tbody>
    ${L.map(x => `<tr><td class="b">${esc(flatLbl(x.m))}</td><td>${esc(x.m.name)}</td><td class="n">${fmt(x.r.bal)}</td><td class="n">${x.r.owe}</td><td class="n">${x.r.avgLate}</td><td class="n">${x.r.bnc || ''}</td><td>${riskTag(x.r)}</td><td><button class="xs ghost" onclick="go('mledger','${x.mid}')">Ledger</button></td></tr>`).join('') || '<tr><td colspan="8" class="empty">No member owes anything 🎉</td></tr>'}</tbody></table></div>
    <p class="small muted" style="margin-top:6px">Risk = months owed (35%, full at 2 months) + average days paid after the due date (30%, full at 30 days) + bill months without any payment, last 6 bills (20%) + bounced cheques (15%).</p>`;
}
function clRem() {
  const rem = BC('_rms'); const L = clMembers().map(([mid, m]) => { const b = MB()[mid] || {}; if (!(b.bal > 0.5)) return null; const o = overdueOf(mid); return { mid, m, bal: b.bal, o, st: remStage(o.days), sent: rem[mid] }; }).filter(x => x && x.st).sort((a, b) => b.o.days - a.o.days);
  AIX.remL = L; const ph = x => String(x.m.phone || '').replace(/\D/g, '').length >= 10;
  $('cl-b').innerHTML = `<div class="row" style="gap:8px;margin-bottom:10px;flex-wrap:wrap">${REM_ST.map(s => `<span class="tag">${s.k}. ${s.n} — ${L.filter(x => x.st === s.k).length}</span>`).join('')}<span class="spacer"></span>${canEdit() ? `<button class="sm" onclick="remRun()">💬 Send WhatsApp one by one</button><button class="sm ghost" onclick="remLetters()">🖨 Letters for ticked</button>` : ''}</div>
    <div class="tw"><table><thead><tr><th class="np"><input type="checkbox" checked onchange="$$('.rm-ck').forEach(c=>c.checked=this.checked)"></th><th>Flat</th><th>Member</th><th class="n">Outstanding</th><th class="n">Days overdue</th><th>Stage</th><th>Last sent</th><th></th></tr></thead><tbody>
    ${L.map((x, i) => `<tr><td class="np"><input type="checkbox" class="rm-ck" data-i="${i}" ${x.sent && x.sent.stage >= x.st && daysAgo(ymd(new Date(x.sent.at))) < 7 ? '' : 'checked'}></td><td class="b">${esc(flatLbl(x.m))}</td><td>${esc(x.m.name)}${ph(x) ? '' : ' <span class="small muted">(no mobile)</span>'}</td><td class="n">${fmt(x.bal)}</td><td class="n">${x.o.days}</td><td>${REM_ST[x.st - 1].n}</td><td class="small">${x.sent ? `${REM_ST[(x.sent.stage || 1) - 1].n.split(' ')[0]} · ${new Date(x.sent.at).toLocaleDateString('en-IN')}` : '—'}</td>
      <td style="white-space:nowrap">${ph(x) ? `<button class="xs" onclick="remSend(${i})">💬</button>` : ''} <button class="xs ghost" onclick="remLetters([${i}])">🖨</button>${aiReady() ? ` <button class="xs ghost" title="Letter written by AI for this member" onclick="remAI(${i})">🤖</button>` : ''}</td></tr>`).join('') || '<tr><td colspan="8" class="empty">Nobody is overdue 🎉</td></tr>'}</tbody></table></div>
    <p class="small muted" style="margin-top:6px">Stage by days past the due date of the oldest unpaid bill: 1–14 gentle · 15–44 firm · 45–89 final · 90+ notice. WhatsApp includes a UPI "Pay now" link when the society's UPI ID is set (Settings → Bill).</p>`;
}
async function remMark(mids) { const up = {}; mids.forEach(({ mid, st }) => up[`bcfg/_rms/${mid}`] = { stage: st, at: Date.now() }); await commit(up, { a: 'edit', e: 'Reminders', s: `${mids.length} reminder(s) sent` }).catch(() => { }); }
function remSend(i) { const x = AIX.remL[i]; const pl = payLink(x.mid, x.bal); window.open(`https://wa.me/${waNum(x.m.phone)}?text=${encodeURIComponent(remText(x.mid, x.st) + (pl ? `\n\nPay now (UPI): ${pl}` : ''))}`, '_blank'); remMark([{ mid: x.mid, st: x.st }]); }
function remRun() { const L = $$('.rm-ck').filter(c => c.checked).map(c => AIX.remL[+c.dataset.i]).filter(x => String(x.m.phone || '').replace(/\D/g, '').length >= 10); if (!L.length) return toast('No ticked member has a mobile number', 'warn'); AIX.rq = L; AIX.rqi = 0; remRunStep(); }
function remRunStep() { const L = AIX.rq, i = AIX.rqi; if (i >= L.length) { closeAllModals(); toast(`Done — ${L.length} reminder(s)`); render(); return; } const x = L[i];
  openModal({ title: `💬 Reminder ${i + 1} of ${L.length} — ${esc(memLbl(x.m))}`, ok: 'Open WhatsApp & next', cancel: 'Stop', body: `<p class="small muted">${REM_ST[x.st - 1].n} · ₹${fmt(x.bal)} · ${x.o.days} days</p><div class="card small" style="white-space:pre-wrap">${esc(remText(x.mid, x.st))}</div><button class="xs ghost" onclick="AIX.rqi++;closeAllModals();remRunStep()">Skip</button>`,
    onOk: () => { remSend(L.indexOf(x) >= 0 ? AIX.remL.indexOf(x) : 0); AIX.rqi++; setTimeout(remRunStep, 300); } }); }
function remLetterHtml(x, body) { return `<div class="doc">${letterhead()}<div style="display:flex;justify-content:space-between;margin:8px 0 14px"><span>Ref.: REM/${esc(flatLbl(x.m))}/${today().slice(0, 7)}</span><span>Date: ${fd(today())}</span></div>
  <p>To,<br><b>${esc(x.m.name)}</b><br>Flat No. ${esc(flatLbl(x.m))}, ${esc(S.meta.name || '')}</p><p style="margin:12px 0"><b>Sub.: ${esc(REM_ST[x.st - 1].n)} — outstanding dues of ₹${fmt(x.bal)}</b></p>
  <div style="white-space:pre-line;line-height:1.8;text-align:justify">${esc(body)}</div>${signBlock(['Secretary'], { space: 50 })}</div>`; }
function remLetters(idx) { const L = (idx || $$('.rm-ck').filter(c => c.checked).map(c => +c.dataset.i)).map(i => AIX.remL[i]); if (!L.length) return toast('Tick members first', 'warn');
  printDoc('Reminder letters', L.map(x => remLetterHtml(x, `Dear Sir / Madam,\n\n${remText(x.mid, x.st).replace(/^Dear [^,]+,\s*/, '').replace(/^FINAL REMINDER:\s*/, '')}\n\nA statement of your account is available with the society office. Kindly ignore this letter if the payment has already been made.`)).join('<div class="pb"></div>'), { auto: false }); remMark(L.map(x => ({ mid: x.mid, st: x.st }))); }
async function remAI(i) { const x = AIX.remL[i]; const r = riskOf(x.mid); const bills = Object.values(S.bills).filter(b => b.mid === x.mid).length; const lastP = Object.values(S.vch).filter(v => v.t === 'R' && vMembers(v).includes(x.mid) && !v.bnc).map(v => v.d).sort().pop();
  const R = await aiTry('Writing the letter…', () => aiRun(`Write the body of a ${REM_ST[x.st - 1].n.toLowerCase()} letter from the Secretary of "${S.meta.name}", a co-operative housing society in Maharashtra, to member ${x.m.name}, flat ${flatLbl(x.m)}. Facts: outstanding ₹${fmt(x.bal)}; oldest unpaid since ${fd(x.o.since)} (${x.o.days} days); ${bills} bills this year; last payment ${lastP ? fd(lastP) : 'none this year'}; ${r.bnc} bounced cheque(s); average ${r.avgLate} days late. Tone: ${['', 'polite and friendly', 'firm but courteous', 'serious, mention consequences under the bye-laws', 'formal, mention that recovery under Section 154B-29 of the MCS Act 1960 may be initiated'][x.st]}. Mention interest as per bye-laws. 120–180 words, plain paragraphs, start with "Dear Sir / Madam,", no signature. Return {"body":"..."}`, []));
  if (R && R.body) printDoc('Reminder letter', remLetterHtml(x, R.body), { auto: false }); }
// ── 31: instalment plans ─────────────────────────────────────────────────
function instState(mid) { const p = (M(mid) || {}).inst; if (!p) return null; const due = []; for (let k = 0; k < p.n; k++) { const d = pd(p.start); d.setMonth(d.getMonth() + k * (p.every || 1)); due.push({ d: ymd(d), amt: k === p.n - 1 ? r2(p.total - p.amt * (p.n - 1)) : p.amt }); }
  const paid = r2(sum(Object.values(S.vch).filter(v => v && v.t === 'R' && !v.bnc && v.d >= p.at && vMembers(v).includes(mid)), v => sum(v.lines.filter(l => l.m === mid && l.cr), l => l.cr)));
  const shouldBe = r2(sum(due.filter(x => x.d <= today()), x => x.amt)); return { p, due, paid, shouldBe, behind: r2(Math.max(0, shouldBe - paid)), next: due.find(x => x.d > today()) }; }
function clInst() { const L = clMembers().filter(([, m]) => m.inst);
  $('cl-b').innerHTML = `${canEdit() ? `<button class="sm" onclick="instModal()" style="margin-bottom:10px">+ Instalment plan</button>` : ''}<div class="tw"><table><thead><tr><th>Flat</th><th>Member</th><th class="n">Plan amount</th><th>Instalments</th><th class="n">Due till today</th><th class="n">Paid</th><th>Status</th><th></th></tr></thead><tbody>
    ${L.map(([mid, m]) => { const s = instState(mid); return `<tr><td class="b">${esc(flatLbl(m))}</td><td>${esc(m.name)}</td><td class="n">${fmt(s.p.total)}</td><td class="small">${s.p.n} × ₹${fmt(s.p.amt)} from ${fd(s.p.start)}</td><td class="n">${fmt(s.shouldBe)}</td><td class="n">${fmt(s.paid)}</td><td>${s.paid >= s.p.total - 0.5 ? '<span class="tag t-ok">Completed</span>' : s.behind > 0.5 ? `<span class="tag t-err">Behind ₹${fmt(s.behind)}</span>` : `<span class="tag t-ok">On track</span>${s.next ? `<div class="small muted">next ${fd(s.next.d)}</div>` : ''}`}</td>
      <td style="white-space:nowrap"><button class="xs ghost" onclick="instPrint('${mid}')">🖨</button>${canEdit() ? ` <button class="xs ghost" onclick="instDel('${mid}')">🗑</button>` : ''}</td></tr>`; }).join('') || '<tr><td colspan="8" class="empty">No instalment plans</td></tr>'}</tbody></table></div>`; }
function instModal() { openModal({ title: '🗓 Instalment plan for arrears', ok: 'Save plan', body: `<div data-form><label>Member</label>${accPicker('in-m', memberOptions(), { ph: 'Select flat', onchange: 'instPick' })}<div class="fr c3" style="margin-top:8px"><div><label>Amount to settle ₹</label><input id="in-t" class="num" type="number" step="0.01"></div><div><label>No. of instalments</label><input id="in-n" class="num" type="number" value="6" min="2" max="36"></div><div><label>First instalment on</label><input id="in-s" type="date" value="${todayInFY()}"></div></div>
  <div class="fr c2"><div><label>Every</label><select id="in-e"><option value="1">month</option><option value="3">quarter</option></select></div><div><label>Resolution / note</label><input id="in-x" placeholder="e.g. MC resolution no. 5 dt. …"></div></div><p class="small muted">Current bills must also be paid as they fall due; the plan tracks the arrears only.</p></div>`,
  onOk: async () => { guardEdit(); const mid = val('in-m').replace(/^M:/, ''); const t = r2(nval('in-t')), n = Math.round(nval('in-n')); if (!mid || !(t > 0) || !(n >= 2)) throw new Error('Member, amount and number of instalments are required');
    await commit({ [`members/${mid}/inst`]: { total: t, n, amt: Math.round(t / n), start: val('in-s'), every: +val('in-e'), note: val('in-x'), at: val('in-s') < today() ? val('in-s') : today() } }, { a: 'create', e: 'Instalment plan', s: `${memLbl(M(mid))}: ₹${fmt(t)} in ${n}` }); toast('Plan saved'); render(); } }); }
function instPick(v) { const mid = String(v || '').replace(/^M:/, ''); const b = (MB()[mid] || {}).bal || 0; if ($('in-t') && b > 0) $('in-t').value = r2(b); }
async function instDel(mid) { if (!(await confirmBox('Delete this instalment plan?', { danger: true, ok: 'Delete' }))) return; await commit({ [`members/${mid}/inst`]: null }, { a: 'delete', e: 'Instalment plan', s: memLbl(M(mid)) }); render(); }
function instPrint(mid) { const s = instState(mid), m = M(mid); printDoc('Instalment plan', `<div class="doc">${letterhead()}<h2 class="tt">INSTALMENT PLAN FOR ARREARS</h2><p>Member: <b>${esc(m.name)}</b>, Flat No. <b>${esc(flatLbl(m))}</b></p><p>Arrears of <b>₹${fmt(s.p.total)}</b> (${esc(wordsEN(s.p.total))}) to be paid as below, in addition to the regular bills as they fall due.${s.p.note ? ' ' + esc(s.p.note) + '.' : ''}</p>
  <table><thead><tr><th class="n">No.</th><th>Due on</th><th class="n">Amount ₹</th></tr></thead><tbody>${s.due.map((x, i) => `<tr><td class="n">${i + 1}</td><td>${fd(x.d)}</td><td class="n">${fmt(x.amt)}</td></tr>`).join('')}<tr class="tot"><td colspan="2">Total</td><td class="n">${fmt(s.p.total)}</td></tr></tbody></table>
  <p style="margin-top:10px">If any instalment is not paid on time, the whole balance becomes payable at once with interest as per the bye-laws.</p><div style="display:flex;justify-content:space-between;margin-top:40px"><div>Accepted by the member<div style="height:40px"></div>${esc(m.name)}</div>${signBlock(['Secretary'], { space: 40 })}</div></div>`, { auto: false }); }
// ── 32: recovery workflow up to Section 154B-29 ──────────────────────────
const RCV_ST = ['Reminder 1', 'Reminder 2', 'Final reminder', 'Demand notice', '154B-29 application'];
function clRcv() { const min = +RP.get('rc_min', 90); const L = clMembers().map(([mid, m]) => { const b = MB()[mid] || {}; const o = overdueOf(mid); return { mid, m, bal: b.bal || 0, o, rv: m.rcv || {} }; }).filter(x => x.bal > 0.5 && (x.o.days >= min || (x.rv.st >= 0))).sort((a, b) => b.o.days - a.o.days);
  AIX.rcL = L; $('cl-b').innerHTML = `<div class="row small" style="gap:8px;margin-bottom:10px">Members overdue for at least <input type="number" class="num" style="width:70px" value="${min}" onchange="RP.set('rc_min',this.value);render()"> days, and everyone already in the process.</div>
    <div class="tw"><table><thead><tr><th>Flat</th><th>Member</th><th class="n">Outstanding</th><th class="n">Days</th>${RCV_ST.map(s => `<th class="small">${s}</th>`).join('')}<th></th></tr></thead><tbody>
    ${L.map((x, i) => `<tr><td class="b">${esc(flatLbl(x.m))}</td><td>${esc(x.m.name)}</td><td class="n">${fmt(x.bal)}</td><td class="n">${x.o.days}</td>${RCV_ST.map((s, k) => `<td class="small">${(x.rv.d || {})[k] ? '✓ ' + fd(x.rv.d[k]) : canEdit() ? `<button class="xs ghost" onclick="rcvDoc(${i},${k})">${k < 3 ? '🖨' : k === 3 ? '📜' : '⚖'}</button>` : ''}</td>`).join('')}<td><button class="xs ghost" onclick="go('mledger','${x.mid}')">Ledger</button></td></tr>`).join('') || '<tr><td colspan="10" class="empty">No member in recovery</td></tr>'}</tbody></table></div>
    <div class="alert a-info small" style="margin-top:8px">Since the 2019 amendment, arrears of a co-operative housing society are recovered under <b>Section 154B-29</b> of the Maharashtra Co-operative Societies Act, 1960 (earlier Section 101). The application drafted here is a starting point — have it checked by your legal advisor / the Registrar's office for the current format, fees and enclosures before filing.</div>`; }
function rcvDoc(i, k) { const x = AIX.rcL[i];
  if (k < 3) { const st = k + 2 > 4 ? 4 : [1, 2, 3][k]; const y = { ...x, st }; printDoc(RCV_ST[k], remLetterHtml(y, `Dear Sir / Madam,\n\n${remText(x.mid, st).replace(/^Dear [^,]+,\s*/, '').replace(/^FINAL REMINDER:\s*/, '')}`), { auto: false }); return rcvMark(x.mid, k); }
  if (k === 3) return openModal({ title: '📜 Demand notice', ok: 'Print', body: `<div data-form><div class="fr c2"><div><label>Days to pay</label><input id="rn-d" class="num" type="number" value="15"></div><div><label>MC resolution (optional)</label><input id="rn-r" placeholder="Res. no. / date"></div></div></div>`,
    onOk: () => { const d = +val('rn-d') || 15; printDoc('Demand notice', `<div class="doc">${letterhead()}<div style="display:flex;justify-content:space-between;margin:8px 0 14px"><span>Ref.: DN/${esc(flatLbl(x.m))}/${today().slice(0, 7)}</span><span>Date: ${fd(today())}</span></div><p><b>By Registered Post A.D. / Hand delivery</b></p><p>To,<br><b>${esc(x.m.name)}</b><br>Flat No. ${esc(flatLbl(x.m))}, ${esc(S.meta.name || '')}</p><h3 class="tt" style="margin:14px 0">DEMAND NOTICE</h3>
      <p style="line-height:1.9;text-align:justify">You are a member of the society holding the above flat. As per the books of the society, a sum of <b>₹${fmt(x.bal)}</b> (${esc(wordsEN(x.bal))}) including interest up to ${fd(today())} is due from you towards maintenance and other charges, outstanding since ${fd(x.o.since)}. In spite of reminders you have not paid.</p>
      <p style="line-height:1.9;text-align:justify">You are hereby called upon to pay the said amount with further interest within <b>${d} days</b> of receipt of this notice${val('rn-r') ? `, as decided by the Managing Committee (${esc(val('rn-r'))})` : ''}, failing which the society shall apply to the Registrar for recovery under Section 154B-29 of the Maharashtra Co-operative Societies Act, 1960, at your cost and risk, without further notice.</p>${signBlock(['Secretary'], { space: 50 })}</div><div class="pb"></div>${rcvStmt(x)}`, { auto: false }); rcvMark(x.mid, 3); } });
  openModal({ title: '⚖ Application under Section 154B-29', wide: true, ok: 'Print draft', body: `<div data-form><div class="fr c2"><div><label>To (Registrar)</label><input id="ra-to" value="The Deputy Registrar, Co-operative Societies"></div><div><label>Ward / Taluka</label><input id="ra-w" placeholder="e.g. Thane / Navi Mumbai"></div></div>
    <div class="fr c3"><div><label>MC resolution no.</label><input id="ra-r"></div><div><label>Resolution date</label><input id="ra-rd" type="date"></div><div><label>Demand notice date</label><input id="ra-nd" type="date" value="${((x.rv.d || {})[3]) || ''}"></div></div></div><p class="small muted">Prints the application, a statement of dues and a list of enclosures. Check the current format with your legal advisor before filing.</p>`,
    onOk: () => { printDoc('Application 154B-29', `<div class="doc">${letterhead()}<p style="margin-top:8px">Date: ${fd(today())}</p><p>To,<br>${esc(val('ra-to'))}${val('ra-w') ? ',<br>' + esc(val('ra-w')) : ''}</p>
      <p style="margin:12px 0"><b>Sub.: Application for recovery of arrears under Section 154B-29 of the Maharashtra Co-operative Societies Act, 1960 — ${esc(x.m.name)}, Flat No. ${esc(flatLbl(x.m))}</b></p>
      <p>Respected Sir / Madam,</p><ol style="line-height:1.9;text-align:justify;padding-left:18px"><li>The applicant ${esc(S.meta.name || '')}${S.meta.regNo ? ` (Registration No. ${esc(S.meta.regNo)})` : ''} is a co-operative housing society registered under the said Act.</li>
      <li>The opponent, <b>${esc(x.m.name)}</b>, is a member of the society holding Flat No. <b>${esc(flatLbl(x.m))}</b>.</li>
      <li>As per the books of the society, an amount of <b>₹${fmt(x.bal)}</b> (${esc(wordsEN(x.bal))}) including interest up to ${fd(today())} is outstanding from the opponent towards maintenance and other charges since ${fd(x.o.since)}, as per the statement of dues enclosed.</li>
      <li>Reminders were sent${(x.rv.d || {})[0] ? ' on ' + [0, 1, 2].filter(k => (x.rv.d || {})[k]).map(k => fd(x.rv.d[k])).join(', ') : ''} and a demand notice was served${val('ra-nd') ? ' on ' + fd(val('ra-nd')) : ''}, but the opponent has failed to pay.</li>
      <li>The Managing Committee, by resolution${val('ra-r') ? ' no. ' + esc(val('ra-r')) : ''}${val('ra-rd') ? ' dated ' + fd(val('ra-rd')) : ''}, authorised this application.</li></ol>
      <p style="line-height:1.9">The society therefore prays that a recovery certificate be issued under Section 154B-29 for ₹${fmt(x.bal)} with further interest and costs.</p>
      <p style="margin-top:10px"><b>Enclosures:</b> 1. Statement of dues · 2. Copies of reminders and demand notice with proof of delivery · 3. Copy of MC resolution · 4. Copy of bye-laws on interest / charges · 5. Fee as applicable</p>${signBlock(['Chairman', 'Secretary'], { space: 50 })}</div><div class="pb"></div>${rcvStmt(x)}`, { auto: false }); rcvMark(x.mid, 4); } });
}
function rcvStmt(x) { const st = ENG.replayMember(S, x.mid, { lines: L_() }); const ob = st.ob || {}; const o = r2((ob.p || 0) + (ob.n || 0) + (ob.i || 0)); const nm = e => e.kind === 'bill' ? `Bill ${e.no || ''}` : e.kind === 'supp' ? `Supplementary bill ${e.no || ''}` : `${({ R: 'Receipt', J: 'Journal', P: 'Payment', C: 'Contra' })[e.t] || 'Entry'} ${e.no || ''}`;
  return `<div class="doc">${letterhead(true)}<h2 class="tt">STATEMENT OF DUES — ${esc(x.m.name)}, Flat ${esc(flatLbl(x.m))}</h2><table><thead><tr><th>Date</th><th>Particulars</th><th class="n">Debit</th><th class="n">Credit</th><th class="n">Balance</th></tr></thead><tbody><tr><td>${fd(S.fy.start)}</td><td>Opening balance</td><td></td><td></td><td class="n">${drcr(o)}</td></tr>${(st.timeline || []).filter(e => !e.skip).map(e => `<tr><td>${fd(e.d)}</td><td>${esc(nm(e))}</td><td class="n">${e.dr ? fmt(e.dr) : ''}</td><td class="n">${e.cr ? fmt(e.cr) : ''}</td><td class="n">${drcr(r2(e.P + e.N + e.I))}</td></tr>`).join('')}<tr class="tot"><td colspan="4">Outstanding as on ${fd(today())}</td><td class="n">${fmt(x.bal)}</td></tr></tbody></table>${signBlock(['Treasurer'], { space: 40 })}</div>`; }
async function rcvMark(mid, k) { await commit({ [`members/${mid}/rcv/d/${k}`]: today(), [`members/${mid}/rcv/st`]: k }, { a: 'edit', e: 'Recovery', s: `${memLbl(M(mid))}: ${RCV_ST[k]}` }).catch(() => { }); setTimeout(() => CUR.id === 'coll' && render(), 300); }
// ── 26, 27, 28, 30, 34: rules & tools ───────────────────────────────────
function clTools() { const c = COLL();
  $('cl-b').innerHTML = `<div class="grid g2"><div class="card"><h3>Rules</h3><div data-form>
      <label class="row"><input type="checkbox" id="cl-ex" ${c.explain ? 'checked' : ''} ${canEdit() ? '' : 'disabled'}> Print "why this bill is different from the last one" on bills</label>
      <label class="row"><input type="checkbox" id="cl-tn" ${c.tnAuto ? 'checked' : ''} ${canEdit() ? '' : 'disabled'}> Mark flats as rented from the Tenant Register before each bill run (non-occupancy charges)</label>
      <div class="fr c2"><div><label>Interest waiver: paid within (days after due date)</label><input id="cl-gr" class="num" type="number" value="${c.grace || ''}" placeholder="e.g. 7" ${canEdit() ? '' : 'disabled'}></div><div style="align-self:end">${canEdit() ? `<button class="sm" onclick="clSave()">💾 Save rules</button>` : ''}</div></div></div></div>
    <div class="card"><h3>Tools</h3><div class="col" style="gap:8px;align-items:flex-start">${canEdit() ? `<button class="sm ghost" onclick="waiverRun()">🎁 Interest waivers due under the rule</button><button class="sm ghost" onclick="rateWizard()">📈 Rate revision wizard</button><button class="sm ghost" onclick="tnRentSync()">🏠 Sync rented flats from Tenant Register now</button>` : ''}<button class="sm ghost" onclick="langModal()">🌐 Bill language per member</button></div></div></div>`; }
async function clSave() { guardEdit(); await commit({ 'bcfg/_coll': { ...COLL(), explain: $('cl-ex').checked, tnAuto: $('cl-tn').checked, grace: Math.max(0, Math.round(nval('cl-gr'))) || null } }, { a: 'edit', e: 'Collection rules', s: 'updated' }); toast('Saved'); }
// 26 — waive interest of members who paid within the grace days of the previous bill's due date
function waiverList() { const g = +COLL().grace; if (!g) return []; const runs = Array.from(new Set(Object.values(S.bills).filter(b => b && !b.supp).map(b => b.run))).sort(); const last = runs[runs.length - 1]; if (!last) return [];
  const I = IDS(); return Object.entries(S.bills).filter(([, b]) => b && b.run === last && +b.int > 0).map(([bid, b]) => { const prev = Object.values(S.bills).filter(x => x.mid === b.mid && x.d < b.d && !x.supp).sort((a, c) => c.d.localeCompare(a.d))[0]; if (!prev || !prev.due) return null;
    const cut = ymd(new Date(pd(prev.due).getTime() + g * 864e5)); const bal = ENG.replayMember(S, b.mid, { lines: L_(), asOf: cut < b.d ? cut : b.d }).bal; const done = Object.values(S.vch).some(v => v && v.wv && v.wvb === bid);
    return bal <= 0.5 && !done ? { bid, mid: b.mid, int: +b.int, cut } : null; }).filter(Boolean); }
function waiverRun() { const L = waiverList(); if (!+COLL().grace) return toast('Set the waiver days in Rules first', 'warn');
  openModal({ title: '🎁 Interest to waive under the rule', wide: true, ok: L.length ? `Waive for ${L.length} member(s)` : '', hideOk: !L.length, body: L.length ? `<p class="small muted">These members paid in full within ${COLL().grace} days of the due date, but the latest bill charged them interest.</p><div class="tw"><table><thead><tr><th>Member</th><th>Paid by</th><th class="n">Interest</th></tr></thead><tbody>${L.map(x => `<tr><td>${esc(memLbl(M(x.mid)))}</td><td>${fd(x.cut)}</td><td class="n">${fmt(x.int)}</td></tr>`).join('')}</tbody></table></div>` : '<p class="muted">Nobody qualifies in the latest bill run.</p>',
    onOk: async () => { const I = IDS(); let n = 0; for (const x of L) { await saveVoucher({ t: 'J', d: S.bills[x.bid].d, nar: `Interest waived — paid within ${COLL().grace} days of due date (rule)`, wv: 'rule', wvb: x.bid, lines: [{ h: I.int, dr: x.int }, { h: I.dues, m: x.mid, cr: x.int }] }, { noDup: true }); n++; } toast(`Interest waived for ${n} member(s)`); } }); }
// 27 — rate revision
function rateWizard() { const BH = billHeads();
  openModal({ title: '📈 Rate revision', wide: true, ok: 'Fill Billing Setup', body: `<div data-form><label>Heads to revise</label><div class="row" style="flex-wrap:wrap;gap:10px;margin-bottom:8px">${BH.map(([id, h]) => `<label class="row small"><input type="checkbox" class="rw-h" value="${id}"> ${esc(h.name)}</label>`).join('')}</div>
    <div class="fr c3"><div><label>Change</label><select id="rw-k"><option value="p">Increase by %</option><option value="a">Increase by ₹ per month</option><option value="s">Set to ₹ per month</option><option value="r">Rate per sq.ft per month</option></select></div><div><label>Value</label><input id="rw-v" class="num" type="number" step="0.01"></div><div><label>Round to</label><select id="rw-r"><option value="1">₹1</option><option value="5">₹5</option><option value="10">₹10</option><option value="0.01">paise</option></select></div></div>
    <div class="fr"><div><label>Only flats of type</label><select id="rw-t"><option value="">All</option>${Array.from(new Set(Object.values(S.members).filter(Boolean).map(m => m.type || 'Flat'))).map(t => `<option>${esc(t)}</option>`).join('')}</select></div></div><div id="rw-p" class="small muted"></div></div>`,
    onOpen: () => { const pv = () => { const v = rateCalcVals(); if (!v) return; const o = sum(Object.keys(v), mid => sum(Object.keys(v[mid]), h => +((S.bcfg[mid] || {})[h] || 0))), n = sum(Object.values(v), x => sum(Object.values(x), a => a)); $('rw-p').innerHTML = `Monthly total of the chosen heads: ₹${fmt(o)} → <b>₹${fmt(n)}</b> (${o ? ((n - o) / o * 100).toFixed(1) : '—'}%) for ${Object.keys(v).length} flats`; }; $$('.rw-h,#rw-k,#rw-v,#rw-r,#rw-t').forEach(e => { e.onchange = pv; e.oninput = pv; }); },
    onOk: () => { const v = rateCalcVals(); if (!v || !Object.keys(v).length) throw new Error('Choose heads and a value'); closeAllModals(); go('bsetup'); setTimeout(() => { bsxApply(v); bsxBar(); toast('New rates filled — check the grid and Save', 'ok', 7000); }, 200); } }); }
function rateCalcVals() { const hs = $$('.rw-h').filter(c => c.checked).map(c => c.value); const k = val('rw-k'), x = numv(val('rw-v')), rd = +val('rw-r') || 1, t = val('rw-t'); if (!hs.length || !x) return null; const out = {};
  for (const [mid, m] of Object.entries(S.members)) { if (!m || m.active === false || (t && (m.type || 'Flat') !== t)) continue; for (const h of hs) { const o = +((S.bcfg[mid] || {})[h] || 0); let n = k === 'p' ? o * (1 + x / 100) : k === 'a' ? o + x : k === 's' ? x : (+m.area || 0) * x; if (k !== 's' && k !== 'r' && !o) continue; n = Math.round(n / rd) * rd; (out[mid] = out[mid] || {})[h] = r2(n); } } return out; }
// 30 — rented flats from the Tenant Register
async function tnRentSync(quiet) { const up = {}; let n = 0; const t = today();
  for (const [mid, m] of Object.entries(S.members)) { if (!m || m.active === false) continue; const tn = m.tn; const rented = !!(tn && tn.name && (!tn.from || tn.from <= t) && (!tn.to || tn.to >= t)); const cur = !!((PV()[mid] || {}).rent); if (rented !== cur) { up[`bcfg/_pv/${mid}/rent`] = rented || null; n++; } }
  if (n) { await commit(up, { a: 'edit', e: 'Non-occupancy', s: `${n} flat(s) marked rented / not rented from the Tenant Register` }); await pkSync(true); } if (!quiet) toast(n ? `${n} flat(s) updated from the Tenant Register` : 'Already in line with the Tenant Register'); return n; }
// 34 — bill language per member
function langModal() { const L = clMembers(); openModal({ title: '🌐 Bill language per member', wide: true, ok: canEdit() ? 'Save' : '', hideOk: !canEdit(), body: `<p class="small muted">Society default: <b>${({ en: 'English', mr: 'मराठी', hi: 'हिंदी' })[SET().bill.lang] || 'English'}</b>. Choose another language for members who prefer it — their bills print in it.</p><div class="tw" style="max-height:55vh"><table><tbody>${L.map(([mid, m]) => `<tr><td class="b">${esc(flatLbl(m))}</td><td>${esc(m.name)}</td><td><select class="lg-s" data-m="${mid}"><option value="">Society default</option>${[['en', 'English'], ['mr', 'मराठी'], ['hi', 'हिंदी']].map(([k, l]) => `<option value="${k}" ${m.lang === k ? 'selected' : ''}>${l}</option>`).join('')}</select></td></tr>`).join('')}</tbody></table></div>`,
  onOk: async () => { guardEdit(); const up = {}; $$('.lg-s').forEach(s => { const o = (M(s.dataset.m) || {}).lang || ''; if (s.value !== o) up[`members/${s.dataset.m}/lang`] = s.value || null; }); if (Object.keys(up).length) await commit(up, { a: 'edit', e: 'Members', s: `Bill language set for ${Object.keys(up).length} member(s)` }); toast('Saved'); } }); }
(() => { const ob = billDocHtml; window.billDocHtml = billDocHtml = function (bid) { const b = S.bills[bid]; const ml = b && (M(b.mid) || {}).lang; if (!ml) return ob.apply(this, arguments); const st = S.meta.settings = S.meta.settings || {}; const had = Object.prototype.hasOwnProperty.call(st, 'bill'); const old = st.bill; st.bill = { ...(old || {}), lang: ml }; try { return ob.apply(this, arguments); } finally { if (had) st.bill = old; else delete st.bill; } }; })();
// 28 — explanation line on bills; 30 — tenant sync before a bill run
(() => { const og = genParams; window.genParams = genParams = function () { const p = og(); if (p.supp || !COLL().explain) return p; const prevAdj = p.adj;
  p.adj = function (x) { if (prevAdj) prevAdj.apply(this, arguments); try { const last = Object.values(S.bills).filter(b => b && b.mid === x.mid && !b.supp && b.d < p.d).sort((a, b) => b.d.localeCompare(a.d))[0]; if (!last) return; const parts = [];
      const hs = new Set([...Object.keys(x.ch), ...Object.keys(last.ch || {})]); for (const h of hs) { const a = r2((x.ch[h] || 0) - ((last.ch || {})[h] || 0)); if (Math.abs(a) >= 1) parts.push(`${(S.heads[h] || {}).name || 'charge'} ${a > 0 ? '+' : '−'}₹${fmt(Math.abs(a))}`); }
      const ni = r2(x.st.planInt || 0), li = r2(+last.int || 0); if (Math.abs(ni - li) >= 1) parts.push(ni > li ? `interest ₹${fmt(ni)} on unpaid ₹${fmt(Math.max(0, x.st.bal))}` : `interest lower by ₹${fmt(li - ni)}`);
      if (parts.length) (x.xo.xn = x.xo.xn || []).push('Change from last bill: ' + parts.join('; ')); } catch (e) { } }; return p; }; })();
