async function mbClaim(mid, rid, f = 'st', from = null) { try { const r = await FBX.txn(sp(`minbox/${mid}/${rid}/${f}`), cur => (cur == null ? null : cur) === from || (f === 'done' && cur == null) ? (f === 'done' ? 'proc' : 'proc') : undefined); return r.committed; } catch (e) { return false; } }
