        if (!(await mbClaim(mid, rid))) continue; const d = isYmd(x.d) && x.d >= S.fy.start && x.d <= S.fy.end ? x.d : todayInFY(); const dupe = x.utr && (MB_UTR.has(x.utr) || Object.values(S.vch).some(v => v && (v.ref === x.utr || (v.unc || {}).utr === x.utr))); if (x.utr) MB_UTR.add(x.utr);
