function mpReq() { const F = Object.entries((MP.pub || {}).fac || {}); const mine = Object.entries(MP.box || {}).filter(([, x]) => x && ['cmp', 'noc', 'upd', 'book'].includes(x.k)).sort((a, b) => (b[1].at || 0) - (a[1].at || 0)).slice(0, 10);
  const stl = x => ({ ok: '✓', no: '✗', open: '⏳', rec: '✓' })[x.st] || '⏳';
  mpShell(`<div class="card"><h3>🛠 ${mt('cmp')}</h3><select id="mr-c">${CMP_CAT.map(c => `<option>${esc(c)}</option>`).join('')}</select><textarea id="mr-t" rows="3" style="width:100%;margin-top:6px"></textarea><button style="width:100%;margin-top:6px" onclick="mpSend({k:'cmp',cat:val('mr-c'),t:val('mr-t')})">${mt('send')}</button></div>
    ${F.length ? `<div class="card"><h3>🏛 ${mt('book')}</h3><select id="mr-f">${F.map(([id, f]) => `<option value="${id}">${esc(f.name)}${f.rate ? ' — ₹' + fmt(f.rate) : ''}</option>`).join('')}</select><input type="date" id="mr-d" style="margin-top:6px"><input id="mr-s" placeholder="Morning / Evening / Full day" style="margin-top:6px"><button style="width:100%;margin-top:6px" onclick="mpSend({k:'book',fac:val('mr-f'),d:val('mr-d'),slot:val('mr-s')})">${mt('send')}</button></div>` : ''}
    <div class="card"><h3>📄 ${mt('noc')}</h3><select id="mr-n"><option>Sale</option><option>Loan</option><option>Passport</option><option>Electricity meter</option><option>Gas</option><option>Other</option></select><input id="mr-nt" placeholder="Details (bank name, purpose…)" style="margin-top:6px"><button style="width:100%;margin-top:6px" onclick="mpSend({k:'noc',type:val('mr-n'),t:val('mr-nt')})">${mt('send')}</button></div>
    <div class="card"><h3>✏ ${mt('upd')}</h3><input id="mu-p" placeholder="${mt('phone')}" value="${esc(MP.P.m.phone || '')}" inputmode="tel"><input id="mu-e" placeholder="Email" value="${esc(MP.P.m.email || '')}" style="margin-top:6px"><input id="mu-n" placeholder="Nominee" style="margin-top:6px"><input id="mu-k" placeholder="Parking / vehicle no." style="margin-top:6px"><button style="width:100%;margin-top:6px" onclick="mpUpd()">${mt('send')}</button></div>
    ${mine.length ? `<div class="card small">${mine.map(([, x]) => `<div style="padding:4px 0;border-bottom:1px solid var(--border)">${stl(x)} ${esc({ cmp: mt('cmp'), noc: mt('noc'), upd: mt('upd'), book: mt('book') }[x.k])} · ${new Date(x.at).toLocaleDateString('en-IN')}${x.st === 'no' ? ' — rejected' : ''}</div>`).join('')}</div>` : ''}`); }
async function mpSend(x, quiet) { if (x.k === 'cmp' && !String(x.t || '').trim()) return toast('Write the complaint', 'warn'); if (x.k === 'book' && !isYmd(x.d)) return toast('Choose the date', 'warn');
  try { await FBX.set(`societies/${MP.sid}/minbox/${MP.mid}/${FBX.key('i')}`, { ...x, at: Date.now(), uid: S.user.uid }); if (!quiet) toast(mt('sent')); } catch (e) { if (!quiet) toast(e.message, 'err'); } }
const mpSendQuiet = x => mpSend(x, true);
function mpUpd() { const f = {}; const p = val('mu-p').trim(), e = val('mu-e').trim(), n = val('mu-n').trim(), k = val('mu-k').trim(); if (p && p !== MP.P.m.phone) f.phone = p; if (e && e !== MP.P.m.email) f.email = e; if (n) f.nominee = n; if (k) f.parking = k; if (!Object.keys(f).length) return toast('Nothing changed', 'warn'); mpSend({ k: 'upd', f }); }
function mpVote(pid, i) { mpSend({ k: 'vote', pid, opt: i }); }
// screenshot → read on the phone → details confirmed by the member → sent (the picture itself is never uploaded)
function mpShot() { pickFiles('image/*', async ([f]) => { aiBusy(MP.lang === 'mr' ? 'स्क्रीनशॉट वाचत आहे…' : 'Reading the screenshot on your phone…'); let o = {}; let thumb = '';
  try { const t = await ocrText(f); o = upiParse(t); o.bad = /failed|declined|pending/i.test(t); } catch (e) { toast(e.message, 'warn'); } finally { aiBusy(false); }
  try { const bm = await createImageBitmap(f); const c = document.createElement('canvas'); const k = 72 / Math.max(bm.width, bm.height); c.width = bm.width * k; c.height = bm.height * k; c.getContext('2d').drawImage(bm, 0, 0, c.width, c.height); thumb = c.toDataURL('image/jpeg', 0.6); } catch (e) { }
  openModal({ title: '📸 ' + mt('upload'), ok: mt('send'), body: `<div data-form>${o.bad ? '<div class="alert a-err small">The screenshot does not look like a successful payment.</div>' : ''}<label>${mt('amt')} ₹</label><input id="ms-a" type="number" inputmode="decimal" value="${o.amt || ''}"><label>UTR / UPI ref.</label><input id="ms-u" inputmode="numeric" value="${esc(o.utr || '')}"><label>${mt('date')}</label><input id="ms-d" type="date" value="${o.d || today()}"><p class="small muted">${MP.lang === 'mr' ? 'फोटो सर्व्हरवर साठवला जात नाही; फक्त वरील माहिती पाठवली जाते.' : 'The picture stays on your phone — only these details are sent.'}</p></div>`,
    onOk: async () => { const a = r2(nval('ms-a')), u = val('ms-u').trim(); if (!(a > 0)) throw new Error('Amount needed'); if (!/^\d{12}$/.test(u)) throw new Error('The 12-digit UTR / UPI reference is needed'); try { if (thumb) localStorage.setItem('sb_mshot_' + u, thumb); } catch (e) { }
      await mpSend({ k: 'pay', amt: a, utr: u, d: val('ms-d'), vpa: o.vpa || '', name: o.name || '' }); } }); }); }
// member-app styles
(() => { const st = document.createElement('style'); st.textContent = `.mp{max-width:520px;margin:0 auto;min-height:100vh;padding-bottom:84px}.mp-top{position:sticky;top:0;z-index:5;display:flex;gap:8px;align-items:center;padding:12px 14px;background:var(--surface);border-bottom:1px solid var(--border)}.mp-b{padding:12px}.mp .card{margin-bottom:12px}.mp-hero{text-align:center}.mp-amt{font-size:38px;font-weight:800;margin:6px 0}
.mp-nav{position:fixed;left:0;right:0;bottom:0;display:flex;justify-content:center;background:color-mix(in srgb,var(--surface) 88%,transparent);backdrop-filter:blur(16px);-webkit-backdrop-filter:blur(16px);border-top:1px solid var(--border);padding:6px 6px calc(6px + env(safe-area-inset-bottom))}.mp-nav button{flex:1;max-width:104px;background:none;border:0;color:var(--tx2);font-size:11px;display:flex;flex-direction:column;align-items:center;gap:2px;padding:6px 0;min-height:auto}.mp-nav button span{font-size:20px}.mp-nav button.on{color:var(--accent);font-weight:700}`; document.head.appendChild(st); })();

// committee members land on the Committee page when they open a society
(() => { const oo = openSociety; window.openSociety = openSociety = async function () { const r = await oo.apply(this, arguments); try { if (S.role === 'committee' && CUR && CUR.id === 'dash') go('cmte'); } catch (e) { } return r; }; })();

// ═══════════════════════════════════════════════════════════════════════
// SOCIETY EXTRAS (Batch E1): 73 water tanker register · 75 payments above a limit need committee approval
// 78 festival / event collections · 87 quality check before bills go out · 95 firm branding on printouts
// 97 changes to closed months need approval (maker-checker)
// ═══════════════════════════════════════════════════════════════════════
// ── 87: quality check shown on the bill preview ─────────────────────────
function billQC(p, plan) { const W = []; const inPlan = new Set(plan.map(x => x.mid));
  const act = Object.entries(S.members).filter(([, m]) => m && m.active !== false); const miss = act.filter(([mid]) => !inPlan.has(mid)); if (miss.length) W.push(`${miss.length} active member(s) get no bill (no Billing Setup amounts): ${miss.slice(0, 8).map(([, m]) => flatLbl(m)).join(', ')}${miss.length > 8 ? '…' : ''}`);
  const zero = plan.filter(x => !(sum(Object.values(x.ch)) > 0)); if (zero.length) W.push(`${zero.length} bill(s) with no charges: ${zero.slice(0, 8).map(x => flatLbl(x.m)).join(', ')}`);
  const jump = []; for (const x of plan) { const last = Object.values(S.bills).filter(b => b && b.mid === x.mid && !b.supp && b.d < p.d).sort((a, b) => b.d.localeCompare(a.d))[0]; if (!last) continue; const a = sum(Object.values(x.ch)), b = sum(Object.values(last.ch || {})); if (b > 0 && Math.abs(a - b) / b > 0.25) jump.push(`${flatLbl(x.m)} ₹${fmt0(b)}→₹${fmt0(a)}`); }
  if (jump.length) W.push(`Charges changed by more than 25% from the last bill for ${jump.length} flat(s): ${jump.slice(0, 6).join(', ')}${jump.length > 6 ? '…' : ''}`);
  if (!p.due) W.push('No due date — interest and reminders depend on it'); else if (p.due < p.d) W.push('Due date is before the bill date');
  const noC = plan.filter(x => !String(x.m.phone || '').replace(/\D/g, '') && !x.m.email).length; if (noC) W.push(`${noC} member(s) have neither mobile nor email — they cannot get the bill on WhatsApp / email`);
  return W; }
(() => { const og = genPreview; window.genPreview = genPreview = function () { const r = og.apply(this, arguments); try { const p = genParams(); const plan = ENG.planRun(S, p); const W = billQC(p, plan); const ov = $$('.ov'); const b = ov.length && ov[ov.length - 1].querySelector('.md-b');
  if (b) b.insertAdjacentHTML('afterbegin', W.length ? `<div class="alert a-warn small" id="qc-box"><b>Check before generating:</b><br>${W.map(esc).join('<br>')}</div>` : `<div class="alert a-ok small" id="qc-box">✓ Quality check passed — every active member billed, no unusual changes.</div>`); } catch (e) { } return r; }; })();
// ── 73: water tanker register ───────────────────────────────────────────
const TNK = () => BC('_tnk');
page('tanker', {
  render() { const m = RP.get('tk_m', today().slice(0, 7)); const L = Object.entries(TNK()).filter(([, x]) => x && x.d && x.d.slice(0, 7) === m).sort((a, b) => a[1].d.localeCompare(b[1].d));
    const tot = r2(sum(L, ([, x]) => +x.amt || 0)), qty = sum(L, ([, x]) => +x.qty || 0); const flats = Object.values(S.members).filter(x => x && x.active !== false).length || 1;
    shell('🚰 Water Tankers', 'Tankers ordered, cost per month and per flat — and add the cost to the next bills', canEdit() ? `<button onclick="tnkModal()">+ Tanker</button>` : '',
      `<div class="toolbar"><input type="month" value="${m}" onchange="RP.set('tk_m',this.value);render()"><span class="spacer"></span>${canEdit() && tot ? `<button class="sm ghost" onclick="tnkBill('${m}')">🧾 Add ₹${fmt0(tot)} to next bills</button>` : ''}</div>
      <div class="grid g3" style="margin-bottom:12px"><div class="stat"><div class="v">${L.length}</div><div class="l">tankers</div></div><div class="stat"><div class="v">${(qty / 1000).toLocaleString('en-IN')} kL</div><div class="l">water</div></div><div class="stat"><div class="v">₹${fmt0(tot)}</div><div class="l">cost · ₹${fmt(r2(tot / flats))} per flat</div></div></div>
      <div class="tw"><table><thead><tr><th>Date</th><th>Supplier</th><th class="n">Litres</th><th class="n">Amount</th><th>Paid</th><th></th></tr></thead><tbody>${L.map(([id, x]) => `<tr><td>${fd(x.d)}</td><td>${esc(x.v || '')}</td><td class="n">${(+x.qty || 0).toLocaleString('en-IN')}</td><td class="n">${fmt(x.amt)}</td><td class="small">${x.paid ? '✓ ' + esc(x.paid) : ''}</td><td>${canEdit() ? `<button class="xs ghost" onclick="tnkModal('${id}')">✏</button>` : ''}</td></tr>`).join('') || '<tr><td colspan="6" class="empty">No tankers this month</td></tr>'}</tbody></table></div>`); }
});
function tnkModal(id) { const x = id ? TNK()[id] : { d: todayInFY(), qty: 10000 }; const last = Object.values(TNK()).filter(Boolean).sort((a, b) => b.d.localeCompare(a.d))[0] || {};
  openModal({ title: id ? 'Tanker' : '+ Tanker', ok: 'Save', body: `<div data-form><div class="fr c2"><div><label>Date</label><input type="date" id="tk-d" value="${x.d}"></div><div><label>Supplier</label><input id="tk-v" value="${esc(x.v || last.v || '')}"></div></div><div class="fr c3"><div><label>Litres</label><input id="tk-q" class="num" type="number" value="${x.qty || ''}"></div><div><label>Amount ₹</label><input id="tk-a" class="num" type="number" value="${x.amt || last.amt || ''}"></div><div><label>Paid by (voucher / cash)</label><input id="tk-p" value="${esc(x.paid || '')}"></div></div></div>`,
    extraBtns: id ? `<button class="danger" onclick="commit({['bcfg/_tnk/${id}']:null},{a:'delete',e:'Tanker',s:'deleted'}).then(()=>{closeAllModals()})">Delete</button>` : '',
    onOk: async () => { guardEdit(); const r = { d: val('tk-d'), v: val('tk-v').trim(), qty: Math.round(nval('tk-q')), amt: r2(nval('tk-a')), paid: val('tk-p').trim() }; if (!isYmd(r.d) || !(r.amt > 0)) throw new Error('Date and amount required'); await commit({ [`bcfg/_tnk/${id || FBX.key('t')}`]: r }, { a: id ? 'edit' : 'create', e: 'Tanker', s: `${fd(r.d)} ₹${fmt(r.amt)}` }); } }); }
function tnkBill(m) { const L = Object.values(TNK()).filter(x => x && x.d && x.d.slice(0, 7) === m); const tot = r2(sum(L, x => +x.amt || 0)); const act = Object.entries(S.members).filter(([, x]) => x && x.active !== false); const hs = headOptions(h => h.grp === 'Income');
  openModal({ title: '🧾 Recover tanker cost through the bills', ok: 'Add to next bills', body: `<div data-form><p class="small">₹${fmt(tot)} for ${perLbl(m + '-01', m + '-28')} — added as a one-time charge on each flat's next bill.</p><div class="fr c2"><div><label>Income head</label><select id="tb-h">${hs.map(o => `<option value="${o.v}" ${/water|tanker/i.test(o.label) ? 'selected' : ''}>${esc(o.label)}</option>`).join('')}</select></div><div><label>Share</label><select id="tb-s"><option value="eq">Equally per flat</option><option value="area">By area (sq.ft)</option></select></div></div></div>`,
    onOk: async () => { guardEdit(); const h = val('tb-h'), how = val('tb-s'); const area = sum(act, ([, x]) => +x.area || 0); if (how === 'area' && !area) throw new Error('Areas are not filled in Members'); const up = {}; let given = 0;
      act.forEach(([mid, x], i) => { let a = how === 'eq' ? tot / act.length : tot * (+x.area || 0) / area; a = i === act.length - 1 ? r2(tot - given) : r2(a); given = r2(given + a); if (a > 0) up[`pending/${mid}/${FBX.key('p')}`] = { h, amt: a, note: `Water tanker charges ${m}` }; });
      await commit(up, { a: 'create', e: 'One-time charges', s: `Tanker cost ₹${fmt(tot)} for ${m} spread over ${act.length} flats` }); toast('Added — they appear on the next bills'); } }); }
// ── 78: festival / event collections ────────────────────────────────────
const EVT = () => BC('_evt');
page('events', {
  render() { const E = Object.entries(EVT()).filter(([, e]) => e).sort((a, b) => String(b[1].from).localeCompare(String(a[1].from))); const id = RP.get('ev_id', (E[0] || [])[0] || ''); const e = EVT()[id];
    shell('🎉 Festival & Event Collections', 'Ganesh Utsav, Navratri, Republic Day… contributions by flat, kept apart from maintenance', canEdit() ? `<button onclick="evtModal()">+ Event</button>` : '',
      `<div class="toolbar"><select onchange="RP.set('ev_id',this.value);render()">${E.map(([k, x]) => `<option value="${k}" ${k === id ? 'selected' : ''}>${esc(x.name)}</option>`).join('') || '<option>No events yet</option>'}</select>${e && canEdit() ? `<button class="sm ghost" onclick="evtModal('${id}')">✏</button><button class="sm ghost" onclick="evtAppeal('${id}')">💬 Appeal on WhatsApp</button>` : ''}</div><div id="ev-b"></div>`);
    if (e) evtShow(id, e); }
});
function evtRows(e) { const rc = Object.values(S.vch).filter(v => v && v.t === 'R' && !v.bnc && v.d >= (e.from || S.fy.start) && v.d <= (e.to || S.fy.end) && (v.lines || []).some(l => l.h === e.h && l.cr)); const by = {}; let outs = 0;
  rc.forEach(v => { const amt = sum(v.lines.filter(l => l.h === e.h && l.cr), l => l.cr); const mid = (v.evm || (v.lines.find(l => l.m) || {}).m || ''); if (mid && S.members[mid]) by[mid] = r2((by[mid] || 0) + amt); else outs = r2(outs + amt); });
  const spent = r2(sum(Object.values(S.vch).filter(v => v && v.t === 'P' && v.d >= (e.from || S.fy.start) && v.d <= (e.to || S.fy.end)), v => sum(v.lines.filter(l => l.h === e.h && l.dr), l => l.dr))); return { by, outs, spent }; }
function evtShow(id, e) { const R = evtRows(e); const got = r2(sum(Object.values(R.by)) + R.outs); const ms = memSorted(false).filter(([, m]) => m.active !== false); const paid = ms.filter(([mid]) => R.by[mid] > 0).length;
  $('ev-b').innerHTML = `<div class="grid g4" style="margin-bottom:12px"><div class="stat"><div class="v">₹${fmt0(got)}</div><div class="l">collected${e.target ? ' of ₹' + fmt0(e.target) : ''}</div></div><div class="stat"><div class="v">${paid} / ${ms.length}</div><div class="l">flats contributed</div></div><div class="stat"><div class="v">₹${fmt0(R.spent)}</div><div class="l">spent</div></div><div class="stat"><div class="v">₹${fmt0(r2(got - R.spent))}</div><div class="l">balance</div></div></div>
    ${canEdit() ? `<button class="sm" style="margin-bottom:8px" onclick="evtRcpt('${id}')">+ Contribution</button>` : ''}<div class="tw"><table><thead><tr><th>Flat</th><th>Member</th><th class="n">Contributed</th></tr></thead><tbody>${ms.map(([mid, m]) => `<tr><td class="b">${esc(flatLbl(m))}</td><td>${esc(m.name)}</td><td class="n">${R.by[mid] ? fmt(R.by[mid]) : `<span class="muted">${e.sug ? 'suggested ' + fmt0(e.sug) : '—'}</span>`}</td></tr>`).join('')}${R.outs ? `<tr><td colspan="2">Others / non-members</td><td class="n">${fmt(R.outs)}</td></tr>` : ''}</tbody></table></div>
    <p class="small muted" style="margin-top:6px">Contributions are receipts credited to <b>${esc(H(e.h).name)}</b>; expenses are payments debited to it.</p>`; }
function evtModal(id) { const e = id ? EVT()[id] : { from: todayInFY() }; const hs = headOptions(h => ['Income', 'Liabilities'].includes(h.grp));
  openModal({ title: id ? 'Event' : '+ Event', ok: 'Save', body: `<div data-form><label>Name</label><input id="ev-n" value="${esc(e.name || '')}" placeholder="Ganesh Utsav 2026"><div class="fr c3"><div><label>From</label><input type="date" id="ev-f" value="${e.from || ''}"></div><div><label>To</label><input type="date" id="ev-t" value="${e.to || ''}"></div><div><label>Suggested per flat ₹</label><input id="ev-s" class="num" type="number" value="${e.sug || ''}"></div></div>
    <div class="fr c2"><div><label>Head (fund / income)</label><select id="ev-h">${hs.map(o => `<option value="${o.v}" ${o.v === e.h || (!e.h && /festival|utsav|event|celebration/i.test(o.label)) ? 'selected' : ''}>${esc(o.label)}</option>`).join('')}</select></div><div><label>Target ₹</label><input id="ev-g" class="num" type="number" value="${e.target || ''}"></div></div><p class="small muted">Tip: create a head like "Festival Fund" (Liabilities › Funds) so the money stays separate from maintenance.</p></div>`,
    onOk: async () => { guardEdit(); const r = { name: val('ev-n').trim(), from: val('ev-f'), to: val('ev-t'), sug: r2(nval('ev-s')) || 0, h: val('ev-h'), target: r2(nval('ev-g')) || 0 }; if (!r.name || !r.h) throw new Error('Name and head required'); const k = id || FBX.key('e'); await commit({ [`bcfg/_evt/${k}`]: r }, { a: id ? 'edit' : 'create', e: 'Event', s: r.name }); RP.set('ev_id', k); render(); } }); }
function evtRcpt(id) { const e = EVT()[id]; const cb = cbOptions();
  openModal({ title: `+ Contribution — ${esc(e.name)}`, ok: 'Save receipt', body: `<div data-form><label>From member (leave blank for an outsider)</label>${accPicker('er-m', memberOptions(), { ph: 'Select flat (optional)' })}<div class="fr c3" style="margin-top:8px"><div><label>Amount ₹</label><input id="er-a" class="num" type="number" value="${e.sug || ''}"></div><div><label>Date</label><input type="date" id="er-d" value="${todayInFY()}"></div><div><label>Received in</label><select id="er-c">${cbSelOpts((cb[0] || {}).v)}</select></div></div><div class="fr c2"><div><label>Mode</label><select id="er-o"><option>Cash</option><option>UPI</option><option>Cheque</option><option>NEFT</option></select></div><div><label>Name (outsider) / note</label><input id="er-x"></div></div></div>`,
    onOk: async () => { const mid = val('er-m'), a = r2(nval('er-a')); if (!(a > 0)) throw new Error('Amount required'); await saveVoucher({ t: 'R', d: val('er-d'), mode: val('er-o'), evm: mid || null, nar: `${e.name} contribution${mid ? ' from ' + memLbl(M(mid)) : val('er-x') ? ' from ' + val('er-x') : ''}`, lines: [{ h: val('er-c'), dr: a }, { h: e.h, cr: a }] }, { noDup: true }); toast('Receipt saved'); render(); } }); }
function evtAppeal(id) { const e = EVT()[id]; const t = `🙏 ${e.name}\n\nDear members, contributions for ${e.name} are welcome${e.sug ? ` (suggested ₹${fmt0(e.sug)} per flat)` : ''}. Please pay the society by UPI${SET().bill.upi ? ' to ' + SET().bill.upi : ''} and write your flat no. in the note, or give cash to the committee.\n\n— ${S.meta.name}`; window.open('https://wa.me/?text=' + encodeURIComponent(t), '_blank'); }
// ── 75: payments above a limit need approval ────────────────────────────
const APV = () => BC('_apv');
(() => { const os = saveVoucher; window.saveVoucher = saveVoucher = async function (v, opt) {
  const lim = +APV().lim; if (lim && v && v.t === 'P' && !isAdmin() && !(opt && opt.apvOk) && vAmount(v) > lim && !v.id) { const id = FBX.key('a'); await FBX.update({ [sp(`mapp/payreq/${id}`)]: { v, at: Date.now(), by: uname(), uid: S.user.uid } }); await commit({}, { a: 'create', e: 'Payment approval', s: `₹${fmt(vAmount(v))} — ${vParticulars(v)} sent for approval` }); const err = new Error(`Payments above ₹${fmt0(lim)} need approval — sent to the committee / admin (Committee page).`); err.soft = true; throw err; }
  return os.apply(this, arguments); }; })();
function apvList() { return Object.entries(((S.mapp || {}).payreq) || {}).filter(([, x]) => x && !x.st).sort((a, b) => a[1].at - b[1].at); }
