// ── 91 + 79: smart search understands plain questions and commands ─────
const SQM = { jan: 1, feb: 2, mar: 3, apr: 4, may: 5, jun: 6, jul: 7, aug: 8, sep: 9, oct: 10, nov: 11, dec: 12 };
function sqMonth(q) { const m = q.match(/\b(jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)[a-z]*\b/); if (!m) return null; const n = SQM[m[1]]; const y = n >= 4 ? +S.fy.start.slice(0, 4) : +S.fy.start.slice(0, 4) + 1; return `${y}-${String(n).padStart(2, '0')}`; }
function smartQuery(q) { q = String(q || '').toLowerCase().trim(); const R = { title: '', items: [] }; const n = (q.match(/(\d[\d,]*)/) || [])[1]; const N = n ? +n.replace(/,/g, '') : 0;
  if (/(due|dues|unpaid|outstanding|defaulter|pending)/.test(q) && !/bill/.test(q.replace(/bills?\s+due/, ''))) { const L = Object.entries(MB()).filter(([mid, r]) => M(mid) && r.bal > Math.max(0.5, /above|over|more than|>/.test(q) ? N : 0)).sort((a, b) => b[1].bal - a[1].bal);
    R.title = `Members with dues${N && /above|over|more than|>/.test(q) ? ' above ₹' + fmt0(N) : ''} (${L.length}) · total ₹${fmt0(sum(L, ([, r]) => r.bal))}`; R.items = L.map(([mid, r]) => ({ h: `<b>${esc(flatLbl(M(mid)))}</b> ${esc(M(mid).name)} · <span class="dr">₹${fmt(r.bal)}</span>`, on: `closeModals();m360('${mid}')` })); return R; }
  const t = /receipt|received|collection/.test(q) ? 'R' : /payment|paid|expense|spent/.test(q) ? 'P' : /journal/.test(q) ? 'J' : /contra|transfer/.test(q) ? 'C' : ''; if (!t) return null;
  const mo = sqMonth(q); const to = (q.match(/\b(?:to|for|from|of)\s+([a-z][a-z .&-]{2,})/) || [])[1]; const ab = /above|over|more than|>/.test(q) ? N : 0, be = /below|under|less than|</.test(q) ? N : 0;
  let L = Object.entries(S.vch).filter(([, v]) => v && v.t === t && (!mo || v.d.slice(0, 7) === mo) && (!ab || vAmount(v) > ab) && (!be || vAmount(v) < be));
  if (to) { const w = to.replace(/\b(in|on|during|above|below|over|under|this|last|month|year)\b.*$/, '').trim(); if (w && !SQM[w.slice(0, 3)]) L = L.filter(([, v]) => `${vParticulars(v)} ${v.nar || ''}`.toLowerCase().includes(w)); }
  L.sort((a, b) => b[1].d.localeCompare(a[1].d)); R.title = `${{ R: 'Receipts', P: 'Payments', J: 'Journals', C: 'Contras' }[t]}${mo ? ' in ' + perLbl(mo + '-01', mo + '-28').split(' ')[0] : ''} (${L.length}) · ₹${fmt0(sum(L, ([, v]) => vAmount(v)))}`;
  R.items = L.map(([id, v]) => ({ h: `<span class="mono small">${esc(v.no)}</span> ${fd(v.d)} · ${esc(vParticulars(v))} · <b>₹${fmt(vAmount(v))}</b>`, on: `openVch('${id}')` })); return R; }
const CMDS = [[/^(new |add |make )?(receipt|rcpt)\b/, 'receipt'], [/^(new |add |make )?(payment|expense)\b/, 'payment'], [/^(generate|make|raise) (the )?bills?/, 'bills', 'genModal()'], [/^(trial balance|tb)$/, 'tb'], [/^balance sheet$/, 'bs'], [/^(income|i ?& ?e)/, 'ie'], [/^(bank statement|upload statement)/, 'bstmt'], [/^(reconcil|brs)/, 'recon'], [/^(backup|take backup)/, null, 'abkModal()'], [/^(add|new) member/, 'members', 'memberModal&&memberModal()']];
(() => { const og = gsRun; window.gsRun = gsRun = function (q) { og.apply(this, arguments); try { const el = $('gs-r'); const s = String(q || '').trim(); if (!el || s.length < 3 || !S.sid) return; const low = s.toLowerCase(); let top = '';
  for (const [re, pg, fn] of CMDS) if (re.test(low)) { top += `<div class="gs-it" onclick="closeModals();${pg ? `go('${pg}');` : ''}${fn ? `setTimeout(()=>{${fn}},250)` : ''}">⚡ <b>Do it:</b> ${esc(s)}</div>`; break; }
  if (/^(received|got|paid)\s/.test(low) && typeof voiceApply === 'function') top += `<div class="gs-it" onclick="closeModals();go('${/^paid/.test(low) ? 'payment' : 'receipt'}');setTimeout(()=>voiceApply(${esc(JSON.stringify(s))},'${/^paid/.test(low) ? 'P' : 'R'}'),300)">⚡ <b>Fill the entry:</b> ${esc(s)}</div>`;
  const R = smartQuery(s); if (R && R.items.length) top += `<div class="small b muted" style="margin:8px 0 4px">${esc(R.title)}</div>${R.items.slice(0, 30).map(x => `<div class="gs-it" onclick="${x.on}">${x.h}</div>`).join('')}`;
  const hp = helpFind(s).slice(0, 3); if (hp.length) top += `<div class="small b muted" style="margin:8px 0 4px">Help</div>${hp.map(x => `<div class="gs-it" onclick="closeModals();helpOpen(${HELP.indexOf(x)})">❓ ${esc(x.q)}</div>`).join('')}`;
  if (s.split(' ').length >= 3 && aiReady()) top += `<div class="gs-it" onclick="closeModals();go('askbooks');setTimeout(()=>{const i=$('ak-q');if(i){i.value=${esc(JSON.stringify(s))};askBooks()}},300)">🤖 <b>Ask AI:</b> ${esc(s)}</div>`;
  if (top) el.insertAdjacentHTML('afterbegin', `<div id="gs-smart">${top}</div>`); } catch (e) { } }; })();
// ── 84: client health score ─────────────────────────────────────────────
function healthOf(sm) { sm = sm || {}; let s = 100; const W = []; const tm = today().slice(0, 7), lm = ymd(new Date(new Date(today()).setDate(0))).slice(0, 7);
  if (!sm.lastBill) { s -= 25; W.push('no bills yet'); } else if (sm.lastBill.slice(0, 7) < lm) { s -= 25; W.push('billing behind (last ' + sm.lastBill.slice(0, 7) + ')'); } else if (sm.lastBill.slice(0, 7) < tm && +today().slice(8) > 10) { s -= 10; W.push('this month not billed'); }
  const lv = sm.lastV ? Math.round((pd(today()) - pd(sm.lastV)) / 864e5) : 999; if (lv > 60) { s -= 30; W.push(sm.lastV ? `no entries for ${lv} days` : 'no entries'); } else if (lv > 30) { s -= 15; W.push(`no entries for ${lv} days`); }
  const per = sm.members ? (sm.out || 0) / sm.members : 0; if (per > 25000) { s -= 25; W.push(`dues ₹${fmt0(per)} per flat`); } else if (per > 10000) { s -= 12; W.push(`dues ₹${fmt0(per)} per flat`); }
  const od = (sm.rem || []).filter(x => x.d && x.d < today()).length; if (od) { s -= Math.min(20, od * 10); W.push(`${od} compliance date(s) passed`); }
  s = Math.max(0, Math.min(100, s)); return { s, W, c: s >= 80 ? 't-ok' : s >= 55 ? 't-warn' : 't-err' }; }
// ── 80: morning brief + 84 on the firm page ─────────────────────────────
function briefLines() { const rows = Object.entries(FIRM.info || {}).map(([sid, r]) => ({ sid, ...r })); const L = []; if (!rows.length) return L; const tm = today().slice(0, 7);
  const nb = rows.filter(r => !(r.summary || {}).lastBill || r.summary.lastBill.slice(0, 7) < tm); if (nb.length && +today().slice(8) >= 3) L.push(['🧾', `${nb.length} societ${nb.length > 1 ? 'ies' : 'y'} not billed for this month`, nb.map(r => r.name)]);
  const rem = rows.flatMap(r => ((r.summary || {}).rem || []).map(x => ({ ...x, n: r.name }))).filter(x => x.d && x.d <= ymd(new Date(Date.now() + 7 * 864e5))); if (rem.length) L.push(['📅', `${rem.length} compliance date(s) within 7 days`, rem.map(x => `${x.n}: ${x.t || x.l || ''} ${fd(x.d)}`)]);
  const idle = rows.filter(r => { const v = (r.summary || {}).lastV; return !v || (pd(today()) - pd(v)) / 864e5 > 30; }); if (idle.length) L.push(['⏸', `${idle.length} societ${idle.length > 1 ? 'ies have' : 'y has'} no entries for 30+ days`, idle.map(r => r.name)]);
  const sick = rows.map(r => ({ r, h: healthOf(r.summary) })).filter(x => x.h.s < 55); if (sick.length) L.push(['🩺', `${sick.length} societ${sick.length > 1 ? 'ies need' : 'y needs'} attention (health below 55)`, sick.map(x => `${x.r.name}: ${x.h.W.join(', ')}`)]);
  const my = Object.values(((typeof DESK !== 'undefined' && DESK.d) || {}).tasks || {}).filter(t => t && t.st !== 'Done' && String(t.who || '').toLowerCase() === uname().toLowerCase() && t.due && t.due <= today()); if (my.length) L.push(['✅', `${my.length} of your task(s) due today or overdue`, my.map(t => t.t)]);
  const out = sum(rows, r => (r.summary || {}).out || 0); L.push(['💰', `Total dues across ${rows.length} societies: ₹${fmt0(out)}`, []]); return L; }
(() => { const p = PAGES.firm; if (!p) return; const r = p.render; p.render = function () { const x = r.apply(this, arguments); setTimeout(firmDecorate, 60); setTimeout(firmDecorate, 900); return x; }; })();
function firmDecorate() { try { if (CUR.id !== 'firm' || !Object.keys(FIRM.info || {}).length) return; const pc = document.querySelector('#main .pc'); if (!pc) return;
  if (!$('brief')) { const L = briefLines(); const h = new Date().getHours(); pc.insertAdjacentHTML('afterbegin', `<div class="card" id="brief" style="margin-bottom:14px"><div class="row"><h3 style="margin:0">${h < 12 ? '☀️ Good morning' : h < 17 ? '🌤 Good afternoon' : '🌙 Good evening'} — today's brief</h3><span class="spacer"></span><button class="xs ghost" onclick="briefShare()">💬 WhatsApp</button>${pageOn('desk') ? `<button class="xs ghost" onclick="go('desk')">📋 Tasks</button>` : ''}</div>${L.map(([i, t, d]) => `<details style="margin-top:6px"><summary>${i} ${esc(t)}</summary>${d.length ? `<div class="small muted" style="padding-left:22px">${d.slice(0, 15).map(esc).join('<br>')}</div>` : ''}</details>`).join('')}</div>`); }
  Object.entries(FIRM.info).forEach(([sid, r]) => { const h = healthOf(r.summary); document.querySelectorAll(`[onclick*="openSociety('${sid}')"]`).forEach(el => { if (el.querySelector('.hscore') || el.tagName === 'BUTTON') return; el.insertAdjacentHTML('beforeend', ` <span class="tag ${h.c} hscore" title="Health ${h.s}/100${h.W.length ? ': ' + esc(h.W.join(', ')) : ''}">♥ ${h.s}</span>`); }); }); } catch (e) { } }
