function wqAuto() { const L = []; const tm = today().slice(0, 7); Object.entries(FIRM.info || {}).forEach(([sid, r]) => { const sm = r.summary || {}; if (!sm.lastBill || sm.lastBill.slice(0, 7) < tm) L.push({ sid, t: `Generate ${perLbl(tm + '-01', tm + '-28').split(' ')[0]} bills`, n: r.name }); if (sm.lastV && (pd(today()) - pd(sm.lastV)) / 864e5 > 20) L.push({ sid, t: `Enter vouchers / bank statement (nothing since ${fd(sm.lastV)})`, n: r.name }); (sm.rem || []).filter(x => x.d && x.d <= ymd(new Date(Date.now() + 15 * 864e5))).forEach(x => L.push({ sid, t: `${x.t || x.l || 'Compliance'} — due ${fd(x.d)}`, n: r.name })); }); return L; }
