  const fy = (() => { const d = new Date(); const y = d.getMonth() >= 3 ? d.getFullYear() : d.getFullYear() - 1; return `${y}-04-01`; })(); const name = 'Demo – Training CHS ' + today().slice(5).replace('-', '');
