  for (let i = 0; i < 80 && !(S.meta && S.meta.name === name && CUR.id === 'dash'); i++) await sleep(150); if (!(S.meta && S.meta.name === name)) return toast('Could not create the demo society', 'err');
  const hid = n => Object.keys(S.heads).find(k => S.heads[k].name === n); const SV = hid('Service Charges'), SF = hid('Sinking Fund') || hid('Sinking Fund Contribution'), RF = hid('Repair Fund') || hid('Repairs & Maintenance Fund'), B = hid('Bank – Savings A/c'), C = hid('Cash in Hand') || hid('Cash'), E = hid('Electricity Charges') || hid('Electricity – Common'), L = hid('Lift AMC & Repairs');
