  if (B) up[`ob/${S.fyId}/heads/${B}`] = 250000; if (RF) up[`ob/${S.fyId}/heads/${RF}`] = -250000; up['meta/demo'] = true; await commit(up, { a: 'create', e: 'Demo data', s: 'sample flats and set-up' });
  if (B && E) await saveVoucher({ t: 'P', d: S.fy.start.slice(0, 8) + '10', mode: 'NEFT', nar: 'MSEDCL common electricity', lines: [{ h: E, dr: 6400 }, { h: B, cr: 6400 }] }, { noDup: true }).catch(() => { });
