async function guardIn(tell) { const n = val('gv-n').trim(), mid = val('gv-f'); if (!n) return toast('Type the visitor name', 'warn'); if (!mid) return toast('Select the flat', 'warn'); const fx = (GATE.pub.flats || {})[mid] || {}; const id = FBX.key('g');
  const x = { d: today(), tin: Date.now(), name: n, ph: val('gv-p').replace(/\D/g, '').slice(-10), mid, f: fx.f || '', pur: val('gv-u'), veh: val('gv-v').trim().toUpperCase(), cnt: Math.max(1, +val('gv-c') || 1), by: uname() };
  await FBX.update({ [`societies/${GATE.sid}/gate/${id}`]: x, [`societies/${GATE.sid}/mvis/${mid}/${id}`]: { d: x.d, tin: x.tin, name: x.name, pur: x.pur, veh: x.veh } });
  if (tell && fx.ph) window.open(`https://wa.me/91${fx.ph}?text=` + encodeURIComponent(`🛡 ${(GATE.pub.soc || {}).name || 'Society'} gate: ${x.name}${x.cnt > 1 ? ` (+${x.cnt - 1})` : ''} (${x.pur}) is here for ${x.f}. ${x.veh ? 'Vehicle ' + x.veh + '. ' : ''}Please reply YES to allow.`), '_blank'); else if (tell) toast('No mobile number for this flat', 'warn');
  toast('Entry recorded'); ['gv-n', 'gv-p', 'gv-v'].forEach(k => { const e = $(k); if (e) e.value = ''; }); }
async function guardOut(id) { await FBX.update({ [`societies/${GATE.sid}/gate/${id}/tout`]: Date.now() }); }
// ── office: gate register page ──
