async function vendorRevoke(hid) { const tok = ((S.heads[hid] || {}).vm || {}).tok; if (!tok) return; const em = String(((S.heads[hid] || {}).vm || {}).em || '').trim().toLowerCase(); await FBX.update({ [`publicLedgers/${tok}`]: null, [sp(`heads/${hid}/vm/tok`)]: null, ...(em ? { [`vendorIdx/${emailKey(em)}/${tok}`]: null } : {}) }); closeAllModals(); toast('Link withdrawn'); }
(() => { const os = showPublicLedger; window.showPublicLedger = showPublicLedger = async function (tok) { await os.apply(this, arguments); try { const d = await FBX.get('publicLedgers/' + tok); if (!d || d.kind !== 'vendor') return; const el = $('public'); if (!el) return;
  el.innerHTML = el.innerHTML.replace(/Flat\s+·\s+Statement for FY/, 'Vendor statement for FY').replace('>Outstanding<', '>Payable to you<').replace('Read-only statement shared by the society. For queries contact the society office.', `Read-only statement shared by the society${d.pan ? ' · PAN ' + esc(d.pan) : ''}. Send new invoices and queries to the society office${d.ph ? ' (' + esc(d.ph) + ')' : ''}.`); } catch (e) { } }; })();
(() => { const p = PAGES.vendors; if (!p) return; const r = p.render; p.render = function () { const x = r.apply(this, arguments); try { if (!canEdit()) return x; document.querySelectorAll('#main tbody tr').forEach(tr => { const a = tr.querySelector('a.lk'); const m = a && a.getAttribute('onclick').match(/openHead\('([^']+)'\)/); const last = tr.lastElementChild; if (m && last && !last.querySelector('.vlink')) last.insertAdjacentHTML('beforeend', ` <button class="xs ghost vlink" title="Statement link for the vendor" onclick="vendorLink('${m[1]}')">🔗</button>`); }); } catch (e) { } return x; }; })();

// ═══════════════════════════════════════════════════════════════════════
// FEATURES — switch whole groups of screens on or off.
// Accounting & billing are always on. Everything else is a feature: off unless turned on firm-wide
// (Firm → Features, stored at firm/desk/features) or for one society (Settings → Features, meta/settings/features).
// A feature that is off disappears from the menu, the search, the keyboard shortcuts and from buttons on other screens.
// ═══════════════════════════════════════════════════════════════════════
const FEAT_MODS = [
  { k: 'txadv', ic: '🔁', name: 'Advanced entries', desc: 'Credit / debit notes, recurring payments, post-dated cheques, bounced cheques', pages: ['cnotes', 'recur', 'pdc', 'bounces'] },
  { k: 'vendors', ic: '🏢', name: 'Vendors & payables', desc: 'Vendor bills, payables and the vendor master', pages: ['vbills', 'vendors'] },
  { k: 'billx', ic: '🧮', name: 'Billing extras', desc: 'Billing rules (discounts, rebates, wing series), one-off bills, rate calculator, multi-flat receipts, meter readings, bill variance, head-wise arrears', pages: ['billx', 'meter', 'billvar', 'arrhead'], fns: ['oneBillModal', 'rateCalc', 'mfModal'] },
  { k: 'fsx', ic: '📊', name: 'Final-accounts extras', desc: 'Balance-sheet schedules, cash flow, 3-year comparison, ratios, notes to accounts', pages: ['schedules', 'cashflow', 'cmp3', 'ratios', 'notes'] },
  { k: 'audit', ic: '🔎', name: 'Audit tools', desc: 'Auditor query sheet, ledger scrutiny, voucher sampling', pages: ['aq', 'scrutiny', 'sampling'] },
  { k: 'rptx', ic: '📈', name: 'More reports', desc: 'Annual member statement, budget vs actual, month-wise I&E', pages: ['annstmt', 'budget', 'ietrend'] },
  { k: 'tax', ic: '🧾', name: 'GST, TDS & Income-tax', desc: 'GST register, GSTR-1 / 3B, TDS register, challans & Form 140, income-tax (80P)', pages: ['gstreg', 'gstr', 'tdsreg', 'tdsx', 'itr'] },
  { k: 'invest', ic: '💰', name: 'Investments & assets', desc: 'FD / RD register, maturity calendar, FD working, AMC register, fixed assets', pages: ['inv', 'invcal', 'fdw', 'amc', 'fa'] },
  { k: 'memrec', ic: '📜', name: 'Member records', desc: 'Flat transfers, KYC & documents, share register, statutory registers (I, J, nomination), associate members, tenants', pages: ['transfers', 'kyc', 'shares', 'statreg', 'assocreg', 'tenants'], fns: ['transferModal'] },
  { k: 'comm', ic: '📣', name: 'Meetings & communication', desc: 'Meetings & minutes, committee & election, notices & letters, complaints, payment-reminder schedule', pages: ['meetings', 'committee', 'notices', 'complaints'], fns: ['rsModal'], sel: ['#rs-ban'] },
  { k: 'stat', ic: '📕', name: 'Statutory & compliance', desc: 'Annual return, meeting & compliance checklist, licences & certificates, conveyance, compliance calendar, audit rectification (Form O)', pages: ['anret', 'mchk', 'certs', 'conv', 'comp', 'formo'] },
  { k: 'wizard', ic: '🧭', name: 'Setup wizard', desc: 'Step-by-step setup guide and its reminder on the dashboard', pages: ['wizard'], sel: ['#wiz-ban'] },
  { k: 'desk', ic: '📋', name: 'Firm desk', desc: 'Tasks, client status board, bulk bill generation, firm reports, onboarding, templates, staff activity, fee invoices', pages: ['desk', 'board', 'bulkbill', 'freports', 'onboard', 'tpl', 'activity', 'finv'], firm: true },
];
const FEAT = { firm: null, req: false, sig: '' };
const FEAT_PAGE = {}; FEAT_MODS.forEach(m => m.pages.forEach(p => FEAT_PAGE[p] = m));
const FEAT_ALL = { soc: JSON.parse(JSON.stringify(NAV_SOC)), firm: JSON.parse(JSON.stringify(NAV_FIRM)), keys: { ...KEYS } };
const featFirm = () => FEAT.firm || (() => { try { return JSON.parse(LS.get('sb_feat', '{}')) || {}; } catch (e) { return {}; } })();
const featSoc = () => (S.sid && ((S.meta || {}).settings || {}).features) || {};
function featOn(k) { if (LS.get('sb_feat_all', '') === '1') return true; const m = FEAT_MODS.find(x => x.k === k); const s = featSoc(); if (!m.firm && S.sid && s[k] != null) return !!s[k]; return !!featFirm()[k]; }
const pageOn = id => { const m = FEAT_PAGE[id]; return !m || featOn(m.k); };
function featApply() {
  const f = items => items.filter(x => pageOn(x[0]));
  NAV_SOC.splice(0, NAV_SOC.length, ...FEAT_ALL.soc.map(([s, i]) => [s, f(i)]).filter(([, i]) => i.length));
  NAV_FIRM.splice(0, NAV_FIRM.length, ...FEAT_ALL.firm.map(([s, i]) => [s, f(i)]).filter(([, i]) => i.length));
  Object.keys(KEYS).forEach(k => delete KEYS[k]); Object.entries(FEAT_ALL.keys).forEach(([k, p]) => { if (pageOn(p)) KEYS[k] = p; });
  FEAT.sig = featSig();
}
const featSig = () => JSON.stringify([S.sid || '', featFirm(), featSoc(), LS.get('sb_feat_all', '')]);
function featLoad() { if (FEAT.req || !S.user) return; FEAT.req = true;
  FBX.get('firm/desk/features').then(v => { FEAT.firm = v || {}; LS.set('sb_feat', JSON.stringify(FEAT.firm)); featRefresh(); }).catch(() => { }); }
function featRefresh() { if (featSig() === FEAT.sig) return; buildSide(); if (CUR && CUR.id && !pageOn(CUR.id)) go(S.sid ? 'dash' : 'firm'); else if (CUR && CUR.id && PAGES[CUR.id]) render(); }
// hide buttons / banners on other screens that lead to a feature that is off
function featHide() {
  const off = FEAT_MODS.filter(m => !featOn(m.k)); if (!off.length) return; const main = document.getElementById('main'); if (!main) return;
  const fns = off.flatMap(m => m.fns || []); const re = fns.length ? new RegExp('\\b(' + fns.join('|') + ')\\(') : null;
  main.querySelectorAll('[onclick]').forEach(el => { const a = el.getAttribute('onclick') || ''; const g = a.match(/\bgo\('([a-z0-9]+)'/); if ((g && !pageOn(g[1])) || (re && re.test(a))) el.style.display = 'none'; });
  off.flatMap(m => m.sel || []).forEach(s => document.querySelectorAll(s).forEach(el => el.remove()));
}
(() => {
  const ob = buildSide; window.buildSide = buildSide = function () { featLoad(); featApply(); return ob.apply(this, arguments); };
  const og = go; window.go = go = function (id, arg) {
    if (PAGES[id] && !pageOn(id)) { const m = FEAT_PAGE[id]; toast(`“${m.name}” is turned off — turn it on in ${m.firm ? 'Firm → Features' : 'Settings → Features'}.`, 'warn', 5000); if (!CUR || !CUR.id || !PAGES[CUR.id] || !pageOn(CUR.id)) return og.call(this, S.sid ? 'dash' : 'firm'); return; }
    return og.apply(this, arguments); };
  const or = render; window.render = render = function () { if (S.user && featSig() !== FEAT.sig) { buildSide(); if (CUR && CUR.id && !pageOn(CUR.id)) return go(S.sid ? 'dash' : 'firm'); } const r = or.apply(this, arguments); try { featHide(); } catch (e) { } return r; };
})();

// ── Firm → Features (firm-wide defaults) ──────────────────────────────────
FEAT_ALL.firm[0][1].push(['features', '🧩', 'Features']); NAV_FIRM[0][1].push(['features', '🧩', 'Features']);
const featRow = (m, ctl) => `<tr><td style="width:34px;font-size:20px">${m.ic}</td><td><b>${esc(m.name)}</b><div class="small muted">${esc(m.desc)}</div></td><td style="white-space:nowrap">${ctl}</td></tr>`;
const featSw = (id, on, dis) => `<label class="row small" style="gap:6px;cursor:pointer"><input type="checkbox" id="${id}" ${on ? 'checked' : ''} ${dis ? 'disabled' : ''}> ${on ? 'On' : 'Off'}</label>`;
page('features', {
  render() {
    const F = featFirm(); const ed = FIRM.admin;
    shell('🧩 Features', 'Accounting and billing are always on. Turn on only what you use — the rest stays out of the menu.', ed ? `<button onclick="featSaveFirm()">💾 Save</button>` : '',
      `${ed ? '' : '<div class="alert a-warn small">Only the firm owner can change these.</div>'}
      <div class="card"><h3>Always on</h3><p class="small muted">Dashboard · Receipt, Payment, Contra, Journal, Bulk receipts & payments, Day Book · Bills & Billing Setup · Cash, Bank, General & Member Ledger · Trial Balance, I&E, Balance Sheet, Receipts & Payments · Complete Books, Outstanding, Bill / Receipt / Payment / Journal registers, Collection reports · Account Heads, Members, Opening Balances · Bank statement & reconciliation · Year-End, Team, Audit Trail, Data Tools, Settings</p></div>
      <div class="card"><h3>Features for all societies</h3><p class="small muted" style="margin-bottom:8px">These apply to every society. A society can still turn a feature on or off for itself in its Settings → Features.</p>
      <div class="tw"><table><tbody>${FEAT_MODS.map(m => featRow(m, featSw('ff-' + m.k, !!F[m.k], !ed))).join('')}</tbody></table></div></div>
      <div class="card"><h3>This device</h3><div class="tw"><table><tbody>${featRow({ ic: '✨', name: 'Animations', desc: 'Smooth iOS / macOS-style motion — windows, pages, lists and buttons. Turn off on slow computers.' }, `<label class="row small" style="gap:6px;cursor:pointer"><input type="checkbox" ${typeof UX !== 'undefined' && UX.anim() ? 'checked' : ''} onchange="uxAnimSet(this.checked)"> On</label>`)}</tbody></table></div></div>`);
    $$('#main input[id^="ff-"]').forEach(c => c.onchange = () => { c.parentElement.lastChild.textContent = c.checked ? ' On' : ' Off'; });
  }
});
async function featSaveFirm() {
  if (!FIRM.admin) return toast('Only the firm owner can change features.', 'err');
  const v = {}; FEAT_MODS.forEach(m => { v[m.k] = !!($('ff-' + m.k) || {}).checked; });
  await FBX.update({ 'firm/desk/features': v }); FEAT.firm = v; LS.set('sb_feat', JSON.stringify(v)); toast('Features saved'); featRefresh(); render();
}
// ── Society → Settings → Features (this society only) ────────────────────
function featSocModal() {
  const s = featSoc(); const F = featFirm(); const ed = isAdmin();
  openModal({ title: '🧩 Features for this society', wide: true, ok: ed ? 'Save' : '', hideOk: !ed, body: `<p class="small muted" style="margin-bottom:8px">Accounting and billing are always on. “As firm” follows Firm → Features.</p>
    <div class="tw" style="max-height:60vh;overflow:auto"><table><tbody>${FEAT_MODS.filter(m => !m.firm).map(m => featRow(m, `<select id="fs-${m.k}" style="min-width:0" ${ed ? '' : 'disabled'}><option value="" ${s[m.k] == null ? 'selected' : ''}>As firm (${F[m.k] ? 'On' : 'Off'})</option><option value="1" ${s[m.k] === true ? 'selected' : ''}>On</option><option value="0" ${s[m.k] === false ? 'selected' : ''}>Off</option></select>`)).join('')}</tbody></table></div>`,
    onOk: async () => { guardEdit(); const v = {}; FEAT_MODS.filter(m => !m.firm).forEach(m => { const x = val('fs-' + m.k); v[m.k] = x === '' ? null : x === '1'; });
      await commit({ 'meta/settings/features': v }, { a: 'edit', e: 'settings', s: 'Features: ' + FEAT_MODS.filter(m => v[m.k] != null).map(m => `${m.name} ${v[m.k] ? 'on' : 'off'}`).join(', ') || 'all as firm' }); toast('Features saved'); setTimeout(featRefresh, 50); } });
}
addAct('settings', () => `<button class="ghost" onclick="featSocModal()">🧩 Features</button>`);

// ═══════════════════════════════════════════════════════════════════════
// COMBINED FINANCIAL STATEMENTS (56) — societies whose wings keep separate books (e.g. A&B Wing and C Wing)
// Pick the books and the year; heads with the same name (and group) are added together into one
// trial balance, Income & Expenditure account and Balance Sheet. Print or Excel.
// ═══════════════════════════════════════════════════════════════════════
const CFS = { res: null };
async function cfsLoad(sid, label) {
  const d = await FBX.get(`societies/${sid}`); if (!d || !d.meta) throw new Error('Could not open one of the societies');
  const fid = Object.keys(d.fys || {}).find(k => (d.fys[k] || {}).label === label); if (!fid) throw new Error(`${d.meta.name} has no FY ${label}`);
  const s = { heads: d.heads || {}, members: d.members || {}, bcfg: d.bcfg || {}, ob: (d.ob || {})[fid] || {}, vch: (d.vch || {})[fid] || {}, bills: (d.bills || {})[fid] || {}, runs: (d.runs || {})[fid] || {}, pending: d.pending || {}, fy: { ...d.fys[fid], id: fid }, meta: d.meta };
  const tb = ENG.trialBalance(s, s.fy.end); return { name: d.meta.name, rows: tb.rows.map(r => ({ grp: r.h.grp, sub: r.h.sub || '', name: r.h.name, cl: r.cl, tag: r.h.tag || '' })), py: s.ob.py || {}, heads: s.heads };
}
function cfsCombine(parts) {
  const key = r => r.tag === 'dues' ? 'Assets|Dues from Members' : r.tag === 'ie' ? 'Liabilities|Income & Expenditure Account' : `${r.grp}|${String(r.name).trim().toLowerCase()}`; const C = {};
  parts.forEach((p, i) => p.rows.forEach(r => { const k = key(r); const x = C[k] = C[k] || { grp: r.grp, sub: r.sub, name: r.tag === 'dues' ? "Members' dues" : r.tag === 'ie' ? 'Income & Expenditure Account' : r.name, by: {}, cl: 0 }; x.by[i] = r2((x.by[i] || 0) + r.cl); x.cl = r2(x.cl + r.cl); }));
  const L = Object.values(C).filter(x => Math.abs(x.cl) >= 0.005 || Object.values(x.by).some(v => Math.abs(v) >= 0.005));
  const inc = L.filter(x => x.grp === 'Income'), exp = L.filter(x => x.grp === 'Expenses'); const surplus = r2(-sum(inc, x => x.cl) - sum(exp, x => x.cl));
  return { L, inc, exp, liab: L.filter(x => x.grp === 'Liabilities'), ast: L.filter(x => x.grp === 'Assets'), surplus };
}
page('combfs', {
  render() { const socs = Object.entries(FIRM.list || {}).map(([sid]) => [sid, (FIRM.info[sid] || {}).name || sid]).sort((a, b) => a[1].localeCompare(b[1]));
    shell('🧩 Combined Financial Statements', 'Wings (or units) that keep separate books — one trial balance, I&E and Balance Sheet for the whole society', '',
      `<div class="card" data-form><label>Books to combine (tick two or more)</label><div style="max-height:220px;overflow:auto;border:1px solid var(--border);border-radius:8px;padding:8px;margin-bottom:10px">${socs.map(([sid, n]) => `<label class="row small"><input type="checkbox" class="cf-s" value="${sid}"> ${esc(n)}</label>`).join('')}</div>
        <div class="fr c3"><div><label>Financial year</label><input id="cf-y" placeholder="e.g. 2025-26" value="${esc(RP.get('cf_y', ''))}"></div><div><label>Name for the combined statements</label><input id="cf-n" placeholder="e.g. Chandraprabha CHS Ltd (A&B and C Wing)"></div><div style="align-self:end"><button onclick="cfsRun()">Combine</button></div></div></div><div id="cf-res"></div>`);
    if (CFS.res) cfsShow(); }
});
async function cfsRun() { const ids = $$('.cf-s').filter(c => c.checked).map(c => c.value); const y = val('cf-y').trim(); RP.set('cf_y', y); if (ids.length < 2) return toast('Tick at least two books', 'warn'); if (!/^\d{4}-\d{2}$/.test(y)) return toast('Type the year like 2025-26', 'warn');
  const parts = await aiTry('Opening the books…', () => Promise.all(ids.map(sid => cfsLoad(sid, y)))); if (!parts) return; CFS.res = { parts, y, name: val('cf-n').trim() || parts.map(p => p.name).join(' + '), ...cfsCombine(parts) }; cfsShow(); }
function cfsShow() { const R = CFS.res; const el = $('cf-res'); if (!el) return; const P = R.parts; const dr = r2(sum(R.L.filter(x => x.cl > 0), x => x.cl)), cr = r2(-sum(R.L.filter(x => x.cl < 0), x => x.cl));
  const tb = rows => rows.map(x => `<tr><td>${esc(x.name)}<div class="small muted">${esc(x.sub)}</div></td>${P.map((p, i) => `<td class="n small">${x.by[i] ? drcr(x.by[i]) : ''}</td>`).join('')}<td class="n b">${drcr(x.cl)}</td></tr>`).join('');
  el.innerHTML = `<div class="card"><div class="row" style="gap:8px;margin-bottom:8px"><h3 style="margin:0">${esc(R.name)} — FY ${esc(R.y)}</h3><span class="spacer"></span><span class="tag ${Math.abs(dr - cr) < 1 ? 't-ok' : 't-err'}">Dr ₹${fmt(dr)} · Cr ₹${fmt(cr)}</span><button class="sm" onclick="cfsPrint()">🖨 Print</button><button class="sm ghost" onclick="cfsXl()">📊 Excel</button></div>
    <p class="small">Surplus / (deficit) for the year, combined: <b>₹${fmt(R.surplus)}</b> (${P.map(p => esc(p.name)).join(' + ')})</p>
    <div class="tw" style="max-height:60vh"><table><thead><tr><th>Account head</th>${P.map(p => `<th class="n small">${esc(p.name)}</th>`).join('')}<th class="n">Combined</th></tr></thead><tbody>${['Liabilities', 'Assets', 'Income', 'Expenses'].map(g => `<tr class="grp"><td colspan="${P.length + 2}">${g}</td></tr>${tb(R.L.filter(x => x.grp === g).sort((a, b) => (a.sub + a.name).localeCompare(b.sub + b.name)))}`).join('')}</tbody></table></div>
    <p class="small muted" style="margin-top:6px">Heads are matched by name within the same group. Rename a head in one of the books if the same account carries different names. Transfers between the wings (if any) appear on both sides — remove them with a journal before combining, or show them as inter-wing balances.</p></div>`; }
function cfsSide(rows, credit) { const by = {}; rows.forEach(x => (by[x.sub || x.grp] = by[x.sub || x.grp] || []).push(x)); return Object.entries(by).map(([s, L]) => ({ s, L, t: r2(sum(L, x => credit ? -x.cl : x.cl)) })); }
function cfsPrint() { const R = CFS.res; const lia = cfsSide(R.liab, true), ast = cfsSide(R.ast, false), inc = cfsSide(R.inc, true), exp = cfsSide(R.exp, false);
  const col = G => G.map(g => `<tr class="grp"><td>${esc(g.s)}</td><td class="n">${fmt(g.t)}</td></tr>${g.L.map(x => `<tr><td style="padding-left:14px">${esc(x.name)}</td><td class="n small">${fmt(Math.abs(x.cl))}</td></tr>`).join('')}`).join('');
  const two = (lt, L, rt, Rr, lx, rx) => `<table><thead><tr><th>${lt}</th><th class="n">₹</th><th>${rt}</th><th class="n">₹</th></tr></thead><tbody><tr><td colspan="2" style="vertical-align:top;padding:0"><table>${col(L)}${lx || ''}</table></td><td colspan="2" style="vertical-align:top;padding:0"><table>${col(Rr)}${rx || ''}</table></td></tr></tbody></table>`;
  const sp = R.surplus >= 0 ? `<tr class="grp"><td>Excess of income over expenditure</td><td class="n">${fmt(R.surplus)}</td></tr>` : ''; const df = R.surplus < 0 ? `<tr class="grp"><td>Excess of expenditure over income</td><td class="n">${fmt(-R.surplus)}</td></tr>` : '';
  const hd = t => `<div style="text-align:center;margin-bottom:8px"><div style="font-size:17px;font-weight:800">${esc(R.name)}</div><div>${t} — FY ${esc(R.y)} (combined: ${R.parts.map(p => esc(p.name)).join(' + ')})</div></div>`;
  printDoc('Combined statements', `<div class="doc">${hd('INCOME & EXPENDITURE ACCOUNT')}${two('Expenditure', exp, 'Income', inc, sp, df)}</div><div class="pb"></div><div class="doc">${hd('BALANCE SHEET')}${two('Liabilities', lia, 'Assets', ast)}</div>`, { auto: false }); }
function cfsXl() { const R = CFS.res; const P = R.parts; xlsx(`Combined_${safeName(R.name).slice(0, 30)}_${R.y}`, [{ name: 'Combined TB', rows: [['Group', 'Sub-group', 'Head', ...P.map(p => p.name), 'Combined (Dr + / Cr −)'], ...R.L.sort((a, b) => (a.grp + a.sub + a.name).localeCompare(b.grp + b.sub + b.name)).map(x => [x.grp, x.sub, x.name, ...P.map((p, i) => x.by[i] || 0), x.cl])] }]); }
FEAT_ALL.firm[0][1].push(['combfs', '🧩', 'Combined Statements']); NAV_FIRM[0][1].push(['combfs', '🧩', 'Combined Statements']);

// ═══════════════════════════════════════════════════════════════════════
// SELLING AS A SERVICE (Selling 1–7): each customer is an "organisation": an accounting firm, a society that keeps its
// own books, or an auditor. Organisations sign up themselves with a free trial, add their own staff, have their own
// desk / AI key / features / printout line, choose a plan, and renew by paying UPI + uploading the screenshot.
// Shreedeep (the firm owners of this installation) approve payments, extend or close access from "Subscriptions".
// Societies created before this (no meta/org) are not affected in any way.
// ═══════════════════════════════════════════════════════════════════════
const ORG = { id: null, d: null, plat: null };
const PLANS_DEF = {
  trial: { n: 'Free trial', price: 0, socs: 3, feat: 'all', days: 30, d: 'Everything, for 30 days' },
  basic: { n: 'Basic', price: 999, socs: 3, feat: 'core', d: 'Accounting, billing, receipts, final accounts, member ledger, WhatsApp bills' },
  pro: { n: 'Professional', price: 2499, socs: 15, feat: 'all', d: 'Everything: AI, member app, collection & recovery, registers, GST/TDS, audit tools' },
  firm: { n: 'Firm', price: 5999, socs: 100, feat: 'all', d: 'Everything, for firms with many societies and staff' } };
const PLAT_DEF = { upi: '', name: 'Shreedeep Solutions', wa: '919004264282', phones: '90042 64282 / 90042 62639', plans: PLANS_DEF };
const plat = () => ({ ...PLAT_DEF, ...(ORG.plat || {}), plans: { ...PLANS_DEF, ...((ORG.plat || {}).plans || {}) } });
const orgPlan = () => plat().plans[(ORG.d || {}).plan] || PLANS_DEF.trial;
const orgActive = () => !!(ORG.d && !ORG.d.blocked && +ORG.d.until > Date.now());
const orgOwner = () => !!(ORG.d && S.user && ORG.d.owner === S.user.uid);
const orgDays = () => ORG.d ? Math.ceil((+ORG.d.until - Date.now()) / 864e5) : 0;
// firm/desk and firm/fin are the firm's own workspace; for an organisation they live under orgs/{id}/
function orgPath(p) { if (!ORG.id || FIRM.staff || typeof p !== 'string') return p; if (p === 'firm/desk' || p.startsWith('firm/desk/')) return `orgs/${ORG.id}/desk${p.slice(9)}`; if (p === 'firm/fin' || p.startsWith('firm/fin/')) return `orgFin/${ORG.id}${p.slice(8)}`; return p; }
function orgWrap() { if (FBX._orgW === FBX.get) return; ['get', 'set', 'remove', 'key', 'listen', 'lastN', 'range', 'txn'].forEach(m => { const o = FBX[m]; if (typeof o !== 'function') return; FBX[m] = function (p, ...a) { return o.call(this, orgPath(p), ...a); }; });
  const ou = FBX.update; FBX.update = function (map) { const m = {}; Object.entries(map || {}).forEach(([k, v]) => m[orgPath(k)] = v); return ou.call(this, m); }; FBX._orgW = FBX.get; }
// called from firmInit for users who are not Shreedeep staff
async function orgInit(u) { orgWrap(); ORG.id = null; ORG.d = null; let oid = null; try { oid = await FBX.get('userOrg/' + u.uid); } catch (e) { }
  if (!oid) { try { const k = emailKey(u.email); const inv = await FBX.get('orgInv/' + k); if (inv && inv.oid) { await FBX.update({ [`orgs/${inv.oid}/users/${u.uid}`]: { r: 'staff', e: u.email, n: u.displayName || u.email.split('@')[0], at: Date.now() }, ['userOrg/' + u.uid]: inv.oid, ['orgInv/' + k]: null }); oid = inv.oid; setTimeout(() => toast(`You have joined ${inv.n || 'your firm'}`, 'ok', 6000), 800); } } catch (e) { console.warn('org invite', e); } }
  if (!oid) return false; await orgLoad(oid); if (!ORG.d) { ORG.id = null; return false; } FIRM.ok = orgActive(); FIRM.admin = orgOwner(); return true; }
async function orgLoad(oid) { ORG.id = oid; try { ORG.d = await FBX.get('orgs/' + oid); } catch (e) { ORG.d = null; } try { ORG.plat = await FBX.get('plat/pub'); } catch (e) { }
  try { const b = await FBX.get('firm/desk/brand'); LS.set('sb_brand', JSON.stringify(b || (ORG.d ? { on: true, text: `Accounts maintained by ${ORG.d.name}${ORG.d.phone ? ' · ' + ORG.d.phone : ''}` } : null))); } catch (e) { } }
async function orgReload() { if (ORG.id) { await orgLoad(ORG.id); FIRM.ok = orgActive(); FIRM.admin = orgOwner(); } }
// ── societies belong to the organisation; the owner always gets access ──
function orgCanAdd() { if (!ORG.id) return; if (!orgActive()) throw new Error('Your subscription has ended — renew in My Firm → Plan'); const n = Object.keys(ORG.d.socs || {}).length, p = orgPlan(); if (n >= p.socs) throw new Error(`Your ${p.n} plan allows ${p.socs} societ${p.socs > 1 ? 'ies' : 'y'} — upgrade in My Firm → Plan`); }
function orgSocUp(up, P, sid) { if (!ORG.id) return; const m = up[`${P}/meta`]; m.org = ORG.id; const ow = ORG.d.owner; if (ow && ow !== S.user.uid) { const x = (ORG.d.users || {})[ow] || {}; m.access[ow] = { r: 'admin', e: x.e || '', n: x.n || '' }; } up[`orgs/${ORG.id}/socs/${sid}`] = { n: m.name, by: S.user.uid, at: Date.now() }; ORG.d.socs = { ...(ORG.d.socs || {}), [sid]: true }; }
(() => { const ol = loadFirmInfo; window.loadFirmInfo = loadFirmInfo = async function () { try { if (ORG.id && orgOwner()) Object.keys(ORG.d.socs || {}).forEach(sid => { if (!FIRM.list[sid]) FIRM.list[sid] = 'admin'; }); } catch (e) { } return ol.apply(this, arguments); }; })();
// expired subscription → the organisation's societies open read-only
(() => { const os = openSociety; window.openSociety = openSociety = async function (sid) { const r = await os.apply(this, arguments); try { if (S.sid && S.meta && S.meta.org && ORG.id === S.meta.org && !orgActive() && S.role !== 'viewer') { S.role = 'viewer'; buildSide(); render(); toast('The subscription has ended — the books are read-only. Renew in My Firm → Plan.', 'warn', 9000); } } catch (e) { } return r; }; })();
// plan → features (Basic = accounting & billing only)
(() => { const of = featOn; window.featOn = featOn = function (k) { if (ORG.id && !FIRM.staff && orgPlan().feat === 'core') return false; return of.apply(this, arguments); }; })();
// ── firm page: trial sign-up for a new user, banner for an organisation ─
(() => { const p = PAGES.firm; if (!p) return; const r = p.render; p.render = function () { const x = r.apply(this, arguments); setTimeout(orgDecorate, 30); return x; }; })();
function orgDecorate() { try { if (CUR.id !== 'firm' || $('org-ban')) return; const pc = document.querySelector('#main .pc'); if (!pc) return;
  if (!FIRM.ok && !ORG.id && !FIRM.staff) { const w = pc.querySelector('.alert.a-warn'); if (w && /waiting/i.test(w.textContent)) w.style.display = 'none';
    pc.insertAdjacentHTML('afterbegin', `<div id="org-ban" class="grid g3" style="margin-bottom:14px"><div class="card" style="border-color:var(--accent)"><h3>🚀 Start your free ${plat().plans.trial.days || 30}-day trial</h3><p class="small">For accounting firms, societies that keep their own books, and auditors. No card needed. Your data stays private to your team.</p><button onclick="trialModal()">Start free trial</button></div><div class="card"><h3>👥 Joining a firm?</h3><p class="small">Ask your firm to invite <b>${esc(S.user.email)}</b> (My Firm → Team), then log in again. Shreedeep Solutions staff: your request is waiting for approval.</p><button class="ghost" onclick="location.reload()">↻ Check again</button></div><div class="card"><h3>🏠 A society member?</h3><p class="small">See your bills, pay by UPI and send requests — join your society with the code or invite link from the society office.</p><button class="ghost" onclick="firmUnpend();mpJoin(S.user,'')">Join my society</button></div></div>`); return; }
  if (ORG.id && ORG.d) { const w = pc.querySelector('.alert.a-warn'); if (w && /waiting/i.test(w.textContent)) w.style.display = 'none'; const dl = orgDays(); const p = orgPlan(); const pend = Object.values(ORG.d.pays || {}).some(x => x && x.st === 'new');
    pc.insertAdjacentHTML('afterbegin', `<div id="org-ban" class="alert ${!orgActive() ? 'a-err' : dl <= 7 ? 'a-warn' : 'a-ok'} small" style="margin-bottom:12px"><b>${esc(ORG.d.name)}</b> · ${esc(p.n)} plan · ${ORG.d.blocked ? 'access closed — contact ' + esc(plat().phones) : !orgActive() ? 'subscription ended — books are read-only' : dl + ' day' + (dl === 1 ? '' : 's') + ' left'}${pend ? ' · payment awaiting confirmation' : ''} <button class="xs ${orgActive() && dl > 7 ? 'ghost' : ''}" style="margin-left:8px" onclick="go('org')">${orgActive() && dl > 7 ? 'My Firm' : 'Renew'}</button></div>`); } } catch (e) { } }
function trialModal() { openModal({ title: '🚀 Start your free trial', ok: 'Start trial', body: `<div data-form><label>Who are you?</label><select id="tr-k"><option value="firm">An accounting firm (we keep books for societies)</option><option value="society">A society — we keep our own books (secretary / treasurer / committee)</option><option value="auditor">An auditor</option></select>
  <div class="fr c2" style="margin-top:8px"><div><label>Firm / society name</label><input id="tr-n" placeholder="e.g. ABC Associates"></div><div><label>Mobile</label><input id="tr-p" inputmode="tel" placeholder="10-digit"></div></div><div class="fr c2"><div><label>City</label><input id="tr-c"></div><div><label>Your name</label><input id="tr-y" value="${esc(uname())}"></div></div>
  <label class="row small" style="margin-top:10px"><input type="checkbox" id="tr-ok"> I agree to the <a href="?terms" target="_blank">Terms of Service</a> and <a href="?privacy" target="_blank">Privacy Policy</a></label></div>`,
  onOk: async () => { const n = val('tr-n').trim(), ph = val('tr-p').replace(/\D/g, '').slice(-10); if (!n) throw new Error('Name required'); if (!/^[6-9]\d{9}$/.test(ph)) throw new Error('Valid 10-digit mobile required'); if (!$('tr-ok').checked) throw new Error('Please accept the Terms and Privacy Policy');
    const oid = FBX.key('orgs'); const u = S.user; const days = Math.min(30, +(plat().plans.trial.days || 30));
    await FBX.update({ [`orgs/${oid}`]: { name: n, kind: val('tr-k'), phone: ph, city: val('tr-c').trim(), owner: u.uid, plan: 'trial', until: Date.now() + days * 864e5 - 60000, at: Date.now(), users: { [u.uid]: { r: 'owner', e: u.email, n: val('tr-y').trim() || uname(), at: Date.now() } } }, ['userOrg/' + u.uid]: oid, ['firm/pending/' + u.uid]: null });
    await orgInit(u); buildSide(); toast(`Welcome! Your trial runs till ${fd(ymd(new Date(+ORG.d.until)))}.`, 'ok', 8000); render();
    setTimeout(async () => { if (await confirmBox('Create a practice society with sample flats to try things out? (You can delete it later.)', { ok: 'Yes, create demo' })) demoSociety(); }, 600); } }); }
// ── My Firm page (organisation owner and staff) ─────────────────────────
page('org', {
  async render() { if (!ORG.id) return shell('My Firm', '', '', '<div class="card empty">This login does not belong to an organisation.</div>'); await orgReload(); const d = ORG.d || {}; const P = plat(); const p = orgPlan(); const own = orgOwner(); const U = Object.entries(d.users || {}); const pays = Object.entries(d.pays || {}).sort((a, b) => b[1].at - a[1].at);
    shell('🏢 My Firm', 'Your organisation, plan, team and printouts', '',
      `<div class="grid g2"><div class="card"><h3>Plan</h3><div class="stat"><div class="v">${esc(p.n)}</div><div class="l">${d.blocked ? '<span class="dr">access closed</span>' : orgActive() ? `valid till ${fd(ymd(new Date(+d.until)))} (${orgDays()} days)` : '<span class="dr">ended ' + fd(ymd(new Date(+d.until))) + '</span>'}</div></div><p class="small">${esc(p.d || '')} · up to ${p.socs} societ${p.socs > 1 ? 'ies' : 'y'} (using ${Object.keys(d.socs || {}).length})</p>${own ? `<button onclick="orgPayModal()">💳 Renew / upgrade</button>` : ''}</div>
        <div class="card" data-form><h3>Details</h3><div class="fr c2"><div><label>Name</label><input id="og-n" value="${esc(d.name || '')}" ${own ? '' : 'disabled'}></div><div><label>Mobile</label><input id="og-p" value="${esc(d.phone || '')}" ${own ? '' : 'disabled'}></div></div><div class="fr c2"><div><label>City</label><input id="og-c" value="${esc(d.city || '')}" ${own ? '' : 'disabled'}></div><div><label>Type</label><input value="${esc({ firm: 'Accounting firm', society: 'Society (own books)', auditor: 'Auditor' }[d.kind] || '')}" disabled></div></div>${own ? `<button class="sm" onclick="orgSave()">Save</button>` : ''}</div></div>
      <div class="card"><h3>Team (${U.length})</h3><table><tbody>${U.map(([u, x]) => `<tr><td class="b">${esc(x.n || '')}</td><td class="small">${esc(x.e || '')}</td><td>${x.r === 'owner' ? '<span class="tag t-ok">Owner</span>' : 'Staff'}</td><td>${own && x.r !== 'owner' ? `<button class="xs ghost" onclick="orgRemove('${u}')">Remove</button>` : ''}</td></tr>`).join('')}</tbody></table>
        ${own ? `<div class="row" style="gap:6px;margin-top:10px"><input id="og-i" type="email" placeholder="staff@email.com" style="flex:1"><button class="sm" onclick="orgInvite()">+ Invite</button></div><p class="small muted">They register / log in with this email and join automatically. Then add them to societies from each society's Team page.</p>` : ''}</div>
      <div class="card"><h3>Payments</h3><table><tbody>${pays.map(([, x]) => `<tr><td>${new Date(x.at).toLocaleDateString('en-IN')}</td><td>${esc((P.plans[x.plan] || {}).n || x.plan)} × ${x.months} month(s)</td><td class="n">₹${fmt(x.amt)}</td><td class="small mono">${esc(x.utr || '')}</td><td>${x.st === 'ok' ? '<span class="tag t-ok">Confirmed</span>' : x.st === 'no' ? '<span class="tag t-err">Not received</span>' : '<span class="tag t-warn">Waiting</span>'}</td></tr>`).join('') || '<tr><td class="empty">No payments yet</td></tr>'}</tbody></table></div>
      <p class="small muted">AI key, features, printout line and the desk (tasks, fee invoices) are your organisation's own — set them from All Societies. <a href="?terms" target="_blank">Terms</a> · <a href="?privacy" target="_blank">Privacy</a> · Help: ${esc(P.phones)}</p>`); }
});
async function orgSave() { if (!orgOwner()) return; const n = val('og-n').trim(); if (!n) return toast('Name required', 'warn'); await FBX.update({ [`orgs/${ORG.id}/name`]: n, [`orgs/${ORG.id}/phone`]: val('og-p').trim(), [`orgs/${ORG.id}/city`]: val('og-c').trim() }); toast('Saved'); render(); }
async function orgInvite() { const e = val('og-i').trim().toLowerCase(); if (!/^\S+@\S+\.\S+$/.test(e)) return toast('Type a valid email', 'warn'); await FBX.update({ ['orgInv/' + emailKey(e)]: { oid: ORG.id, n: ORG.d.name, by: uname(), at: Date.now() } }); toast(`Invited ${e} — they join when they log in`, 'ok', 6000); $('og-i').value = ''; }
async function orgRemove(u) { if (!await confirmBox('Remove this person from your organisation? Also remove them from each society\'s Team page.', { danger: true })) return; await FBX.update({ [`orgs/${ORG.id}/users/${u}`]: null, ['userOrg/' + u]: null }); toast('Removed'); render(); }
// ── renew / upgrade: UPI + screenshot (or WhatsApp the screenshot) ──────
function orgPayModal() { const P = plat(); const L = Object.entries(P.plans).filter(([k, x]) => k !== 'trial' && x.price > 0); const cur = (ORG.d.plan !== 'trial' && P.plans[ORG.d.plan]) ? ORG.d.plan : (L[0] || [])[0];
  openModal({ title: '💳 Renew / upgrade', wide: true, hideOk: true, cancel: 'Close', body: `<div data-form><div class="grid g3" style="margin-bottom:10px">${L.map(([k, x]) => `<label class="card" style="cursor:pointer;margin:0"><input type="radio" name="op-p" value="${k}" ${k === cur ? 'checked' : ''} onchange="orgPayCalc()"> <b>${esc(x.n)}</b><div class="v" style="font-size:20px;font-weight:800">₹${fmt0(x.price)}<span class="small muted">/month</span></div><div class="small">${esc(x.d || '')}<br>Up to ${x.socs} societies</div></label>`).join('')}</div>
    <div class="fr c3"><div><label>Months</label><select id="op-m" onchange="orgPayCalc()">${[1, 3, 6, 12].map(m => `<option value="${m}" ${m === 12 ? 'selected' : ''}>${m}${m === 12 ? ' (2 months free)' : ''}</option>`).join('')}</select></div><div><label>Amount</label><div id="op-a" class="b" style="font-size:20px;padding-top:4px"></div></div><div></div></div>
    <div id="op-pay" style="margin-top:8px"></div><p class="small" style="margin-top:10px"><b>After paying:</b> upload the payment screenshot here — your plan is extended as soon as ${esc(P.name)} confirms it (usually the same day).</p>
    <div class="row" style="gap:8px;flex-wrap:wrap"><button onclick="orgPayShot()">📷 Upload screenshot</button><button class="ghost" onclick="orgPayWa()">💬 Send screenshot on WhatsApp</button></div><div id="op-r" class="small" style="margin-top:8px"></div></div>`, onOpen: orgPayCalc }); }
function orgPaySel() { const P = plat(); const k = (document.querySelector('input[name="op-p"]:checked') || {}).value; const m = +val('op-m') || 1; const x = P.plans[k] || {}; return { k, m, x, amt: r2((x.price || 0) * (m === 12 ? 10 : m)) }; }
function orgPayCalc() { const P = plat(); const s = orgPaySel(); if (!s.k) return; $('op-a').textContent = '₹' + fmt(s.amt); const tn = `S4S ${ORG.d.name} ${s.x.n} ${s.m}m`.slice(0, 60); const url = P.upi ? `upi://pay?pa=${encodeURIComponent(P.upi)}&pn=${encodeURIComponent(P.name)}&am=${s.amt.toFixed(2)}&cu=INR&tn=${encodeURIComponent(tn)}` : '';
  $('op-pay').innerHTML = url ? `<div class="row" style="gap:14px;align-items:center">${typeof qrImg === 'function' ? qrImg(url) : ''}<div><a class="btn" href="${url}">Pay ₹${fmt(s.amt)} by UPI app</a><div class="small muted" style="margin-top:6px">UPI ID: <b>${esc(P.upi)}</b> · on a computer, scan the QR with your phone</div></div></div>` : `<div class="alert a-warn small">Call ${esc(P.phones)} for payment details.</div>`; }
async function orgPayShot() { const s = orgPaySel(); if (!s.k) return toast('Pick a plan', 'warn'); pickFiles('image/*', async fs => { const f = fs[0]; if (!f) return; let x = {}; try { const t = await aiTry('Reading the screenshot on this device…', () => ocrText(f)); x = upiParse(t || '') || {}; } catch (e) { }
  const rec = { plan: s.k, months: s.m, amt: s.amt, paid: x.amt || null, utr: x.utr || '', d: x.d || today(), at: Date.now(), by: uname(), st: 'new' }; await FBX.update({ [`orgs/${ORG.id}/pays/${FBX.key('p')}`]: rec });
  $('op-r').innerHTML = `<div class="alert a-ok">Received${x.utr ? ` — UTR <b>${esc(x.utr)}</b>` : ''}${x.amt ? `, ₹${fmt(x.amt)}` : ''}. We will confirm shortly. ${x.amt && Math.abs(x.amt - s.amt) > 1 ? '<br><span class="dr">The amount on the screenshot differs from the plan amount — we will check.</span>' : ''}</div>`; await orgReload(); }, false); }
function orgPayWa() { const s = orgPaySel(); window.open(`https://wa.me/${plat().wa}?text=` + encodeURIComponent(`Payment for Solutions4Society\nOrganisation: ${ORG.d.name}\nPlan: ${(s.x || {}).n} × ${s.m} month(s)\nAmount: ₹${fmt(s.amt)}\nLogin: ${S.user.email}\n\n(screenshot attached)`), '_blank'); }
// ── platform owners: Subscriptions ──────────────────────────────────────
page('subs', {
  async render() { if (!FIRM.staff || !(await FBX.get('firm/admins/' + S.user.uid).catch(() => null))) return shell('Subscriptions', '', '', '<div class="alert a-warn">Only the firm owners can see subscriptions.</div>');
    shell('💼 Subscriptions', 'Organisations using the software, their plans and payments', `<button class="ghost" onclick="platModal()">⚙ Plans & UPI</button>`, loading('Loading…'));
    const [O, pp] = await Promise.all([FBX.get('orgs').catch(() => null), FBX.get('plat/pub').catch(() => null)]); ORG.plat = pp; const P = plat(); const f = RP.get('sb_f', 'all'); const now = Date.now();
    const L = Object.entries(O || {}).filter(([, o]) => o && o.name).map(([id, o]) => ({ id, o, act: !o.blocked && +o.until > now, pend: Object.entries(o.pays || {}).filter(([, x]) => x && x.st === 'new') })).filter(x => f === 'all' || (f === 'pend' ? x.pend.length : f === 'act' ? x.act : !x.act)).sort((a, b) => b.pend.length - a.pend.length || (+a.o.until) - (+b.o.until));
    const mrr = sum(Object.values(O || {}).filter(o => o && !o.blocked && +o.until > now && o.plan !== 'trial'), o => (P.plans[o.plan] || {}).price || 0);
    $('main').querySelector('.pc').innerHTML = `<div class="grid g4" style="margin-bottom:12px"><div class="stat"><div class="v">${Object.keys(O || {}).length}</div><div class="l">organisations</div></div><div class="stat"><div class="v">${Object.values(O || {}).filter(o => o && o.plan === 'trial' && +o.until > now).length}</div><div class="l">on trial</div></div><div class="stat"><div class="v">${Object.values(O || {}).filter(o => o && o.plan !== 'trial' && +o.until > now && !o.blocked).length}</div><div class="l">paying</div></div><div class="stat"><div class="v">₹${fmt0(mrr)}</div><div class="l">per month</div></div></div>
      <div class="toolbar"><select onchange="RP.set('sb_f',this.value);render()">${[['all', 'All'], ['pend', 'Payment waiting'], ['act', 'Active'], ['exp', 'Ended / closed']].map(([k, l]) => `<option value="${k}" ${k === f ? 'selected' : ''}>${l}</option>`).join('')}</select></div>
      <div class="tw"><table><thead><tr><th>Organisation</th><th>Plan</th><th>Valid till</th><th class="n">Societies</th><th>Payment</th><th></th></tr></thead><tbody>${L.map(({ id, o, act, pend }) => `<tr><td class="b">${esc(o.name)}<div class="small muted">${esc({ firm: 'Firm', society: 'Society', auditor: 'Auditor' }[o.kind] || '')} · ${esc(o.city || '')} · ${esc(o.phone || '')} · ${esc(((o.users || {})[o.owner] || {}).e || '')}</div></td><td>${esc((P.plans[o.plan] || {}).n || o.plan)}</td><td class="${act ? '' : 'dr b'}">${o.blocked ? 'closed' : fd(ymd(new Date(+o.until)))}</td><td class="n">${Object.keys(o.socs || {}).length}</td>
        <td class="small">${pend.map(([pid, x]) => `₹${fmt(x.amt)} ${esc((P.plans[x.plan] || {}).n || x.plan)} × ${x.months}m${x.utr ? ` · UTR ${esc(x.utr)}` : ''}${x.paid && Math.abs(x.paid - x.amt) > 1 ? ` · <span class="dr">screenshot ₹${fmt(x.paid)}</span>` : ''}<br><button class="xs" onclick="subPay('${id}','${pid}',true)">✓ Received</button> <button class="xs ghost" onclick="subPay('${id}','${pid}',false)">✗</button>`).join('<br>')}</td>
        <td style="white-space:nowrap"><button class="xs ghost" onclick="subExtend('${id}')">+ Days</button> ${o.blocked ? `<button class="xs ghost" onclick="subBlock('${id}',false)">Reopen</button>` : `<button class="xs ghost" onclick="subBlock('${id}',true)">Close access</button>`}</td></tr>`).join('') || '<tr><td colspan="6" class="empty">No organisations yet</td></tr>'}</tbody></table></div>`; }
});
async function subPay(oid, pid, ok) { const o = await FBX.get('orgs/' + oid); const x = (o.pays || {})[pid]; if (!x) return; const up = { [`orgs/${oid}/pays/${pid}/st`]: ok ? 'ok' : 'no', [`orgs/${oid}/pays/${pid}/dec`]: { by: uname(), at: Date.now() } };
  if (ok) { const from = Math.max(Date.now(), +o.until || 0); const d = new Date(from); d.setMonth(d.getMonth() + (+x.months || 1)); up[`orgs/${oid}/until`] = d.getTime(); up[`orgs/${oid}/plan`] = x.plan; up[`orgs/${oid}/blocked`] = null; }
  await FBX.update(up); toast(ok ? 'Confirmed — plan extended' : 'Marked not received'); render(); }
function subExtend(oid) { openModal({ title: 'Extend access', ok: 'Extend', body: `<div data-form><label>Days</label><input id="sx-n" class="num" type="number" value="15"></div>`, onOk: async () => { const n = Math.round(nval('sx-n')); if (!(n > 0)) throw new Error('Type the number of days'); const o = await FBX.get('orgs/' + oid); await FBX.update({ [`orgs/${oid}/until`]: Math.max(Date.now(), +o.until || 0) + n * 864e5, [`orgs/${oid}/blocked`]: null }); toast(`Extended by ${n} days`); render(); } }); }
async function subBlock(oid, on) { if (on && !await confirmBox('Close access for this organisation? They cannot open their societies until you reopen it.', { danger: true })) return; await FBX.update({ [`orgs/${oid}/blocked`]: on ? true : null }); toast(on ? 'Access closed' : 'Access reopened'); render(); }
function platModal() { const P = plat(); openModal({ title: '⚙ Plans & UPI', wide: true, ok: 'Save', body: `<div data-form><div class="fr c3"><div><label>Your UPI ID (customers pay here)</label><input id="pl-u" value="${esc(P.upi)}" placeholder="shreedeep@okhdfc"></div><div><label>Name shown</label><input id="pl-n" value="${esc(P.name)}"></div><div><label>WhatsApp no. for screenshots</label><input id="pl-w" value="${esc(P.wa)}"></div></div>
  <table style="margin-top:8px"><thead><tr><th>Plan</th><th>Name</th><th class="n">₹ / month</th><th class="n">Societies</th><th>Features</th><th>Description</th></tr></thead><tbody>${Object.entries(P.plans).map(([k, x]) => `<tr data-pl="${k}"><td class="small">${k}</td><td><input class="pl-n" value="${esc(x.n)}"></td><td><input class="pl-p num" type="number" value="${x.price || 0}" ${k === 'trial' ? 'disabled' : ''}></td><td><input class="pl-s num" type="number" value="${x.socs}"></td><td><select class="pl-f"><option value="all" ${x.feat !== 'core' ? 'selected' : ''}>Everything</option><option value="core" ${x.feat === 'core' ? 'selected' : ''}>Accounting & billing</option></select></td><td><input class="pl-d" value="${esc(x.d || '')}"></td></tr>`).join('')}</tbody></table><p class="small muted">Trial length (days): <input id="pl-t" class="num" type="number" style="width:80px" value="${P.plans.trial.days || 30}"></p></div>`,
  onOk: async () => { const plans = {}; $$('tr[data-pl]').forEach(tr => { const k = tr.dataset.pl; const q = c => tr.querySelector(c); plans[k] = { n: q('.pl-n').value.trim() || k, price: +q('.pl-p').value || 0, socs: Math.max(1, +q('.pl-s').value || 1), feat: q('.pl-f').value, d: q('.pl-d').value.trim(), ...(k === 'trial' ? { days: Math.max(1, +val('pl-t') || 30) } : {}) }; });
    await FBX.set('plat/pub', { upi: val('pl-u').trim(), name: val('pl-n').trim() || 'Shreedeep Solutions', wa: val('pl-w').replace(/\D/g, '') || PLAT_DEF.wa, phones: PLAT_DEF.phones, plans }); toast('Saved'); render(); } }); }
// ── menus: organisation users get My Firm (and no Shreedeep staff page); owners get Subscriptions ──
(() => { const ob = buildSide; window.buildSide = buildSide = function () { try { const F = (typeof FEAT_ALL !== 'undefined' ? FEAT_ALL.firm : NAV_FIRM)[0][1]; const has = id => F.some(x => x[0] === id); if (ORG.id && !has('org')) F.splice(1, 0, ['org', '🏢', 'My Firm']); if (!ORG.id && has('org')) F.splice(F.findIndex(x => x[0] === 'org'), 1);
  const st = F.findIndex(x => x[0] === 'staff'); if (ORG.id && !FIRM.staff && st >= 0) ORG._staff = F.splice(st, 1)[0]; else if ((!ORG.id || FIRM.staff) && st < 0 && ORG._staff) F.splice(1, 0, ORG._staff);
  if (FIRM.staff && FIRM.admin && !has('subs')) F.push(['subs', '💼', 'Subscriptions']); if (!(FIRM.staff && FIRM.admin) && has('subs')) F.splice(F.findIndex(x => x[0] === 'subs'), 1); } catch (e) { } return ob.apply(this, arguments); }; })();
