function nrPayee(bankNar) { const s = String(bankNar || '').toUpperCase().replace(/[^A-Z ]+/g, ' '); const STOP = new Set(['NEFT', 'RTGS', 'IMPS', 'UPI', 'CHQ', 'CHEQUE', 'CLG', 'INWARD', 'OUTWARD', 'TRANSFER', 'TRF', 'PAID', 'TO', 'FROM', 'BY', 'FOR', 'THE', 'AND', 'BANK', 'LTD', 'LIMITED', 'PVT', 'HDFC', 'ICICI', 'SBIN', 'SBI', 'UTIB', 'AXIS', 'KKBK', 'KOTAK', 'BARB', 'CNRB', 'PUNB', 'IDFB', 'YESB', 'INDB', 'MAHB', 'COSB', 'SVCB', 'DEBIT', 'CREDIT', 'PAYMENT', 'IB', 'MB', 'BIL', 'ONL', 'INB', 'REF', 'NO', 'AC', 'ACC', 'OKAXIS', 'OKHDFCBANK', 'OKICICI', 'OKSBI', 'YBL', 'PAYTM']);
  const clean = seg => seg.toUpperCase().replace(/[^A-Z ]+/g, ' ').split(' ').filter(x => x.length >= 2 && !STOP.has(x) && !/^[A-Z]{4}0/.test(x));
  const segs = String(bankNar || '').split(/[\/|:\\]+/).map(clean).filter(w => w.length && w.join('').length >= 4).sort((a, b) => b.join('').length - a.join('').length);
  const w = (segs[0] || s.split(' ').filter(x => x.length >= 3 && !STOP.has(x))).slice(0, 4); return w.map(x => x[0] + x.slice(1).toLowerCase()).join(' '); }
function nrFill(tpl, x, vars) { return tpl.replace(/\{(\w+)\}/g, (a, k) => vars[k] != null ? vars[k] : a).replace(/\s+/g, ' ').trim(); }
function narSmart(x, bank) { if (!x || x.err) return null; const d = x.d; const isP = !!x.dr; const head = x.h ? (S.heads[x.h] || {}).name || '' : ''; const m = x.m ? M(x.m) : null;
  const vars = { month: nrFmt(d.slice(0, 7), { full: true, sep: ' ', yl: 4 }), prev: nrFmt(nrShift(d, -1), { full: true, sep: ' ', yl: 4 }), next: nrFmt(nrShift(d, 1), { full: true, sep: ' ', yl: 4 }), head, payee: nrPayee(x.nar), ref: x.ref || '', mode: x.mode || '', flat: m ? flatLbl(m) : '', name: m ? m.name || '' : '', member: m ? memLbl(m) : '' };
  const rule = x.h && NR_RULES()[x.h]; if (rule && rule.t) return { t: nrFill(rule.t, x, vars), how: 'rule' };
  const lr = nrLearn()[m ? 'm:dues' : x.h]; if (lr) { const t = lr.off != null ? lr.tpl.replace('{M}', nrFmt(nrShift(d, lr.off), lr.st || { full: true, sep: ' ', yl: 4 })) : lr.tpl; return { t: nrFill(t, x, vars), how: 'learned' }; }
  // standard wording
  const hn = head.toLowerCase(); let t;
  if (m) t = `Being amount received from ${vars.member}${x.mode ? ' by ' + x.mode : ''}${x.ref ? ' (ref ' + x.ref + ')' : ''}`;
  else if (isCB(x.h)) t = /cash/i.test(head) ? (isP ? 'Being cash withdrawn from bank' : 'Being cash deposited into bank') : `Being amount transferred ${isP ? 'to' : 'from'} ${head}`;
  else if (!isP) t = /interest/.test(hn) ? `Being ${head} credited by the bank` : `Being amount received towards ${head}${vars.payee ? ' from ' + vars.payee : ''}`;
  else if (/salar|wage|security|watchm|housekeep|sweep|conservancy|garden|caretaker|liftman|accounting|account writing|book.?keep|professional|audit fee|manager|staff/.test(hn)) t = `Being amount paid towards ${head} for ${vars.prev}`;
  else if (/electric|mseb|msedcl|adani|tata power|water|telephone|internet|broadband|mobile/.test(hn)) t = `Being amount paid towards ${head} bill${vars.payee ? ' to ' + vars.payee : ''} for ${vars.prev}`;
  else if (/bank charge|charges|commission|gst on/.test(hn)) t = `Being ${head} debited by the bank`;
  else if (/tds|tax|property tax|nmmc|bmc|municipal/.test(hn)) t = `Being ${head} paid${vars.ref ? ' (challan ' + vars.ref + ')' : ''}`;
  else t = `Being amount paid${vars.payee ? ' to ' + vars.payee : ''} towards ${head}`;
  return { t, how: 'standard' }; }
// statement preview: fill blank "Narration for books" and let the user edit before posting
(() => { const op = bsPreview; window.bsPreview = bsPreview = function (P) { try { (P.rows || []).forEach(x => { if (!x.err && !String(x.bnar || '').trim()) { const s = narSmart(x, P.bank); if (s) { x.bnar = s.t; x.bnarHow = s.how; } } }); } catch (e) { console.warn('narration', e); }
  const r = op.apply(this, arguments); try { const rows = P.rows; $$('.bs-ck').forEach(ck => { const i = +ck.dataset.i; const x = rows[i]; const tr = ck.closest('tr'); const td = tr && tr.children[4]; if (!td || x.err || td.querySelector('.bs-nar')) return;
    td.insertAdjacentHTML('beforeend', `<input class="bs-nar" data-i="${i}" value="${esc(x.bnar || '')}" title="Narration in the books${x.bnarHow ? ' (' + ({ rule: 'from your rule', learned: 'learned from your earlier entries', standard: 'standard wording' })[x.bnarHow] + ')' : ''}" style="display:block;width:100%;min-width:240px;margin-top:4px;font-size:12px;padding:4px 6px" oninput="__BS.rows[${i}].bnar=this.value">`); });
    const th = document.querySelectorAll('.ov:last-child thead th')[4]; if (th && !/narration/i.test(th.textContent)) th.innerHTML = 'Account <span class="muted small">· narration in books (edit if needed)</span>';
    const b = document.querySelector('.ov:last-child .md-b p.small.muted:last-child'); if (b && !b.querySelector('.nr-l')) b.insertAdjacentHTML('beforeend', ` <span class="nr-l">Narrations follow <a href="#" onclick="nrModal();return false">your narration rules</a> or your earlier entries.</span>`); } catch (e) { } return r; }; })();
// narration rules per head
function nrModal() { guardEdit(); const R = NR_RULES(); const lr = nrLearn(); const hs = Object.entries(S.heads).filter(([, h]) => h && h.active !== false && !h.tag && h.type !== 'bank' && h.type !== 'cash' && ['Expenses', 'Income', 'Liabilities', 'Assets'].includes(h.grp)).sort((a, b) => (a[1].grp + a[1].name).localeCompare(b[1].grp + b[1].name));
  const ex = hid => { const l = lr[hid]; if (!l) return ''; return l.off != null ? l.tpl.replace('{M}', l.off === -1 ? '{prev}' : l.off === 1 ? '{next}' : l.off === 0 ? '{month}' : '{month}') : l.tpl; };
  openModal({ title: '📝 Narration rules', wide: true, ok: 'Save', body: `<p class="small">How entries from the bank statement are narrated in the books. Use <b>{prev}</b> = previous month (May 2026 for a payment in June), <b>{month}</b> = month of payment, <b>{next}</b>, <b>{payee}</b> = name from the bank narration, <b>{head}</b>, <b>{ref}</b>. Blank = learned from your earlier entries (shown in grey), else a standard narration.</p>
    <div class="tw" style="max-height:55vh"><table><thead><tr><th>Head</th><th>Narration</th></tr></thead><tbody>${hs.map(([id, h]) => `<tr><td class="small">${esc(h.name)}<div class="muted" style="font-size:10.5px">${esc(h.grp)}</div></td><td><input class="nr-r" data-h="${id}" value="${esc((R[id] || {}).t || '')}" placeholder="${esc(ex(id) || 'e.g. Being amount paid towards ' + h.name + ' for {prev}')}" style="width:100%"></td></tr>`).join('')}</tbody></table></div>`,
    onOk: async () => { const up = {}; $$('.nr-r').forEach(i => { const v = i.value.trim(); const o = (R[i.dataset.h] || {}).t || ''; if (v !== o) up[`bcfg/_nar/${i.dataset.h}`] = v ? { t: v } : null; }); if (!Object.keys(up).length) return; await commit(up, { a: 'edit', e: 'Narration rules', s: `${Object.keys(up).length} head(s)` }); toast('Saved'); } }); }
addAct('bstmt', () => canEdit() ? `<button class="ghost" onclick="nrModal()">📝 Narration rules</button>` : '');
// the template for Claude / AI also tells it how this society writes narrations
function nrStyleLines() { const R = NR_RULES(), L = nrLearn(); const out = []; const seen = new Set();
  Object.entries(R).forEach(([h, r]) => { if (r && r.t && S.heads[h]) { out.push(`   – ${S.heads[h].name}: "${r.t}"`); seen.add(h); } });
  Object.entries(L).forEach(([h, l]) => { if (seen.has(h) || out.length > 40) return; const name = h === 'm:dues' ? 'Members (maintenance received)' : (S.heads[h] || {}).name; if (!name) return; out.push(`   – ${name}: "${l.off != null ? l.tpl.replace('{M}', l.off === -1 ? '{previous month}' : l.off === 0 ? '{month of payment}' : '{month ' + (l.off > 0 ? '+' : '') + l.off + '}') : l.tpl}"`); });
  return out; }

// ═══════════════════════════════════════════════════════════════════════
// KEYBOARD EVERYWHERE (Tally-style)
// • Enter → next box … on the last box Enter saves (OK / Save). Shift+Enter → previous box.
//   In a drop-down list, Enter picks the highlighted item and moves on; Enter on a filled list moves on.
// • Ctrl+S → save the open window or the form on the page · Alt+= (plus) → the page's "+ New" button (Alt+N stays Notices)
// • Delete (when not typing) → delete the entry / item that is open (asks to confirm first)
// ═══════════════════════════════════════════════════════════════════════
const KB_FIELDS = 'input:not([type=hidden]):not([type=file]):not([disabled]):not([readonly]), select:not([disabled]), textarea:not([disabled]), .ap-d[tabindex="0"]';
const kbVisible = el => !!(el && el.offsetParent !== null && el.getClientRects().length);
function kbScope(el) { return (el.closest && (el.closest('.ov') || el.closest('#vf') || el.closest('[data-form]') || el.closest('#main') || el.closest('#public'))) || document.body; }
function kbSaveBtn(scope) { const ov = scope.closest ? scope.closest('.ov') : null; if (ov) return ov.querySelector('[data-ok]:not([disabled])');
  const root = scope.id === 'main' || scope.closest('#main') ? document.getElementById('main') : scope;
  return root.querySelector('button[onclick^="vfSave"], button[onclick^="jvSave"], button[onclick^="bcSave"], button[onclick^="pkSave"], button[onclick^="budSave"], button[onclick^="guardIn"], button[onclick^="mpSend"], button[onclick^="crSave"]') || [...root.querySelectorAll('button')].find(b => kbVisible(b) && /^(💾\s*)?(save|post|ok)\b/i.test(b.textContent.trim())); }
function kbMove(from, dir) { const scope = kbScope(from); const F = [...scope.querySelectorAll(KB_FIELDS)].filter(e => kbVisible(e) && !e.closest('.ap-l, .ap-box, .ap-list') && !e.classList.contains('ap-s') && e.type !== 'search');
  const cur = from.closest('.ap') ? from.closest('.ap').querySelector('.ap-d') : from; const i = F.indexOf(cur);
  const nx = F[i + dir]; if (nx) { nx.focus(); if (nx.select && nx.tagName === 'INPUT' && !/checkbox|radio|date|month/.test(nx.type)) try { nx.select(); } catch (e) { } return true; }
  if (dir > 0) { const b = kbSaveBtn(scope); if (b && kbVisible(b)) { b.focus(); b.click(); return true; } } return false; }
const kbOwnEnter = el => { const a = (el.getAttribute && (el.getAttribute('onkeydown') || el.getAttribute('onkeyup') || el.getAttribute('onkeypress'))) || ''; return /Enter/.test(a) && !/apKey/.test(a); };
const kbTyping = () => { const a = document.activeElement; return !!a && (/INPUT|TEXTAREA|SELECT/.test(a.tagName) || a.isContentEditable); };
document.addEventListener('keydown', e => {
  const t = e.target; if (!t || !t.closest) return;
  // ── Enter → next ──
  if (e.key === 'Enter' && !e.ctrlKey && !e.metaKey && !e.altKey) {
    if (t.tagName === 'TEXTAREA' || t.tagName === 'BUTTON' || t.tagName === 'A' || t.type === 'search' || t.closest('#gs, .gs, #gs-r') || t.dataset.noenter != null || kbOwnEnter(t) || /search|filter|ask anything|type a command/i.test(t.placeholder || '')) return;
    if (t.closest('#auth')) return;
    const ap = t.closest('.ap');
    if (ap) { if (ap.classList.contains('open')) { setTimeout(() => { if (!ap.classList.contains('open')) kbMove(ap.querySelector('.ap-d'), 1); }, 0); return; }
      const hid = ap.id && document.getElementById(ap.id.replace(/^ap_/, '')); if (hid && hid.value) { e.preventDefault(); e.stopPropagation(); kbMove(t, e.shiftKey ? -1 : 1); } return; }
    if (!t.matches(KB_FIELDS)) return; e.preventDefault(); e.stopPropagation(); kbMove(t, e.shiftKey ? -1 : 1); return; }
  // ── Ctrl+S → save the window / form ──
  if ((e.ctrlKey || e.metaKey) && !e.shiftKey && e.key.toLowerCase() === 's') { const ov = $$('.ov'); if (ov.length) { const b = ov[ov.length - 1].querySelector('[data-ok]:not([disabled])'); if (b) { e.preventDefault(); e.stopPropagation(); b.click(); } } return; }
  // ── Alt+N → "+ New …" on this page ──
  if (e.altKey && !e.ctrlKey && (e.key === '=' || e.key === '+' || e.code === 'Equal' || e.code === 'NumpadAdd') && S.sid && !document.querySelector('.ov')) { const b = [...document.querySelectorAll('#main .ph button, #main .acts button, #main button')].find(x => kbVisible(x) && /^\+/.test(x.textContent.trim())); if (b) { e.preventDefault(); e.stopPropagation(); b.click(); } return; }
  // ── Delete → delete what is open ──
  if ((e.key === 'Delete' && !kbTyping()) || (e.key === 'Delete' && (e.ctrlKey || e.metaKey))) {
    const ov = $$('.ov'); const top = ov.length ? ov[ov.length - 1] : null;
    const b = top ? [...top.querySelectorAll('button')].find(x => kbVisible(x) && /delete/i.test(x.textContent) && !/delete.*(all|import)/i.test(x.textContent)) : [...document.querySelectorAll('#main button[onclick^="vEditDelGo"]')].find(kbVisible);
    if (b) { e.preventDefault(); e.stopPropagation(); b.click(); } }
}, true);
// shortcut list (? or F1) shows the new keys too
(() => { const ok = kbdHelp; window.kbdHelp = kbdHelp = function () { ok.apply(this, arguments); try { const t = document.querySelector('.ov:last-child .md-b table tbody'); if (t && !t.querySelector('.kb-new')) t.insertAdjacentHTML('afterbegin', [['Enter', 'Next box — on the last box it saves'], ['Shift + Enter', 'Previous box'], ['Delete', 'Delete the entry / item that is open (asks first)'], ['Ctrl + S', 'Save the open window or form'], ['Alt + =', '"+ New" on the page (Alt + plus)']].map(([k, l]) => `<tr class="kb-new"><td style="white-space:nowrap"><b>${k}</b></td><td>${l}</td></tr>`).join('')); } catch (e) { } }; })();

