const BD = () => ((S.bcfg || {})._bd) || {};
async function bdSave(patch, what) { if (!canEdit()) throw new Error('Only the admin or accountant can change billing options'); const nv = { ...BD(), ...patch }; Object.keys(nv).forEach(k => (nv[k] === '' || nv[k] == null) && delete nv[k]); await commit({ 'bcfg/_bd': Object.keys(nv).length ? nv : null }, { a: 'settings', e: 'Billing options', s: what || 'updated' }); S.bcfg = S.bcfg || {}; S.bcfg._bd = nv; }
addAct('bills', () => `<button class="ghost bd-more" onclick="bdMenu()">🧮 More billing tools</button>`);
function bdMenu() { const ed = canEdit(); const T = [['📅 Bill calendar', 'bdCal()', 1], ['⚙ Billing options (reminder day, seasonal heads, rounding)', 'bdOpts()', ed], ['🎨 Bill design (font size, margins, black & white)', 'bdDesign()', ed], ['🌐 Head names in मराठी / हिंदी', 'trModal()', ed], ['📊 Arrears month by month', 'arrMonth()', 1], ['📱 SMS the bills', 'smsBills()', ed], ['📬 Delivery tracker', 'dlModal()', 1], ['🏘 Combined bill (one member, several flats)', 'combModal()', 1], ['🧾 Bill a non-member (shop, tower, hoarding)', 'nmBill()', ed]].filter(x => x[2]);
  openModal({ title: '🧮 More billing tools', hideOk: true, cancel: 'Close', body: `<div class="grid g2">${T.map(([l, f]) => `<button class="ghost" style="text-align:left;white-space:normal" onclick="closeModals();setTimeout(()=>${f},60)">${l}</button>`).join('')}</div>` }); }
// ── 101 calendar & 102 reminder ─────────────────────────────────────────
function bdPeriods() { const st = SET().billing; const pi = ENG.periodInfo(st.per); const out = []; let f = S.fy.start; let g = 0; while (f <= S.fy.end && g++ < 24) { const t = monthEnd(f, pi.m); out.push({ f, t: t > S.fy.end ? S.fy.end : t }); f = ENG.addDays(t, 1); } return out; }
function bdRunFor(f) { return regRuns().find(([, r]) => r.from === f); }
function bdCal() { const st = SET().billing; const P = bdPeriods(); const dd = +st.dueDays || 0; const day = +BD().day || 0; const t = today();
  openModal({ title: `📅 Bill calendar ${esc(S.fy.label)} (${esc(st.per)})`, wide: true, hideOk: true, cancel: 'Close', body: `<div class="tw"><table><thead><tr><th>Period</th><th>Make bills on</th><th>Due date</th><th>Status</th></tr></thead><tbody>${P.map(p => { const r = bdRunFor(p.f); const mk = ENG.addDays(p.f, Math.max(0, day - 1)); return `<tr><td>${fd(p.f)} – ${fd(p.t)}</td><td>${r ? fd(r[1].d) : fd(mk)}</td><td>${r ? (r[1].due ? fd(r[1].due) : '—') : dd ? fd(ENG.addDays(mk, dd)) : '—'}</td><td>${r ? `<span class="chip c-ok">Made · ${Object.keys(S.bills).filter(k => S.bills[k] && S.bills[k].run === r[0]).length} bills</span>` : mk <= t ? '<span class="chip c-bad">Due — not made</span>' : '<span class="chip c-mut">Coming</span>'}</td></tr>`; }).join('')}</tbody></table></div><p class="small muted">${day ? `Reminder: on day ${day} of each period the bell 🔔 reminds you to make the bills.` : 'Set a reminder day in Billing options.'}</p>` }); }
function bdDue() { if (!S.sid || !S.fy || S.fy.closed || !canEdit()) return null; const day = +BD().day; if (!day || !regRuns().length) return null; const t = today(); const p = bdPeriods().find(x => x.f <= t && t <= x.t); if (!p) return null; if (ENG.addDays(p.f, day - 1) > t || bdRunFor(p.f)) return null; return p; }
(() => { const ob = bellItems; window.bellItems = bellItems = function () { const L = ob.apply(this, arguments); try { const p = bdDue(); if (p) L.unshift(['🧾', `Time to make the bills for ${fd(p.f)} – ${fd(p.t)}`, "go('bills')"]); } catch (e) { } return L; }; })();
// ── 110 seasonal heads, 111 rounding, 134 why-changed, 102 day — options ─
function bdOpts() { const b = BD(); const bh = billHeads(); const MN = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
  openModal({ title: '⚙ Billing options', xwide: true, body: `<div data-form><div class="fr c3"><div><label>Remind me to make bills on day … of each period</label><input id="bd-day" type="number" min="0" max="28" value="${b.day || ''}" placeholder="off"></div><div><label>Round every charge to</label><select id="bd-rnd">${[['', 'No extra rounding'], ['1', 'Nearest ₹1'], ['5', 'Nearest ₹5'], ['10', 'Nearest ₹10']].map(([v, l]) => `<option value="${v}" ${String(b.rnd || '') === v ? 'selected' : ''}>${l}</option>`).join('')}</select></div><div><label>&nbsp;</label><span class="small">"Why this bill is different" line: <span class="clk" onclick="closeModals();go('coll')">Collection & Recovery › settings</span></span></div></div>
    <h3 style="margin:14px 0 4px">Seasonal heads</h3><p class="small muted">Tick the months a head is charged in (e.g. water tanker only in Apr–Jun). A head with no ticks is charged every period.</p><div class="tw"><table><thead><tr><th>Head</th>${MN.map(m => `<th class="center">${m}</th>`).join('')}</tr></thead><tbody>${bh.map(([hid, h]) => { const s = ((b.sea || {})[hid]) || []; return `<tr><td>${esc(h.name)}</td>${MN.map((m, i) => `<td class="center"><input type="checkbox" class="bd-s" data-h="${hid}" data-m="${i + 1}" ${s.includes(i + 1) ? 'checked' : ''}></td>`).join('')}</tr>`; }).join('')}</tbody></table></div></div>`,
    onOk: async () => { const day = Math.max(0, Math.min(28, Math.round(+val('bd-day') || 0))); const sea = {}; $$('.bd-s').forEach(c => { if (c.checked) (sea[c.dataset.h] = sea[c.dataset.h] || []).push(+c.dataset.m); }); await bdSave({ day: day || null, rnd: +val('bd-rnd') || null, sea: Object.keys(sea).length ? sea : null }, 'Billing options'); toast('Saved'); } }); }
function bdMonthsIn(f, t) { const s = new Set(); let d = f.slice(0, 7) + '-01'; let g = 0; while (d <= t && g++ < 30) { s.add(+d.slice(5, 7)); const x = new Date(d); x.setMonth(x.getMonth() + 1); d = ymd(x); } return s; }
function bdAdj(p) { const b = BD(); const sea = b.sea || {}; const rnd = +b.rnd || 0; const mon = bdMonthsIn(p.from, p.to);
  const skip = Object.entries(sea).filter(([, ms]) => ms && ms.length && !ms.some(m => mon.has(m))).map(([h]) => h);
  if (skip.length || rnd) { const prev = p.adj; p.adj = x => { if (prev) prev(x); for (const h of skip) if (x.ch[h] != null) { delete x.ch[h]; (x.xo.xn = x.xo.xn || []).push(`${H(h).name} is seasonal — not charged in this period`); }
    if (rnd) for (const h of Object.keys(x.ch)) { const v = Math.round(x.ch[h] / rnd) * rnd; if (v) x.ch[h] = v; else delete x.ch[h]; } }; } return p; }
(() => { const o = genParams; window.genParams = genParams = function () { const p = o.apply(this, arguments); try { bdAdj(p); } catch (e) { } return p; }; })();
