(() => { const ol = vfLive; window.vfLive = vfLive = function () { const r = ol.apply(this, arguments); try { const el = $('vf-live'); if (el && VF.t === 'R' && /advance/.test(el.textContent) && !el.querySelector('.adv-n')) el.insertAdjacentHTML('beforeend', '<div class="small muted adv-n" style="font-weight:400">The extra is kept as an advance in the member\'s account and is adjusted against the next bills automatically.</div>'); } catch (e) { } return r; }; })();
// ── 149 reminder wording per language ───────────────────────────────────
const RT_DEF = { en: 'Dear {name} ({flat}), a reminder from {society}: ₹{amount} is outstanding (since {since}). Kindly pay at the earliest. Please ignore if already paid. — Secretary',
  mr: 'प्रिय {name} ({flat}), {society} कडून आठवण: आपली ₹{amount} थकबाकी आहे ({since} पासून). कृपया लवकरात लवकर भरणा करावा. आधीच भरले असल्यास दुर्लक्ष करावे. — सचिव',
  hi: 'प्रिय {name} ({flat}), {society} की ओर से याद दिलाना: आपका ₹{amount} बकाया है ({since} से). कृपया जल्द से जल्द भुगतान करें. यदि भुगतान कर दिया है तो कृपया ध्यान न दें. — सचिव' };
const RT = () => ((S.bcfg || {})._rt) || {};
const memLang = mid => { const m = M(mid) || {}; const l = m.lang || SET().bill.lang || 'en'; return /^(mr|hi)$/.test(l) ? l : 'en'; };
function rtText(mid, amt) { const m = M(mid) || {}; const lg = memLang(mid); let t = RT()[lg] || RT_DEF[lg]; let o = null; try { o = overdueOf(mid); } catch (e) { } const since = o && o.since ? fd(o.since) : ''; const days = o && o.days ? String(o.days) : '';
  if (!since) t = t.replace(/\s*\([^()]*\{since\}[^()]*\)/g, ''); const nm = lg !== 'en' && S.meta.nameMr ? S.meta.nameMr : S.meta.name || '';
  return t.replace(/\{name\}/g, m.name || '').replace(/\{flat\}/g, flatLbl(m)).replace(/\{amount\}/g, fmt(amt != null ? amt : (MB()[mid] || {}).bal || 0)).replace(/\{days\}/g, days).replace(/\{since\}/g, since).replace(/\{society\}/g, nm).replace(/\{upi\}/g, SET().bill.upi || ''); }
// stage 1 (gentle) uses the society's own wording in the member's language; firmer stages stay as written unless the member reads Marathi / Hindi
(() => { const or = remText; window.remText = remText = function (mid, st) { try { const lg = memLang(mid); if (+st === 1 && (RT()[lg] || lg !== 'en')) return rtText(mid); } catch (e) { } return or.apply(this, arguments); }; })();
function rtModal() { const r = RT(); openModal({ title: '✉ Reminder wording', xwide: true, ok: canEdit() ? 'Save' : '', hideOk: !canEdit(), body: `<p class="small">Used for WhatsApp reminders (Outstanding list and Collection & Recovery — first reminder). Each member gets the language set for them (Bill language per member), else the society's bill language. Words in braces are filled in: <code>{name} {flat} {amount} {since} {days} {society} {upi}</code></p>
  ${[['en', 'English'], ['mr', 'मराठी'], ['hi', 'हिंदी']].map(([k, l]) => `<label>${l}</label><textarea id="rt-${k}" rows="3" spellcheck="${k === 'en'}">${esc(r[k] || RT_DEF[k])}</textarea>`).join('')}<div class="small muted" id="rt-pv" style="margin-top:6px"></div>`,
  onOpen: () => { const mid = Object.keys(S.members)[0]; if (mid) $('rt-pv').textContent = 'Example: ' + rtText(mid, 1234); }, onOk: async () => { guardEdit(); const o = {}; ['en', 'mr', 'hi'].forEach(k => { const v = val('rt-' + k).trim(); if (v && v !== RT_DEF[k]) o[k] = v.slice(0, 900); }); await commit({ 'bcfg/_rt': Object.keys(o).length ? o : null }, { a: 'settings', e: 'Reminder wording', s: 'updated' }); S.bcfg._rt = Object.keys(o).length ? o : null; toast('Saved'); } }); }
(() => { const P = PAGES.dues; if (!P) return; const r = P.render; P.render = function () { const x = r.apply(this, arguments); try { const a = document.querySelector('#main .ph .acts'); if (a && !a.querySelector('.rt-b')) a.insertAdjacentHTML('beforeend', `<button class="ghost rt-b" onclick="rtModal()">✉ Reminder wording</button>`); } catch (e) { } return x; }; })();
// the Outstanding list's WhatsApp window uses the wording + the member's language
(() => { const ow = duesWA; window.duesWA = duesWA = function () { const r = ow.apply(this, arguments); try { const fi = flatIndex(); const ov = $$('.ov').pop(); if (ov) ov.querySelectorAll('tr').forEach(tr => { const fl = (tr.cells[0] || {}).textContent || ''; const mid = fi[fl.toLowerCase().replace(/\s+/g, '')]; const a = tr.querySelector('a[href^="https://wa.me/"]'); if (!mid || !a) return; const amt = r2((MB()[mid] || {}).bal || 0); const u = SET().bill.upi; const txt = rtText(mid, amt) + (u && !/\{upi\}/.test(RT()[memLang(mid)] || '') ? ` UPI: upi://pay?pa=${u}&am=${amt}&cu=INR` : ''); a.href = a.href.split('?')[0] + '?text=' + encodeURIComponent(txt); }); } catch (e) { } return r; }; })();
// ── 155 unmatched money on the bell ─────────────────────────────────────
(() => { const ob = bellItems; window.bellItems = bellItems = function () { const L = ob.apply(this, arguments); try { if (!canEdit()) return L; const t = today(); const U = Object.values(S.vch || {}).filter(v => v && v.unc); const old = U.filter(v => (Date.parse(t) - Date.parse(v.d)) / 864e5 >= 3);
  if (U.length) L.push(['⏳', `${U.length} receipt${U.length > 1 ? 's' : ''} waiting for bank confirmation${old.length ? ` (${old.length} older than 3 days)` : ''}`, "go('unconf')"]);
  const sus = Object.keys(S.heads).filter(k => S.heads[k] && S.heads[k].active !== false && /suspense|unidentified|unknown|unmatched/i.test(S.heads[k].name || '')); for (const h of sus) { const ob = +(((S.ob || {}).heads || {})[h]) || 0; const bal = r2(ob + sum(L_().filter(l => l.h === h), l => (l.dr || 0) - (l.cr || 0))); if (Math.abs(bal) > 0.5) L.push(['❓', `₹${fmt(Math.abs(bal))} ${bal > 0 ? 'Dr' : 'Cr'} in ${S.heads[h].name} — move it to the right head / member`, `go('gl','${h}')`]); } } catch (e) { } return L; }; })();
// ── 160 member chart: billed vs paid, month by month ────────────────────
function mlChart(mid) { const I = IDS(); const L = L_().filter(l => l.h === I.dues && l.m === mid); if (!L.length) return ''; const by = {}; for (const l of L) { const k = l.d.slice(0, 7); const o = by[k] = by[k] || { b: 0, p: 0 }; if (l.t === 'B' || l.t === 'S') o.b += l.dr - l.cr; else if (l.t === 'R') o.p += l.cr - l.dr; }
  const K = Object.keys(by).sort(); if (!K.length) return ''; const mx = Math.max(1, ...K.map(k => Math.max(by[k].b, by[k].p))); const W = Math.max(320, K.length * 46), H2 = 120, bw = 14;
  const bars = K.map((k, i) => { const x = 20 + i * 46; const hb = Math.max(0, by[k].b) / mx * (H2 - 30), hp = Math.max(0, by[k].p) / mx * (H2 - 30); return `<rect x="${x}" y="${H2 - 18 - hb}" width="${bw}" height="${hb}" rx="2" fill="#e8a33d"><title>Billed ₹${fmt(by[k].b)}</title></rect><rect x="${x + bw + 2}" y="${H2 - 18 - hp}" width="${bw}" height="${hp}" rx="2" fill="#2f9e5b"><title>Paid ₹${fmt(by[k].p)}</title></rect><text x="${x + bw}" y="${H2 - 4}" font-size="10" text-anchor="middle" fill="currentColor">${new Date(k + '-01').toLocaleDateString('en-IN', { month: 'short' })}</text>`; }).join('');
  return `<div class="card" id="ml-chart" style="padding:10px 14px;margin-bottom:12px"><div class="row small" style="gap:14px"><b>Billed vs paid</b><span><span style="display:inline-block;width:10px;height:10px;background:#e8a33d;border-radius:2px"></span> Billed</span><span><span style="display:inline-block;width:10px;height:10px;background:#2f9e5b;border-radius:2px"></span> Paid</span></div><div style="overflow-x:auto"><svg width="${W}" height="${H2}" role="img" aria-label="Billed and paid by month">${bars}</svg></div></div>`; }
(() => { const P = PAGES.mledger; if (!P || !P.refresh) return; const rf = P.refresh; P.refresh = function () { const x = rf.apply(this, arguments); try { const old = $('ml-chart'); if (old) old.remove(); const mid = CUR.arg; const res = $('ml-res'); if (mid && res && S.members[mid]) res.insertAdjacentHTML('beforebegin', mlChart(mid)); } catch (e) { } return x; }; })();
// ── 163 receipt-book photo → bulk receipts ──────────────────────────────
(() => { const P = PAGES.bulk; if (!P) return; const r = P.render; P.render = function () { const x = r.apply(this, arguments); try { const a = document.querySelector('#main .ph .acts'); if (a && canEdit() && !a.querySelector('.rb-b')) a.insertAdjacentHTML('beforeend', `<button class="ghost rb-b" onclick="rbPhoto()" title="Photo of a hand-written receipt book page or a collection list">📷 Receipt book photo</button>`); } catch (e) { } return x; }; })();
function rbPhoto() { if (!aiOn('receipts')) return toast('AI reading is switched off for this society (Settings › AI)', 'warn'); if (!aiNeed()) return;
  pickFiles('image/*,application/pdf', async files => { const rows = [];
    for (let i = 0; i < files.length; i++) { const r = await aiTry(`Reading page ${i + 1} of ${files.length}…`, () => aiRun(`This is a photo of a page from a housing society's hand-written receipt book or collection list (may be in English, Marathi or Hindi; numbers may be in Devanagari). Read every receipt / row. Return JSON {"rows":[{"date":"YYYY-MM-DD or empty","receipt_no":"","flat":"wing-flat like A-101","name":"","amount":number,"mode":"Cash|Cheque|UPI|NEFT","cheque_no":"","bank":""}]}. Do not guess amounts you cannot read — leave them 0.`, [files[i]]));
      for (const x of ((r && r.rows) || [])) { let flat = String(x.flat || '').trim(); if (!flat && x.name) { const mid = memByName(x.name); if (mid) flat = flatLbl(M(mid)); } rows.push({ flat, amt: +x.amount || '', mode: /cheque|chq/i.test(x.mode) ? 'Cheque' : /upi/i.test(x.mode) ? 'UPI' : /neft|imps|rtgs/i.test(x.mode) ? 'NEFT' : 'Cash', ref: x.cheque_no || x.receipt_no || '', cd: x.date || '', cbank: x.bank || '' }); } }
    if (!rows.length) return toast('Nothing could be read — try a clearer photo', 'warn'); if (CUR.id !== 'bulk') go('bulk'); setTimeout(() => { $('bk-body').innerHTML = ''; BULK.n = 0; bulkAddRows(Math.max(rows.length, 5), rows); toast(`${rows.length} receipts read — check every flat and amount, then save`, 'ok', 8000); }, 150); }); }

// ═══════════════════════════════════════════════════════════════════════
// v12 · BATCH F — members
// Already in the app: 171 member 360° view, KYC, family & documents · 173 flat transfer with premium bill · 175 associate / joint / nominal members
// 176 tenant register · 185 owner history of a flat
