(() => { const P = PAGES.bstmt; if (!P) return; const r = P.render; P.render = function () { const x = r.apply(this, arguments); try { const a = document.querySelector('#main .ph .acts'); if (a && canEdit() && !a.querySelector('.pdf-b')) a.insertAdjacentHTML('afterbegin', `<button class="pdf-b" onclick="pdfStmt()" title="Bank statement PDF downloaded from net-banking — no AI needed">📄 Statement PDF</button>`); } catch (e) { } return x; }; })();
