  if (/charges|chgs|sms|gst|commission|fee/i.test(t) && x.dr) { const h = Object.keys(S.heads).find(k => /bank charges/i.test(S.heads[k].name || '')); if (h) return { acc: h, conf: 'medium', why: 'bank charges' }; }
  if (/\bint\b|interest/i.test(t) && x.cr) { const h = Object.keys(S.heads).find(k => /interest on (savings|bank|sb)/i.test(S.heads[k].name || '')); if (h) return { acc: h, conf: 'medium', why: 'bank interest' }; }
