async function ensureHead(name, grp, sub, code) { const ex = Object.entries(S.heads).find(([, h]) => h && String(h.name).toLowerCase() === name.toLowerCase()); if (ex) return ex[0]; const k = FBX.key('x'); await commit({ [`heads/${k}`]: { code, grp, sub, name, type: 'gen', tag: '', active: true, ...stamp() } }, { a: 'create', e: 'Account head', id: code, s: name }); return k; }
function bankChgModal() { const B = bsBanks(); const d0 = today() > S.fy.end ? S.fy.end : today() < S.fy.start ? S.fy.start : today(); openModal({ title: '🏦 Bank charges with GST', body: `<div data-form><div class="fr c2"><div><label>Bank</label><select id="bg-b">${B.map(([id, h]) => `<option value="${id}">${esc(h.name)}</option>`).join('')}</select></div><div><label>Date</label><input type="date" id="bg-d" value="${d0}"></div></div><div class="fr c2"><div><label>Total debited by the bank ₹ (incl. GST)</label><input id="bg-a" inputmode="decimal" oninput="bankChgLive()"></div><div><label>GST %</label><input id="bg-g" value="18" inputmode="decimal" oninput="bankChgLive()"></div></div><label>Narration</label><input id="bg-n" value="Bank charges"><div id="bg-l" class="small" style="margin-top:8px"></div><p class="small muted">GST paid on bank charges is a cost to most societies (no input credit), so it goes to "GST on Bank Charges" under expenses.</p></div>`, onOk: async () => bankChgSave() }); }
function bankChgSplit() { const t = r2((typeof amtEval === 'function' ? amtEval(val('bg-a')) : null) ?? nval('bg-a')); const g = +val('bg-g') || 0; const base = r2(t * 100 / (100 + g)); return { t, base, gst: r2(t - base) }; }
function bankChgLive() { const s = bankChgSplit(); $('bg-l').innerHTML = s.t > 0 ? `Charges ₹${fmt(s.base)} + GST ₹${fmt(s.gst)} = ₹${fmt(s.t)}` : ''; }
async function bankChgSave() { const s = bankChgSplit(); const b = val('bg-b'), d = val('bg-d'); if (!b) throw new Error('Choose the bank'); if (!(s.t > 0)) throw new Error('Enter the amount'); const bc = await ensureHead('Bank Charges', 'Expenses', 'Administrative Expenses', 'E070'); const gh = s.gst > 0 ? await ensureHead('GST on Bank Charges', 'Expenses', 'Administrative Expenses', 'E071') : null;
  const r = await saveVoucher({ t: 'P', d, mode: 'Other', nar: val('bg-n') || 'Bank charges', lines: [{ h: bc, dr: s.base }, ...(gh ? [{ h: gh, dr: s.gst }] : []), { h: b, cr: s.t }] }, {}); if (r) { toast(`Saved ${r.rec.no}`); if (PAGES[CUR.id] && PAGES[CUR.id].refresh) try { PAGES[CUR.id].refresh(); } catch (e) { } } }
// ── 209 cash ↔ bank transfer check ─────────────────────────────────────
function cbCheck() { const out = []; const I = IDS(); const cash = Object.keys(S.heads).filter(k => S.heads[k] && S.heads[k].type === 'cash'); const bank = Object.keys(S.heads).filter(k => S.heads[k] && S.heads[k].type === 'bank');
  for (const [id, v] of Object.entries(S.vch)) { if (!v || v.t === 'C') continue; const t = `${v.nar || ''} ${v.ref || ''}`; if (/cash deposit|deposited cash|cash withdrawn|withdrawal self|\bself\b|atm|cash wdl/i.test(t)) out.push({ id, v, why: 'Narration says cash deposit / withdrawal — should be a Contra entry' }); }
  const R = Object.entries(S.vch).filter(([, v]) => v && v.t === 'R' && vLines(v).some(l => cash.includes(l.h))); const P = Object.entries(S.vch).filter(([, v]) => v && v.t === 'P' && vLines(v).some(l => bank.includes(l.h)) && vLines(v).some(l => cash.includes(l.h) && l.dr));
  for (const [id, v] of P) out.push({ id, v, why: 'Payment from bank into cash — use Contra (cash withdrawal)' });
  const neg = []; for (const c of cash) { let bal = +(((S.ob || {}).heads || {})[c]) || 0; for (const l of L_().filter(l => l.h === c).sort((a, b) => a.d.localeCompare(b.d))) { bal = r2(bal + l.dr - l.cr); if (bal < -0.5) { neg.push({ d: l.d, h: c, bal }); break; } } }
  return { out, neg }; }
function cbCheckModal() { const { out, neg } = cbCheck(); openModal({ title: '🔄 Cash ↔ bank check', wide: true, hideOk: true, cancel: 'Close', body: `${neg.map(n => `<div class="alert a-warn small">⚠ ${esc(H(n.h).name)} goes below zero on ${fd(n.d)} (₹${fmt(n.bal)}) — a cash withdrawal from the bank may be missing.</div>`).join('')}${out.length ? `<div class="tw"><table><tbody>${out.map(x => `<tr class="clk" onclick="closeModals();openVch('${x.id}')"><td>${fd(x.v.d)}</td><td class="mono small">${esc(x.v.no)}</td><td>${esc(vParticulars(x.v))}<div class="small muted">${esc(x.v.nar || '')}</div></td><td class="n">${fmt(vAmount(x.v))}</td><td class="small">${esc(x.why)}</td></tr>`).join('')}</tbody></table></div>` : neg.length ? '' : '<p class="muted">All cash ↔ bank movements look right ✓</p>'}` }); }
(() => { const P = PAGES.cashbook; if (!P) return; const r = P.render; P.render = function () { const x = r.apply(this, arguments); try { const a = document.querySelector('#main .ph .acts'); if (a && !a.querySelector('.cbc-b')) a.insertAdjacentHTML('beforeend', `<button class="ghost cbc-b" onclick="cbCheckModal()">🔄 Cash ↔ bank check</button>`); } catch (e) { } return x; }; })();

