  const n0 = 4, n1 = rows.length; rows.push([], ['', 'Total', '', { f: `SUM(D${n0}:D${n1})` }, { f: `SUM(E${n0}:E${n1})` }], ['', 'Difference (must be 0)', '', { f: `D${n1 + 2}-E${n1 + 2}` }, '']);
  const ws = XLSX.utils.aoa_to_sheet(rows); ws['!cols'] = [{ wch: 8 }, { wch: 40 }, { wch: 14 }, { wch: 16 }, { wch: 16 }]; for (let i = n0; i <= n1 + 3; i++) ['D', 'E'].forEach(c => { const x = ws[c + i]; if (x && (x.t === 'n' || x.f)) x.z = '#,##0.00'; });
