const AI_FEATS = [['statement', 'Read bank statements (photo / scanned PDF)', ['aiStatement']], ['receipts', 'Read cheques, payment screenshots, receipt-book photos', ['aiCheque', 'aiShots']], ['billing', 'Read old bills & rate lists', ['aiBill', 'aiBillRates']], ['import', 'Read member lists & tables from photos', ['aiMembers', 'aiTable']], ['fd', 'Read FD receipts', ['aiFD']], ['drafting', 'Write minutes, notes, audit replies, AGM speech', ['aiAuditDraft', 'aiNotes', 'aiMinutes', 'aiAgmSpeech']], ['translate', 'Translate head names to मराठी / हिंदी', []], ['explain', '"Explain the numbers on this screen"', []]];
AI_FEATS.forEach(([k, l, fns]) => fns.forEach(fn => { try { const o = window[fn]; if (typeof o !== 'function') return; window[fn] = function () { if (!aiOn(k)) return toast(`AI for "${l}" is switched off for this society (Settings › AI switches)`, 'warn', 6000); return o.apply(this, arguments); }; } catch (e) { } }));
// the global reference has to change too, because buttons call the plain name
(() => { try { aiStatement = window.aiStatement; aiCheque = window.aiCheque; aiShots = window.aiShots; aiBill = window.aiBill; aiBillRates = window.aiBillRates; aiMembers = window.aiMembers; aiTable = window.aiTable; aiFD = window.aiFD; aiAuditDraft = window.aiAuditDraft; aiNotes = window.aiNotes; aiMinutes = window.aiMinutes; aiAgmSpeech = window.aiAgmSpeech; } catch (e) { } })();
function aiSwModal() { const s = ((S.meta.settings || {}).ai) || {}; const ad = isAdmin();
  openModal({ title: '🤖 AI switches for this society', ok: ad ? 'Save' : '', hideOk: !ad, body: `<p class="small">AI only runs when someone presses an AI button, and only with the firm's own AI key. Switch off what this society does not want.</p><label class="row" style="font-weight:700"><input type="checkbox" id="ais-all" ${s.all === false ? '' : 'checked'} ${ad ? '' : 'disabled'} onchange="$$('.ais-f').forEach(c=>c.disabled=!this.checked)"> AI features on for this society</label><div style="margin:8px 0 0 22px">${AI_FEATS.map(([k, l]) => `<label class="row small" style="margin:4px 0"><input type="checkbox" class="ais-f" data-k="${k}" ${s[k] === false ? '' : 'checked'} ${!ad || s.all === false ? 'disabled' : ''}> ${esc(l)}</label>`).join('')}</div>`,
    onOk: async () => { const o = { all: $('ais-all').checked ? null : false }; $$('.ais-f').forEach(c => { o[c.dataset.k] = c.checked ? null : false; }); const clean = Object.fromEntries(Object.entries(o).filter(([, v]) => v === false)); await commit({ 'meta/settings/ai': Object.keys(clean).length ? clean : null }, { a: 'settings', e: 'settings', s: 'AI switches' }); S.meta.settings = S.meta.settings || {}; S.meta.settings.ai = clean; toast('Saved'); } }); }
// ── 406 / 407 margins, text size, black & white for every document ──────
const PD = () => ((S.bcfg || {})._pd) || {};
function pdWrap(html) { try { const p = S.sid ? PD() : {}; const fs = +p.fs || 100, mg = +p.mg || 0, bw = !!p.bw; if ((fs !== 100 || mg || bw) && !/class="bd-wrap"/.test(String(html))) return `<div class="pd-wrap" style="${fs !== 100 ? `zoom:${fs / 100};` : ''}${mg ? `padding:${mg}mm;` : ''}${bw ? 'filter:grayscale(1);' : ''}">${html}</div>`; } catch (e) { } return html; }
(() => { const op = printDoc; window.printDoc = printDoc = function (title, html, o) { return op.call(this, title, pdWrap(html), o); }; })();
function pdModal() { const p = PD(); openModal({ title: '🖨 Printing — all documents', body: `<p class="small">Letters, notices, receipts, reports and registers. (Bills have their own design in Bills › More billing tools.)</p><div class="fr c3"><div><label>Text size</label><select id="pd-fs">${[90, 100, 110, 120].map(v => `<option value="${v}" ${(+p.fs || 100) === v ? 'selected' : ''}>${v}%</option>`).join('')}</select></div><div><label>Extra margin</label><select id="pd-mg">${[0, 3, 6, 10, 15].map(v => `<option value="${v}" ${(+p.mg || 0) === v ? 'selected' : ''}>${v ? v + ' mm' : 'None'}</option>`).join('')}</select></div><div><label>Colour</label><select id="pd-bw"><option value="">Colour</option><option value="1" ${p.bw ? 'selected' : ''}>Black & white</option></select></div></div><p class="small muted">Logo on the letterhead: Settings › Printing (the bill logo is used).</p>`,
  onOk: async () => { guardEdit(); const o = { fs: +val('pd-fs') === 100 ? null : +val('pd-fs'), mg: +val('pd-mg') || null, bw: val('pd-bw') ? true : null }; const c = Object.fromEntries(Object.entries(o).filter(([, v]) => v != null)); await commit({ 'bcfg/_pd': Object.keys(c).length ? c : null }, { a: 'settings', e: 'Printing', s: 'margins / size / colour' }); S.bcfg._pd = c; toast('Saved'); } }); }
// buttons on Settings (next to the search box)
(() => { const P = PAGES.settings; if (!P) return; const r = P.render; P.render = function () { const x = r.apply(this, arguments); try { const q = $('set-q'); if (q && !$('set-x')) q.insertAdjacentHTML('afterend', `<span id="set-x" class="row" style="gap:6px;margin-left:8px"><button class="ghost sm" onclick="aiSwModal()">🤖 AI switches</button><button class="ghost sm" onclick="pdModal()">🖨 Print margins & B/W</button></span>`); } catch (e) { } return x; }; })();
// ── 417 rename an account group ────────────────────────────────────────
(() => { const P = PAGES.heads; if (!P) return; const r = P.render; P.render = function () { const x = r.apply(this, arguments); try { const a = document.querySelector('#main .ph .acts'); if (a && canEdit() && !a.querySelector('.rg-b')) a.insertAdjacentHTML('beforeend', `<button class="ghost rg-b" onclick="grpRename()">✏ Rename a group</button>`); } catch (e) { } return x; }; })();
function grpRename() { const subs = {}; Object.values(S.heads).forEach(h => { if (h && h.sub) subs[h.grp + '|' + h.sub] = (subs[h.grp + '|' + h.sub] || 0) + 1; });
  openModal({ title: '✏ Rename an account group', body: `<p class="small">Renames the sub-group on every head in it (e.g. "Administrative Expenses" → "Office & Administration"). The main groups — Income, Expenses, Assets, Liabilities — stay as they are because the final accounts are built from them.</p><label>Group</label><select id="rg-f">${Object.entries(subs).sort().map(([k, n]) => `<option value="${esc(k)}">${esc(k.split('|')[1])} (${esc(k.split('|')[0])}, ${n} heads)</option>`).join('')}</select><label>New name</label><input id="rg-t" maxlength="60">`,
    onOk: async () => { guardEdit(); const [g, from] = val('rg-f').split('|'); const to = val('rg-t').trim(); if (!to) throw new Error('Enter the new name'); if (to === from) return; const up = {}; Object.entries(S.heads).forEach(([id, h]) => { if (h && h.grp === g && h.sub === from) up[`heads/${id}/sub`] = to; }); await commit(up, { a: 'edit', e: 'Account group', s: `${from} → ${to} (${Object.keys(up).length} heads)` }); toast(`Renamed on ${Object.keys(up).length} heads`); render(); } }); }
// ── 494 open the connections the app needs as early as possible ─────────
(() => { try { const hosts = ['https://cdnjs.cloudflare.com', 'https://www.gstatic.com', 'https://fonts.gstatic.com']; try { const u = typeof dbUrl === 'function' ? dbUrl() : ''; if (u) hosts.push(new URL(u).origin); } catch (e) { } hosts.forEach(h => { if (document.querySelector(`link[rel=preconnect][href="${h}"]`)) return; const l = document.createElement('link'); l.rel = 'preconnect'; l.href = h; l.crossOrigin = ''; document.head.appendChild(l); }); } catch (e) { } })();

