// text of an element including emoji that were turned into pictures
const etxt = el => { if (!el) return ''; let s = ''; el.childNodes.forEach(n => { s += n.nodeType === 3 ? n.nodeValue : n.nodeType === 1 ? (n.tagName === 'IMG' && n.classList.contains('emoji') ? n.alt : etxt(n)) : ''; }); return s; };
// ── 1: Windows 7 / 8 icons ─────────────────────────────────────────────
const TWE_OPT = { base: TWE_BASE, folder: 'svg', ext: '.svg' };
(() => { if (!OLDWIN()) return; const st = document.createElement('style'); st.textContent = 'img.emoji{height:1.05em;width:1.05em;margin:0 .05em;vertical-align:-.15em;display:inline-block}'; document.head.appendChild(st);
  const SKIP = /^(SCRIPT|STYLE|TEXTAREA|SELECT|OPTION|INPUT|TITLE|NOSCRIPT)$/; const Q = new Set(); let T0 = 0;
  const flush = () => { T0 = 0; if (typeof twemoji === 'undefined') return; const L = [...Q]; Q.clear(); for (const n of L) { const el = n.nodeType === 3 ? n.parentNode : n; if (!el || !el.isConnected || el.nodeType !== 1 || SKIP.test(el.tagName) || el.closest('select,textarea,[contenteditable]')) continue; try { twemoji.parse(el, TWE_OPT); } catch (e) { } } };
  const mo = new MutationObserver(recs => { for (const r of recs) { if (r.type === 'characterData') Q.add(r.target); else r.addedNodes.forEach(n => { if (n.nodeType === 1 && n.tagName === 'IMG') return; if (n.nodeType === 3 || n.nodeType === 1) Q.add(n); }); } if (!T0) T0 = setTimeout(flush, 60); });
  loadScript(TWE_JS).then(() => { try { twemoji.parse(document.body, TWE_OPT); } catch (e) { } mo.observe(document.body, { childList: true, subtree: true, characterData: true }); }).catch(() => { }); })();
// ── 10: fast mode ──────────────────────────────────────────────────────
(() => { const st = document.createElement('style'); st.textContent = `html.lite *,html.lite *::before,html.lite *::after{transition:none!important;animation:none!important;backdrop-filter:none!important;-webkit-backdrop-filter:none!important;scroll-behavior:auto!important}
html.lite .card,html.lite .ov .md,html.lite .topbar,html.lite .side,html.lite button,html.lite .qa,html.lite .tw,html.lite .toast{box-shadow:none!important}html.lite .ov{background:rgba(0,0,0,.45)!important}html.lite #main .tw.tw-long{max-height:none!important}`; document.head.appendChild(st);
  if (document.documentElement.classList.contains('lite') && typeof enhObs !== 'undefined') { try { enhObs.disconnect(); let t = 0; const m = $('main'); if (m) new MutationObserver(() => { clearTimeout(t); t = setTimeout(enhance, 450); }).observe(m, { childList: true, subtree: true }); } catch (e) { } } })();
function liteSet(on) { LS.set('sb_lite', on ? '1' : '0'); document.documentElement.classList.toggle('lite', !!on); toast(on ? 'Fast mode on — reload the page once for the full effect' : 'Fast mode off'); }
(() => { const ob = uipBody; window.uipBody = uipBody = function () { const h = ob.apply(this, arguments); const on = document.documentElement.classList.contains('lite'); return h.replace('<div class="row" style="margin-top:10px;gap:8px;flex-wrap:wrap">', `<label class="row small" style="margin:8px 0 0"><input type="checkbox" ${on ? 'checked' : ''} onchange="liteSet(this.checked)"> ⚡ Fast mode for old or slow computers (no shadows, blur or animations) — turned on by itself on Windows 7 / 8</label><div class="row" style="margin-top:10px;gap:8px;flex-wrap:wrap">`); }; })();
