(() => { const P = PAGES.settings; if (!P) return; const r = P.render; P.render = function (tab) { const x = r.apply(this, arguments); try { if ((tab || CUR.arg) !== 'print') return x; const card = document.querySelector('#main .card[data-form]'); if (!card || $('lh-card')) return x; const b = SET().bill || {}; const ad = isAdmin();
  const sz = (id, v, L) => `<select id="${id}" ${ad ? '' : 'disabled'} onchange="lhPrev()"><option value="">Normal</option>${L.map(n => `<option value="${n}" ${+v === n ? 'selected' : ''}>${n}px</option>`).join('')}</select>`;
  card.insertAdjacentHTML('afterend', `<div class="card" id="lh-card" style="margin-top:12px"><h3 style="margin-top:0">Society name on bills, receipts & letters</h3>
    <div class="fr c2"><div><label>Second line under the society name (optional)</label><input id="lh-sub" value="${esc(b.subName || '')}" placeholder="e.g. Agrawal Park" ${ad ? '' : 'disabled'} oninput="lhPrev()"></div><div><label>Second line in मराठी / हिंदी (optional)</label><input id="lh-submr" value="${esc(b.subMr || '')}" placeholder="उदा. अग्रवाल पार्क" ${ad ? '' : 'disabled'} oninput="lhPrev()"></div></div>
    <div class="fr c4"><div><label>Society name size</label>${sz('lh-nfs', b.nameFs, [14, 16, 18, 20, 22, 24, 26, 28])}</div><div><label>Second line size</label>${sz('lh-sfs', b.subFs, [10, 11, 12, 13, 14, 16, 18, 20])}</div><div><label>Registration no. size</label>${sz('lh-rfs', b.regFs, [9, 10, 11, 12, 13, 14, 15, 16])}</div><div><label>Address size</label>${sz('lh-afs', b.addrFs, [9, 10, 11, 12, 13, 14, 15, 16])}</div></div>
    <div id="lh-pv" style="border:1px solid var(--border);border-radius:8px;padding:10px;margin-top:10px;background:#fff;color:#000"></div>
    ${ad ? '<button style="margin-top:10px" onclick="lhSave()">Save</button>' : '<p class="small muted">Only the admin can change this.</p>'}<p class="small muted">If the second line is empty, nothing is printed and no space is left.</p></div>`); lhPrev(); } catch (e) { } return x; }; })();
function lhVals() { return { subName: val('lh-sub').trim().slice(0, 80) || null, subMr: val('lh-submr').trim().slice(0, 80) || null, nameFs: +val('lh-nfs') || null, subFs: +val('lh-sfs') || null, regFs: +val('lh-rfs') || null, addrFs: +val('lh-afs') || null }; }
function lhPrev() { const box = $('lh-pv'); if (!box) return; const st = S.meta.settings = S.meta.settings || {}; const keep = st.bill; st.bill = { ...(keep || {}), ...lhVals() }; try { box.innerHTML = `<style>${PRINT_CSS}</style><div class="doc" style="padding:0;box-shadow:none">${letterhead()}</div>`; } catch (e) { box.textContent = e.message; } finally { st.bill = keep; } }
