const CQC = { L: [], mode: 'save', bank: '', d: '', pend: null };
// v12.2: smaller photos — 1000 px, WebP where the browser supports it (about 40% smaller than JPEG at the same clarity)
async function imgShrink(file, max = 1000, q = 0.6) { const u = URL.createObjectURL(file); try { const img = await new Promise((ok, no) => { const i = new Image(); i.onload = () => ok(i); i.onerror = no; i.src = u; }); const s = Math.min(1, max / Math.max(img.width, img.height)); const c = document.createElement('canvas'); c.width = Math.round(img.width * s); c.height = Math.round(img.height * s); const g = c.getContext('2d'); g.fillStyle = '#fff'; g.fillRect(0, 0, c.width, c.height); g.drawImage(img, 0, 0, c.width, c.height);
  const w = c.toDataURL('image/webp', q); if (/^data:image\/webp/.test(w)) { const j = c.toDataURL('image/jpeg', q); return w.length < j.length ? w : j; } return c.toDataURL('image/jpeg', q); } finally { URL.revokeObjectURL(u); } }
const cqcNew = () => ({ k: Math.random().toString(36).slice(2, 8), f: '', b: '', mid: '', amt: '', no: '', cd: '', bank: '', who: '' });
window.aiCheque = aiCheque = function () { chqCap(CUR.id === 'receipt' ? 'fill' : 'save'); };
function chqCap(mode) { if (!canEdit()) return toast('Only the admin or accountant can enter receipts', 'warn'); CQC.mode = mode || 'save'; CQC.L = [cqcNew()]; CQC.bank = CQC.bank && S.heads[CQC.bank] ? CQC.bank : (cqBank() || ''); CQC.d = todayInFY();
  openModal({ title: CQC.mode === 'fill' ? '📷 Cheque — front & back' : '📷 Collect cheques — front & back photos', xwide: CQC.mode !== 'fill', ok: CQC.mode === 'fill' ? 'Fill the receipt' : 'Save receipts', body: '<div id="cqc-b"></div>', onOpen: cqcRender, onOk: async () => cqcDone() }); }
