// ── 13 command bar (Ctrl+K) ─────────────────────────────────────────────
const CMD_PAGES = [[/^(bs|balance ?sheet)$/, 'bs'], [/^(ie|i ?& ?e|income|income ?& ?expenditure)$/, 'ie'], [/^(tb|trial ?balance)$/, 'tb'], [/^(rp|r ?& ?p|receipts ?& ?payments)$/, 'rp'], [/^(dues|outstanding|defaulters?)$/, 'dues'], [/^(day ?book|db)$/, 'daybook'], [/^(cash ?book|cash)$/, 'cashbook'], [/^(bank ?book|bank)$/, 'bankbook'], [/^(bills?|billing)$/, 'bills'], [/^(members?)$/, 'members'], [/^(dash|dashboard|home)$/, 'dash'], [/^(books|complete books)$/, 'books'], [/^(settings)$/, 'settings'], [/^(recon|brs|reconciliation)$/, 'recon']];
const fyByLabel = t => { const m = String(t).match(/(\d{2,4})\s*[-/]\s*(\d{2,4})/); if (!m) return null; const y1 = m[1].length === 2 ? '20' + m[1] : m[1]; return Object.keys(S.fys || {}).find(k => String(S.fys[k].start || '').startsWith(y1)) || null; };
function memByFlat(t) { const k = String(t).toLowerCase().replace(/\s+/g, ''); if (!k) return null; let hit = null; try { const fi = flatIndex(); hit = fi[k] || null; } catch (e) { }
  if (!hit) { const L = Object.entries(S.members).filter(([, m]) => m && String(m.flat).toLowerCase() === k); if (L.length === 1) hit = L[0][0]; } return hit; }
function cmdHead(t) { t = String(t).toLowerCase().trim(); if (t.length < 3) return null; const L = Object.entries(S.heads).filter(([, h]) => h && h.name.toLowerCase().includes(t)); return L.length ? L.sort((a, b) => a[1].name.length - b[1].name.length)[0][0] : null; }
function cmdParse(q) { const out = []; const raw = String(q || '').trim(); const t = raw.toLowerCase(); if (!t) return out; const w = t.split(/\s+/); const add = (html, on, key) => out.push({ g: '⚡ Do it', html: `<span class="gs-act">${html}</span>${key ? `<span class="gs-key">${key}</span>` : ''}`, on });
  // a society by short code / name
  if (S.user && FIRM.list) socRows(raw).slice(0, 3).forEach(x => { if (x.sid !== S.sid && (x.c.toLowerCase() === t || x.n.toLowerCase().includes(t)) && t.length >= 2) add(`🏢 Open ${esc(x.n)}${x.c ? ` (${esc(x.c)})` : ''}`, `closeModals();openSociety('${esc(x.sid)}')`, 'Ctrl+Enter = new tab'); });
  if (!S.sid) return out;
  const amt = w.length > 2 ? numv(w[w.length - 1]) : 0;
  if (/^(r|rc|rcpt|receipt|rec)$/.test(w[0])) { const mid = w[1] && memByFlat(w[1]); if (mid) add(`📥 New receipt from ${esc(flatLbl(S.members[mid]))} ${esc(S.members[mid].name)}${amt > 0 ? ' · ₹' + fmt(amt) : ''}`, `cmdVoucher('receipt','M:${mid}',${amt || 0})`, 'Enter'); else add('📥 New receipt', `closeModals();go('receipt')`); }
  if (/^(p|pay|payment)$/.test(w[0])) { const rest = w.slice(1, amt > 0 ? -1 : undefined).join(' '); const hid = rest && cmdHead(rest); if (hid) add(`📤 New payment for ${esc(S.heads[hid].name)}${amt > 0 ? ' · ₹' + fmt(amt) : ''}`, `cmdVoucher('payment','${hid}',${amt || 0})`, 'Enter'); else add('📤 New payment', `closeModals();go('payment')`); }
  if (/^(l|led|ledger|gl|stmt|statement)$/.test(w[0]) && w[1]) { const rest = w.slice(1).join(' '); const mid = memByFlat(rest); if (mid) add(`📒 Ledger of ${esc(flatLbl(S.members[mid]))} ${esc(S.members[mid].name)}`, `closeModals();go('mledger','${mid}')`, 'Enter'); const hid = cmdHead(rest); if (hid) add(`📒 Ledger · ${esc(S.heads[hid].name)}`, `closeModals();openHead('${hid}')`); }
  const pg = CMD_PAGES.find(([re]) => re.test(w.filter(x => !/\d{2,4}\s*[-/]\s*\d{2,4}/.test(x)).join(' '))); if (pg && PAGES[pg[1]]) { const fid = fyByLabel(t); add(`${(PNAME()[pg[1]] || ['📄'])[0]} ${esc((PNAME()[pg[1]] || [, pg[1]])[1])}${fid && fid !== S.fyId ? ` · FY ${esc(S.fys[fid].label)}` : ''}`, fid && fid !== S.fyId ? `closeModals();cmdFy('${fid}','${pg[1]}')` : `closeModals();go('${pg[1]}')`, 'Enter'); }
  if (/^\d+[a-z]?$/.test(w[0]) && w.length === 1) { const mid = memByFlat(w[0]); if (mid) { add(`📒 Ledger of ${esc(flatLbl(S.members[mid]))} ${esc(S.members[mid].name)}`, `closeModals();go('mledger','${mid}')`, 'Enter'); add(`📥 Receipt from ${esc(flatLbl(S.members[mid]))}`, `cmdVoucher('receipt','M:${mid}',0)`); } }
  return out; }
function cmdFy(fid, p) { switchFY(fid); waitFor(() => S.fyId === fid && ['ob', 'vch', 'bills', 'runs'].every(k => S.loaded[k])).then(() => go(p)).catch(() => { }); }
function cmdVoucher(p, acc, amt) { closeModals(); go(p); setTimeout(() => { try { apSet('vf-acc', acc); if (typeof vfAccChanged === 'function') vfAccChanged(acc); if (amt > 0) { const a = $('vf-amt'); if (a) { a.value = amt; a.dispatchEvent(new Event('input', { bubbles: true })); } } const a2 = $('vf-amt'); if (a2) { a2.focus(); a2.select && a2.select(); } } catch (e) { } }, 120); }
function gsEmpty() { const R = S.sid ? recList(S.sid, 10) : recList(null, 10); const F = favList().filter(x => !x.sid || x.sid === S.sid).filter(x => PAGES[x.p]);
  const it = x => x.v ? `<div class="gs-it" onclick="closeModals();openVch('${esc(x.v)}')">${x.ic || '🧾'} ${esc(x.tx)}</div>` : x.sid && x.sid !== S.sid ? `<div class="gs-it" onclick="closeModals();openSociety('${esc(x.sid)}')">🏢 ${esc(socNm(x.sid))} · ${esc(x.tx)}</div>` : `<div class="gs-it" onclick="closeModals();go('${x.p}'${x.a ? `,'${esc(x.a)}'` : ''})">${x.ic || '📄'} ${esc(x.tx)}</div>`;
  return `${F.length ? `<div class="small b muted" style="margin:8px 0 4px">★ Favourites</div>${F.map(it).join('')}` : ''}${R.length ? `<div class="small b muted" style="margin:8px 0 4px">🕘 Recent</div>${R.map(it).join('')}` : ''}
    <p class="small muted" style="margin-top:10px">Try: <b>receipt 101 3500</b> · <b>pay electricity 4200</b> · <b>ledger 202</b> · <b>bs 24-25</b> · <b>dues</b> · a society name or short code. ↑↓ to choose, Enter to open.${S.sid ? ` <a class="clk" onclick="closeModals();firmSearch()">Search all my societies</a>` : ''}</p>`; }
(() => { const orun = gsRun; window.gsRun = gsRun = function (q) { const el = $('gs-r'); const t = String(q || '').trim(); if (!el) return;
  if (!t) { el.innerHTML = gsEmpty(); return; }
  if (S.sid) orun.apply(this, arguments); else el.innerHTML = '';
  const C = cmdParse(t); if (C.length) el.insertAdjacentHTML('afterbegin', `<div class="small b muted" style="margin:4px 0">⚡ Do it</div>${C.map(x => `<div class="gs-it" onclick="${x.on}">${x.html}</div>`).join('')}`);
  if (!S.sid && !C.length) el.innerHTML = `<p class="small muted">No society matches. <a class="clk" onclick="closeModals();firmSearch('${esc(t)}')">Search members & entries in all societies</a></p>`;
  const f = el.querySelector('.gs-it'); if (f) f.classList.add('on'); }; })();
(() => { const oo = gsOpen; window.gsOpen = gsOpen = function () { if (!S.sid && S.user) { openModal({ title: '🔍 Search & commands', wide: true, hideOk: true, cancel: 'Close', body: `<input id="gs-q" data-noenter placeholder="Society name or short code, or a member / flat / cheque no. in any society…" oninput="gsRun(this.value)" autocomplete="off"><div id="gs-r" style="margin-top:10px;max-height:60vh;overflow:auto"></div>` }); }
  else oo.apply(this, arguments); setTimeout(() => { const i = $('gs-q'); if (i) { i.setAttribute('data-noenter', ''); i.focus(); i.addEventListener('keydown', gsKey); if (!i.value) gsRun(''); } }, 50); }; })();
function gsKey(e) { const rows = $$('#gs-r .gs-it'); let i = rows.findIndex(r => r.classList.contains('on'));
  if (e.key === 'ArrowDown' || e.key === 'ArrowUp') { e.preventDefault(); i = Math.max(0, Math.min(rows.length - 1, i + (e.key === 'ArrowDown' ? 1 : -1))); rows.forEach((r, k) => r.classList.toggle('on', k === i)); rows[i] && rows[i].scrollIntoView({ block: 'nearest' }); }
  else if (e.key === 'Enter' && rows.length) { e.preventDefault(); const r = rows[Math.max(0, i)]; const on = r.getAttribute('onclick') || ''; const m = on.match(/openSociety\('([^']+)'\)/); if (m && (e.ctrlKey || e.shiftKey)) { socNewTab(m[1]); return; } r.click(); } }

// ── 20 search across all societies ─────────────────────────────────────
// Members of every society you can open (small download, kept for this session). Entries: this year's books of each society,
// fetched one society at a time with a progress bar only when you press the button (it downloads more data).
const FS = { mem: {}, vch: {} };
function firmSearch(q) { openModal({ title: '🔎 Search all my societies', xwide: true, hideOk: true, cancel: 'Close', body: `<div class="row" style="gap:8px"><input id="fs-q" data-noenter style="flex:1" value="${esc(q || '')}" placeholder="Member name, flat, phone — or cheque no. / UTR / amount for entries" onkeydown="if(event.key==='Enter')fsRun(false)"><button class="sm" onclick="fsRun(false)">Search members</button><button class="sm ghost" onclick="fsRun(true)" title="Downloads this year's entries of every society — slower">Also search entries</button></div><div id="fs-r" style="margin-top:10px;max-height:62vh;overflow:auto"></div>` }); setTimeout(() => { const i = $('fs-q'); if (i) i.focus(); if (q) fsRun(false); }, 60); }
async function fsRun(withVch) { const q = val('fs-q').trim().toLowerCase(); const el = $('fs-r'); if (!el || q.length < 2) return toast('Type at least 2 letters', 'warn'); const ids = Object.keys(FIRM.list || {}).filter(s => !(FIRM.info[s] || {}).err); const num = numv(q); const hits = [];
  for (let i = 0; i < ids.length; i++) { const sid = ids[i]; if (!$('fs-r')) return; el.innerHTML = loading(`Searching ${socNm(sid)} — ${i + 1} of ${ids.length}…`);
    try { if (!FS.mem[sid]) FS.mem[sid] = sid === S.sid ? S.members : ((await FBX.get(`societies/${sid}/members`)) || {});
      for (const [mid, m] of Object.entries(FS.mem[sid])) { if (!m) continue; const s = `${m.wing || ''} ${m.flat} ${m.name} ${m.name2 || ''} ${m.phone || ''} ${m.email || ''}`.toLowerCase(); if (s.includes(q)) hits.push({ sid, k: 'm', mid, tx: `${m.wing ? m.wing + '-' : ''}${m.flat} ${m.name}`, sub: m.phone || '' }); }
      if (withVch) { if (!FS.vch[sid]) { const fys = (await FBX.get(`societies/${sid}/fys`)) || {}; const t = today(); const fy = Object.keys(fys).find(k => fys[k].start <= t && fys[k].end >= t) || Object.keys(fys).sort().pop(); FS.vch[sid] = sid === S.sid && fy === S.fyId ? S.vch : (fy ? ((await FBX.get(`societies/${sid}/vch/${fy}`)) || {}) : {}); }
        for (const [vid, v] of Object.entries(FS.vch[sid])) { if (!v) continue; const s = `${v.no} ${(v.chq || {}).no || ''} ${v.ref || ''} ${v.nar || ''}`.toLowerCase(); let a = 0; try { a = vAmount(v); } catch (e) { }
          if (s.includes(q) || (num > 0 && Math.abs(a - num) < 0.005)) hits.push({ sid, k: 'v', vid, tx: `${v.no} · ${fd(v.d)} · ₹${fmt(a)}`, sub: v.nar || '' }); } } } catch (e) { } }
  if (!$('fs-r')) return; const G = {}; hits.forEach(h => (G[h.sid] = G[h.sid] || []).push(h));
  el.innerHTML = hits.length ? Object.entries(G).map(([sid, L]) => `<div class="small b" style="margin:10px 0 4px">🏢 ${esc(socNm(sid))} (${L.length}) <a class="clk small" onclick="socNewTab('${esc(sid)}')">↗ new tab</a></div>${L.slice(0, 30).map(h => `<div class="gs-it" onclick="fsOpen('${esc(sid)}','${h.k}','${esc(h.mid || h.vid)}')">${h.k === 'm' ? '👤' : '🧾'} ${esc(h.tx)} <span class="small muted">${esc(h.sub)}</span></div>`).join('')}`).join('') : `<p class="small muted">Nothing found${withVch ? '' : ' among members — try "Also search entries"'}.</p>`; }
async function fsOpen(sid, k, id) { closeModals(); if (S.sid !== sid) { await openSociety(sid); } if (k === 'm') go('mledger', id); else { await waitFor(() => S.vch && S.vch[id], 8000).catch(() => { }); openVch(id); } }

