// ── 49 learning ─────────────────────────────────────────────────────────
const lrnK = t => String(t).replace(/[.#$\[\]\/]/g, '_').slice(0, 60);
const LRN2 = () => ((S.bcfg || {})._lrn) || {};
// words that say nothing about WHO paid (months, "maint", bank codes) are never learned
const LRN2_STOP = new Set('JAN JANUARY FEB FEBRUARY MAR MARCH APR APRIL MAY JUNE JULY AUG AUGUST SEPT SEP SEPTEMBER OCT OCTOBER NOV NOVEMBER DEC DECEMBER MAINT MAINTAINANCE MNT DUES CHGS CHRG RENT FLAT WING BLDG BUILDING QTR QUARTER QUARTERLY HALF YEARLY ANNUAL P2A P2M HDFC ICIC ICICI SBIN UTIB KKBK BARB SRCB YESB PUNB CNRB UBIN IOBA IDIB MAHB IDFB INDB FDRL'.split(' '));
const lrn2Tok = t => [...lrnTokens(t)].filter(w => !LRN2_STOP.has(w) && !/^[A-Z]{4}0[A-Z0-9]{6}$/.test(w));
function lrn2Teach(rows) { if (!canEdit()) return; const L = LRN2(); const up = {}; let n = 0;
  for (const x of rows) { const acc = x.m ? 'M:' + x.m : x.h; if (!acc || !x.nar) continue; for (const tk of lrn2Tok(x.nar)) { const k = lrnK(tk);
      const key = `bcfg/_lrn/${k}/${acc}`; up[key] = (up[key] != null ? up[key] : ((L[k] || {})[acc] || 0)) + 1; n++; } }
  if (!n) return; const tokens = Object.keys(L).length; if (tokens > 4000) { const drop = Object.entries(L).map(([k, v]) => [k, Object.values(v || {}).reduce((a, b) => a + b, 0)]).sort((a, b) => a[1] - b[1]).slice(0, 500); drop.forEach(([k]) => { up[`bcfg/_lrn/${k}`] = null; }); }
  commit(up, null).catch(e => console.warn('learn', e)); }
// learned words count three times as much as words that only appear in old narrations
(() => { const oi = lrnIndex; window.lrnIndex = lrnIndex = function () { const L = LRN2(); const sig = Object.keys(L).length + ':' + JSON.stringify(L).length; if (AI.lrn2 !== sig) { AI.lix = null; AI.lrn2 = sig; }
  const idx = oi.apply(this, arguments); if (idx.__l2 === sig) return idx; for (const [k, v] of Object.entries(L)) { if (!v) continue; const x = idx[k] = idx[k] || {}; for (const [acc, n] of Object.entries(v)) if (acc.startsWith('M:') ? S.members[acc.slice(2)] : S.heads[acc]) x[acc] = (x[acc] || 0) + 3 * n; } idx.__l2 = sig; return idx; }; })();
function lrn2Hit(text, side) { const L = LRN2(); const sc = {}; for (const tk of lrn2Tok(text)) { const x = L[lrnK(tk)]; if (!x || Object.keys(x).length > 3) continue; /* a word used for many payers proves nothing */ for (const [acc, n] of Object.entries(x)) { if (side === 'P' && acc.startsWith('M:')) continue; if (acc.startsWith('M:') ? !S.members[acc.slice(2)] : !S.heads[acc]) continue; sc[acc] = (sc[acc] || 0) + n; } }
  const R = Object.entries(sc).sort((a, b) => b[1] - a[1]); return R; }
(() => { const op = bsPost; window.bsPost = bsPost = async function (P, sel) { const r = await op.apply(this, arguments); try { lrn2Teach(sel || []); } catch (e) { } return r; }; })();

// ── 50 suggestions & 56 returned cheques ───────────────────────────────
function amtAlts(x) { const amt = r2(x.cr || x.dr); const out = []; const seen = new Set(); const add = (acc, why) => { if (!acc || seen.has(acc) || out.length >= 3) return; seen.add(acc); out.push({ acc, why }); };
  for (const [acc, n] of lrn2Hit(`${x.nar} ${x.ref || ''}`, x.cr ? 'R' : 'P').slice(0, 2)) add(acc, `matched like this ${n} time(s) before`);
  if (x.cr) { const mb = MB(); const rr = regRuns(); const lr = rr.length ? rr[rr.length - 1][0] : null; const lb = {}; if (lr) runBills(lr).forEach(([, b]) => { lb[b.mid] = r2(ENG.billTotal(b)); });
    for (const [mid] of Object.entries(S.members)) { if (lb[mid] && Math.abs(lb[mid] - amt) < 0.5) add('M:' + mid, `last bill ₹${fmt(lb[mid])}`); }
    for (const [mid, b] of Object.entries(mb)) { if (b && Math.abs((b.bal || 0) - amt) < 0.5) add('M:' + mid, `dues ₹${fmt(b.bal)}`); } }
  else { const cnt = {}; for (const v of Object.values(S.vch || {})) { if (!v || v.t !== 'P' || Math.abs(vAmount(v) - amt) > 0.5) continue; const o = vLines(v).find(l => l.dr && !isCB(l.h)); if (o) cnt[o.h] = (cnt[o.h] || 0) + 1; } Object.entries(cnt).sort((a, b) => b[1] - a[1]).forEach(([h, n]) => add(h, `paid ₹${fmt(amt)} ${n} time(s) before`)); }
  return out; }
const RTN_RE = /\b(rtn|return(ed)?|bounce|dishono?u?r|unpaid|insuff|chq ret|i\/w ret|inward return|refer to drawer|funds insufficient)\b/i;
function bounceFind(x) { if (!x.dr || !RTN_RE.test(x.nar || '')) return null; const ref = String(x.ref || '').replace(/^0+/, ''); let best = null;
  for (const [id, v] of Object.entries(S.vch || {})) { if (!v || v.t !== 'R' || v.bnc || v.rev) continue; const no = String((v.chq || {}).no || '').replace(/^0+/, ''); const same = Math.abs(vAmount(v) - x.dr) < 0.5; const near = Math.abs(daysBetween(v.d, x.d)) <= 45;
    if (same && near && ((ref && no && (ref.endsWith(no) || no.endsWith(ref))) || !best)) best = { id, v, chq: !!(ref && no && (ref.endsWith(no) || no.endsWith(ref))) }; if (best && best.chq) break; }
  return best; }
(() => { const og = pdfGuess; window.pdfGuess = pdfGuess = function (x) { let g = og.apply(this, arguments);
  try { const L = lrn2Hit(`${x.nar} ${x.ref || ''}`, x.cr ? 'R' : 'P'); if (L.length && L[0][1] >= 1 && (!L[1] || L[1][1] < L[0][1] * 0.7)) g = { acc: L[0][0], conf: L[0][1] >= 2 ? 'high' : 'medium', why: `you matched this before (${L[0][1]}×)` };
    if (g.conf !== 'high') { const alts = amtAlts(x).filter(a => a.acc !== g.acc); if (alts.length) g = { ...g, alts }; }
    const bn = bounceFind(x); if (bn) g = { ...g, bounce: bn.id, why: `returned cheque — receipt ${bn.v.no}` }; } catch (e) { } return g; }; })();
(() => { const og = pdfGrid; window.pdfGrid = pdfGrid = function () { const r = og.apply(this, arguments); try { const P = window.__PDF; const A = bsAccounts(P.bank); const lbl = v => v.startsWith('M:') ? ((A.mems.find(x => 'M:' + x.mid === v) || {}).label || v) : ((A.heads.find(x => x.id === v) || {}).label || (S.heads[v] || {}).name || v);
    $$('.pdf-a').forEach(s => { const i = +s.dataset.i; const x = P.rows[i]; const td = s.closest('td'); if (!td || !x) return;
      if (x.alts && x.alts.length && !s.value) td.insertAdjacentHTML('beforeend', `<div class="small">${x.alts.map(a => `<span class="alt-c" title="${esc(a.why)}" onclick="pdfAlt(${i},'${esc(a.acc)}')">${esc(lbl(a.acc))} <span class="muted">${esc(a.why)}</span></span>`).join('')}</div>`);
      if (x.bounce) td.insertAdjacentHTML('beforeend', `<div class="small"><button class="xs danger" onclick="pdfBounce(${i})" title="Reverses the receipt, adds bounce charges to the member's next bill and flags the member">↩ Record bounce of ${esc((S.vch[x.bounce] || {}).no || '')}</button></div>`); });
    const ft = document.querySelector('.ov:last-child .md-b p.small'); const chg = P.rows.filter(x => /charges|chgs|sms|gst|commission|fee|\bint\b|interest|int\.?\s*pd|int\.?cr/i.test(x.nar || '')).length;
    if (ft && chg && !$('pdf-bc')) ft.insertAdjacentHTML('afterend', `<div class="row small" style="margin:4px 0"><button class="xs" id="pdf-bc" onclick="pdfBankLines()">🏦 Fill all ${chg} bank charges & interest lines</button><span class="muted">uses the Bank Charges and Interest on Bank heads (made if missing)</span></div>`); } catch (e) { } return r; }; })();
function pdfAlt(i, acc) { const s = document.querySelector(`.pdf-a[data-i="${i}"]`); if (s) { s.value = acc; s.dispatchEvent(new Event('change', { bubbles: true })); const c = s.closest('tr'); if (c) c.dataset.c = 'medium'; } }
async function pdfBounce(i) { const P = window.__PDF; const x = P.rows[i]; if (!x || !x.bounce) return; const vid = x.bounce; bounceModal(vid);
  const t0 = Date.now(); const tick = () => { const v = S.vch[vid]; if (v && v.bnc) { const s = document.querySelector(`.pdf-a[data-i="${i}"]`); if (s) { s.value = ''; const tr = s.closest('tr'); if (tr) { tr.style.opacity = '.45'; tr.dataset.c = 'bounce'; } } x.skip = true; toast('Bounce recorded — this statement line is already in the books now', 'ok', 6000); return; } if (Date.now() - t0 < 300000) setTimeout(tick, 600); }; setTimeout(tick, 800); }
// lines marked as bounce are left out of the import
(() => { const ot = pdfToImport; window.pdfToImport = pdfToImport = function () { const P = window.__PDF; if (P && P.rows.some(x => x.skip)) { window.__PDF = { ...P, rows: P.rows.filter(x => !x.skip) }; } return ot.apply(this, arguments); }; })();
async function pdfBankLines() { try { guardEdit(); const ch = await ensureHead('Bank Charges', 'Expenses', 'Administrative Expenses', 'E070'); const ih = await (Object.keys(S.heads).find(k => S.heads[k] && /interest on (savings|bank|sb)/i.test(S.heads[k].name || '')) || await ensureHead('Interest on Savings Bank Account', 'Income', 'Interest Income', 'I030'));
  await waitFor(() => S.heads[ch] && S.heads[ih], 6000).catch(() => { }); const P = window.__PDF; let n = 0;
  $$('.pdf-a').forEach(s => { const x = P.rows[+s.dataset.i]; if (!x) return; const t = x.nar || ''; let acc = ''; if (x.dr && /charges|chgs|sms|gst|commission|fee/i.test(t)) acc = ch; else if (x.cr && /\bint\b|interest|int\.?\s*pd|int\.?cr/i.test(t)) acc = ih; if (!acc) return;
    if (![...s.options].some(o => o.value === acc)) s.insertAdjacentHTML('beforeend', `<option value="${acc}">${esc(H(acc).name)}</option>`); s.value = acc; const tr = s.closest('tr'); if (tr) tr.dataset.c = 'high'; n++; });
  toast(`${n} line(s) filled — check and press "Check & import"`, 'ok'); } catch (e) { toast(e.message, 'err'); } }

// ── 51 the bank's own Excel / CSV ───────────────────────────────────────
const RAW_F = [['d', 'Date', /^(txn|tran|transaction|value|posting)?date$|^date$/], ['nar', 'Narration / description', /narration|description|particular|details|remark/], ['ref', 'Cheque / ref no.', /chq|cheque|ref|utr|instrument/], ['dr', 'Withdrawal (debit)', /withdraw|debit|^dr$|paidout|payments?/], ['cr', 'Deposit (credit)', /deposit|credit|^cr$|paidin|receipts?/], ['amt', 'Amount (one column)', /^amount|^amt$|txnamount/], ['dc', 'Dr / Cr marker', /^(dr\/?cr|crdr|type|drcr)$/], ['bal', 'Balance', /balance/]];
const rawNum = v => { const s = String(v == null ? '' : v).replace(/[₹,\s]/g, ''); if (!s || s === '-') return 0; const n = parseFloat(s.replace(/(cr|dr)$/i, '')); return isFinite(n) ? Math.abs(n) : 0; };
function rawDate(v) { if (v instanceof Date && !isNaN(v)) return `${v.getFullYear()}-${String(v.getMonth() + 1).padStart(2, '0')}-${String(v.getDate()).padStart(2, '0')}`; if (typeof v === 'number' && v > 20000 && v < 80000) { const d = new Date(Math.round((v - 25569) * 864e5)); return d.toISOString().slice(0, 10); }
  const s = String(v || '').trim(); const p = typeof pdfDate === 'function' ? pdfDate(s) : ''; if (p) return p; const m = s.match(/^(\d{1,2})[-\/. ]([A-Za-z]{3})[a-z]*[-\/. ,]*(\d{2,4})/); if (m) { const mo = MON3.findIndex(x => x.toLowerCase() === m[2].toLowerCase()) + 1; let y = +m[3]; if (y < 100) y += 2000; if (mo) return `${y}-${String(mo).padStart(2, '0')}-${String(+m[1]).padStart(2, '0')}`; } return ''; }
function rawAuto(hdr) { const nk = c => String(c || '').toLowerCase().replace(/[^a-z\/]/g, ''); const map = {}; RAW_F.forEach(([k, , re]) => { const i = hdr.findIndex((c, j) => re.test(nk(c)) && !Object.values(map).includes(j)); if (i >= 0) map[k] = i; }); return map; }
const rawOk = m => m.d != null && m.nar != null && ((m.dr != null && m.cr != null) || (m.amt != null && m.dc != null));
function rawStmt(file) { const bank = val('bs-bank') || RP.get('bsbank', '') || ((bsBanks()[0] || [])[0]); if (!bank) return toast('Add a bank account first', 'warn');
  const go_ = async f => { try { if (typeof XLSX === 'undefined') throw new Error('Excel reader not loaded — check the internet connection'); // CSV is read as plain text so 10/06/2026 stays 10 June (the Excel reader would turn it into 6 October)
    const wb = /\.csv$/i.test(f.name || '') ? XLSX.read(await f.text(), { type: 'string', raw: true }) : XLSX.read(await f.arrayBuffer(), { type: 'array', cellDates: true }); const g = XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]], { header: 1, raw: true, defval: '' });
    // header row = the first row that has a date column and a narration column
    let hi = -1, map = null; const saved0 = ((S.bcfg || {})._bsfmt || {})[bank]; const sgOf = r => (r || []).map(c => String(c).trim().toLowerCase()).join('|');
    if (saved0) { const k = g.slice(0, 60).findIndex(r => sgOf(r) === saved0.sig); if (k >= 0) { rawRows(bank, g, k, saved0.map, saved0.sig, false); return; } }
    for (let i = 0; i < Math.min(g.length, 60); i++) { const m = rawAuto(g[i]); if (m.d != null && (m.nar != null || m.dr != null || m.amt != null)) { hi = i; map = m; break; } }
    const sig = hi >= 0 ? g[hi].map(c => String(c).trim().toLowerCase()).join('|') : ''; const saved = ((S.bcfg || {})._bsfmt || {})[bank];
    if (saved && saved.sig === sig) map = saved.map; if (hi < 0) { hi = 0; map = {}; }
    if (!rawOk(map) || (saved && saved.sig !== sig && !rawOk(map))) return rawMapModal(bank, g, hi, map, sig);
    rawRows(bank, g, hi, map, sig, false); } catch (e) { toast('Could not read the file: ' + e.message, 'err', 8000); } };
  if (file) go_(file); else pickFile('.xlsx,.xls,.csv,.ods', go_); }
function rawMapModal(bank, g, hi, map, sig) { const hdr = g[hi] || []; const opt = sel => `<option value="">— not in this file —</option>${hdr.map((c, i) => `<option value="${i}" ${sel === i ? 'selected' : ''}>${esc(String(c || 'Column ' + (i + 1)))}</option>`).join('')}`;
  window.__RAW = { bank, g, hi, sig }; openModal({ title: `🏦 Which column is which? — ${esc(H(bank).name)}`, wide: true, ok: 'Use these columns', body: `<p class="small">Choose once — it is remembered for this bank account, so next time the file imports straight away.</p><div data-form><label>Heading row number</label><input id="rw-h" type="number" value="${hi + 1}" min="1" onchange="rawMapModal(__RAW.bank,__RAW.g,Math.max(0,this.value-1),rawAuto(__RAW.g[Math.max(0,this.value-1)]||[]),(__RAW.g[Math.max(0,this.value-1)]||[]).map(c=>String(c).trim().toLowerCase()).join('|'))">
    <div class="grid g2" style="margin-top:8px">${RAW_F.map(([k, l]) => `<div><label>${l}</label><select id="rw-${k}">${opt(map[k])}</select></div>`).join('')}</div><p class="small muted">Use either Withdrawal + Deposit, or one Amount column with a Dr / Cr column.</p></div>`,
    onOk: () => { const m = {}; RAW_F.forEach(([k]) => { const v = val('rw-' + k); if (v !== '') m[k] = +v; }); if (!rawOk(m)) throw new Error('Choose Date, Narration and either Withdrawal + Deposit or Amount + Dr/Cr'); const h = Math.max(0, +val('rw-h') - 1); const sg = (g[h] || []).map(c => String(c).trim().toLowerCase()).join('|'); setTimeout(() => rawRows(bank, g, h, m, sg, true), 60); } }); }
function rawRows(bank, g, hi, map, sig, save) { const rows = []; let open = null, close = null;
  for (let i = hi + 1; i < g.length; i++) { const r = g[i]; const d = rawDate(r[map.d]); if (!d) continue; let dr = 0, cr = 0;
    if (map.dr != null || map.cr != null) { dr = map.dr != null ? rawNum(r[map.dr]) : 0; cr = map.cr != null ? rawNum(r[map.cr]) : 0; } else { const a = rawNum(r[map.amt]); const t = String(r[map.dc] || '').toLowerCase(); if (/cr|credit|dep/.test(t)) cr = a; else dr = a; }
    if (!dr && !cr) continue; const bal = map.bal != null ? rawNum(r[map.bal]) : null; const x = { d, nar: String(r[map.nar] || '').replace(/\s+/g, ' ').trim(), ref: map.ref != null ? String(r[map.ref] || '').trim() : '', dr: r2(dr), cr: r2(cr), bal, sure: true };
    if (open == null && bal != null) open = r2(bal - cr + dr); if (bal != null) close = bal; rows.push(x); }
  if (!rows.length) return toast('No entries found under that heading row — check the columns', 'warn', 8000);
  if (rows.length > 1 && rows[0].d > rows[rows.length - 1].d) { rows.reverse(); if (rows[0].bal != null) open = r2(rows[0].bal - rows[0].cr + rows[0].dr); close = rows[rows.length - 1].bal; }
  if (save && canEdit()) commit({ [`bcfg/_bsfmt/${bank}`]: { sig, map, at: Date.now() } }, null).catch(() => { });
  rows.forEach(x => Object.assign(x, pdfGuess(x))); window.__PDF = { rows, open, close, bank }; pdfGrid(); }
(() => { const P = PAGES.bstmt; if (!P) return; const r = P.render; P.render = function () { const x = r.apply(this, arguments); try { const a = document.querySelector('#main .ph .acts'); if (a && canEdit() && !a.querySelector('.raw-b')) a.insertAdjacentHTML('afterbegin', `<button class="raw-b" onclick="rawStmt()" title="The Excel / CSV file downloaded from net banking — any bank">📊 Bank's Excel / CSV</button>`); } catch (e) { } return x; }; })();

// ── 48 drop a statement anywhere ────────────────────────────────────────
const PICK = { next: null };
(() => { const op = pickFile; window.pickFile = pickFile = function (accept, cb) { if (PICK.next) { const f = PICK.next; PICK.next = null; return cb(f); } return op.apply(this, arguments); }; })();
let DROP_N = 0; const dropFileOk = e => S.sid && canEdit() && e.dataTransfer && [...(e.dataTransfer.items || [])].some(i => i.kind === 'file');
document.addEventListener('dragenter', e => { if (!dropFileOk(e) || e.target.closest && e.target.closest('[ondrop], .drop, .dz, input[type=file]')) return; DROP_N++; if (!$('drop-ov')) document.body.insertAdjacentHTML('beforeend', '<div id="drop-ov">🏦 Drop the bank statement (PDF / Excel / CSV) to import it</div>'); });
document.addEventListener('dragleave', () => { DROP_N = Math.max(0, DROP_N - 1); if (!DROP_N) { const o = $('drop-ov'); if (o) o.remove(); } });
document.addEventListener('dragover', e => { if ($('drop-ov')) e.preventDefault(); });
document.addEventListener('drop', e => { const o = $('drop-ov'); DROP_N = 0; if (!o) return; o.remove(); if (e.defaultPrevented) return; e.preventDefault(); const f = e.dataTransfer.files && e.dataTransfer.files[0]; if (!f) return; dropStmt(f); });
async function dropStmt(f) { const n = f.name.toLowerCase(); if (!/\.(pdf|xlsx|xls|csv|ods)$/.test(n)) return toast('Drop a PDF, Excel or CSV bank statement', 'warn'); const B = bsBanks(); if (!B.length) return toast('Add a bank account first', 'warn');
  const cur = RP.get('bsbank', '') || B[0][0];
  openModal({ title: `🏦 Import ${esc(f.name)}`, ok: 'Import', body: `<div data-form><label>Which bank account is this statement for?</label><select id="dr-b">${B.map(([id, h]) => `<option value="${id}" ${id === cur ? 'selected' : ''}>${esc(h.name)}</option>`).join('')}</select><p class="small muted" style="margin-top:6px">You will see every line with the suggested member or head before anything is posted.</p></div>`,
    onOk: () => { const b = val('dr-b'); RP.set('bsbank', b); setTimeout(async () => { if (CUR.id !== 'bstmt' && PAGES.bstmt) { go('bstmt'); await new Promise(r => setTimeout(r, 150)); } const s = $('bs-bank'); if (s) s.value = b;
      if (/\.pdf$/.test(n)) { PICK.next = f; pdfStmt(); return; }
      // the society's own template (has the "Account / Head / Member" column) → normal import; anything else → the bank's own file
      try { const wb = XLSX.read(await f.arrayBuffer(), { type: 'array' }); const g = XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]], { header: 1, defval: '' }).slice(0, 40); const tpl = g.some(r => r.some(c => /account.*head.*member/i.test(String(c))));
        if (tpl) { PICK.next = f; bsImport(); } else rawStmt(f); } catch (e) { toast('Could not read the file: ' + e.message, 'err'); } }, 60); } }); }

// ═══════════════════════════════════════════════════════════════════════
// v12.2 — REPORTS & YEAR END (asked 8 Nov 2026)
// 57 📸 one-page society snapshot (cash, banks, dues, unreconciled, pending work) — printable
// 59 ⬇ Export on every report screen: Excel (totals as real formulas) · PDF · मराठी (final accounts)
// 60 closing the year is blocked until the year-end checklist is clear (an admin may override with a written reason)
// 61 after carrying forward: next year's openings are checked against this year's closing, to the rupee
// 64 every amount in Trial Balance / I&E / Balance Sheet / R&P opens its ledger (English and मराठी)
// 66 🔎 trial-balance difference finder · 67 members' ledgers vs Members' Dues control account
// 68 🧊 closed years: the final figures are frozen at closing; any later change to a closed year is shown at once
// (62 Balance Sheet schedules from the ledgers already exist: Final Accounts › Schedules)
// Data: fys/{fid}/frozen = { at, by, cl: { hid: closing }, sur, diff }
// ═══════════════════════════════════════════════════════════════════════
(() => { const st = document.createElement('style'); st.textContent = `
.snap td{padding:4px 8px}.snap .big{font-size:20px;font-weight:700}.snap .bad{color:#b42323}.snap .ok{color:#1c7a3e}.snap h4{margin:12px 0 4px}
.xp-m{position:absolute;z-index:3000;background:var(--card);border:1px solid var(--border);border-radius:8px;box-shadow:0 8px 24px rgba(0,0,0,.18);padding:4px 0;min-width:230px}.xp-m div{padding:7px 14px;cursor:pointer}.xp-m div:hover{background:var(--soft)}
td.drill{cursor:pointer}td.drill:hover{text-decoration:underline;color:var(--accent2,#a83848)}`; document.head.appendChild(st); })();

// ── 67 members vs control account ───────────────────────────────────────
function ctrlCheck(asOf) { const I = IDS(); const bal = ENG.balances(S, { lines: L_(), asOf }); const ctl = r2(((bal[I.dues] || {}).cl) || 0); let mem = 0; const mb = asOf ? ENG.memberBalances(S, { lines: L_(), asOf }) : MB();
  for (const [mid, b] of Object.entries(mb)) mem = r2(mem + ((b && b.bal) || 0)); const noM = L_().filter(l => l.h === I.dues && !l.m && (!asOf || l.d <= asOf)); const gone = L_().filter(l => l.h === I.dues && l.m && !S.members[l.m]);
  return { ctl, mem, diff: r2(ctl - mem), noM, gone }; }

// ── 66 trial balance difference finder ─────────────────────────────────
function tbFind() { const tb = ENG.trialBalance(S); const out = [];
  for (const [id, v] of Object.entries(S.vch || {})) { if (!v) continue; let dr = 0, cr = 0; for (const l of vLines(v)) { dr += +l.dr || 0; cr += +l.cr || 0; } if (Math.abs(dr - cr) > 0.004) out.push({ k: 'v', id, t: `${v.no} · ${fd(v.d)} — debits ₹${fmt(dr)}, credits ₹${fmt(cr)} (difference ₹${fmt(r2(dr - cr))})` }); }
  const bal = ENG.balances(S, { lines: L_() }); for (const [hid, b] of Object.entries(bal)) if (b.orphan) out.push({ k: 'h', id: hid, t: `Entries on an account head that was deleted — ₹${fmt(b.dr)} Dr / ₹${fmt(b.cr)} Cr` });
  if (Math.abs(tb.obDiff || 0) > 0.004) out.push({ k: 'ob', t: `Opening balances do not tally — Dr ₹${fmt(tb.odr)} vs Cr ₹${fmt(tb.ocr)} (difference ₹${fmt(tb.obDiff)})` });
  const c = ctrlCheck(); if (Math.abs(c.diff) > 0.5) out.push({ k: 'ctl', t: `Members' ledgers total ₹${fmt(c.mem)} but the Members' Dues account shows ₹${fmt(c.ctl)} (difference ₹${fmt(c.diff)})${c.noM.length ? ` — ${c.noM.length} entr${c.noM.length > 1 ? 'ies' : 'y'} on Members' Dues without a member` : ''}${c.gone.length ? ` — ${c.gone.length} entr${c.gone.length > 1 ? 'ies' : 'y'} of deleted members` : ''}` });
  c.noM.slice(0, 20).forEach(l => out.push({ k: l.src === 'b' ? 'b' : 'v', id: l.id, t: `${l.no} · ${fd(l.d)} — Members' Dues line without a member (₹${fmt(l.dr || l.cr)})` }));
  return { tb, out }; }
function tbFindModal() { const { tb, out } = tbFind(); const open = x => x.k === 'v' ? `closeModals();openVch('${x.id}')` : x.k === 'b' ? `closeModals();openBill('${x.id}')` : x.k === 'ob' ? "closeModals();go('obal')" : x.k === 'h' ? "closeModals();go('heads')" : "closeModals();go('dues')";
  openModal({ title: '🔎 Why the trial balance does not tally', wide: true, hideOk: true, cancel: 'Close', body: `<p>${Math.abs(tb.diff) < 0.005 ? '✅ The trial balance tallies.' : `Closing Dr ₹${fmt(tb.cdr)} vs Cr ₹${fmt(tb.ccr)} — difference <b>₹${fmt(tb.diff)}</b>.`}</p>
    ${out.length ? `<div class="tw"><table><tbody>${out.map(x => `<tr class="clk" onclick="${open(x)}"><td>${x.k === 'v' || x.k === 'b' ? '🧾' : x.k === 'ob' ? '📂' : x.k === 'ctl' ? '👥' : '🏷'}</td><td>${esc(x.t)}</td></tr>`).join('')}</tbody></table></div>` : `<p class="small muted">No unbalanced entry, deleted head or opening difference found.${Math.abs(tb.diff) > 0.005 ? ' The difference may come from the opening balances of the previous year — open Year-end › year chain check.' : ''}</p>`}` }); }
afterDom(() => { if (CUR.id !== 'tb' || !S.fy) return; const a = document.querySelector('#main .ph .acts'); if (a && !$('tbf-b')) { const d = Math.abs(ENG.trialBalance(S).diff) > 0.005; a.insertAdjacentHTML('afterbegin', `<button class="${d ? 'warn' : 'ghost'}" id="tbf-b" onclick="tbFindModal()">🔎 ${d ? 'Find the difference' : 'Check'}</button>`); } });

// ── 57 snapshot ─────────────────────────────────────────────────────────
function snapHtml() { const d = today() > S.fy.end ? S.fy.end : today(); const bal = ENG.balances(S, { lines: L_(), asOf: d }); const cb = Object.entries(S.heads).filter(([, h]) => h && (h.type === 'cash' || h.type === 'bank') && h.active !== false);
  const mb = MB(); const owe = Object.entries(mb).filter(([, b]) => b && b.bal > 0.5).map(([mid, b]) => ({ m: S.members[mid], bal: b.bal })).filter(x => x.m).sort((a, b) => b.bal - a.bal); const tot = r2(sum(owe, x => x.bal)); const adv = r2(-sum(Object.values(mb).filter(b => b && b.bal < -0.5), b => b.bal));
  const unc = cb.filter(([, h]) => h.type === 'bank').map(([hid, h]) => ({ h, n: typeof bankLines === 'function' ? bankLines(hid, d).filter(l => !l.clr || l.clr > d).length : 0 }));
  const C = typeof yeChecks === 'function' ? yeChecks() : []; const cd = C.filter(c => c.ok === true).length; const rr = regRuns(); const last = rr.length ? rr[rr.length - 1] : null; const lb = last ? runBills(last[0]) : [];
  const mailed = lb.filter(([, b]) => b.mailed).length; const unconf = Object.values(S.vch || {}).filter(v => v && v.unc).length; const lastE = Object.values(S.vch || {}).filter(Boolean).map(v => v.d).sort().pop() || '';
  const vb = typeof vendorHeads === 'function' ? vendorHeads().map(([hid]) => ({ hid, cl: (bal[hid] || {}).cl || 0 })).filter(x => x.cl < -0.5) : []; const c = ctrlCheck(); const tb = ENG.trialBalance(S, d);
  return `<div class="snap"><h3 style="margin:0">${esc(S.meta.name || '')}</h3><div class="small muted">Snapshot as on ${fd(d)} · FY ${esc(S.fy.label)} · last entry ${lastE ? fd(lastE) : '—'}</div>
    <h4>💰 Cash & bank</h4><table><tbody>${cb.map(([hid, h]) => `<tr><td>${esc(h.name)}</td><td class="n ${((bal[hid] || {}).cl || 0) < 0 ? 'bad' : ''}">₹${fmt((bal[hid] || {}).cl || 0)}</td></tr>`).join('')}<tr><td><b>Total</b></td><td class="n"><b>₹${fmt(sum(cb, ([hid]) => (bal[hid] || {}).cl || 0))}</b></td></tr></tbody></table>
    <h4>🔴 Members' dues</h4><div><span class="big">₹${fmt(tot)}</span> from ${owe.length} member(s)${adv ? ` · advances ₹${fmt(adv)}` : ''}</div><div class="small">${owe.slice(0, 5).map(x => `${esc(flatLbl(x.m))} ${esc(x.m.name)} ₹${fmt(x.bal)}`).join(' · ')}</div>
    <h4>🏦 Bank reconciliation</h4><div class="small">${unc.map(x => `${esc(x.h.name)}: ${x.n ? `<span class="bad">${x.n} entries not yet seen in the bank</span>` : '<span class="ok">all cleared</span>'}`).join('<br>') || '—'}${unconf ? `<br><span class="bad">${unconf} receipt(s) awaiting bank confirmation</span>` : ''}</div>
    <h4>🧾 Bills</h4><div class="small">${last ? `Last bills: ${esc(perLbl(last[1].from, last[1].to))} — ${lb.length} bills, ${mailed} emailed${last[1].lock ? ' · 🔒 locked' : ''}` : 'No bills this year yet'}${vb.length ? `<br>Vendors to be paid: ${vb.length} · ₹${fmt(-sum(vb, x => x.cl))}` : ''}</div>
    <h4>✅ Checks</h4><div class="small">Trial balance ${Math.abs(tb.diff) < 0.5 ? '<span class="ok">tallies</span>' : `<span class="bad">differs by ₹${fmt(tb.diff)}</span>`} · Members vs Dues account ${Math.abs(c.diff) < 0.5 ? '<span class="ok">agree</span>' : `<span class="bad">differ by ₹${fmt(c.diff)}</span>`} · Year-end checklist ${cd} of ${C.length} done</div></div>`; }
function snapModal() { if (!S.sid || !S.fy) return; openModal({ title: '📸 Society snapshot', wide: true, ok: '🖨 Print', cancel: 'Close', body: snapHtml(), onOk: () => { printReport('Society snapshot', S.meta.name || '', snapHtml()); return false; } }); }
afterDom(() => { if (CUR.id !== 'dash' || !S.fy) return; const a = document.querySelector('#main .ph .acts'); if (a && !$('snap-b')) a.insertAdjacentHTML('afterbegin', '<button class="ghost" id="snap-b" onclick="snapModal()" title="One page: cash, banks, dues, reconciliation, bills, checks">📸 Snapshot</button>'); });
(() => { const oc = cmdParse; window.cmdParse = cmdParse = function (q) { const out = oc.apply(this, arguments); try { if (S.sid && /^(snap|snapshot|summary)$/i.test(String(q).trim())) { out.length = 0; out.push({ g: '⚡ Do it', html: '<span class="gs-act">📸 Society snapshot</span>', on: 'closeModals();snapModal()' }); } if (S.sid && /^(diff|difference|tb diff)$/i.test(String(q).trim())) out.push({ g: '⚡ Do it', html: '<span class="gs-act">🔎 Trial balance difference finder</span>', on: 'closeModals();tbFindModal()' }); } catch (e) { } return out; }; })();

// ── 59 one Export button on every report ───────────────────────────────
const XFA_PAGES = /^(bs|ie|rp|tb)$/;
function xpTable() { return document.querySelector('#main .pc table'); }
function xpCellVal(td) { const s = (td.innerText || '').replace(/\s+/g, ' ').trim(); const m = s.replace(/[₹,\s]/g, '').match(/^(-?\d+(?:\.\d+)?)(Dr|Cr)?$/i); if (m) { const v = +m[1]; return m[2] && /cr/i.test(m[2]) ? -v : v; } return s; }
function xpExcel() { const t = xpTable(); if (!t) { const eb = [...document.querySelectorAll('#main .ph .acts button')].find(b => b.id !== 'xp-b' && /excel|xlsx|📊|📥/i.test(b.textContent)); if (eb) return eb.click(); return toast('No table on this screen', 'warn'); } try { prAll(t); } catch (e) { } if (typeof XLSX === 'undefined') return toast('Excel maker not loaded — check the internet', 'err');
  const aoa = []; const head = t.tHead ? [...t.tHead.rows].map(r => [...r.cells].map(c => c.innerText.trim())) : []; head.forEach(h => aoa.push(h)); const hr = aoa.length; let segStart = hr + 1;
  const rows = [...t.querySelectorAll('tbody tr, tfoot tr')].filter(r => r.getClientRects().length && !r.classList.contains('pr-tail'));
  for (const r of rows) { const cells = []; for (const c of r.cells) { const v = xpCellVal(c); cells.push(v); for (let k = 1; k < (c.colSpan || 1); k++) cells.push(''); }
    const rn = aoa.length + 1; if (r.classList.contains('tot') && rn > segStart) { for (let i = 0; i < cells.length; i++) if (typeof cells[i] === 'number') { const col = XLSX.utils.encode_col(i); cells[i] = { f: `SUM(${col}${segStart}:${col}${rn - 1})`, v: cells[i], t: 'n' }; } aoa.push(cells); segStart = rn + 1; continue; } aoa.push(cells); }
  const ws = XLSX.utils.aoa_to_sheet([[S.meta.name || ''], [((document.querySelector('#main .ph h1') || {}).innerText || '').replace(/[☆★]/g, '').trim() + ` · FY ${S.fy.label}`], [], ...aoa]);
  // the formulas were written for rows starting at 1; shift them below the 3 title rows
  Object.keys(ws).forEach(k => { const c = ws[k]; if (c && c.f) c.f = c.f.replace(/([A-Z]+)(\d+)/g, (m, a, n) => a + (+n + 3)); });
  ws['!cols'] = (aoa[0] || []).map((_, i) => ({ wch: Math.min(45, Math.max(10, ...aoa.slice(0, 300).map(r => String(r[i] && r[i].v != null ? r[i].v : r[i] == null ? '' : r[i]).length + 2))) }));
  const wb = XLSX.utils.book_new(); XLSX.utils.book_append_sheet(wb, ws, 'Report'); XLSX.writeFile(wb, safeName(`${socShort()}_${(PNAME()[CUR.id] || [, CUR.id])[1]}_${S.fy.label}`).replace(/\.pdf$/i, '').replace(/\s+/g, '_') + '.xlsx'); toast('Excel downloaded — totals are formulas, so they update if you change a figure'); }
function xpPdf(mr) { const btn = [...document.querySelectorAll('#main .ph .acts button')].find(b => /🖨|print/i.test(b.textContent) && !/bulk|label|all bills/i.test(b.textContent));
  const run = () => { if (btn) btn.click(); else printMain(((document.querySelector('#main .ph h1') || {}).innerText || 'Report').replace(/[☆★]/g, '').trim(), `FY ${S.fy.label}`); };
  if (!mr) { toast('In the print window choose "Save as PDF"'); return run(); }
  const st = S.meta.settings || (S.meta.settings = {}); const b0 = st.bill || {}; const had = b0.lang; st.bill = { ...b0, lang: 'mr' }; S.ver++; try { run(); } finally { setTimeout(() => { st.bill = { ...(st.bill || {}), lang: had }; if (had === undefined) delete st.bill.lang; S.ver++; }, 2500); } }
function xpMenu(btn) { const old = $('xp-m'); if (old) { old.remove(); return; } const r = btn.getBoundingClientRect(); const fa = XFA_PAGES.test(CUR.id);
  document.body.insertAdjacentHTML('beforeend', `<div class="xp-m" id="xp-m" style="left:${Math.round(r.left + scrollX)}px;top:${Math.round(r.bottom + scrollY + 4)}px"><div onclick="$('xp-m').remove();xpExcel()">📊 Excel — totals as formulas</div><div onclick="$('xp-m').remove();xpPdf(false)">📄 PDF / print</div>${fa ? `<div onclick="$('xp-m').remove();xpPdf(true)">🇮🇳 मराठी PDF / print</div>` : ''}</div>`);
  setTimeout(() => document.addEventListener('click', function cl(e) { if (!e.target.closest('#xp-m')) { const m = $('xp-m'); if (m) m.remove(); document.removeEventListener('click', cl, true); } }, true), 0); }
afterDom(() => { if (!S.sid || !CUR.id || /^(receipt|payment|contra|journal|bulk|bulkexp|settings|bsetup|dash)$/.test(CUR.id)) return; const a = document.querySelector('#main .ph .acts'); const t = xpTable(); if (!a || $('xp-b')) return; if (!XFA_PAGES.test(CUR.id) && (!t || !t.tBodies[0] || t.tBodies[0].rows.length < 2)) return; a.insertAdjacentHTML('beforeend', '<button class="ghost" id="xp-b" onclick="xpMenu(this)" title="Excel (with formulas), PDF or मराठी">⬇ Export</button>'); });

// ── 64 click any amount in final accounts → its ledger ─────────────────
function faDrill() { if (!XFA_PAGES.test(CUR.id || '') || !S.heads) return; const byName = {}; for (const [id, h] of Object.entries(S.heads)) { if (!h) continue; byName[String(h.name).trim().toLowerCase()] = id; try { const mr = trName(id, 'mr'); if (mr) byName[String(mr).trim().toLowerCase()] = id; const hi = trName(id, 'hi'); if (hi) byName[String(hi).trim().toLowerCase()] = id; } catch (e) { } }
  document.querySelectorAll('#main .pc table tbody tr').forEach(tr => { if (tr.dataset.dr) return; tr.dataset.dr = '1'; const ln = tr.querySelector('a[onclick*="go(\'gl\'"], [onclick*="openHead"], a[onclick*="go(\'dues\'"]'); if (ln) { const f = ln.getAttribute('onclick'); [...tr.cells].forEach(c => { if (!c.contains(ln) && /\d/.test(c.innerText) && !c.querySelector('a,button')) { c.classList.add('drill'); c.title = 'Open the ledger'; c.onclick = () => { ln.click(); }; } }); return; } if (tr.querySelector('.clk, a')) return; const cells = [...tr.cells]; const nameCell = cells.find(c => byName[(c.innerText || '').trim().toLowerCase()]);
    if (!nameCell) return; const hid = byName[nameCell.innerText.trim().toLowerCase()]; const I = IDS(); cells.forEach(c => { if (c !== nameCell && !/[\d]/.test(c.innerText)) return; c.classList.add('drill'); c.title = 'Open the ledger'; c.onclick = () => (hid === I.dues ? go('dues') : openHead(hid)); }); }); }
afterDom(faDrill);

// ── 60 closing is blocked until the checklist is clear ─────────────────
(() => { const oc = closeYear; window.closeYear = closeYear = async function (final) { if (!final || S.fy.closed || typeof yeChecks !== 'function') return oc.apply(this, arguments);
  const C = yeChecks().filter(c => c.k !== 'lock'); const bad = C.filter(c => c.ok === false); const unk = C.filter(c => c.ok === null);
  if (bad.length) { const ok = await new Promise(res => { let done = false; openModal({ title: `✋ FY ${esc(S.fy.label)} is not ready to close`, wide: true, ok: isAdmin() ? 'Close anyway (admin)' : '', hideOk: !isAdmin(), okClass: 'danger', cancel: 'Go back',
      body: `<p>These year-end points are still open:</p><ul>${bad.map(c => `<li><b>${esc(c.t)}</b> — <span class="small">${esc(c.note || '')}</span></li>`).join('')}</ul>${unk.length ? `<p class="small muted">Not checked: ${unk.map(c => esc(c.t)).join(' · ')}</p>` : ''}
        ${isAdmin() ? `<div data-form><label>Reason for closing anyway (saved in the audit trail) *</label><input id="yc-why" placeholder="e.g. auditor agreed, BRS difference explained in notes"></div>` : '<p class="small">Only an admin can close a year with open points.</p>'}<p class="small"><a class="clk" onclick="closeModals();go('yearck')">Open the Year-End Checklist</a></p>`,
      onOk: () => { const w = val('yc-why').trim(); if (w.length < 5) throw new Error('Write the reason (at least a few words)'); done = true; commit({}, { a: 'override', e: 'Year end', s: `FY ${S.fy.label} closed with ${bad.length} open point(s): ${bad.map(c => c.t).join('; ')} — reason: ${w}` }).catch(() => { }); res(true); } });
      const t = setInterval(() => { if (!$$('.ov').length || done) { clearInterval(t); if (!done) res(false); } }, 300); }); if (!ok) return; }
  const fid = S.fyId; const snap = freezeData(); const r = await oc.apply(this, arguments); try { if ((S.fys[fid] || {}).closed) await freezeYear(fid, snap); } catch (e) { console.warn('freeze', e); } return r; }; })();

// ── 61 after carrying forward: openings = closing? ─────────────────────
(() => { const of = carryForward; window.carryForward = carryForward = async function () { const fid = S.fyId; const r = await of.apply(this, arguments); setTimeout(async () => { try { const L = await linkStatus(fid); if (!L) return;
    if (L.stale) toast(`⚠ FY ${S.fys[L.to] ? S.fys[L.to].label : ''} openings differ from FY ${S.fys[fid] ? S.fys[fid].label : ''} closing for ${L.d.heads.length} head(s) and ${L.d.members.length} member(s) — open Year-end › Year chain to fix`, 'warn', 12000);
    else toast(`✓ Checked: next year's opening balances are exactly this year's closing balances`, 'ok', 6000); } catch (e) { } }, 1500); return r; }; })();

// ── 68 frozen figures of a closed year ─────────────────────────────────
// the final figures are taken just before closing (closing itself does not change that year's entries)
function freezeData() { const tb = ENG.trialBalance(S); const cl = {}; tb.rows.forEach(r => { if (Math.abs(r.cl) > 0.004) cl[r.hid] = r2(r.cl); }); const ie = ENG.incomeExpenditure(S); return { cl, sur: r2(ie.surplus || 0), diff: r2(tb.diff) }; }
async function freezeYear(fid, snap) { const lbl = (S.fys[fid] || {}).label || '';
  await commit({ [`fys/${fid}/frozen`]: { at: Date.now(), by: uname(), ...(snap || freezeData()) } }, { a: 'freeze', e: 'Year end', s: `Final figures of FY ${lbl} frozen at closing` });
  setTimeout(async () => { if (await confirmBox(`FY ${lbl} is closed and its final figures are frozen.\n\nDownload the complete books (PDF) of FY ${lbl} now to keep with the audit file?`, { ok: '📚 Complete Books' })) { if (S.fyId !== fid) { switchFY(fid); await waitFor(() => S.fyId === fid && ['ob', 'vch', 'bills', 'runs'].every(k => S.loaded[k])).catch(() => { }); } go('books'); } }, 900); }
function frozenDiff() { const fz = (S.fy || {}).frozen || ((S.fys || {})[S.fyId] || {}).frozen; if (!fz || !S.fy.closed) return null; const tb = ENG.trialBalance(S); const now = {}; tb.rows.forEach(r => { if (Math.abs(r.cl) > 0.004) now[r.hid] = r2(r.cl); });
  const ids = new Set([...Object.keys(fz.cl || {}), ...Object.keys(now)]); const ch = []; ids.forEach(h => { const a = (fz.cl || {})[h] || 0, b = now[h] || 0; if (Math.abs(a - b) > 0.004) ch.push({ h, a, b }); }); return { fz, ch }; }
afterDom(() => { if (!S.sid || !S.fy || !S.fy.closed || !/^(dash|tb|bs|ie|yearck|year)$/.test(CUR.id || '')) return; const x = frozenDiff(); const pc = document.querySelector('#main .pc'); if (!x || !pc || $('fz-ban')) return;
  pc.insertAdjacentHTML('afterbegin', x.ch.length ? `<div class="alert a-err" id="fz-ban">🧊 <b>FY ${esc(S.fy.label)} was closed on ${fd(new Date(x.fz.at).toISOString().slice(0, 10))}, but its figures have changed since:</b> ${x.ch.slice(0, 6).map(c => `${esc(H(c.h).name)} ₹${fmt(c.a)} → ₹${fmt(c.b)}`).join(' · ')}${x.ch.length > 6 ? ` and ${x.ch.length - 6} more` : ''}. Check the audit trail, then re-carry forward if the change is correct.</div>` : `<div class="alert a-ok small" id="fz-ban">🧊 FY ${esc(S.fy.label)} closed on ${fd(new Date(x.fz.at).toISOString().slice(0, 10))} — figures unchanged since closing.</div>`); });

// ═══════════════════════════════════════════════════════════════════════
// v12.3 — FIRM (asked 8 Nov 2026)
// 69 firm dashboard as one table: every society's dues, last entry, bills, bank reconciliation, year end
// 70 📋 My work today — built by itself from each society's bill calendar, bank reconciliation and pending receipts
// 71 status colour per society: 🟢 on time · 🟠 due · 🔴 late
// 80 📦 move many MAXX societies at once: one MAXX file → each society (all its years) into its own new society, one after another
// Data: societies/{sid}/summary/x = { lastE, unc, brs, bill, ye, closed } (written when someone with edit rights works in the society)
// ═══════════════════════════════════════════════════════════════════════
(() => { const st = document.createElement('style'); st.textContent = `
.fd-t td,.fd-t th{padding:5px 8px;font-size:12.5px;white-space:nowrap}.fd-t tr.clk:hover{background:var(--soft)}
.st-ok{color:#1c7a3e}.st-due{color:#9a5b00}.st-late{color:#b42323}.st-dot{display:inline-block;width:10px;height:10px;border-radius:50%;margin-right:6px;vertical-align:middle}
.st-dot.ok{background:#2fa35a}.st-dot.due{background:#f0a020}.st-dot.late{background:#d93636}.st-dot.na{background:#c4c9d2}
.socc.st-ok{border-left:4px solid #2fa35a}.socc.st-due{border-left:4px solid #f0a020}.socc.st-late{border-left:4px solid #d93636}
.wq{margin-bottom:14px}.wq-i{display:flex;gap:8px;align-items:center;padding:7px 4px;border-bottom:1px solid var(--border);cursor:pointer}.wq-i:hover{background:var(--soft)}.wq-i .wq-s{flex:1}`; document.head.appendChild(st); })();

const SXC = { sid: null, fy: null, at: 0, brs: 0, ye: null, force: false };
(() => { const oc = closeSociety; window.closeSociety = closeSociety = function () { SXC.force = true; return oc.apply(this, arguments); }; })();
// what the firm needs to know about a society (kept small; recalculated with the society summary)
function summaryX() { if (!S.fy) return null; const t = today(); const d = t > S.fy.end ? S.fy.end : t; let lastE = ''; let unc = 0; for (const v of Object.values(S.vch || {})) { if (!v) continue; if (v.d > lastE) lastE = v.d; if (v.unc) unc++; }
  // the heavy parts (bank reconciliation count, year-end checklist) at most every 15 minutes, and always when leaving the society
  const heavy = SXC.sid !== S.sid || SXC.fy !== S.fyId || Date.now() - SXC.at > 15 * 60e3 || SXC.force; let brs = SXC.brs, ye0 = SXC.ye;
  if (heavy) { brs = 0; try { for (const [hid, h] of Object.entries(S.heads)) if (h && h.type === 'bank' && h.active !== false) brs += bankLines(hid, d).filter(l => (!l.clr || l.clr > d) && daysBetween(l.d, d) > 30).length; } catch (e) { } }
  let bill = null; try { const day = +((BD() || {}).day) || 1; const P = bdPeriods().filter(p => p.f <= t && !bdRunFor(p.f)); if (P.length) { const p = P[0]; bill = { f: p.f, t: p.t, mk: ENG.addDays(p.f, Math.max(0, day - 1)) }; } } catch (e) { }
  let ye = heavy ? null : ye0; if (heavy) { try { if (t > S.fy.end && !S.fy.closed && typeof yeChecks === 'function') { const C = yeChecks().filter(c => c.k !== 'lock'); ye = [C.filter(c => c.ok === true).length, C.length]; } } catch (e) { } Object.assign(SXC, { sid: S.sid, fy: S.fyId, at: Date.now(), brs, ye, force: false }); }
  return { lastE, unc, brs, bill, ye, closed: !!S.fy.closed, per: SET().billing.per, at: Date.now() }; }
// 🟢 / 🟠 / 🔴 from the summary
function socStatus(sm) { const x = (sm || {}).x; if (!x) return { k: 'na', why: ['not opened since v12.3 — open it once to get its status'] }; const t = today(); const why = []; let k = 'ok';
  const bump = (lv, w) => { why.push(w); if (lv === 'late' || (lv === 'due' && k === 'ok')) k = lv; };
  if (x.bill) { const late = daysBetween(x.bill.mk, t); if (late > 7) bump('late', `bills for ${perLbl(x.bill.f, x.bill.t)} not made (${late} days late)`); else if (late >= 0) bump('due', `bills for ${perLbl(x.bill.f, x.bill.t)} to be made`); }
  if (x.brs) bump(x.brs > 20 ? 'late' : 'due', `${x.brs} bank entr${x.brs > 1 ? 'ies' : 'y'} not reconciled for over 30 days`);
  if (x.unc) bump('due', `${x.unc} receipt(s) awaiting bank confirmation`);
  if (x.ye) bump(daysBetween(`${t.slice(0, 4)}-06-30`, t) > 0 && t.slice(5) > '06-30' ? 'late' : 'due', `year end: ${x.ye[0]} of ${x.ye[1]} checklist points done`);
  if (x.lastE && daysBetween(x.lastE, t) > 45) bump('due', `no entry for ${daysBetween(x.lastE, t)} days`);
  return { k, why }; }
const ST_LBL = { ok: 'On time', due: 'Due', late: 'Late', na: '—' };

// ── 69 / 71 table view + colours on the cards ──────────────────────────
const FDV = () => LS.get('sb_firmview', 'cards');
function fdTable() { const ids = Object.keys(FIRM.list || {}).filter(s => !(FIRM.info[s] || {}).err); const q = (LS.get('sb_firmq', '') || '').toLowerCase();
  const R = ids.map(sid => { const i = FIRM.info[sid] || {}; const sm = i.summary || {}; return { sid, i, sm, x: sm.x || {}, st: socStatus(sm) }; }).filter(r => !q || `${r.i.name} ${r.i.code || ''} ${r.i.city || ''}`.toLowerCase().includes(q))
    .sort((a, b) => ({ late: 0, due: 1, na: 2, ok: 3 })[a.st.k] - ({ late: 0, due: 1, na: 2, ok: 3 })[b.st.k] || String(a.i.name).localeCompare(String(b.i.name)));
  return `<div class="tw tall"><table class="fd-t"><thead><tr><th>Status</th><th>Society</th><th class="n">Members</th><th class="n">Dues ₹</th><th>Last entry</th><th>Bills</th><th>Bank reco</th><th>Year end</th><th></th></tr></thead><tbody>${R.map(r => `<tr class="clk" onclick="openSociety('${r.sid}')" title="${esc(r.st.why.join(' · '))}">
    <td><span class="st-dot ${r.st.k}"></span><span class="st-${r.st.k}">${ST_LBL[r.st.k]}</span></td><td><b>${esc(r.i.name || '')}</b>${r.i.code ? ` <span class="ss-code">${esc(r.i.code)}</span>` : ''}<div class="small muted">${esc(r.st.why.slice(0, 2).join(' · '))}</div></td>
    <td class="n">${r.sm.members || 0}</td><td class="n">${fmt0(r.sm.out || 0)}</td><td>${r.x.lastE ? fd(r.x.lastE) : '—'}</td><td>${r.x.bill ? `<span class="chip ${daysBetween(r.x.bill.mk, today()) > 7 ? 'c-bad' : daysBetween(r.x.bill.mk, today()) >= 0 ? 'c-warn' : 'c-mut'}">${esc(perLbl(r.x.bill.f, r.x.bill.t))} to make</span>` : r.sm.lastBill ? `<span class="chip c-ok">✓ ${esc(monLbl(r.sm.lastBill))}</span>` : '—'}</td>
    <td>${r.sm.x ? (r.x.brs ? `<span class="chip ${r.x.brs > 20 ? 'c-bad' : 'c-warn'}">${r.x.brs} open</span>` : '<span class="chip c-ok">✓</span>') : '—'}${r.x.unc ? ` <span class="chip c-warn">${r.x.unc} unconfirmed</span>` : ''}</td>
    <td>${r.x.closed ? '<span class="chip c-ok">closed</span>' : r.x.ye ? `<span class="chip c-warn">${r.x.ye[0]}/${r.x.ye[1]}</span>` : '<span class="small muted">year running</span>'}</td><td><button class="xs ghost" title="Open in a new tab" onclick="event.stopPropagation();socNewTab('${r.sid}')">↗</button></td></tr>`).join('')}</tbody></table></div>
    <p class="small muted" style="margin-top:6px">🟢 on time · 🟠 something to do soon · 🔴 late. Each society's line updates when someone works in it (hover a line to see why). Sorted: late first.</p>`; }
(() => { const P = PAGES.firm; if (!P) return; const r = P.render; P.render = function () { const x = r.apply(this, arguments); try { fdDecorate(); } catch (e) { console.warn(e); } return x; }; })();
function fdDecorate() { const main = $('main'); if (!main || CUR.id !== 'firm') return; const a = main.querySelector('.ph .acts'); const ids = Object.keys(FIRM.list || {});
  if (a && ids.length && !$('fdv-b')) a.insertAdjacentHTML('afterbegin', `<button class="ghost" id="fdv-b" onclick="LS.set('sb_firmview',FDV()==='table'?'cards':'table');render()">${FDV() === 'table' ? '▦ Cards' : '☰ Table'}</button>${FIRM.ok || isFirmAdmin_() ? '<button class="ghost" id="mxb-b" onclick="mxBulkStart()" title="Move many MAXX societies at once">📦 MAXX → all societies</button>' : ''}`);
  // 71 colours on the cards
  main.querySelectorAll('.socc').forEach(c => { const m = (c.getAttribute('onclick') || '').match(/openSociety\('([^']+)'\)/); if (!m) return; const st = socStatus(((FIRM.info || {})[m[1]] || {}).summary); c.classList.add('st-' + st.k); c.title = st.why.join(' · '); });
  // 69 table view replaces the cards
  if (FDV() === 'table') { const grid = main.querySelector('.socc') && main.querySelector('.socc').parentElement; if (grid && !$('fd-tbl')) { grid.style.display = 'none'; grid.insertAdjacentHTML('afterend', `<div id="fd-tbl">${fdTable()}</div>`); } }
  // 70 my work today
  const pc = main.querySelector('.pc'); if (pc && !$('wq')) pc.insertAdjacentHTML('afterbegin', wqHtml()); }
const isFirmAdmin_ = () => { try { return !!(FIRM && (FIRM.ok || FIRM.admin)); } catch (e) { return false; } };

// ── 70 my work today ────────────────────────────────────────────────────
function wqItems() { const out = []; const t = today(); for (const sid of Object.keys(FIRM.list || {})) { const i = FIRM.info[sid] || {}; if (i.err || !/admin|accountant/.test(i.role || '')) continue; const x = (i.summary || {}).x; if (!x) continue; const nm = i.code || i.name || '';
    if (x.bill) { const late = daysBetween(x.bill.mk, t); if (late >= 0) out.push({ sid, nm, p: 'bills', pr: late > 7 ? 0 : 1, ic: '🧾', tx: `Make bills for ${perLbl(x.bill.f, x.bill.t)}`, sub: late ? `${late} day(s) since the bill day` : 'today is the bill day' }); }
    if (x.unc) out.push({ sid, nm, p: 'unconf', pr: 1, ic: '⏳', tx: `Confirm ${x.unc} receipt(s) with the bank statement` });
    if (x.brs) out.push({ sid, nm, p: 'recon', pr: x.brs > 20 ? 0 : 2, ic: '🏦', tx: `Bank reconciliation — ${x.brs} entr${x.brs > 1 ? 'ies' : 'y'} older than 30 days` });
    if (x.ye) out.push({ sid, nm, p: 'yearck', pr: 2, ic: '✅', tx: `Year-end checklist — ${x.ye[0]} of ${x.ye[1]} done` }); }
  return out.sort((a, b) => a.pr - b.pr || a.nm.localeCompare(b.nm)); }
function wqHtml() { const L = wqItems(); if (!L.length) return `<div class="card wq small muted" id="wq">📋 <b>My work today:</b> nothing due in your societies ✓ <span class="muted">(built from each society's bill calendar, bank reconciliation and pending receipts)</span></div>`;
  return `<div class="card wq" id="wq"><div class="row" style="justify-content:space-between"><h3 style="margin:0">📋 My work today <span class="small muted">${L.length}</span></h3><span class="small muted">from the bill calendar, bank reconciliation and pending receipts of your societies</span></div>
    ${L.slice(0, 15).map(x => `<div class="wq-i" onclick="wqGo('${x.sid}','${x.p}')"><span class="st-dot ${x.pr === 0 ? 'late' : x.pr === 1 ? 'due' : 'ok'}"></span><span>${x.ic}</span><span class="wq-s"><b>${esc(x.nm)}</b> — ${esc(x.tx)}${x.sub ? ` <span class="small muted">${esc(x.sub)}</span>` : ''}</span><button class="xs ghost" onclick="event.stopPropagation();socNewTab('${x.sid}')" title="New tab">↗</button></div>`).join('')}${L.length > 15 ? `<div class="small muted" style="padding:6px">… and ${L.length - 15} more — switch to ☰ Table to see every society</div>` : ''}</div>`; }
async function wqGo(sid, p) { if (S.sid !== sid) await openSociety(sid); await waitFor(() => S.sid === sid && S.fy && ['vch', 'bills'].every(k => S.loaded[k]), 15000).catch(() => { }); if (PAGES[p]) go(p); }

// ── 80 many MAXX societies at once ─────────────────────────────────────
const MXB = { groups: [], res: [], stop: false, busy: false };
function mxBulkStart() { pickFile('.mdb,.zip', async f => { openModal({ title: '📦 MAXX → all societies', hideOk: true, body: loading(`Reading ${f.name}…`) });
  try { await mdbLibLoad(); mdbLib(); let buf = new Uint8Array(await f.arrayBuffer());
    if (/\.zip$/i.test(f.name)) { const z = XLSX.CFB.read(buf, { type: 'array' }); const e = z.FileIndex.find(x => /\.mdb$/i.test(x.name) && x.size > 0); if (!e) throw new Error('No .mdb file inside the zip'); buf = new Uint8Array(e.content); }
    MX.r = new MDBReader(MdbBuffer.from(buf)); MX.t = {}; MX.tbl = n => MX.t[n] || (MX.t[n] = MX.r.getTable(n).getData()); MX.socs = MX.tbl('SETUP2').map(x => ({ no: String(x.doc), name: x.company || ('Society ' + x.doc) }));
    const Y = mxYearInfo(); const G = {}; Y.forEach(y => (G[y.base] = G[y.base] || []).push(y)); const have = new Set(Object.values(FIRM.info || {}).map(i => mxBase(i.name || '')));
    MXB.groups = Object.entries(G).map(([base, ys]) => ({ base, ys: ys.sort((a, b) => String(a.sd).localeCompare(String(b.sd))), name: ys.slice().sort((a, b) => String(b.sd).localeCompare(String(a.sd)))[0].name.replace(/[\s.,\-–]*((19|20)\d{2}.*|\d{2}\s*-\s*\d{2}.*)$/, '').trim(), done: have.has(base) })).sort((a, b) => a.name.localeCompare(b.name));
    closeAllModals(); mxBulkModal(); } catch (e) { closeAllModals(); toast('MAXX: ' + e.message, 'err', 9000); } }); }
function mxBulkModal() { const G = MXB.groups;
  openModal({ title: `📦 MAXX → all societies (${G.length} found in this MAXX file)`, xwide: true, ok: 'Start moving the ticked societies', body: `<p class="small">Each ticked society gets a <b>new society here</b> with <b>all its MAXX years</b> (bills, entries, members, accounts). Every year is checked against MAXX's own ledger, like the normal import. Societies already here (same name) are not ticked. They are moved one after another — keep this window open; you can stop after the current society.</p>
    <div class="fr c3"><div><label>Member opening balance in MAXX</label><select id="mxb-oi"><option value="incl">Includes interest</option><option value="excl">Excludes interest (add Opening Int)</option></select></div><div><label>After the latest year</label><select id="mxb-end"><option value="open">Keep it open (continue working in it)</option><option value="next">Close it and carry forward to the next year</option></select></div><div><label>Openings of later years</label><select id="mxb-ob"><option value="maxx">As in MAXX for that year</option><option value="carry">Carried forward here</option></select></div></div>
    <div class="tw" style="max-height:46vh"><table><thead><tr><th><input type="checkbox" onchange="$$('.mxb-c').forEach(c=>c.checked=this.checked)"></th><th>Society</th><th>Years in MAXX</th><th class="n">Entries</th><th>Here already?</th></tr></thead><tbody>${G.map((g, i) => `<tr><td><input type="checkbox" class="mxb-c" value="${i}" ${g.done ? '' : 'checked'}></td><td><b>${esc(g.name)}</b></td><td class="small">${g.ys.map(y => esc(y.fy)).join(', ')}</td><td class="n">${sum(g.ys, y => y.n)}</td><td>${g.done ? '<span class="chip c-warn">yes — skip</span>' : ''}</td></tr>`).join('')}</tbody></table></div>`,
    onOk: () => { const sel = $$('.mxb-c').filter(c => c.checked).map(c => +c.value); if (!sel.length) throw new Error('Tick at least one society'); const o = { oi: val('mxb-oi'), end: val('mxb-end'), ob: val('mxb-ob'), meta: true }; setTimeout(() => mxBulkRun(sel, o), 60); } }); }
function mxbBar(html) { let b = $('mxb-bar'); if (!b) { b = document.createElement('div'); b.id = 'mxb-bar'; b.style.cssText = 'position:fixed;left:50%;bottom:16px;transform:translateX(-50%);z-index:4500;background:var(--card);border:1px solid var(--border);border-radius:12px;box-shadow:0 8px 30px rgba(0,0,0,.25);padding:12px 16px;min-width:340px;max-width:640px'; document.body.appendChild(b); } b.innerHTML = html; }
async function mxBulkRun(sel, o) { if (MXB.busy) return; MXB.busy = true; MXB.stop = false; MXB.res = []; const N = sel.length;
  const bar = (i, t) => mxbBar(`<b>📦 Moving MAXX societies — ${i + 1} of ${N}</b>${loading(t)}<div class="row" style="justify-content:space-between"><span class="small muted">${MXB.res.filter(r => r.ok).length} done · ${MXB.res.filter(r => !r.ok).length} with problems</span><button class="xs ghost" onclick="MXB.stop=true;toast('Will stop after this society')">■ Stop after this one</button></div>`);
  try { for (let k = 0; k < N; k++) { if (MXB.stop) break; const g = MXB.groups[sel[k]]; bar(k, `${g.name}: creating the society…`);
      try { if (S.sid) { goFirm(); await new Promise(r => setTimeout(r, 400)); }
        const before = new Set(Object.keys(FIRM.list || {})); newSocietyModal(); await new Promise(r => setTimeout(r, 120)); $('ns-name').value = g.name; const fs = (g.ys[0].sd && isYmd(g.ys[0].sd)) ? g.ys[0].sd : fyStartOf(g.ys[0].sd || today()); $('ns-fy').value = fs;
        $$('.ov').pop().querySelector('[data-ok]').click();
        await waitFor(() => S.sid && !before.has(S.sid) && S.fy && ['vch', 'bills', 'heads', 'members'].every(x => S.loaded[x]), 30000); const sid = S.sid;
        bar(k, `${g.name}: importing ${g.ys.length} year(s) from MAXX…`);
        if (g.ys.length === 1) { const p = maxxPlan(g.ys[0].no, { mode: 'open', oi: o.oi, cs: 'mem', meta: o.meta }); p.full = maxxFull(p, g.ys[0].no); p.oiExcl = o.oi === 'excl'; p.yr = o.end === 'next' ? 'prev' : 'cur'; await maxxCommitFull(p); }
        else { const plans = g.ys.map(y => { const p = maxxPlan(y.no, { mode: 'open', oi: o.oi, cs: 'mem', meta: o.meta }); p.full = maxxFull(p, y.no); p.oiExcl = o.oi === 'excl'; p.fs = p.sd && isYmd(p.sd) ? p.sd : fyStartOf(p.full.first); return p; }).sort((a, b) => a.fs.localeCompare(b.fs));
          MXM.plans = plans; MXM.o = { end: o.end, oi: o.oi, meta: o.meta, ob: o.ob }; await mxMultiCommit(); }
        const top = $$('.ov').pop(); const txt = top ? top.innerText.replace(/\s+/g, ' ').slice(0, 400) : ''; const okk = /import complete/i.test(txt); const pn = document.getElementById('mx-panel'); const err = pn && /❌/.test(pn.innerText) ? pn.innerText.replace(/\s+/g, ' ').slice(0, 300) : '';
        MXB.res.push({ name: g.name, sid, ok: okk && !err, note: err || (/difference|differs|mismatch/i.test(txt) ? txt.match(/[^.]*(difference|differs|mismatch)[^.]*/i)[0] : 'checked against MAXX') });
        closeAllModals(); if (pn) pn.remove(); } catch (e) { MXB.res.push({ name: g.name, ok: false, note: e.message }); closeAllModals(); const pn = document.getElementById('mx-panel'); if (pn) pn.remove(); } }
  } finally { MXB.busy = false; const b = $('mxb-bar'); if (b) b.remove(); LS.set('sb_mxbulk', JSON.stringify({ at: Date.now(), res: MXB.res })); goFirm();
    setTimeout(() => openModal({ title: `📦 MAXX move finished — ${MXB.res.filter(r => r.ok).length} of ${MXB.res.length} societies`, wide: true, hideOk: true, cancel: 'Close', body: `<div class="tw"><table><tbody>${MXB.res.map(r => `<tr><td>${r.ok ? '✅' : '⚠️'}</td><td><b>${esc(r.name)}</b></td><td class="small">${esc(r.note || '')}</td><td>${r.sid ? `<button class="xs ghost" onclick="closeModals();openSociety('${r.sid}')">Open</button>` : ''}</td></tr>`).join('')}</tbody></table></div><p class="small muted">Check each society's year-chain and MAXX check result before you stop using MAXX for it.</p>` }), 600); } }

