// v12.3 — SAFETY & COMFORT (asked 8 Nov 2026)
// 81 ↶ Undo for 10 seconds after saving an entry · 82 🗑 recycle bin: deleted entries & members come back within 30 days
// 83 locked / outside-the-year date warned as soon as it is picked · 84 wrong kind of head warned (income in a payment…)
// 86 hover any entry: who entered / changed it and when · 87 flat numbers kept in one form (A-101) · 88 cheque no. / narration checks
// 89 "Saving…" → "Saved ✓" even on slow internet (the change is kept and sent when the line is back)
// 90 two people cannot post the same bank statement at the same time · 91 shorter entry form (cheque boxes only for cheques)
// 92 column sort & widths remembered per screen · 93 ◫ bank book beside the entry form · 94 phonetic मराठी typing (Ctrl+M)
// 95 print settings remembered per report (paper, orientation, margins, text size) · (96 Quick Receipt removed — use Receipt / 🎤)
// 97 "Show me how" guides on the screen for the main jobs · 98 a daily tip about the shortcut that would save YOU the most time
// Data: bcfg/_bin/{k} = { k: 'v'|'m', fy, id, d: record, at, by } (kept 30 days)
// ═══════════════════════════════════════════════════════════════════════
(() => { const st = document.createElement('style'); st.textContent = `
#undo-bar{position:fixed;left:50%;bottom:22px;transform:translateX(-50%);z-index:4600;background:#222;color:#fff;border-radius:10px;padding:9px 14px;display:flex;gap:12px;align-items:center;box-shadow:0 6px 24px rgba(0,0,0,.3);font-size:13.5px}
#undo-bar button{background:#ffd27a;color:#222;border:0;border-radius:6px;padding:4px 12px;font-weight:700;cursor:pointer}#undo-bar .u-t{opacity:.7}
#sv-pill{font-size:11px;padding:2px 8px;border-radius:99px;margin-left:6px}#sv-pill.busy{background:#fff3dc;color:#9a5b00}#sv-pill.ok{background:#e3f6ea;color:#1c7a3e}#sv-pill:empty{display:none}
.vf-w{margin-top:4px}.th-rs{position:absolute;right:0;top:0;bottom:0;width:6px;cursor:col-resize}th{position:relative}th.srt-a::after{content:' ▲';font-size:9px}th.srt-d::after{content:' ▼';font-size:9px}
#side-bb{position:fixed;right:0;top:56px;bottom:0;width:340px;background:var(--card);border-left:1px solid var(--border);z-index:900;overflow:auto;padding:10px 12px;font-size:12px;box-shadow:-4px 0 16px rgba(0,0,0,.08)}
body.has-bb #main{margin-right:340px}.mr-on{outline:2px solid #f0a020!important}
.qr-w{max-width:440px;margin:0 auto}.qr-w input,.qr-w select{font-size:20px;padding:12px}.qr-m{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin:10px 0}.qr-m button{padding:14px 4px;font-size:16px}.qr-m button.on{outline:3px solid var(--accent)}
.qr-sug div{padding:10px;border-bottom:1px solid var(--border);font-size:16px}.qr-save{width:100%;padding:16px;font-size:18px;margin-top:12px}
.hw-hl{outline:3px solid #f0a020!important;outline-offset:2px;border-radius:6px;position:relative;z-index:2}#hw-box{position:fixed;z-index:6000;background:#1d2433;color:#fff;border-radius:10px;padding:12px 14px;max-width:320px;font-size:13px;box-shadow:0 8px 30px rgba(0,0,0,.35)}#hw-box button{margin-top:8px}`; document.head.appendChild(st); })();

// ── 82 recycle bin ──────────────────────────────────────────────────────
const BIN = () => ((S.bcfg || {})._bin) || {};
(() => { const oc = commit; window.commit = commit = async function (up, audit) { try { if (S.sid && up && typeof up === 'object') { const add = {}; const now = Date.now();
    for (const [p, v] of Object.entries(up)) { if (v !== null) continue; let m = p.match(/^vch\/([^/]+)\/([^/]+)$/); if (m && S.vch && m[1] === S.fyId && S.vch[m[2]]) { add[`bcfg/_bin/${FBX.key('b')}`] = { k: 'v', fy: m[1], id: m[2], d: S.vch[m[2]], at: now, by: uname() }; continue; }
      m = p.match(/^members\/([^/]+)$/); if (m && S.members && S.members[m[1]]) add[`bcfg/_bin/${FBX.key('b')}`] = { k: 'm', id: m[1], d: S.members[m[1]], bc: (S.bcfg || {})[m[1]] || null, at: now, by: uname() }; }
    if (Object.keys(add).length) { for (const [k, x] of Object.entries(BIN())) if (x && now - (x.at || 0) > 30 * 864e5) add[`bcfg/_bin/${k}`] = null; up = { ...up, ...add }; } } } catch (e) { } return oc.call(this, up, audit); }; })();
function binModal() { const L = Object.entries(BIN()).filter(([, x]) => x && Date.now() - x.at < 30 * 864e5).sort((a, b) => b[1].at - a[1].at);
  openModal({ title: `🗑 Recycle bin — deleted in the last 30 days (${L.length})`, wide: true, hideOk: true, cancel: 'Close', body: L.length ? `<div class="tw"><table><thead><tr><th>Deleted</th><th>What</th><th>By</th><th></th></tr></thead><tbody>${L.map(([k, x]) => `<tr><td class="small">${fd(new Date(x.at).toISOString().slice(0, 10))}</td><td>${x.k === 'v' ? `🧾 ${esc(x.d.no || '')} · ${fd(x.d.d)} · ₹${fmt(vAmount(x.d))} <span class="small muted">${esc(x.d.nar || '')}${x.fy !== S.fyId ? ' · other year' : ''}</span>` : `👤 ${esc(flatLbl(x.d))} ${esc(x.d.name || '')}`}</td><td class="small">${esc(x.by || '')}</td><td>${canEdit() ? `<button class="xs" onclick="binRestore('${k}')">↺ Restore</button>` : ''}</td></tr>`).join('')}</tbody></table></div>` : '<p class="small muted">Nothing deleted in the last 30 days.</p>' }); }
async function binRestore(k) { guardEdit(); const x = BIN()[k]; if (!x) return; const up = { [`bcfg/_bin/${k}`]: null };
  if (x.k === 'v') { if (x.fy !== S.fyId) return toast(`Switch to FY ${(S.fys[x.fy] || {}).label || ''} first, then restore`, 'warn'); guardDate(x.d.d, 'voucher'); const clash = Object.values(S.vch).find(v => v && v.t === x.d.t && v.no === x.d.no);
    if (clash && !(await confirmBox(`Number ${x.d.no} is used again by a newer entry. Restore it anyway (two entries with the same number)?`))) return; up[`vch/${S.fyId}/${x.id}`] = x.d; await commit(up, { a: 'restore', e: TNAME[x.d.t] || 'voucher', id: x.d.no, s: `Restored from the recycle bin: ${x.d.no} ${fd(x.d.d)} ₹${fmt(vAmount(x.d))}` }); }
  else { up[`members/${x.id}`] = x.d; if (x.bc) up[`bcfg/${x.id}`] = x.bc; await commit(up, { a: 'restore', e: 'Member', s: `Restored from the recycle bin: ${flatLbl(x.d)} ${x.d.name}` }); }
  toast('Restored ✓', 'ok'); closeModals(); binModal(); }
afterDom(() => { if (!/^(daybook|members)$/.test(CUR.id || '') || !S.sid) return; const a = document.querySelector('#main .ph .acts'); if (a && !$('bin-b') && Object.keys(BIN()).length) a.insertAdjacentHTML('beforeend', '<button class="ghost sm" id="bin-b" onclick="binModal()" title="Restore something deleted in the last 30 days">🗑 Recycle bin</button>'); });

// ── 81 undo for 10 seconds ──────────────────────────────────────────────
const UNDO = { t: 0, last: 0, quietTill: 0 };
function undoBar(msg, fn) { let b = $('undo-bar'); if (b) b.remove(); clearInterval(UNDO.t); document.body.insertAdjacentHTML('beforeend', `<div id="undo-bar"><span>${esc(msg)}</span><button id="undo-go">↶ Undo</button><span class="u-t">10</span></div>`); b = $('undo-bar'); let n = 10;
  $('undo-go').onclick = async () => { clearInterval(UNDO.t); b.remove(); try { await fn(); toast('Undone ✓', 'ok'); } catch (e) { toast('Could not undo: ' + e.message, 'err'); } };
  UNDO.t = setInterval(() => { n--; const c = b.querySelector('.u-t'); if (c) c.textContent = n; if (n <= 0) { clearInterval(UNDO.t); b.remove(); } }, 1000); }
(() => { const os = saveVoucher; window.saveVoucher = saveVoucher = async function (v, opt = {}) { const old = opt && opt.editId && S.vch[opt.editId] ? JSON.parse(JSON.stringify(S.vch[opt.editId])) : null; const r = await os.apply(this, arguments);
  // many entries saved one after another (bulk receipts, imports): no undo bar — it could undo only the last one
  const now = Date.now(); const burst = now - UNDO.last < 2500; UNDO.last = now; if (burst) { UNDO.quietTill = now + 4000; const b = $('undo-bar'); if (b) { clearInterval(UNDO.t); b.remove(); } }
  try { if (r && r.vid && !burst && now > UNDO.quietTill && !/^(bulk|bulkexp|bstmt)$/.test(CUR.id || '') && document.visibilityState !== 'hidden' && !document.querySelector('#bsp-b, #mx-panel, #mxb-bar')) { const vid = r.vid, fy = S.fyId; const nv = S.vch[vid] || v;
      undoBar(old ? `${old.no} changed` : `${(nv && nv.no) || 'Entry'} saved · ₹${fmt(vAmount(nv || v))}`, async () => { if (S.fyId !== fy) throw new Error('the year was switched'); if (old) await commit({ [`vch/${fy}/${vid}`]: old }, { a: 'edit', e: TNAME[old.t] || 'voucher', id: old.no, s: `Change undone: ${old.no}` });
        else await commit({ [`vch/${fy}/${vid}`]: null }, { a: 'delete', e: TNAME[(nv || v).t] || 'voucher', id: (nv || {}).no, s: `Undone straight after saving: ${(nv || {}).no || ''} ₹${fmt(vAmount(nv || v))}` }); if (/^(receipt|payment|contra|journal)$/.test(CUR.id)) go(CUR.id); }); } } catch (e) { } return r; }; })();

// ── 83 / 84 / 88 warnings while typing ──────────────────────────────────
function vfWarn2() { const f = $('vf'); if (!f) return; let w = $('vf-w'); const out = []; const d = val('vf-d'); const t = VF.t;
  if (d && S.fy && (d < S.fy.start || d > S.fy.end)) out.push(`⛔ ${fd(d)} is outside FY ${esc(S.fy.label)} (${fd(S.fy.start)} – ${fd(S.fy.end)})`);
  else if (d && S.fy && S.fy.lock && d <= S.fy.lock) out.push(`🔒 The books are locked up to ${fd(S.fy.lock)} — this date cannot be saved`);
  else if (d && d > today()) out.push(`📅 ${fd(d)} is in the future`);
  const acc = val('vf-acc'); const h = acc && !acc.startsWith('M:') ? S.heads[acc] : null;
  if (h && t === 'P' && h.grp === 'Income') out.push(`⚠ “${esc(h.name)}” is an income head — a payment usually goes to an expense, a vendor or a liability`);
  if (h && t === 'R' && h.grp === 'Expenses') out.push(`⚠ “${esc(h.name)}” is an expense head — is this a refund? A receipt usually comes from a member or an income head`);
  if (h && (t === 'R' || t === 'P') && (h.type === 'cash' || h.type === 'bank')) out.push('⚠ Cash ↔ bank is a Contra entry, not a receipt or payment');
  if (!out.length) { if (w) w.remove(); return; } if (!w) { const di = $('vf-d'); (di ? di.parentElement : f).insertAdjacentHTML('beforeend', '<div id="vf-w" class="alert a-warn small vf-w"></div>'); w = $('vf-w'); } w.innerHTML = out.join('<br>'); }
document.addEventListener('change', e => { if (e.target && /^vf-(d|acc|cb)$/.test(e.target.id)) vfWarn2(); }, true);
document.addEventListener('input', e => { if (e.target && e.target.id === 'vf-d') vfWarn2(); }, true);
(() => { const oc = vfAccChanged; window.vfAccChanged = vfAccChanged = function () { const r = oc.apply(this, arguments); try { vfWarn2(); } catch (e) { } return r; }; })();
// 88 before saving a receipt / payment: cheque no. for cheques, a narration that says something
(() => { const os = vfSave; window.vfSave = vfSave = async function (t) { try { const tt = t || VF.t; if (/^[RP]$/.test(tt) && !VFX.chkOk) { const mode = val('vf-mode'); const p = [];
    if (/cheque|dd/i.test(mode) && !val('vf-chq').trim()) p.push('the cheque number is empty');
    const nar = (val('vf-nar') || '').trim(); if (nar && nar.length < 4) p.push('the narration is very short');
    if (p.length) { const ok = await confirmBox(`Before saving: ${p.join(' and ')}.\n\nSave anyway?`, { ok: 'Save anyway' }); if (!ok) return; VFX.chkOk = true; try { return await os.apply(this, arguments); } finally { VFX.chkOk = false; } } } } catch (e) { } return os.apply(this, arguments); }; })();

// ── 86 who entered / changed it ─────────────────────────────────────────
function whoTxt(vid) { const v = S.vch[vid]; if (!v) return ''; const by = v.by || v.cb || v.n || ''; const at = v.at ? new Date(v.at) : null; const ch = v.ub && v.ua && (!v.at || v.ua - v.at > 5000) ? `\nChanged by ${v.ub} on ${new Date(v.ua).toLocaleString('en-IN', { dateStyle: 'medium', timeStyle: 'short' })}` : '';
  return `${v.no} · entered${by ? ' by ' + by : ''}${at ? ' on ' + at.toLocaleString('en-IN', { dateStyle: 'medium', timeStyle: 'short' }) : ''}${ch}`; }
// worked out only when the mouse is over a row (no cost for long lists)
document.addEventListener('mouseover', e => { if (!S.sid || !e.target.closest) return; const tr = e.target.closest('#main tr'); if (!tr || tr.dataset.who) return; tr.dataset.who = '1'; const el = tr.matches('[onclick]') ? tr : tr.querySelector('[onclick*="openVch("], [onclick*="openLine(\'v\'"]'); const a = el && el.getAttribute('onclick') || ''; const m = a.match(/openVch\('([^']+)'\)/) || a.match(/openLine\('v',\s*'([^']+)'\)/); if (!m) return; const t = whoTxt(m[1]); if (t && !/entered/.test(tr.title || '')) tr.title = tr.title ? tr.title + '\n' + t : t; }, true);

// ── 87 flat numbers in one form ─────────────────────────────────────────
function flatNorm(w, f) { let wing = String(w || '').trim().toUpperCase(), flat = String(f || '').trim().toUpperCase().replace(/\s+/g, '');
  const m = flat.match(/^([A-Z]{1,2})[-/]?(\d{1,4}[A-Z]?)$/); if (m && (!wing || wing === m[1])) { wing = m[1]; flat = m[2]; }
  const m2 = flat.match(/^(\d{1,4})[-/]?([A-Z])$/); if (m2 && !wing) { wing = m2[2]; flat = m2[1]; } return { wing, flat }; }
document.addEventListener('focusout', e => { const t = e.target; if (!t || !/^mm-(f|w)$/.test(t.id)) return; const w = $('mm-w'), f = $('mm-f'); if (!w || !f) return; const n = flatNorm(w.value, f.value); if (n.flat !== f.value || n.wing !== w.value.trim().toUpperCase()) { f.value = n.flat; if (w.tagName === 'SELECT') { if ([...w.options].some(o => o.value === n.wing)) w.value = n.wing; } else w.value = n.wing; toast(`Flat number written as ${n.wing ? n.wing + '-' : ''}${n.flat}`, 'ok', 2500); } }, true);
function flatFixList() { return Object.entries(S.members).filter(([, m]) => m).map(([id, m]) => ({ id, m, n: flatNorm(m.wing, m.flat) })).filter(x => x.n.flat !== String(x.m.flat || '') || x.n.wing !== String(x.m.wing || '').trim().toUpperCase()); }
function flatFixModal() { const L = flatFixList(); openModal({ title: `🏷 Flat numbers in one form (${L.length})`, wide: true, ok: L.length && canEdit() ? `Fix ${L.length}` : '', hideOk: !L.length || !canEdit(), body: L.length ? `<p class="small">Wing and flat are kept in separate boxes and in capitals, so A-101, A101 and a 101 are the same flat everywhere (search, imports, bank matching).</p><div class="tw"><table><tbody>${L.map(x => `<tr><td>${esc(x.m.wing || '')} / ${esc(x.m.flat || '')}</td><td>→</td><td><b>${esc(x.n.wing || '—')} / ${esc(x.n.flat)}</b></td><td>${esc(x.m.name || '')}</td></tr>`).join('')}</tbody></table></div>` : '<p>✅ All flat numbers are already in one form.</p>',
  onOk: async () => { const up = {}; L.forEach(x => { up[`members/${x.id}/flat`] = x.n.flat; up[`members/${x.id}/wing`] = x.n.wing || null; }); await commit(up, { a: 'edit', e: 'Members', s: `${L.length} flat number(s) written in one form` }); toast('Done ✓'); } }); }
afterDom(() => { if (CUR.id !== 'members' || !S.sid) return; const a = document.querySelector('#main .ph .acts'); if (a && !$('ff-b') && flatFixList().length) a.insertAdjacentHTML('beforeend', `<button class="ghost sm warn" id="ff-b" onclick="flatFixModal()">🏷 ${flatFixList().length} flat no(s). to tidy</button>`); });

// ── 89 Saving… → Saved ✓ ────────────────────────────────────────────────
const SAVE = { n: 0, t: 0 };
function svPill() { let p = $('sv-pill'); const c = $('tbConn'); if (!p && c) { c.insertAdjacentHTML('afterend', '<span id="sv-pill"></span>'); p = $('sv-pill'); } return p; }
(() => { const oc = commit; window.commit = commit = function () { SAVE.n++; const p = svPill(); clearTimeout(SAVE.t); const slow = setTimeout(() => { const q = svPill(); if (q && SAVE.n) { q.className = 'busy'; q.textContent = S.online === false ? `⏳ ${SAVE.n} change(s) kept — will be sent when the internet is back` : '⏳ Saving…'; } }, 700);
  const pr = Promise.resolve().then(() => oc.apply(this, arguments)); pr.then(() => { SAVE.n = Math.max(0, SAVE.n - 1); clearTimeout(slow); const q = svPill(); if (q && !SAVE.n) { q.className = 'ok'; q.textContent = '✓ Saved'; SAVE.t = setTimeout(() => { q.textContent = ''; }, 2500); } }, () => { SAVE.n = Math.max(0, SAVE.n - 1); clearTimeout(slow); const q = svPill(); if (q) q.textContent = ''; }); return pr; }; })();
window.addEventListener('beforeunload', e => { if (SAVE.n > 0) { e.preventDefault(); e.returnValue = 'Some changes are still being saved'; return e.returnValue; } });

// ── 90 one bank statement import at a time ─────────────────────────────
(() => { const op = bsPost; window.bsPost = bsPost = async function (P) { const args = arguments; const bank = (P && P.bank) || 'bank'; try { return await withLock('bstmt_' + bank, () => op.apply(this, args)); } catch (e) { if (/lock|busy|another|someone/i.test(e.message || '')) { toast(`Someone else is posting a statement for ${H(bank).name} right now — wait until they finish (entries already posted are skipped anyway)`, 'warn', 9000); return; } throw e; } }; })();

// ── 91 shorter entry form ───────────────────────────────────────────────
function vfShort() { const md = $('vf-mode'); const chq = $('vf-chq'); if (!md || !chq) return; const row = chq.closest('.fr'); if (!row) return; const m = md.value || ''; const isChq = /cheque|dd|draft/i.test(m); const isRef = /upi|neft|rtgs|imps|online|nach|card/i.test(m);
  const cd = $('vf-chqd'), cb = $('vf-chqb'); row.style.display = isChq || isRef || chq.value ? '' : 'none'; if (cd) cd.parentElement.style.display = isChq || (cd.value) ? '' : 'none'; if (cb) cb.parentElement.style.display = isChq || (cb.value) ? '' : 'none';
  const l = chq.previousElementSibling; if (l && l.tagName === 'LABEL') l.textContent = isChq ? 'Cheque No.' : isRef ? 'UTR / reference no.' : 'Cheque / UTR No.'; }
document.addEventListener('change', e => { if (e.target && e.target.id === 'vf-mode') vfShort(); }, true);
afterDom(() => { if ($('vf') && !$('vf').dataset.short) { $('vf').dataset.short = '1'; vfShort(); } });

// ── 92 sort & widths remembered ─────────────────────────────────────────
const TBK = () => 'sb_tb_' + (CUR.id || 'x'); const tbPref = () => { try { return JSON.parse(LS.get(TBK(), '{}')) || {}; } catch (e) { return {}; } };
function tbSort(th, dirForce) { const t = th.closest('table'); const tb = t.tBodies[0]; if (!tb) return; try { prAll(t); } catch (e) { } const i = [...th.parentElement.children].indexOf(th); const dir = dirForce || (th.classList.contains('srt-a') ? 'd' : 'a');
  const rows = [...tb.rows].filter(r => !r.classList.contains('tot') && !r.classList.contains('pr-tail')); const tots = [...tb.rows].filter(r => r.classList.contains('tot'));
  const key = r => { const c = r.cells[i]; const s = c ? c.innerText.trim() : ''; const n = s.replace(/[₹,\s]/g, '').replace(/(Dr|Cr)$/i, ''); if (/^-?\d+(\.\d+)?$/.test(n)) return [0, +n * (/Cr$/i.test(s) ? -1 : 1)]; const d = s.match(/^(\d{2})-(\d{2})-(\d{4})$/); if (d) return [0, +(d[3] + d[2] + d[1])]; return [1, s.toLowerCase()]; };
  rows.sort((a, b) => { const x = key(a), y = key(b); const r = x[0] - y[0] || (x[1] < y[1] ? -1 : x[1] > y[1] ? 1 : 0); return dir === 'a' ? r : -r; }); rows.concat(tots).forEach(r => tb.appendChild(r));
  th.parentElement.querySelectorAll('th').forEach(x => x.classList.remove('srt-a', 'srt-d')); th.classList.add('srt-' + dir); const p = tbPref(); p.s = [i, dir]; LS.set(TBK(), JSON.stringify(p)); }
afterDom(() => { if (!S.sid) return; const t = document.querySelector('#main .pc table'); if (!t || !t.tHead || t.dataset.tb || !t.tBodies[0] || t.tBodies[0].rows.length < 3 || t.closest('.ent')) return; if (t.classList.contains('ent') || t.querySelector('tbody input')) return; t.dataset.tb = '1'; const p = tbPref(); const ths = [...t.tHead.rows[t.tHead.rows.length - 1].cells];
  ths.forEach((th, i) => { if (th.querySelector('input,button') || th.onclick) return; th.style.cursor = 'pointer'; th.title = (th.title ? th.title + ' · ' : '') + 'Click to sort · drag the edge to widen'; th.addEventListener('click', e => { if (e.target.classList.contains('th-rs')) return; tbSort(th); });
    const h = document.createElement('span'); h.className = 'th-rs'; th.appendChild(h); h.addEventListener('mousedown', e => { e.preventDefault(); e.stopPropagation(); const x0 = e.clientX, w0 = th.offsetWidth; const mv = ev => { th.style.width = th.style.minWidth = Math.max(40, w0 + ev.clientX - x0) + 'px'; }; const up = () => { document.removeEventListener('mousemove', mv); document.removeEventListener('mouseup', up); const q = tbPref(); q.w = q.w || {}; q.w[i] = th.offsetWidth; LS.set(TBK(), JSON.stringify(q)); }; document.addEventListener('mousemove', mv); document.addEventListener('mouseup', up); });
    if (p.w && p.w[i]) th.style.width = th.style.minWidth = p.w[i] + 'px'; });
  if (p.s && ths[p.s[0]]) tbSort(ths[p.s[0]], p.s[1]); });

// ── 93 bank book beside the entry form ─────────────────────────────────
const BBK = { on: LS.get('sb_bb', '0') === '1' };
function bbRender() { const el = $('side-bb'); if (!el) return; const cb = val('vf-cb'); const h = S.heads[cb]; const X = '<button class="xs ghost" id="bb-x" onclick="bbToggle()" title="Close the bank book">✕</button>'; let html;
  if (!h) html = `<div class="row" style="justify-content:space-between"><b>◫ Bank book</b>${X}</div><p class="small muted">Choose the cash / bank account in the form.</p>`;
  else { let st = null; try { st = statement(cb, S.fy.start, S.fy.end); } catch (e) { } const rows = ((st && st.rows) || []).slice(-60).reverse();
    html = `<div class="row" style="justify-content:space-between"><b>${esc(h.name)}</b>${X}</div><div class="small muted" style="margin-bottom:6px">Latest entries — balance ₹${fmt(rows.length ? (rows[0].bal != null ? rows[0].bal : rows[0].b) : 0)}</div><table class="small" style="width:100%"><tbody>${rows.map(r => `<tr class="clk" ${r.id ? `onclick="openVch('${r.id}')"` : ''}><td style="white-space:nowrap">${fd(r.d)}</td><td>${esc(String(r.part || r.nar || r.p || '').slice(0, 34))}</td><td class="n">${r.dr ? fmt(r.dr) : ''}</td><td class="n">${r.cr ? '−' + fmt(r.cr) : ''}</td></tr>`).join('')}</tbody></table>`; }
  if (el._h === html) return; /* v12.8: redraw only when something changed — redrawing on every page change replaced the ✕ before a click could land */ el._h = html; el.innerHTML = html; }
function bbToggle() { BBK.on = !BBK.on; LS.set('sb_bb', BBK.on ? '1' : '0'); bbSync(); }
function bbSync() { const want = BBK.on && $('vf') && /^(receipt|payment|contra)$/.test(CUR.id) && innerWidth > 1100; let el = $('side-bb'); document.body.classList.toggle('has-bb', !!want); if (!want) { if (el) el.remove(); return; } if (!el) { document.body.insertAdjacentHTML('beforeend', '<div id="side-bb"></div>'); } bbRender(); }
afterDom(() => { const a = document.querySelector('#main .ph .acts'); if ($('vf') && a && !$('bb-b') && innerWidth > 1100) a.insertAdjacentHTML('beforeend', '<button class="ghost sm" id="bb-b" onclick="bbToggle()" title="Show the cash / bank book beside the form">◫ Bank book</button>'); bbSync(); });
document.addEventListener('click', e => { if (e.target && e.target.closest && e.target.closest('#ap_vf-cb .ap-o')) setTimeout(bbRender, 40); }, true);

// ── 94 phonetic मराठी typing ────────────────────────────────────────────
const MRV = [['aa', 'आ', 'ा'], ['ai', 'ऐ', 'ै'], ['au', 'औ', 'ौ'], ['ee', 'ई', 'ी'], ['ii', 'ई', 'ी'], ['oo', 'ऊ', 'ू'], ['uu', 'ऊ', 'ू'], ['ru', 'ऋ', 'ृ'], ['A', 'आ', 'ा'], ['I', 'ई', 'ी'], ['U', 'ऊ', 'ू'], ['a', 'अ', ''], ['i', 'इ', 'ि'], ['u', 'उ', 'ु'], ['e', 'ए', 'े'], ['o', 'ओ', 'ो']];
const MRC = [['ksh', 'क्ष'], ['dny', 'ज्ञ'], ['chh', 'छ'], ['kh', 'ख'], ['gh', 'घ'], ['ch', 'च'], ['jh', 'झ'], ['Th', 'ठ'], ['Dh', 'ढ'], ['th', 'थ'], ['dh', 'ध'], ['ph', 'फ'], ['bh', 'भ'], ['sh', 'श'], ['Sh', 'ष'], ['k', 'क'], ['g', 'ग'], ['c', 'च'], ['j', 'ज'], ['z', 'ज'], ['T', 'ट'], ['D', 'ड'], ['N', 'ण'], ['t', 'त'], ['d', 'द'], ['n', 'न'], ['p', 'प'], ['f', 'फ'], ['b', 'ब'], ['m', 'म'], ['y', 'य'], ['r', 'र'], ['l', 'ल'], ['L', 'ळ'], ['v', 'व'], ['w', 'व'], ['s', 'स'], ['h', 'ह'], ['x', 'क्स'], ['q', 'क']];
function mrWord(w) { let o = '', i = 0; const vow = (s, at) => MRV.find(([k]) => s.startsWith(k, at)); const con = (s, at) => MRC.find(([k]) => s.startsWith(k, at)); let prevC = false;
  while (i < w.length) { if (w[i] === 'M') { o += 'ं'; i++; prevC = false; continue; } if (w[i] === 'H') { o += 'ः'; i++; prevC = false; continue; }
    const c = con(w, i); if (c) { const nx = c[0].length + i; if ((c[0] === 'n' || c[0] === 'm') && !prevC && i > 0 && nx < w.length && !vow(w, nx) && con(w, nx) && !/^[yhr]/.test(w.slice(nx))) { o += 'ं'; i = nx; continue; } // Marathi writes शिंदे, बंगला: n / m before another consonant = anusvara
      if (prevC) o += '्'; o += c[1]; i += c[0].length; prevC = true; const v = vow(w, i); if (v) { o += v[2]; i += v[0].length; prevC = false; } continue; }
    const v = vow(w, i); if (v) { o += v[1]; i += v[0].length; prevC = false; continue; } o += w[i]; i++; prevC = false; }
  return o; }
const MRT = { on: false }; const mrBox = el => el && (el.tagName === 'TEXTAREA' || (el.tagName === 'INPUT' && (!el.type || el.type === 'text' || el.type === 'search'))) && /nar|name|-n$|nm|desc|note|rem|addr|mr/i.test(el.id + ' ' + (el.className || '') + ' ' + (el.placeholder || ''));
document.addEventListener('keydown', e => { if ((e.ctrlKey || e.metaKey) && !e.shiftKey && e.key.toLowerCase() === 'm' && mrBox(e.target)) { e.preventDefault(); MRT.on = !MRT.on; $$('.mr-on').forEach(x => x.classList.remove('mr-on')); if (MRT.on) e.target.classList.add('mr-on'); toast(MRT.on ? 'मराठी typing ON — type in English letters (e.g. ramesh paaTeel), it becomes मराठी after each word. Ctrl+M to stop.' : 'मराठी typing off', 'ok', 4000); } }, true);
document.addEventListener('keyup', e => { if (!MRT.on || !mrBox(e.target) || !/^[ ,.;:\-\/)\n]$|^Enter$/.test(e.key === 'Enter' ? 'Enter' : e.key)) return; const el = e.target; const pos = el.selectionStart; const before = el.value.slice(0, pos); const m = before.match(/([A-Za-z]+)([ ,.;:\-\/)\n]?)$/); if (!m) return;
  const rep = mrWord(m[1]) + m[2]; el.value = before.slice(0, before.length - m[0].length) + rep + el.value.slice(pos); const np = pos - m[0].length + rep.length; el.setSelectionRange(np, np); el.dispatchEvent(new Event('input', { bubbles: true })); }, true);
document.addEventListener('focusin', e => { if (MRT.on && mrBox(e.target)) { $$('.mr-on').forEach(x => x.classList.remove('mr-on')); e.target.classList.add('mr-on'); } }, true);

// ── 95 print settings per report ───────────────────────────────────────
const PSK = t => 'sb_ps_' + String(t || CUR.id || 'x').replace(/\W+/g, '_').slice(0, 40);
const psGet = t => { try { return JSON.parse(LS.get(PSK(t), '{}')) || {}; } catch (e) { return {}; } };
(() => { const op = printDoc; window.printDoc = printDoc = function (title, html, o) { const p = psGet(CUR.id); if (p.size || p.orient || p.m || p.fs) { const css = `<style>@page{size:${p.size || 'A4'} ${p.orient || 'portrait'};margin:${p.m != null ? p.m : 12}mm}${p.fs ? `body,.doc{font-size:${p.fs}px!important}td,th{font-size:${Math.max(8, p.fs - 1)}px!important}` : ''}</style>`; html = css + html; } return op.call(this, title, html, o); }; })();
function psModal() { const p = psGet(CUR.id); const nm = ((document.querySelector('#main .ph h1') || {}).innerText || CUR.id).replace(/[☆★]/g, '').trim();
  openModal({ title: `⚙ Print settings — ${esc(nm)}`, ok: 'Save for this report', body: `<div data-form class="grid g2"><div><label>Paper</label><select id="ps-s">${['A4', 'Legal', 'Letter', 'A5'].map(x => `<option ${p.size === x ? 'selected' : ''}>${x}</option>`).join('')}</select></div><div><label>Orientation</label><select id="ps-o"><option value="portrait">Portrait</option><option value="landscape" ${p.orient === 'landscape' ? 'selected' : ''}>Landscape (wide reports)</option></select></div><div><label>Margins (mm)</label><input id="ps-m" type="number" min="3" max="30" value="${p.m != null ? p.m : 12}"></div><div><label>Text size (px)</label><input id="ps-f" type="number" min="8" max="16" placeholder="normal" value="${p.fs || ''}"></div></div><p class="small muted">Saved on this computer for this report only. Choosing the printer stays with the browser's print window.</p>`,
    onOk: () => { LS.set(PSK(CUR.id), JSON.stringify({ size: val('ps-s'), orient: val('ps-o'), m: +val('ps-m') || 12, fs: +val('ps-f') || 0 })); toast('Print settings saved for this report'); } }); }
(() => { const om = xpMenu; window.xpMenu = xpMenu = function (btn) { const r = om.apply(this, arguments); const m = $('xp-m'); if (m) m.insertAdjacentHTML('beforeend', `<div onclick="$('xp-m').remove();psModal()">⚙ Print settings for this report</div>`); return r; }; })();

