// ── ✏ Edit a recorded flat transfer (date / MC resolution) ────────────────
// A transfer saves: members/{mid}/hist/{k} (seller snapshot, to = transfer date), the buyer's admission date (since),
// share-register transfer lines (shr/{sid}/tr/{t}) and maybe a transfer-charges bill. Changing the date keeps all of these in step.
function tfEditModal(mid, k) { if (!canEdit()) return toast('Only the admin or accountant can change transfers', 'warn'); const m = M(mid); const h = ((m || {}).hist || {})[k]; if (!m || !h) return toast('Transfer not found', 'warn');
  const H_ = HIST(mid); const i = H_.findIndex(([kk]) => kk === k); const prev = i > 0 ? H_[i - 1][1].to : (h.since || ''); const next = i < H_.length - 1 ? H_[i + 1][1].to : '';
  const bill = Object.entries(S.bills || {}).find(([, b]) => b && b.mid === mid && b.supp && b.d === h.to && /^Transfer of flat/i.test(b.desc || ''));
  openModal({ title: `✏ Edit transfer — ${esc(flatLbl(m))}`, ok: 'Save', body: `<div data-form><p class="small" style="margin-top:0"><b>${esc(h.name)}${h.name2 ? ' & ' + esc(h.name2) : ''}</b> → <b>${esc(h.buyer || '')}</b></p>
    <div class="fr c2"><div><label>Date of transfer *</label><input type="date" id="te-d" value="${esc(h.to)}" ${prev ? `min="${ENG.addDays(prev, 1)}"` : ''} ${next ? `max="${ENG.addDays(next, -1)}"` : ''}></div><div><label>MC resolution no. / date</label><input id="te-mc" value="${esc(h.mc || '')}"></div></div>
    <p class="small muted">Changing the date also moves: the buyer's admission date (if it was the transfer date), the share-register transfer entry, and which name prints on bills, receipts and ledgers (old owner before the date, new owner from it). Amounts do not change.${prev || next ? ` The date must be ${prev ? 'after ' + fd(prev) : ''}${prev && next ? ' and ' : ''}${next ? 'before ' + fd(next) + ' (next transfer)' : ''}.` : ''}</p>
    ${bill ? `<div class="alert a-info small" style="margin:0">The transfer charges bill <b>${esc(bill[1].no)}</b> is dated ${fd(bill[1].d)}. It keeps its date — <a href="#" onclick="closeModals();openBill('${bill[0]}');return false">open the bill</a> to change it too.</div>` : ''}</div>`,
    onOk: () => tfEditSave(mid, k) }); }
async function tfEditSave(mid, k) { guardEdit(); const m = M(mid); const h = ((m || {}).hist || {})[k]; if (!h) throw new Error('Transfer not found'); const d = val('te-d'), mc = val('te-mc').trim();
  if (!isYmd(d)) throw new Error('Enter the date of transfer');
  const H_ = HIST(mid); const i = H_.findIndex(([kk]) => kk === k); const prev = i > 0 ? H_[i - 1][1].to : ''; const next = i < H_.length - 1 ? H_[i + 1][1] : null;
  if (prev && d <= prev) throw new Error(`The date must be after the earlier transfer (${fd(prev)})`); if (h.since && d <= h.since && !prev) throw new Error(`The date must be after the seller's admission date (${fd(h.since)})`);
  if (next && d >= next.to) throw new Error(`The date must be before the next transfer (${fd(next.to)})`);
  const old = h.to; if (d === old && mc === (h.mc || '')) return true; const up = { [`members/${mid}/hist/${k}/to`]: d, [`members/${mid}/hist/${k}/mc`]: mc || null };
  if (d !== old) {
    if (next) { if (next.since === old) up[`members/${mid}/hist/${H_[i + 1][0]}/since`] = d; } else if (m.since === old) up[`members/${mid}/since`] = d;
    const seller = h.name + (h.name2 ? ' & ' + h.name2 : '');
    for (const [sid, x] of Object.entries(S.shr || {})) if (x && x.mid === mid && x.tr) for (const [tk, t] of Object.entries(x.tr)) if (t && t.d === old && String(t.from || '') === seller) up[`shr/${sid}/tr/${tk}/d`] = d;
  }
  await commit(up, { a: 'edit', e: 'Flat transfer', id: flatLbl(m), s: `${flatLbl(m)}: transfer ${h.name} → ${h.buyer || ''}${d !== old ? ` date ${fd(old)} → ${fd(d)}` : ''}${mc !== (h.mc || '') ? ' · MC resolution updated' : ''}` });
  toast(d !== old ? `Transfer date changed to ${fd(d)} ✓` : 'Saved ✓'); setTimeout(() => { if (CUR.id === 'transfers') render(); }, 150); return true; }
// ✏ button on the Flat Transfers list and in 🕘 Owner history
afterDom(() => { if (CUR.id !== 'transfers' || !canEdit()) return; const m = $('main'); if (!m || m.querySelector('.te-b')) return;
  m.querySelectorAll('tbody tr').forEach(tr => { const b = tr.querySelector('button[onclick^="ownerHist("]'); if (!b) return; const mid = (b.getAttribute('onclick').match(/'([^']+)'/) || [])[1]; const dt = tr.cells[0].innerText.trim();
    const e = HIST(mid).find(([, h]) => fd(h.to) === dt && tr.cells[3] && String(h.buyer || '') === tr.cells[3].innerText.trim()); if (e) b.insertAdjacentHTML('beforebegin', `<button class="xs ghost te-b" onclick="tfEditModal('${mid}','${e[0]}')">✏ Edit</button> `); }); });
