  const skip = id => V13_GONE.includes(id) || V13_TABONLY.has(id); const used = new Set();
  const sec = V13_SEC.map(([s, ids]) => [s, ids.filter(id => all.has(id) && !skip(id) && !used.has(id)).map(id => { used.add(id); return [id, ico(id), lbl(id)]; })]);
  const rest = [...all.keys()].filter(id => !used.has(id) && !skip(id)); sec[sec.length - 1][1].push(...rest.map(id => [id, ico(id), lbl(id)]));
