// 84 help in Marathi — ❓ on every page has an English / मराठी switch
const PG_HELP_MR = { dash: 'मुख्य पान: रोजच्या कामाची बटणे, आजचा सारांश आणि सूचना.', receipt: 'मिळालेली रक्कम नोंदवा — सभासद निवडा (किंवा फ्लॅट नंबर टाइप करा), रक्कम आपोआप भरली जाते. Enter दाबल्यावर पुढच्या बॉक्सवर जाते आणि शेवटी सेव्ह होते.', payment: 'दिलेली रक्कम नोंदवा — खर्चाचा हेड, रक्कम, पद्धत आणि चेक नंबर निवडा. F8 ने तयार नॅरेशन मिळते.', contra: 'कॅश आणि बँक मधील रक्कम हलवा (कॅश भरणा, कॅश काढणे, एका बँकेतून दुसऱ्या बँकेत).', journal: 'कॅश किंवा बँक नसलेल्या दुरुस्त्या — उदा. व्याज माफ करणे, हेड बदलणे, वर्षअखेरीच्या नोंदी.', bulk: 'अनेक सभासदांच्या पावत्या एकाच वेळी — थकबाकी आपोआप भरली जाते.', bulkexp: 'अनेक पेमेंट एकाच वेळी नोंदवा.', daybook: 'सर्व नोंदी तारखेनुसार. नोंद उघडण्यासाठी त्यावर क्लिक करा; फिल्टर वापरून शोधा.', bills: 'एका कालावधीची मेंटेनन्स बिले तयार करा, प्रिंट करा, पाठवा आणि प्रत्येक बिल पहा.', bsetup: 'प्रत्येक फ्लॅटचे प्रत्येक कालावधीचे चार्जेस (हेडनुसार). बिले यावरून तयार होतात.', mledger: 'एका सभासदाचे खाते: बिले, पावत्या, व्याज आणि चालू शिल्लक.', dues: 'कोणाकडे किती आणि किती दिवसांपासून थकबाकी आहे. येथून स्मरणपत्रे प्रिंट करा किंवा WhatsApp पाठवा.', gl: 'कोणत्याही हेडचे लेजर, चालू शिल्लकेसह.', tb: 'ट्रायल बॅलन्स — प्रत्येक हेडची एकूण रक्कम; डेबिट आणि क्रेडिट समान असले पाहिजेत.', ie: 'उत्पन्न व खर्च पत्रक — वर्षाचे उत्पन्न वजा खर्च.', bs: 'बॅलन्स शीट — एका तारखेला संस्थेची मालमत्ता आणि देणी.', members: 'फ्लॅट आणि सभासद: नावे, संपर्क, क्षेत्रफळ, पार्किंग, नॉमिनी. नवीन जोडा, बदला, Excel मधून आयात करा.', heads: 'खाते हेडची (लेजर) यादी आणि त्यांचे गट.', bstmt: 'बँक स्टेटमेंट अपलोड करा — नोंदी तुमच्यासाठी तयार होतात; आधीच पुस्तकात असलेल्या नोंदी वगळल्या जातात.', recon: 'बँकेने क्लिअर केलेल्या नोंदींवर टिक करा आणि बँक रिकन्सिलिएशन स्टेटमेंट (BRS) मिळवा.', settings: 'संस्थेची सेटिंग्ज: बिलिंग, व्याज, प्रिंटिंग, टेम्प्लेट्स, ईमेल आणि डिस्प्ले.', team: 'ही संस्था कोण उघडू शकते आणि काय करू शकते (ॲडमिन, अकाउंटंट, कमिटी, व्ह्यूअर, सिक्युरिटी).', year: 'वर्ष बंद करा, महिने लॉक करा, शिल्लक पुढे न्या.', notices: 'नोटीस आणि पत्रे लिहा, प्रिंट करा किंवा ॲपवर सभासदांना पाठवा.', meetings: 'सभेचा अजेंडा आणि इतिवृत्त.', mreqs: 'ॲपवरून सभासदांच्या विनंत्या (पेमेंट, बदल, NOC, बुकिंग) आणि ॲपवर नवीन सभासद.', cmte: 'कमिटी सदस्यांसाठी — मंजुरी, थकबाकीचा आढावा आणि मुख्य अहवाल.', coll: 'वसुली सारांश — बिल केलेले, मिळालेले आणि बाकी.', health: 'पुस्तकातील नेहमीच्या चुका तपासते आणि त्या कशा दुरुस्त करायच्या ते सांगते.', audit: 'कोणी, काय आणि केव्हा बदलले.', data: 'बॅकअप, रिस्टोअर, एक्सपोर्ट आणि इम्पोर्ट.', statreg: 'आय, जे, शेअर आणि नॉमिनेशन रजिस्टर — फ्लॅटनुसार सभासद, शेअर्स आणि नॉमिनी.', transfers: 'फ्लॅट हस्तांतरणाच्या नोंदी — जुना सभासद, नवीन सभासद, तारीख आणि ठराव.', cashbook: 'कॅश बुक — कॅशच्या सर्व नोंदी आणि शिल्लक.', bankbook: 'बँक बुक — बँकेच्या सर्व नोंदी आणि शिल्लक.', books: 'संपूर्ण हिशोब पुस्तके एका क्लिकमध्ये — PDF आणि Excel.', rp: 'जमा-खर्च पत्रक — वर्षात मिळालेली आणि दिलेली रक्कम.' };
(() => { const ep = explainPage; window.explainPage = explainPage = function () { const r = ep.apply(this, arguments); try { const id = CUR.id; const mr = PG_HELP_MR[id]; const md = $$('.ov').pop(); const p = md && md.querySelector('.md-b p, .body p, p'); if (mr && p && !md.querySelector('#v13-lang')) { const en = p.textContent; const pref = LS.get('sb_help_lang', 'en');
  p.insertAdjacentHTML('beforebegin', `<div id="v13-lang" class="row" style="gap:4px;margin-bottom:6px"><button class="xs ${pref === 'en' ? '' : 'ghost'}" data-l="en">English</button><button class="xs ${pref === 'mr' ? '' : 'ghost'}" data-l="mr">मराठी</button></div>`);
  const set = l => { p.textContent = l === 'mr' ? mr : en; md.querySelectorAll('#v13-lang button').forEach(b => b.className = 'xs ' + (b.dataset.l === l ? '' : 'ghost')); LS.set('sb_help_lang', l); };
  md.querySelectorAll('#v13-lang button').forEach(b => b.onclick = () => set(b.dataset.l)); if (pref === 'mr') set('mr'); } } catch (e) { } return r; }; })();

// ═══════════════════════════════════════════════════════════════════════
// v13 — Batch E: the I, J, Share & Nomination registers = Society Register Manager (SRM) inside S4S
// ═══════════════════════════════════════════════════════════════════════
// SRM's own screens and engine run in an iframe (srm/index.html, made by build/srm_embed.py). S4S gives it
// window.api — SRM's storage interface — so every register is saved in this society's S4S data:
//   chqimg/_srm/soc      = { f: JSON of the SRM society without flats (+ flatOrder) }
//   chqimg/_srm/f_<id>   = { f: JSON of one flat with its holders (owners), nominations, associates, charges }
// (chqimg is written by admins/accountants and is not downloaded when the society opens; no rules change.)
// S4S → registers: every S4S member is a flat; owners come from S4S's transfer history. New flats and new
// transfers recorded in S4S are added to the registers when Registers opens (later owners get the next I Form No.,
// marked late entry if numbers were frozen). Editing a transfer date in S4S moves that owner's admission date too.
// Versions (SRM "Tools & Versions") are kept on this computer (IndexedDB).
const SRMX = { last: {}, soc: null, frame: null, idb: null };
const srmId = () => 's4s-' + S.sid;
const srmPath = k => sp('chqimg/_srm' + (k ? '/' + k : ''));
const srmNm = m => (m.name || '') + (m.name2 ? ' & ' + m.name2 : '');
const srmNorm = s => String(s || '').toLowerCase().replace(/\b(mr|mrs|ms|miss|shri|smt|dr|late)\.?\s+/g, '').replace(/[^a-z0-9ऀ-ॿ]+/g, ' ').trim();
const srmMod = () => { try { return SRMX.frame && SRMX.frame.contentWindow.__srm.M; } catch (e) { return null; } };
async function srmRead() { const d = await FBX.get(srmPath()); if (!d || !d.soc || !d.soc.f) return null; const soc = JSON.parse(d.soc.f); const order = soc.flatOrder || []; delete soc.flatOrder;
  const fl = {}; for (const [k, v] of Object.entries(d)) if (k.startsWith('f_') && v && v.f) fl[k.slice(2)] = JSON.parse(v.f);
  soc.flats = [...order.filter(id => fl[id]).map(id => fl[id]), ...Object.keys(fl).filter(id => !order.includes(id)).map(id => fl[id])];
  SRMX.last = { soc: d.soc.f }; for (const [k, v] of Object.entries(d)) if (k.startsWith('f_') && v && v.f) SRMX.last[k] = v.f; return soc; }
async function srmWrite(soc) { if (!canEdit()) throw new Error('View-only access — registers cannot be changed'); const c = JSON.parse(JSON.stringify(soc)); const flats = c.flats || []; c.flatOrder = flats.map(f => f.id); delete c.flats;
  const up = {}; const ss = JSON.stringify(c); if (SRMX.last.soc !== ss) up[srmPath('soc')] = { f: ss, at: Date.now() };
  const now = new Set(); for (const f of flats) { const k = 'f_' + f.id; now.add(k); const fs_ = JSON.stringify(f); if (SRMX.last[k] !== fs_) up[srmPath(k)] = { f: fs_ }; }
  for (const k of Object.keys(SRMX.last)) if (k.startsWith('f_') && !now.has(k)) up[srmPath(k)] = null;
  if (!Object.keys(up).length) return; await FBX.update(up); SRMX.last = { soc: ss }; for (const f of flats) SRMX.last['f_' + f.id] = JSON.stringify(f); }
// S4S members and transfers → register flats and owners
function srmSync(soc, Mod) { let added = 0, owners = 0, moved = 0; const key = (w, f) => String(w || '').trim().toLowerCase() + '|' + String(f || '').trim().toLowerCase();
  soc.name = soc.name || S.meta.name || ''; if (!soc.regNo && S.meta.regNo) soc.regNo = S.meta.regNo; if (!soc.address) soc.address = [S.meta.address, S.meta.city, S.meta.pin].filter(Boolean).join(', ');
  const byMid = new Map(soc.flats.filter(f => f.s4s).map(f => [f.s4s, f])); const byKey = new Map(soc.flats.filter(f => !f.s4s).map(f => [key(f.wing, f.flatNo), f]));
  for (const [mid, m] of Object.entries(S.members).filter(([, x]) => x).sort((a, b) => sortFlat(a[1], b[1]))) {
    const H_ = HIST(mid).map(([, h]) => h); const chain = H_.map((h, i) => ({ name: srmNm(h), date: h.since || (i ? H_[i - 1].to : '') || '' }));
    chain.push({ name: srmNm(m), date: m.since || (H_.length ? H_[H_.length - 1].to : '') || '' });
    let f = byMid.get(mid) || byKey.get(key(m.wing, m.flat));
    if (!f) { f = Mod.newFlat(String(m.flat || ''), String(m.wing || '')); f.s4s = mid; if (m.type) f.type = m.type; if (m.area) f.area = String(m.area); if (m.parking) f.parking = String(m.parking);
      chain.forEach((c, i) => f.holders.push(Mod.newHolder(soc, { name: c.name, admissionDate: c.date, via: i ? 'Sale Deed' : 'Original Allotment', memberClass: 'Original' })));
      const cur = f.holders[f.holders.length - 1]; const sh = Object.values(S.shr || {}).filter(x => x && x.mid === mid);
      if (cur && sh.length) { const x = sh[0]; if (x.cert) cur.certNo = x.cert; if (x.from) cur.distFrom = +x.from; if (x.to) cur.distTo = +x.to; if (+x.qty) { cur.shares = cur.application = cur.allotment = +x.qty; cur.amount = +x.qty * (Number(soc.shareValue) || 50); } }
      if (cur && m.nominee) cur.nominations.push(Mod.newNomination({ date: m.nomDate || '', nominees: [{ name: m.nominee, pct: m.nomPct != null ? String(m.nomPct) : '', relation: m.nomRel || '', address: '' }] }));
      soc.flats.push(f); added++; continue; }
    f.s4s = mid; if (String(f.flatNo) !== String(m.flat || '') || String(f.wing || '') !== String(m.wing || '')) { f.flatNo = String(m.flat || ''); f.wing = String(m.wing || ''); moved++; }
    const last = f.holders[f.holders.length - 1]; const lastD = last ? last.admissionDate || '' : '';
    for (const c of chain.slice(1)) { if (!c.date || c.date <= lastD) continue; if (f.holders.some(h => srmNorm(h.name) === srmNorm(c.name))) continue; const p = f.holders[f.holders.length - 1] || {};
      f.holders.push(Mod.newHolder(soc, { name: c.name, admissionDate: c.date, via: 'Sale Deed', memberClass: 'Original', shares: p.shares, application: p.shares, allotment: p.shares, amount: p.amount })); owners++; } }
  return { added, owners, moved }; }
// SRM's storage interface, backed by S4S
const srmApi = () => ({ platform: /android|iphone|ipad/i.test(navigator.userAgent) ? 'phone' : 'browser', autoOpen: srmId(), user: { name: uname(), role: canEdit() ? 'admin' : 'staff' },
  ready() { const e = $('srm-wait'); if (e) e.remove(); },
  async listSocieties() { const s = SRMX.soc; return [{ id: srmId(), name: S.meta.name || '', flats: s ? s.flats.length : Object.keys(S.members).length, members: s ? s.flats.reduce((a, f) => a + f.holders.length, 0) : 0, updatedAt: s ? s.updatedAt : '', savedBy: s ? s.savedBy || '' : '', summary: s ? s.summary || null : null }]; },
  async loadSociety(id) { if (id !== srmId()) return null; const Mod = srmMod(); let soc = await srmRead(); let fresh = false;
    if (!soc) { soc = Mod.newSociety(S.meta.name || 'Society'); soc.id = srmId(); fresh = true; }
    const r = srmSync(soc, Mod); if (fresh || r.added || r.owners || r.moved) { Mod.recompute(soc); soc.updatedAt = new Date().toISOString(); soc.saveId = soc.saveId || Mod.uid('v');
      (soc.log = soc.log || []).push({ at: new Date().toISOString(), what: fresh ? `Registers started from S4S: ${r.added} flat(s)` : `From S4S: ${r.added} new flat(s), ${r.owners} new owner(s) from transfers${r.moved ? `, ${r.moved} flat no(s). updated` : ''}` });
      if (canEdit()) await srmWrite(soc); if (!fresh && (r.added || r.owners)) toast(`Registers updated from S4S — ${r.added ? r.added + ' new flat(s) ' : ''}${r.owners ? r.owners + ' new owner(s) from transfers' : ''}`, 'ok', 6000); }
    SRMX.soc = soc; return JSON.parse(JSON.stringify(soc)); },
  async statSociety(id) { if (id !== srmId()) return null; const v = await FBX.get(srmPath('soc/f')); if (!v) return null; const s = JSON.parse(v); return { saveId: s.saveId || '', updatedAt: s.updatedAt, savedBy: s.savedBy || '' }; },
  async saveSociety(soc) { if (soc.id !== srmId()) throw new Error('In Solutions4Society, registers belong to the open society — make new societies in S4S'); await srmWrite(soc); SRMX.soc = JSON.parse(JSON.stringify(soc)); await srmVerPut(soc, 'daily', true); return { ok: true }; },
  async deleteSociety() { throw new Error('Delete the society from S4S, not from Registers'); },
  async snapshot(soc, label) { return srmVerPut(soc, label); },
  async listVersions(id) { return (await srmIdb('getAll')).filter(x => x.id === id).map(x => ({ file: x.k, when: x.when, label: x.label, size: x.size })).sort((a, b) => b.when.localeCompare(a.when)); },
  async loadVersion(k) { const x = await srmIdb('get', k); return x ? x.soc : null; },
  async saveFile({ name, data }) { const t = /\.xlsx$/.test(name) ? 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' : /\.docx$/.test(name) ? 'application/vnd.openxmlformats-officedocument.wordprocessingml.document' : /\.pdf$/.test(name) ? 'application/pdf' : 'application/octet-stream';
    try { const f = new File([data], name, { type: t }); if (/android|iphone|ipad/i.test(navigator.userAgent) && navigator.canShare && navigator.canShare({ files: [f] })) { await navigator.share({ files: [f], title: name }); return name; } } catch (e) { if (e && e.name === 'AbortError') return null; }
    download(name, new Blob([data], { type: t }), t); return name; },
  async openFile({ filters } = {}) { return new Promise(res => { const i = document.createElement('input'); i.type = 'file'; if (filters && !/android|iphone|ipad/i.test(navigator.userAgent)) i.accept = filters.flatMap(n => n.extensions.map(x => '.' + x)).join(','); i.onchange = async () => { const f = i.files[0]; if (!f) return res(null); res({ name: f.name, data: await f.arrayBuffer() }); }; i.click(); }); },
  async openImage() { const f = await srmApi().openFile({ filters: [{ name: 'Image', extensions: ['png', 'jpg', 'jpeg'] }] }); if (!f) return null; const b = new Uint8Array(f.data); let s = ''; for (let i = 0; i < b.length; i++) s += String.fromCharCode(b[i]); return `data:image/${/\.png$/i.test(f.name) ? 'png' : 'jpeg'};base64,` + btoa(s); },
  async printPDF({ html, name }) { srmPrint(name, html); return name; },
  async openFolder() { return true; }, async chooseFolder() { return null; }, async copyToFolder() { return null; },
  async info() { return { root: 'Solutions4Society', version: 'S4S ' + APP_VERSION, computer: uname() }; },
  async getSettings() { try { return JSON.parse(LS.get('sb_srm_set', '{}')) || {}; } catch (e) { return {}; } },
  async saveSettings(x) { const c = await srmApi().getSettings(); delete x.users; LS.set('sb_srm_set', JSON.stringify(Object.assign(c, x))); return true; } });
// SRM's print pages (legal / A4 I Forms, certificates…) shown exactly as SRM makes them, in S4S's print preview
// (no pop-up window: works on phones and is never blocked) — 🖨 Print / Save PDF prints with SRM's own page size
function srmPrint(name, html) { const old = $('printov'); if (old) old.remove(); const ov = document.createElement('div'); ov.id = 'printov';
  ov.innerHTML = `<div class="pov-bar"><b>${esc(name)}</b><span class="spacer"></span><button id="pov-go" onclick="printOvGo()" disabled>⏳ Preparing…</button><button class="ghost" onclick="printOvClose()">✕ Close</button></div><iframe id="printov-f" title="${esc(name)}"></iframe>`;
  document.body.appendChild(ov); POV.ready = false; POV.want = false; const f = $('printov-f'); f.dataset.srm = '1';
  const ready = () => { if (POV.ready || !$('printov')) return; POV.ready = true; const b = $('pov-go'); if (b) { b.disabled = false; b.textContent = '🖨 Print / Save PDF'; } if (POV.want) { POV.want = false; printOvGo(); } };
  f.addEventListener('load', () => { const d = f.contentDocument; const fin = () => setTimeout(ready, 150); if (d && d.fonts && d.fonts.ready) Promise.race([d.fonts.ready, new Promise(r => setTimeout(r, 2500))]).then(fin); else fin(); });
  f.srcdoc = html; setTimeout(ready, 6000); try { history.pushState({ printov: 1 }, ''); } catch (e) { } }
// versions on this computer (last 30 per society + one per day)
function srmIdb(op, a) { return new Promise((res, rej) => { const o = indexedDB.open('s4s-srm', 1); o.onupgradeneeded = () => o.result.createObjectStore('ver', { keyPath: 'k' }); o.onerror = () => rej(o.error);
  o.onsuccess = () => { const t = o.result.transaction('ver', op === 'get' || op === 'getAll' ? 'readonly' : 'readwrite'); const st = t.objectStore('ver'); const r = op === 'put' ? st.put(a) : op === 'del' ? st.delete(a) : op === 'get' ? st.get(a) : st.getAll(); r.onsuccess = () => res(r.result); r.onerror = () => rej(r.error); }; }); }
async function srmVerPut(soc, label, daily) { const id = soc.id; const k = daily ? `${id}__${today()}__daily` : `${id}__${Date.now()}__${label}`; try { if (daily && await srmIdb('get', k)) return k; const c = JSON.parse(JSON.stringify(soc));
  await srmIdb('put', { k, id, when: new Date().toISOString(), label, soc: c, size: JSON.stringify(c).length }); const L = (await srmIdb('getAll')).filter(x => x.id === id).sort((a, b) => a.when.localeCompare(b.when)); for (const x of L.slice(0, Math.max(0, L.length - 30))) await srmIdb('del', x.k); } catch (e) { console.warn('srm version', e); } return k; }
